CREATE OR REPLACE FUNCTION "public"."_resolve_plan_base_for_resource"("p_org_id" "uuid", "p_resource_key" "text") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_limit INTEGER;
BEGIN
  -- Priority 1: org_subscriptions → subscription_plans.limits
  SELECT (sp.limits ->> p_resource_key)::INTEGER
  INTO v_limit
  FROM public.org_subscriptions os
  JOIN public.subscription_plans sp ON sp.id = os.plan_id
  WHERE os.organization_id = p_org_id
    AND os.cancelled_at IS NULL;

  IF v_limit IS NOT NULL THEN
    RETURN v_limit;
  END IF;

  -- Priority 2: organizations.subscription_plan → subscription_plans.limits
  SELECT (sp.limits ->> p_resource_key)::INTEGER
  INTO v_limit
  FROM public.organizations o
  JOIN public.subscription_plans sp ON sp.name = o.subscription_plan
  WHERE o.id = p_org_id;

  IF v_limit IS NOT NULL THEN
    RETURN v_limit;
  END IF;

  -- Fallback
  RETURN 0;
END;
$$;


ALTER FUNCTION "public"."_resolve_plan_base_for_resource"("p_org_id" "uuid", "p_resource_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_resolve_plan_base_for_resource"("p_org_id" "uuid", "p_resource_key" "text") IS 'Internal: derives plan_base for a resource from the org current plan. Used during quota row creation.';



CREATE OR REPLACE FUNCTION "public"."acquire_copilot_lock"("p_phone" "text", "p_organization_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_affected int;
BEGIN
  INSERT INTO copilot_processing_locks (phone, organization_id, locked_at)
  VALUES (p_phone, p_organization_id, now())
  ON CONFLICT (phone, organization_id)
  DO UPDATE SET locked_at = now()
  WHERE copilot_processing_locks.locked_at < now() - interval '60 seconds';

  GET DIAGNOSTICS v_affected = ROW_COUNT;
  RETURN v_affected > 0;
END;
$$;


ALTER FUNCTION "public"."acquire_copilot_lock"("p_phone" "text", "p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."acquire_copilot_lock"("p_phone" "text", "p_organization_id" "uuid") IS 'Tenta adquirir lock de processing para phone+org. Retorna true se adquiriu, false se lock ativo (<60s).';



CREATE OR REPLACE FUNCTION "public"."admin_get_org_quota_summary"("p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_quotas       JSONB;
  v_recent_audit JSONB;
BEGIN
  -- Auth gate: master users only
  IF NOT public.is_master_user() THEN
    RAISE EXCEPTION 'access_denied: only master users can view org quota summaries';
  END IF;

  -- Build quotas array with current_usage per resource
  SELECT COALESCE(jsonb_agg(row_obj ORDER BY q.resource_key), '[]'::JSONB)
  INTO v_quotas
  FROM (
    SELECT
      to_jsonb(q.*) || jsonb_build_object(
        'current_usage',
        CASE q.resource_key
          WHEN 'max_whatsapp_instances' THEN (
            SELECT COUNT(*)::INTEGER
            FROM public.whatsapp_instances
            WHERE organization_id = p_org_id
          )
          WHEN 'max_users' THEN (
            SELECT COUNT(*)::INTEGER
            FROM public.team_members
            WHERE organization_id = p_org_id
              AND is_active = true
              AND NOT public.is_master_user(user_id)
          )
          WHEN 'max_copilot_agents' THEN (
            SELECT COUNT(*)::INTEGER
            FROM public.copilot_agents
            WHERE organization_id = p_org_id
          )
          ELSE 0
        END
      ) AS row_obj
    FROM public.org_quotas q
    WHERE q.organization_id = p_org_id
  ) sub;

  -- Build recent audit entries
  SELECT COALESCE(jsonb_agg(to_jsonb(a.*) ORDER BY a.created_at DESC), '[]'::JSONB)
  INTO v_recent_audit
  FROM (
    SELECT *
    FROM public.quota_audit_log
    WHERE organization_id = p_org_id
    ORDER BY created_at DESC
    LIMIT 10
  ) a;

  RETURN jsonb_build_object(
    'quotas',       v_quotas,
    'recent_audit', v_recent_audit
  );
END;
$$;


ALTER FUNCTION "public"."admin_get_org_quota_summary"("p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_get_org_quota_summary"("p_org_id" "uuid") IS 'Master-only: returns all org_quotas rows (with live current_usage) and last 10 audit log entries for an org.';



CREATE OR REPLACE FUNCTION "public"."admin_set_purchased_addons"("p_org_id" "uuid", "p_resource_key" "text", "p_purchased" integer, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_old_value   INTEGER;
  v_plan_base   INTEGER;
  v_result      RECORD;
  v_is_service  BOOLEAN;
  v_is_master   BOOLEAN;
BEGIN
  -- Auth gate: master users OR service_role
  v_is_service := (current_setting('role', true) = 'service_role');
  v_is_master  := public.is_master_user();

  IF NOT v_is_service AND NOT v_is_master THEN
    RAISE EXCEPTION 'access_denied: only master users or service_role can set purchased addons';
  END IF;

  -- Capture old value
  SELECT purchased_addons
  INTO v_old_value
  FROM public.org_quotas
  WHERE organization_id = p_org_id AND resource_key = p_resource_key;

  -- Resolve plan_base for potential INSERT
  v_plan_base := public._resolve_plan_base_for_resource(p_org_id, p_resource_key);

  -- UPSERT
  INSERT INTO public.org_quotas (organization_id, resource_key, plan_base, purchased_addons, admin_adjustment)
  VALUES (p_org_id, p_resource_key, v_plan_base, p_purchased, 0)
  ON CONFLICT (organization_id, resource_key)
  DO UPDATE SET
    purchased_addons = EXCLUDED.purchased_addons,
    updated_at       = NOW()
  RETURNING * INTO v_result;

  -- Audit log
  INSERT INTO public.quota_audit_log (
    organization_id, resource_key, field_changed,
    old_value, new_value, changed_by, change_reason
  ) VALUES (
    p_org_id, p_resource_key, 'purchased_addons',
    COALESCE(v_old_value, 0), p_purchased,
    auth.uid(), p_reason
  );

  RETURN to_jsonb(v_result);
END;
$$;


ALTER FUNCTION "public"."admin_set_purchased_addons"("p_org_id" "uuid", "p_resource_key" "text", "p_purchased" integer, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_purchased_addons"("p_org_id" "uuid", "p_resource_key" "text", "p_purchased" integer, "p_reason" "text") IS 'Master or service_role: sets the purchased_addons column on org_quotas. Creates the row if needed.';



CREATE OR REPLACE FUNCTION "public"."admin_set_quota_adjustment"("p_org_id" "uuid", "p_resource_key" "text", "p_admin_adjustment" integer, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_old_value   INTEGER;
  v_plan_base   INTEGER;
  v_result      RECORD;
BEGIN
  -- Auth gate: master users only
  IF NOT public.is_master_user() THEN
    RAISE EXCEPTION 'access_denied: only master users can set quota adjustments';
  END IF;

  -- Capture old value before mutation (NULL when row does not exist yet)
  SELECT admin_adjustment
  INTO v_old_value
  FROM public.org_quotas
  WHERE organization_id = p_org_id AND resource_key = p_resource_key;

  -- Resolve plan_base for potential INSERT
  v_plan_base := public._resolve_plan_base_for_resource(p_org_id, p_resource_key);

  -- UPSERT
  INSERT INTO public.org_quotas (organization_id, resource_key, plan_base, purchased_addons, admin_adjustment)
  VALUES (p_org_id, p_resource_key, v_plan_base, 0, p_admin_adjustment)
  ON CONFLICT (organization_id, resource_key)
  DO UPDATE SET
    admin_adjustment = EXCLUDED.admin_adjustment,
    updated_at       = NOW()
  RETURNING * INTO v_result;

  -- Audit log
  INSERT INTO public.quota_audit_log (
    organization_id, resource_key, field_changed,
    old_value, new_value, changed_by, change_reason
  ) VALUES (
    p_org_id, p_resource_key, 'admin_adjustment',
    COALESCE(v_old_value, 0), p_admin_adjustment,
    auth.uid(), p_reason
  );

  RETURN to_jsonb(v_result);
END;
$$;


ALTER FUNCTION "public"."admin_set_quota_adjustment"("p_org_id" "uuid", "p_resource_key" "text", "p_admin_adjustment" integer, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_quota_adjustment"("p_org_id" "uuid", "p_resource_key" "text", "p_admin_adjustment" integer, "p_reason" "text") IS 'Master-only: sets the admin_adjustment column on org_quotas for a given resource. Creates the row if needed.';



CREATE OR REPLACE FUNCTION "public"."advance_onboarding_state"("p_org_id" "uuid", "p_expected_state" "text", "p_payload" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_current text;
  v_next text;
BEGIN
  SELECT onboarding_state INTO v_current
  FROM organizations WHERE id = p_org_id FOR UPDATE;

  IF v_current IS NULL THEN
    RAISE EXCEPTION 'Organization not found: %', p_org_id;
  END IF;

  IF v_current != p_expected_state THEN
    RAISE EXCEPTION 'State mismatch: expected %, got %', p_expected_state, v_current;
  END IF;

  v_next := CASE v_current
    WHEN 'pending_whatsapp' THEN 'pending_profile'
    WHEN 'pending_profile' THEN 'pending_pipelines'
    WHEN 'pending_pipelines' THEN 'pending_automations'
    WHEN 'pending_automations' THEN 'completed'
  END;

  IF v_next IS NULL THEN
    RAISE EXCEPTION 'Cannot advance from state: %', v_current;
  END IF;

  IF v_current = 'pending_profile' AND p_payload IS NOT NULL THEN
    UPDATE organizations SET onboarding_answers = p_payload WHERE id = p_org_id;
  END IF;

  IF v_next = 'completed' THEN
    UPDATE organizations SET onboarding_completed_at = now() WHERE id = p_org_id;
  END IF;

  UPDATE organizations
  SET onboarding_state = v_next, updated_at = now()
  WHERE id = p_org_id;

  RETURN jsonb_build_object('previous_state', v_current, 'new_state', v_next);
END;
$$;


ALTER FUNCTION "public"."advance_onboarding_state"("p_org_id" "uuid", "p_expected_state" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_add_lead_tags"("p_org" "uuid", "p_lead_id" "uuid", "p_tags" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE tag_name text; v_tag_id uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM leads WHERE id = p_lead_id AND organization_id = p_org AND deleted_at IS NULL) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'not_found');
  END IF;
  FOREACH tag_name IN ARRAY p_tags LOOP
    CONTINUE WHEN NULLIF(btrim(tag_name), '') IS NULL;
    SELECT id INTO v_tag_id FROM tags WHERE organization_id = p_org AND lower(name) = lower(btrim(tag_name)) LIMIT 1;
    IF v_tag_id IS NULL THEN
      INSERT INTO tags (organization_id, name) VALUES (p_org, btrim(tag_name)) RETURNING id INTO v_tag_id;
    END IF;
    INSERT INTO lead_tags (lead_id, tag_id) VALUES (p_lead_id, v_tag_id) ON CONFLICT (lead_id, tag_id) DO NOTHING;
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'tags', COALESCE((
    SELECT jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'color', t.color))
    FROM lead_tags lt JOIN tags t ON t.id = lt.tag_id WHERE lt.lead_id = p_lead_id), '[]'::jsonb));
END;
$$;


ALTER FUNCTION "public"."api_add_lead_tags"("p_org" "uuid", "p_lead_id" "uuid", "p_tags" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_get_lead"("p_org" "uuid", "p_lead_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'id', l.id, 'name', l.name, 'company', l.company, 'email', l.email, 'phone', l.phone,
    'origin', l.origin::text, 'rating', l.rating, 'qualification_score', l.qualification_score,
    'tier', COALESCE(l.qualification_tier, l.pre_qualification_tier)::text,
    'responsible_id', l.responsible_id, 'sdr_id', l.sdr_id, 'closer_id', l.closer_id,
    'pre_sale_responsible_id', l.pre_sale_responsible_id, 'sale_responsible_id', l.sale_responsible_id,
    'created_at', l.created_at, 'updated_at', l.updated_at,
    'tags', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'color', t.color))
      FROM lead_tags lt JOIN tags t ON t.id = lt.tag_id WHERE lt.lead_id = l.id), '[]'::jsonb),
    'custom_fields', COALESCE((SELECT jsonb_agg(jsonb_build_object('field_name', cf.field_name,
      'field_type', cf.field_type, 'value', cfv.value) ORDER BY cf.display_order)
      FROM lead_custom_field_values cfv JOIN lead_custom_fields cf ON cf.id = cfv.field_id
      WHERE cfv.lead_id = l.id), '[]'::jsonb),
    'pipes', COALESCE((SELECT jsonb_agg(jsonb_build_object('pipeline', pip.slug, 'pipeline_name', pip.name,
      'type', pip.type, 'stage_key', pe.stage_key,
      'sold', (pe.stage_key = 'vendido' AND pip.slug = 'propostas' AND pip.type = 'system'),
      'sale_value', (pe.metadata->>'sale_value')::numeric, 'entered_at', pe.entered_at,
      'stage_changed_at', pe.stage_changed_at) ORDER BY pip.display_order)
      FROM pipeline_entries pe JOIN pipelines pip ON pip.id = pe.pipeline_id
      WHERE pe.lead_id = l.id AND pe.organization_id = p_org), '[]'::jsonb)
  )
  FROM leads l
  WHERE l.id = p_lead_id AND l.organization_id = p_org AND l.deleted_at IS NULL;
$$;


