CREATE OR REPLACE FUNCTION "public"."api_lead_timeline"("p_org" "uuid", "p_lead_id" "uuid", "p_limit" integer DEFAULT 50, "p_cursor_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "created_at" timestamp with time zone, "action" "text", "description" "text", "source" "text", "entity_type" "text", "entity_id" "uuid", "metadata" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT h.id, h.created_at, h.action, h.description, h.source, h.entity_type, h.entity_id, h.metadata
  FROM lead_history h
  WHERE h.organization_id = p_org AND h.lead_id = p_lead_id
    AND (p_cursor_created_at IS NULL OR h.created_at < p_cursor_created_at
         OR (h.created_at = p_cursor_created_at AND h.id < p_cursor_id))
  ORDER BY h.created_at DESC, h.id DESC
  LIMIT GREATEST(p_limit, 1);
$$;


