CREATE OR REPLACE FUNCTION "public"."api_remove_lead_tag"("p_org" "uuid", "p_lead_id" "uuid", "p_tag" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_tag_id uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM leads WHERE id = p_lead_id AND organization_id = p_org AND deleted_at IS NULL) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'not_found');
  END IF;
  SELECT id INTO v_tag_id FROM tags WHERE organization_id = p_org AND lower(name) = lower(btrim(p_tag)) LIMIT 1;
  IF v_tag_id IS NOT NULL THEN
    DELETE FROM lead_tags WHERE lead_id = p_lead_id AND tag_id = v_tag_id;
  END IF;
  RETURN jsonb_build_object('ok', true);
END;
$$;


