CREATE OR REPLACE FUNCTION "public"."api_set_custom_fields"("p_org" "uuid", "p_lead_id" "uuid", "p_values" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE k text; v_field_id uuid; unknown text[] := '{}';
BEGIN
  IF NOT EXISTS (SELECT 1 FROM leads WHERE id = p_lead_id AND organization_id = p_org AND deleted_at IS NULL) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'not_found');
  END IF;
  FOR k IN SELECT jsonb_object_keys(p_values) LOOP
    IF NOT EXISTS (SELECT 1 FROM lead_custom_fields WHERE organization_id = p_org AND field_name = k) THEN
      unknown := array_append(unknown, k);
    END IF;
  END LOOP;
  IF array_length(unknown, 1) IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'unknown_field', 'unknown_fields', to_jsonb(unknown));
  END IF;
  FOR k IN SELECT jsonb_object_keys(p_values) LOOP
    SELECT id INTO v_field_id FROM lead_custom_fields WHERE organization_id = p_org AND field_name = k LIMIT 1;
    INSERT INTO lead_custom_field_values (lead_id, field_id, value, updated_at)
    VALUES (p_lead_id, v_field_id, p_values->>k, now())
    ON CONFLICT (lead_id, field_id) DO UPDATE SET value = excluded.value, updated_at = now();
  END LOOP;
  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."api_set_custom_fields"("p_org" "uuid", "p_lead_id" "uuid", "p_values" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."api_update_lead"("p_org" "uuid", "p_lead_id" "uuid", "p_patch" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE rf text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM leads WHERE id = p_lead_id AND organization_id = p_org AND deleted_at IS NULL) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'not_found');
  END IF;
  FOREACH rf IN ARRAY ARRAY['responsible_id','sdr_id','closer_id','pre_sale_responsible_id','sale_responsible_id'] LOOP
    IF p_patch ? rf AND NULLIF(p_patch->>rf, '') IS NOT NULL THEN
      IF NOT EXISTS (SELECT 1 FROM team_members WHERE id = (p_patch->>rf)::uuid AND organization_id = p_org) THEN
        RETURN jsonb_build_object('ok', false, 'code', 'invalid_responsible', 'field', rf);
      END IF;
    END IF;
  END LOOP;
  UPDATE leads SET
    name = CASE WHEN p_patch ? 'name' THEN p_patch->>'name' ELSE name END,
    company = CASE WHEN p_patch ? 'company' THEN p_patch->>'company' ELSE company END,
    email = CASE WHEN p_patch ? 'email' THEN p_patch->>'email' ELSE email END,
    phone = CASE WHEN p_patch ? 'phone' THEN p_patch->>'phone' ELSE phone END,
    notes = CASE WHEN p_patch ? 'notes' THEN p_patch->>'notes' ELSE notes END,
    rating = CASE WHEN p_patch ? 'rating' THEN (p_patch->>'rating')::int ELSE rating END,
    qualification_score = CASE WHEN p_patch ? 'qualification_score' THEN (p_patch->>'qualification_score')::int ELSE qualification_score END,
    qualification_tier = CASE WHEN p_patch ? 'qualification_tier' THEN (p_patch->>'qualification_tier')::qualification_tier ELSE qualification_tier END,
    pre_qualification_tier = CASE WHEN p_patch ? 'pre_qualification_tier' THEN (p_patch->>'pre_qualification_tier')::qualification_tier ELSE pre_qualification_tier END,
    responsible_id = CASE WHEN p_patch ? 'responsible_id' THEN NULLIF(p_patch->>'responsible_id','')::uuid ELSE responsible_id END,
    sdr_id = CASE WHEN p_patch ? 'sdr_id' THEN NULLIF(p_patch->>'sdr_id','')::uuid ELSE sdr_id END,
    closer_id = CASE WHEN p_patch ? 'closer_id' THEN NULLIF(p_patch->>'closer_id','')::uuid ELSE closer_id END,
    pre_sale_responsible_id = CASE WHEN p_patch ? 'pre_sale_responsible_id' THEN NULLIF(p_patch->>'pre_sale_responsible_id','')::uuid ELSE pre_sale_responsible_id END,
    sale_responsible_id = CASE WHEN p_patch ? 'sale_responsible_id' THEN NULLIF(p_patch->>'sale_responsible_id','')::uuid ELSE sale_responsible_id END,
    updated_at = now()
  WHERE id = p_lead_id AND organization_id = p_org;
  RETURN jsonb_build_object('ok', true, 'lead', public.api_get_lead(p_org, p_lead_id));
END;
$$;


ALTER FUNCTION "public"."api_update_lead"("p_org" "uuid", "p_lead_id" "uuid", "p_patch" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_stage_checklist"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_template_id uuid;
  v_stage_org_id uuid;
  v_new_checklist_id uuid;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF TG_TABLE_NAME = 'pipeline_entries' THEN
      IF NEW.stage_key IS NOT DISTINCT FROM OLD.stage_key THEN
        RETURN NEW;
      END IF;
    END IF;
    IF TG_TABLE_NAME = 'custom_pipe_entries' THEN
      IF NEW.stage_id IS NOT DISTINCT FROM OLD.stage_id THEN
        RETURN NEW;
      END IF;
    END IF;
  END IF;

  IF TG_TABLE_NAME = 'pipeline_entries' THEN
    SELECT ps.checklist_template_id, ps.organization_id
      INTO v_template_id, v_stage_org_id
    FROM public.pipeline_stages ps
    JOIN public.pipelines p ON p.id = NEW.pipeline_id
    WHERE ps.organization_id = NEW.organization_id
      AND ps.pipeline_type = p.slug
      AND ps.stage_key = NEW.stage_key
      AND ps.is_active = true
    LIMIT 1;
  ELSIF TG_TABLE_NAME = 'custom_pipe_entries' THEN
    SELECT cps.checklist_template_id, cps.organization_id
      INTO v_template_id, v_stage_org_id
    FROM public.custom_pipeline_stages cps
    WHERE cps.id = NEW.stage_id
    LIMIT 1;
  END IF;

  IF v_template_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF v_stage_org_id IS NULL OR v_stage_org_id <> NEW.organization_id THEN
    RETURN NEW;
  END IF;

  IF NEW.lead_id IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.checklists (
    organization_id, lead_id, source_template_id, title, description, created_by
  )
  SELECT t.organization_id, NEW.lead_id, t.id, t.title, t.description, NULL
  FROM public.checklists t
  WHERE t.id = v_template_id
    AND t.lead_id IS NULL
    AND t.organization_id = NEW.organization_id
  ON CONFLICT (lead_id, source_template_id)
    WHERE source_template_id IS NOT NULL AND lead_id IS NOT NULL
  DO NOTHING
  RETURNING id INTO v_new_checklist_id;

  IF v_new_checklist_id IS NOT NULL THEN
    INSERT INTO public.checklist_items (checklist_id, title, position, template_item_id)
    SELECT v_new_checklist_id, ci.title, ci.position, ci.id
    FROM public.checklist_items ci
    WHERE ci.checklist_id = v_template_id
    ORDER BY ci.position;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."apply_stage_checklist"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_org_access"("p_org_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- backend (service_role) e jobs internos passam
  IF coalesce(auth.role(), '') = 'service_role' THEN RETURN; END IF;

  -- master vê qualquer org
  IF public.is_master_user() THEN RETURN; END IF;

  -- org nula nunca concede acesso
  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'access_denied' USING ERRCODE = 'P0001';
  END IF;

  -- membro ATIVO da org, ou gestor de portfólio da org (ADR-0021).
  -- get_my_organization_ids() é a fonte única: team_members com
  -- is_active = true UNION get_my_gestor_organization_ids().
  IF EXISTS (
    SELECT 1 FROM public.get_my_organization_ids() AS t(org_id)
    WHERE t.org_id = p_org_id
  ) THEN
    RETURN;
  END IF;

  RAISE EXCEPTION 'access_denied' USING ERRCODE = 'P0001';
END;
$$;


ALTER FUNCTION "public"."assert_org_access"("p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assert_org_access"("p_org_id" "uuid") IS 'Gate de tenancy dos leitores SECURITY DEFINER (ADR-0017). Passa: service_role, master, membro ATIVO da org e gestor de portfólio da org (ADR-0021). Delega a regra de vínculo a get_my_organization_ids() para não divergir do RLS. Caso contrário RAISE access_denied (P0001). Ver issue #1209.';



CREATE OR REPLACE FUNCTION "public"."assert_org_member"("p_org_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF coalesce(auth.role(), '') = 'service_role' THEN RETURN; END IF;
  IF public.is_master_user() THEN RETURN; END IF;

  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'access_denied' USING ERRCODE = 'P0001';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.get_my_organization_ids() AS t(org_id)
    WHERE t.org_id = p_org_id
  ) THEN
    RAISE EXCEPTION 'access_denied' USING ERRCODE = 'P0001';
  END IF;
END;
$$;


ALTER FUNCTION "public"."assert_org_member"("p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assert_org_member"("p_org_id" "uuid") IS 'Gate de tenancy dos leitores de Carteira (get_portfolio_*, get_revenue_at_risk, get_vendedor_ranking, get_pending_orders). Mesma regra de assert_org_access: service_role, master, membro ATIVO e gestor de portfólio. Ver issue #1209.';



CREATE OR REPLACE FUNCTION "public"."audit_table_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
  v_func text;
  v_org uuid;
  v_row_id text;
  v_changes jsonb;
  v_claims_raw text;
  v_claims jsonb;
BEGIN
  -- Captura role: tenta formato novo (JSON claims), depois antigo (claim.role)
  BEGIN
    v_claims_raw := current_setting('request.jwt.claims', true);
    IF v_claims_raw IS NOT NULL AND v_claims_raw <> '' THEN
      v_claims := v_claims_raw::jsonb;
      v_role := v_claims->>'role';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_role := NULL;
  END;

  IF v_role IS NULL THEN
    BEGIN
      v_role := current_setting('request.jwt.claim.role', true);
    EXCEPTION WHEN OTHERS THEN
      v_role := NULL;
    END;
  END IF;

  -- Skip se não é service_role
  IF v_role IS NULL OR v_role <> 'service_role' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- Captura nome da edge function (header opcional)
  BEGIN
    v_func := current_setting('request.headers', true)::jsonb->>'x-edge-function';
  EXCEPTION WHEN OTHERS THEN
    v_func := NULL;
  END;

  v_org := COALESCE(
    (to_jsonb(NEW)->>'organization_id')::uuid,
    (to_jsonb(OLD)->>'organization_id')::uuid
  );

  v_row_id := COALESCE(
    (to_jsonb(NEW)->>'id'),
    (to_jsonb(OLD)->>'id')
  );

  IF TG_OP = 'UPDATE' THEN
    v_changes := jsonb_build_object(
      'before', to_jsonb(OLD),
      'after', to_jsonb(NEW)
    );
  ELSE
    v_changes := NULL;
  END IF;

  INSERT INTO public.audit_log (
    table_name, operation, row_id, organization_id,
    actor_role, actor_function, changes
  ) VALUES (
    TG_TABLE_NAME, TG_OP, v_row_id, v_org,
    v_role, v_func, v_changes
  );

  RETURN COALESCE(NEW, OLD);
EXCEPTION WHEN OTHERS THEN
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."audit_table_change"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."audit_table_change"() IS 'Onda 2 T2.A.3 (fix QA): captura role via request.jwt.claims (JSON) com fallback request.jwt.claim.role.';



