CREATE OR REPLACE FUNCTION "public"."bulk_add_to_custom_pipe"("p_lead_ids" "uuid"[], "p_pipeline_id" "uuid", "p_stage_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_is_master  boolean := public.is_master_user();
  v_member_org uuid;
  v_lead_id    uuid;
  v_lead_org   uuid;
BEGIN
  -- Membros: pinam a propria org. Master: sem pin (escopo limitado por p_lead_ids).
  IF NOT v_is_master THEN
    SELECT tm.organization_id INTO v_member_org
    FROM public.team_members tm
    WHERE tm.user_id = auth.uid() AND tm.is_active = true
    LIMIT 1;

    IF v_member_org IS NULL THEN
      RAISE EXCEPTION 'No active organization membership';
    END IF;
  END IF;

  FOREACH v_lead_id IN ARRAY p_lead_ids LOOP
    -- Org do lead + autorizacao (membro: so a propria org; master: qualquer org)
    SELECT l.organization_id INTO v_lead_org
    FROM public.leads l
    WHERE l.id = v_lead_id
      AND l.deleted_at IS NULL
      AND (v_is_master OR l.organization_id = v_member_org);

    IF v_lead_org IS NULL THEN
      CONTINUE;  -- inexistente, deletado, ou sem permissao
    END IF;

    -- Funil custom alvo deve pertencer a org do lead e estar ativo
    IF NOT EXISTS (
      SELECT 1 FROM public.custom_pipelines cp
      WHERE cp.id = p_pipeline_id
        AND cp.organization_id = v_lead_org
        AND cp.is_active = true
    ) THEN
      CONTINUE;
    END IF;

    -- Etapa alvo deve pertencer ao funil
    IF NOT EXISTS (
      SELECT 1 FROM public.custom_pipeline_stages cps
      WHERE cps.id = p_stage_id
        AND cps.pipeline_id = p_pipeline_id
    ) THEN
      CONTINUE;
    END IF;

    INSERT INTO public.custom_pipe_entries (
      organization_id, pipeline_id, lead_id, stage_id, entered_at, stage_changed_at
    ) VALUES (
      v_lead_org, p_pipeline_id, v_lead_id, p_stage_id, now(), now()
    )
    ON CONFLICT (pipeline_id, lead_id) DO UPDATE SET
      stage_id = EXCLUDED.stage_id,
      stage_changed_at = now(),
      updated_at = now();
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."bulk_add_to_custom_pipe"("p_lead_ids" "uuid"[], "p_pipeline_id" "uuid", "p_stage_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_assign_leads"("p_lead_ids" "uuid"[], "p_responsible_id" "uuid" DEFAULT NULL::"uuid", "p_sdr_id" "uuid" DEFAULT NULL::"uuid", "p_closer_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_is_master boolean := public.is_master_user();
  v_org_id    uuid;
BEGIN
  IF NOT v_is_master THEN
    SELECT tm.organization_id INTO v_org_id
    FROM public.team_members tm
    WHERE tm.user_id = auth.uid() AND tm.is_active = true
    LIMIT 1;

    IF v_org_id IS NULL THEN
      RAISE EXCEPTION 'No active organization membership';
    END IF;
  END IF;

  UPDATE public.leads
  SET
    responsible_id = p_responsible_id,
    sdr_id = p_sdr_id,
    closer_id = p_closer_id,
    updated_at = now()
  WHERE id = ANY(p_lead_ids)
    AND deleted_at IS NULL
    AND (v_org_id IS NULL OR organization_id = v_org_id);
END;
$$;


ALTER FUNCTION "public"."bulk_assign_leads"("p_lead_ids" "uuid"[], "p_responsible_id" "uuid", "p_sdr_id" "uuid", "p_closer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_delete_leads"("p_lead_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_org_id uuid;
  v_user_id uuid;
  v_count integer;
BEGIN
  v_user_id := auth.uid();

  IF public.is_master_user() THEN
    -- master: no org pin; scope is bounded by the explicit p_lead_ids
    v_org_id := NULL;
  ELSE
    SELECT organization_id INTO v_org_id
    FROM public.team_members
    WHERE user_id = v_user_id AND is_active = true
    LIMIT 1;

    IF v_org_id IS NULL THEN
      RAISE EXCEPTION 'No active organization membership';
    END IF;
  END IF;

  -- Soft-delete leads (caller's org for members; any matching id for master)
  UPDATE public.leads
  SET deleted_at = now(), deleted_by = v_user_id
  WHERE id = ANY(p_lead_ids)
    AND (v_org_id IS NULL OR organization_id = v_org_id)
    AND deleted_at IS NULL;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  -- Remove from pipeline_entries so kanban is clean
  DELETE FROM public.pipeline_entries
  WHERE lead_id = ANY(p_lead_ids)
    AND (v_org_id IS NULL OR organization_id = v_org_id);

  -- Remove from legacy pipe tables
  DELETE FROM public.pipe_whatsapp    WHERE lead_id = ANY(p_lead_ids) AND (v_org_id IS NULL OR organization_id = v_org_id);
  DELETE FROM public.pipe_confirmacao WHERE lead_id = ANY(p_lead_ids) AND (v_org_id IS NULL OR organization_id = v_org_id);
  DELETE FROM public.pipe_propostas   WHERE lead_id = ANY(p_lead_ids) AND (v_org_id IS NULL OR organization_id = v_org_id);
  DELETE FROM public.custom_pipe_entries WHERE lead_id = ANY(p_lead_ids) AND (v_org_id IS NULL OR organization_id = v_org_id);

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."bulk_delete_leads"("p_lead_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_move_stage"("p_lead_ids" "uuid"[], "p_target_pipe" "text", "p_target_stage" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_is_master  boolean := public.is_master_user();
  v_member_org uuid;
  v_lead_id    uuid;
  v_lead_org   uuid;
  v_pipeline_id uuid;
BEGIN
  -- Membros: pinam a propria org. Master: sem pin (escopo limitado por p_lead_ids).
  IF NOT v_is_master THEN
    SELECT tm.organization_id INTO v_member_org
    FROM public.team_members tm
    WHERE tm.user_id = auth.uid() AND tm.is_active = true
    LIMIT 1;

    IF v_member_org IS NULL THEN
      RAISE EXCEPTION 'No active organization membership';
    END IF;
  END IF;

  FOREACH v_lead_id IN ARRAY p_lead_ids LOOP
    -- Org do lead + autorizacao (membro: so a propria org; master: qualquer org)
    SELECT l.organization_id INTO v_lead_org
    FROM public.leads l
    WHERE l.id = v_lead_id
      AND l.deleted_at IS NULL
      AND (v_is_master OR l.organization_id = v_member_org);

    IF v_lead_org IS NULL THEN
      CONTINUE;  -- inexistente, deletado, ou sem permissao
    END IF;

    -- Pipeline de sistema alvo, dentro da org do lead
    SELECT p.id INTO v_pipeline_id
    FROM public.pipelines p
    WHERE p.slug = p_target_pipe
      AND p.organization_id = v_lead_org
      AND p.type = 'system'
    LIMIT 1;

    IF v_pipeline_id IS NULL THEN
      CONTINUE;
    END IF;

    INSERT INTO public.pipeline_entries (
      organization_id, pipeline_id, lead_id, stage_key, stage_changed_at, entered_at
    ) VALUES (
      v_lead_org, v_pipeline_id, v_lead_id, p_target_stage, now(), now()
    )
    ON CONFLICT (pipeline_id, lead_id) DO UPDATE SET
      stage_key = EXCLUDED.stage_key,
      stage_changed_at = now(),
      updated_at = now();
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."bulk_move_stage"("p_lead_ids" "uuid"[], "p_target_pipe" "text", "p_target_stage" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_tag_leads"("p_lead_ids" "uuid"[], "p_add_tag_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_remove_tag_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_is_master boolean := public.is_master_user();
  v_org_id    uuid;
  v_lead_id   uuid;
  v_tag_id    uuid;
BEGIN
  IF NOT v_is_master THEN
    SELECT tm.organization_id INTO v_org_id
    FROM public.team_members tm
    WHERE tm.user_id = auth.uid() AND tm.is_active = true
    LIMIT 1;

    IF v_org_id IS NULL THEN
      RAISE EXCEPTION 'No active organization membership';
    END IF;
  END IF;

  -- Remove tags
  IF array_length(p_remove_tag_ids, 1) > 0 THEN
    DELETE FROM public.lead_tags lt
    WHERE lt.lead_id = ANY(p_lead_ids)
      AND lt.tag_id = ANY(p_remove_tag_ids)
      AND lt.lead_id IN (
        SELECT l.id FROM public.leads l
        WHERE l.deleted_at IS NULL
          AND (v_org_id IS NULL OR l.organization_id = v_org_id)
      );
  END IF;

  -- Add tags (skip duplicates)
  IF array_length(p_add_tag_ids, 1) > 0 THEN
    FOREACH v_lead_id IN ARRAY p_lead_ids LOOP
      IF NOT EXISTS (
        SELECT 1 FROM public.leads l
        WHERE l.id = v_lead_id
          AND l.deleted_at IS NULL
          AND (v_org_id IS NULL OR l.organization_id = v_org_id)
      ) THEN
        CONTINUE;
      END IF;

      FOREACH v_tag_id IN ARRAY p_add_tag_ids LOOP
        INSERT INTO public.lead_tags (lead_id, tag_id)
        VALUES (v_lead_id, v_tag_id)
        ON CONFLICT DO NOTHING;
      END LOOP;
    END LOOP;
  END IF;
END;
$$;


ALTER FUNCTION "public"."bulk_tag_leads"("p_lead_ids" "uuid"[], "p_add_tag_ids" "uuid"[], "p_remove_tag_ids" "uuid"[]) OWNER TO "postgres";


