COMMENT ON FUNCTION "public"."can_user_write_instance"("p_user_id" "uuid", "p_instance_id" "uuid") IS 'Verifica se usuário pode escrever via instância. True para owner, admin da org, ou master da plataforma.';



CREATE OR REPLACE FUNCTION "public"."can_view_lead"("p_lead_id" "uuid") RETURNS TABLE("status" "public"."lead_visibility_status", "metadata" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_is_master boolean := false;
  v_lead RECORD;
  v_in_org boolean := false;
BEGIN
  -- Auth required
  IF v_user_id IS NULL THEN
    status := 'permission_denied'::public.lead_visibility_status;
    metadata := jsonb_build_object('reason', 'unauthenticated');
    RETURN NEXT;
    RETURN;
  END IF;

  -- Master check
  SELECT EXISTS (
    SELECT 1 FROM public.master_users
    WHERE user_id = v_user_id AND is_active = true
  ) INTO v_is_master;

  -- Lookup lead bypassing RLS
  SELECT id, organization_id, deleted_at, deleted_by
    INTO v_lead
    FROM public.leads
    WHERE id = p_lead_id;

  IF NOT FOUND THEN
    status := 'not_found'::public.lead_visibility_status;
    metadata := '{}'::jsonb;
    RETURN NEXT;
    RETURN;
  END IF;

  -- Master sees everything as `exists`; flag cross_org when applicable.
  IF v_is_master THEN
    SELECT EXISTS (
      SELECT 1 FROM public.team_members
      WHERE user_id = v_user_id
        AND organization_id = v_lead.organization_id
        AND is_active = true
    ) INTO v_in_org;

    -- Master sees deleted leads too — flag both in metadata so UI can
    -- show "lead na lixeira" overlay without changing the gate.
    status := 'exists'::public.lead_visibility_status;
    metadata := jsonb_build_object(
      'master', true,
      'cross_org', NOT v_in_org,
      'organization_id', v_lead.organization_id,
      'deleted_at', v_lead.deleted_at,
      'deleted_by', v_lead.deleted_by
    );
    RETURN NEXT;
    RETURN;
  END IF;

  -- Regular user — must share org with the lead.
  SELECT EXISTS (
    SELECT 1 FROM public.team_members
    WHERE user_id = v_user_id
      AND organization_id = v_lead.organization_id
      AND is_active = true
  ) INTO v_in_org;

  IF NOT v_in_org THEN
    -- Don't leak existence of cross-org lead. Permission denied is the
    -- correct response — UI shows "peça acesso ao admin".
    status := 'permission_denied'::public.lead_visibility_status;
    metadata := '{}'::jsonb;
    RETURN NEXT;
    RETURN;
  END IF;

  IF v_lead.deleted_at IS NOT NULL THEN
    status := 'deleted'::public.lead_visibility_status;
    metadata := jsonb_build_object(
      'deleted_at', v_lead.deleted_at,
      'deleted_by', v_lead.deleted_by
    );
    RETURN NEXT;
    RETURN;
  END IF;

  status := 'exists'::public.lead_visibility_status;
  metadata := jsonb_build_object('organization_id', v_lead.organization_id);
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."can_view_lead"("p_lead_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_view_lead"("p_lead_id" "uuid") IS 'Distingue not_found / deleted / permission_denied / exists para o modal de lead. SECURITY DEFINER bypassa RLS. Master vê tudo como exists com cross_org+deleted_at em metadata. PRD #284 Fase 3 error states.';



CREATE OR REPLACE FUNCTION "public"."check_auth_rate_limit"("p_ip" "text", "p_endpoint" "text", "p_max" integer, "p_window" interval) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_ip    text := COALESCE(NULLIF(btrim(p_ip), ''), 'unknown');
  v_count integer;
BEGIN
  INSERT INTO public.auth_rate_limits AS arl (ip, endpoint, window_start, request_count)
  VALUES (v_ip, p_endpoint, now(), 1)
  ON CONFLICT (ip, endpoint) DO UPDATE
    SET
      request_count = CASE
        WHEN arl.window_start < now() - p_window THEN 1
        ELSE arl.request_count + 1
      END,
      window_start = CASE
        WHEN arl.window_start < now() - p_window THEN now()
        ELSE arl.window_start
      END
  RETURNING arl.request_count INTO v_count;

  RETURN v_count <= p_max;
END;
$$;


ALTER FUNCTION "public"."check_auth_rate_limit"("p_ip" "text", "p_endpoint" "text", "p_max" integer, "p_window" interval) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_auth_rate_limit"("p_ip" "text", "p_endpoint" "text", "p_max" integer, "p_window" interval) IS 'Atomic per-(ip,endpoint) fixed-window rate limit. Increments and returns TRUE while within p_max in p_window, FALSE once exceeded. NULL/empty ip is coalesced to a shared "unknown" bucket (never fails open).';



CREATE OR REPLACE FUNCTION "public"."check_cron_job_health"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'cron'
    AS $$
DECLARE
  v_window_minutes  int  := 10;
  v_stale_minutes   int  := 15;
  v_rec             record;
  v_alerts_created  int  := 0;
  v_result          jsonb;
BEGIN
  -- ── 1. Jobs with recent failures ──────────────────────────────────────────
  FOR v_rec IN
    SELECT j.jobname, jrd.status, jrd.return_message, jrd.start_time, jrd.end_time
    FROM cron.job_run_details jrd
    JOIN cron.job j ON j.jobid = jrd.jobid
    WHERE jrd.start_time >= NOW() - (v_window_minutes || ' minutes')::interval
      AND jrd.status NOT IN ('succeeded')
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM public.system_alerts
      WHERE category = 'cron_job_failure'
        AND metadata->>'job_name' = v_rec.jobname
        AND resolved_at IS NULL
        AND created_at >= NOW() - INTERVAL '30 minutes'
    ) THEN
      INSERT INTO public.system_alerts (
        organization_id, severity, category, title, message, metadata
      ) VALUES (
        NULL,
        'critical',
        'cron_job_failure',
        'Cron job falhou: ' || v_rec.jobname,
        'Status: ' || v_rec.status || E'\n' ||
          COALESCE('Mensagem: ' || v_rec.return_message, '') || E'\n' ||
          'Horário: ' || v_rec.start_time::text,
        jsonb_build_object(
          'job_name', v_rec.jobname,
          'status', v_rec.status,
          'return_message', v_rec.return_message,
          'start_time', v_rec.start_time,
          'end_time', v_rec.end_time
        )
      );
      v_alerts_created := v_alerts_created + 1;
    END IF;
  END LOOP;

  -- ── 2. Stale jobs ─────────────────────────────────────────────────────────
  FOR v_rec IN
    SELECT j.jobname, j.schedule, MAX(jrd.start_time) AS last_run
    FROM cron.job j
    LEFT JOIN cron.job_run_details jrd ON jrd.jobid = j.jobid
    WHERE j.active = true
      AND j.schedule IN ('* * * * *', '*/2 * * * *')
    GROUP BY j.jobname, j.schedule
    HAVING MAX(jrd.start_time) < NOW() - (v_stale_minutes || ' minutes')::interval
        OR MAX(jrd.start_time) IS NULL
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM public.system_alerts
      WHERE category = 'cron_job_stale'
        AND metadata->>'job_name' = v_rec.jobname
        AND resolved_at IS NULL
        AND created_at >= NOW() - INTERVAL '30 minutes'
    ) THEN
      INSERT INTO public.system_alerts (
        organization_id, severity, category, title, message, metadata
      ) VALUES (
        NULL,
        'error',
        'cron_job_stale',
        'Cron job parado: ' || v_rec.jobname,
        'Última execução: ' || COALESCE(v_rec.last_run::text, 'nunca') ||
          E'\n' || 'Schedule: ' || v_rec.schedule,
        jsonb_build_object(
          'job_name', v_rec.jobname,
          'schedule', v_rec.schedule,
          'last_run', v_rec.last_run
        )
      );
      v_alerts_created := v_alerts_created + 1;
    END IF;
  END LOOP;

  v_result := jsonb_build_object(
    'checked_at', NOW(),
    'window_minutes', v_window_minutes,
    'alerts_created', v_alerts_created
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."check_cron_job_health"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_cron_job_health"() IS 'Queries cron.job_run_details for failures and stale jobs, inserts system_alerts. Called every 5 min by pg_cron job cron-health-monitor.';



CREATE OR REPLACE FUNCTION "public"."check_oraculo_limit"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_used INTEGER; v_limit INTEGER := 3;
BEGIN
  SELECT COUNT(*) INTO v_used FROM oraculo_usage
  WHERE user_id = p_user_id
    AND created_at >= DATE_TRUNC('day', NOW() AT TIME ZONE 'UTC')
    AND created_at < DATE_TRUNC('day', NOW() AT TIME ZONE 'UTC') + INTERVAL '1 day';
  RETURN jsonb_build_object('used', v_used, 'remaining', GREATEST(v_limit - v_used, 0), 'limit', v_limit);
END; $$;


