CREATE OR REPLACE FUNCTION "public"."check_rate_limit"("p_key" "text", "p_max_requests" integer DEFAULT 100, "p_window_seconds" integer DEFAULT 60) RETURNS TABLE("allowed" boolean, "remaining" integer, "reset_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_window_start TIMESTAMPTZ;
  v_request_count INT;
  v_max_requests INT;
BEGIN
  -- Calculate window start: truncate to minute for 60s windows, sliding for custom
  IF p_window_seconds = 60 THEN
    v_window_start := date_trunc('minute', now());
  ELSE
    v_window_start := now() - (p_window_seconds || ' seconds')::interval;
  END IF;

  -- Upsert: insert new window or increment existing
  INSERT INTO rate_limits (key, window_start, window_seconds, request_count, max_requests)
  VALUES (p_key, v_window_start, p_window_seconds, 1, p_max_requests)
  ON CONFLICT (key, window_start)
  DO UPDATE SET request_count = rate_limits.request_count + 1
  RETURNING rate_limits.request_count, rate_limits.max_requests
  INTO v_request_count, v_max_requests;

  RETURN QUERY
    SELECT
      (v_request_count <= v_max_requests)::BOOLEAN AS allowed,
      GREATEST(v_max_requests - v_request_count, 0)::INT AS remaining,
      (v_window_start + (p_window_seconds || ' seconds')::interval) AS reset_at;
END;
$$;


ALTER FUNCTION "public"."check_rate_limit"("p_key" "text", "p_max_requests" integer, "p_window_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_sla_breaches"() RETURNS TABLE("pipeline_type" "text", "stage_id" "uuid", "stage_name" "text", "sla_hours" integer, "lead_id" "uuid", "lead_name" "text", "hours_in_stage" numeric, "responsible_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    ps.pipeline_type,
    ps.id AS stage_id,
    ps.name AS stage_name,
    ps.sla_hours,
    l.id AS lead_id,
    l.name AS lead_name,
    ROUND(EXTRACT(EPOCH FROM (now() - COALESCE(
      (SELECT MAX(lh.created_at)
       FROM lead_history lh
       WHERE lh.lead_id = l.id
         AND lh.action = 'stage_changed'
         AND lh.metadata->>'to_stage_id' = ps.id::text),
      l.created_at
    ))) / 3600.0, 1)::numeric AS hours_in_stage,
    l.responsible_id
  FROM pipeline_stages ps
  JOIN leads l ON l.organization_id = ps.organization_id
  WHERE ps.sla_hours IS NOT NULL
    AND ps.organization_id IN (
      SELECT tm.organization_id FROM team_members tm WHERE tm.user_id = auth.uid()
    )
    AND l.deleted_at IS NULL;
END;
$$;


