CREATE OR REPLACE FUNCTION "public"."claim_campaign_dispatch_batch"("p_campanha_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 50) RETURNS TABLE("claimed_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH batch AS (
    SELECT id
    FROM public.scheduled_campaign_messages
    WHERE status = 'scheduled'
      AND scheduled_at <= now()
      AND (p_campanha_id IS NULL OR campanha_id = p_campanha_id)
    ORDER BY scheduled_at ASC
    LIMIT p_limit
    FOR UPDATE SKIP LOCKED
  )
  UPDATE public.scheduled_campaign_messages scm
  SET status = 'processing'
  FROM batch
  WHERE scm.id = batch.id
  RETURNING scm.id AS claimed_id;
END;
$$;


