CREATE OR REPLACE FUNCTION "public"."claim_copilot_batch"("p_batch_key" "text", "p_lease_seconds" integer DEFAULT 120) RETURNS SETOF "public"."copilot_message_queue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  UPDATE copilot_message_queue
  SET status = 'processing', claimed_at = now()
  WHERE id IN (
    SELECT id
    FROM copilot_message_queue
    WHERE batch_key = p_batch_key
      AND (
        (status = 'pending'
          AND (next_attempt_at IS NULL OR next_attempt_at <= now()))
        OR
        (status = 'processing'
          AND claimed_at IS NOT NULL
          AND claimed_at < now() - make_interval(secs => p_lease_seconds))
      )
    FOR UPDATE SKIP LOCKED
  )
  RETURNING *;
END;
$$;


