COMMENT ON TABLE "public"."pending_ai_actions" IS 'Fila de ações do Copilot AI. Processada pelo worker process-ai-actions a cada 1 minuto.';



CREATE OR REPLACE FUNCTION "public"."claim_pending_ai_actions"("batch_size" integer DEFAULT 10, "per_org_cap" integer DEFAULT 3) RETURNS SETOF "public"."pending_ai_actions"
    LANGUAGE "sql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
  WITH eligible AS (
    SELECT id, organization_id, created_at,
           ROW_NUMBER() OVER (PARTITION BY organization_id ORDER BY created_at ASC) AS rn_org
    FROM public.pending_ai_actions
    WHERE (status = 'pending' AND (next_retry_at IS NULL OR next_retry_at <= NOW()))
       OR (status = 'processing' AND updated_at < NOW() - INTERVAL '10 minutes')
  ),
  capped AS (
    SELECT id FROM eligible WHERE rn_org <= per_org_cap
  ),
  picked AS (
    SELECT pa.id
    FROM public.pending_ai_actions pa
    WHERE pa.id IN (SELECT id FROM capped)
    ORDER BY pa.created_at ASC
    LIMIT batch_size
    FOR UPDATE SKIP LOCKED
  )
  UPDATE public.pending_ai_actions
  SET status = 'processing', updated_at = NOW()
  WHERE id IN (SELECT id FROM picked)
  RETURNING *;
$$;


