CREATE OR REPLACE FUNCTION "public"."cleanup_copilot_message_queue"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_deleted_queue int;
  v_deleted_locks int;
BEGIN
  DELETE FROM copilot_message_queue
  WHERE status = 'done' AND processed_at < now() - interval '7 days';
  GET DIAGNOSTICS v_deleted_queue = ROW_COUNT;

  DELETE FROM copilot_processing_locks
  WHERE locked_at < now() - interval '24 hours';
  GET DIAGNOSTICS v_deleted_locks = ROW_COUNT;

  IF v_deleted_queue > 0 OR v_deleted_locks > 0 THEN
    RAISE LOG 'copilot_cleanup: queue=% locks=%', v_deleted_queue, v_deleted_locks;
  END IF;
END;
$$;


ALTER FUNCTION "public"."cleanup_copilot_message_queue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_old_logs"("days_to_keep" integer DEFAULT 90) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  deleted_count INTEGER;
BEGIN
  DELETE FROM application_logs
  WHERE created_at < NOW() - (days_to_keep || ' days')::INTERVAL
    AND level != 'audit'; -- Nunca deletar logs de auditoria
  
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


ALTER FUNCTION "public"."cleanup_old_logs"("days_to_keep" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_old_logs"("days_to_keep" integer) IS 'Remove logs antigos (exceto auditoria) para manter performance';



CREATE OR REPLACE FUNCTION "public"."clear_human_pause"("p_conversation_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id   uuid;
  v_lead_id  uuid;
  v_phone    text;
BEGIN
  SELECT organization_id, lead_id
  INTO v_org_id, v_lead_id
  FROM public.conversations
  WHERE id = p_conversation_id;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Conversation not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.team_members
    WHERE user_id = auth.uid()
      AND organization_id = v_org_id
      AND is_active = true
  ) THEN
    RAISE EXCEPTION 'Not a member of this organization';
  END IF;

  UPDATE public.conversations
  SET human_paused_until = NULL,
      updated_at = now()
  WHERE id = p_conversation_id;

  SELECT normalize_brazilian_phone(phone)
  INTO v_phone
  FROM public.leads
  WHERE id = v_lead_id;

  IF v_phone IS NOT NULL AND length(v_phone) > 0 THEN
    UPDATE public.phone_ai_preferences
    SET human_paused_until = NULL,
        updated_at = now()
    WHERE organization_id = v_org_id
      AND normalized_phone = v_phone;
  END IF;
END;
$$;


ALTER FUNCTION "public"."clear_human_pause"("p_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_resolved_support_tickets"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  fechados INTEGER;
BEGIN
  PERFORM set_config('torque.support_clock', 'on', true);

  WITH alvo AS (
    SELECT id FROM public.support_tickets
     WHERE status = 'resolvido'
       AND resolved_at IS NOT NULL
       AND resolved_at < now() - interval '7 days'
     LIMIT 1000
  )
  UPDATE public.support_tickets t
     SET status = 'fechado', closed_at = now()
    FROM alvo
   WHERE t.id = alvo.id;

  GET DIAGNOSTICS fechados = ROW_COUNT;

  PERFORM set_config('torque.support_clock', 'off', true);

  PERFORM public.purge_expired_support_attachments();

  RETURN fechados;
END; $$;


ALTER FUNCTION "public"."close_resolved_support_tickets"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."close_resolved_support_tickets"() IS 'Fecha os chamados resolvidos ha mais de 7 dias e dispara a retencao de anexos. Lotes de 1000. Ver ADR-0018 e ADR-0022.';



