CREATE OR REPLACE FUNCTION "public"."copilot_v2_claim_messages"("p_batch_size" integer DEFAULT 10) RETURNS SETOF "public"."copilot_v2_message_queue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  return query
  update public.copilot_v2_message_queue q
     set status = 'processing', attempts = q.attempts + 1, updated_at = now()
   where q.id in (
     select id from public.copilot_v2_message_queue
      where status = 'pending'
         or (status = 'retry' and (next_retry_at is null or next_retry_at <= now()))
      order by created_at
      for update skip locked
      limit p_batch_size
   )
  returning q.*;
end $$;


