CREATE OR REPLACE FUNCTION "public"."create_lead_with_pipe"("p_name" "text", "p_email" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text", "p_normalized_phone" "text" DEFAULT NULL::"text", "p_company" "text" DEFAULT NULL::"text", "p_origin" "text" DEFAULT 'outro'::"text", "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_sdr_id" "uuid" DEFAULT NULL::"uuid", "p_closer_id" "uuid" DEFAULT NULL::"uuid", "p_rating" integer DEFAULT 0, "p_notes" "text" DEFAULT NULL::"text", "p_segment" "text" DEFAULT NULL::"text", "p_faturamento" "text" DEFAULT NULL::"text", "p_urgency" "text" DEFAULT NULL::"text", "p_responsible_id" "uuid" DEFAULT NULL::"uuid", "p_meeting_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_compromisso_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_utm_source" "text" DEFAULT NULL::"text", "p_utm_medium" "text" DEFAULT NULL::"text", "p_utm_campaign" "text" DEFAULT NULL::"text", "p_utm_term" "text" DEFAULT NULL::"text", "p_utm_content" "text" DEFAULT NULL::"text", "p_pipe_type" "text" DEFAULT NULL::"text", "p_pipe_status" "text" DEFAULT NULL::"text", "p_pipe_meeting_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_meet_link" "text" DEFAULT NULL::"text", "p_pipe_responsible_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lead_id UUID;
  v_pipe_id UUID;
  v_result JSONB;
BEGIN
  PERFORM public.assert_org_access(p_organization_id);
  -- Insert lead
  INSERT INTO public.leads (
    name, email, phone, normalized_phone, company, origin,
    organization_id, sdr_id, closer_id, rating, notes,
    segment, faturamento, urgency, responsible_id,
    meeting_date, compromisso_date,
    utm_source, utm_medium, utm_campaign, utm_term, utm_content
  ) VALUES (
    p_name, p_email, p_phone, p_normalized_phone, p_company, p_origin,
    p_organization_id, p_sdr_id, p_closer_id, p_rating, p_notes,
    p_segment, p_faturamento, p_urgency, p_responsible_id,
    p_meeting_date, p_compromisso_date,
    p_utm_source, p_utm_medium, p_utm_campaign, p_utm_term, p_utm_content
  )
  RETURNING id INTO v_lead_id;

  v_result := jsonb_build_object('lead_id', v_lead_id, 'pipe_id', NULL, 'pipe_type', p_pipe_type);

  -- Insert pipe entry if requested
  IF p_pipe_type = 'whatsapp' THEN
    INSERT INTO public.pipe_whatsapp (
      lead_id, organization_id, status, responsible_id, sdr_id
    ) VALUES (
      v_lead_id, p_organization_id,
      COALESCE(p_pipe_status, 'novo'),
      p_pipe_responsible_id,
      p_sdr_id
    )
    RETURNING id INTO v_pipe_id;
    v_result := v_result || jsonb_build_object('pipe_id', v_pipe_id);

  ELSIF p_pipe_type = 'confirmacao' THEN
    INSERT INTO public.pipe_confirmacao (
      lead_id, organization_id, status, meeting_date,
      meet_link, sdr_id, closer_id, responsible_id
    ) VALUES (
      v_lead_id, p_organization_id,
      COALESCE(p_pipe_status, 'reuniao_marcada'),
      p_pipe_meeting_date, p_meet_link,
      p_sdr_id, p_closer_id,
      COALESCE(p_pipe_responsible_id, p_sdr_id, p_closer_id)
    )
    RETURNING id INTO v_pipe_id;
    v_result := v_result || jsonb_build_object('pipe_id', v_pipe_id);
  END IF;

  RETURN v_result;
END;
$$;


