CREATE OR REPLACE FUNCTION "public"."distribute_campaign_round_robin"("p_campaign_id" "uuid", "p_member_ids" "uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_last_assigned UUID;
  v_last_idx      INT;
  v_arr_len       INT;
BEGIN
  -- Serialize concurrent callers for the same campaign.
  PERFORM pg_advisory_xact_lock(hashtext('camp_dist:' || p_campaign_id::text));

  v_arr_len := array_length(p_member_ids, 1);
  IF v_arr_len IS NULL OR v_arr_len = 0 THEN
    RETURN NULL;
  END IF;

  -- Find who was last assigned in this campaign (most recent campanha_leads).
  SELECT cl.responsible_id INTO v_last_assigned
  FROM public.campanha_leads cl
  WHERE cl.campanha_id = p_campaign_id
    AND cl.responsible_id = ANY(p_member_ids)
  ORDER BY cl.created_at DESC
  LIMIT 1;

  -- No previous assignment → pick first member.
  IF v_last_assigned IS NULL THEN
    RETURN p_member_ids[1];
  END IF;

  -- Find position of last assigned member in the array.
  v_last_idx := NULL;
  FOR i IN 1..v_arr_len LOOP
    IF p_member_ids[i] = v_last_assigned THEN
      v_last_idx := i;
      EXIT;
    END IF;
  END LOOP;

  -- If last assigned member is no longer in the pool, start from first.
  IF v_last_idx IS NULL THEN
    RETURN p_member_ids[1];
  END IF;

  -- Next in rotation (wrap around to 1 if at end).
  IF v_last_idx >= v_arr_len THEN
    RETURN p_member_ids[1];
  ELSE
    RETURN p_member_ids[v_last_idx + 1];
  END IF;
END;
$$;


ALTER FUNCTION "public"."distribute_campaign_round_robin"("p_campaign_id" "uuid", "p_member_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."distribute_campaign_round_robin"("p_campaign_id" "uuid", "p_member_ids" "uuid"[]) IS 'Sequential round-robin for campaigns. Finds last assigned member and picks the next in rotation order. Serialized by advisory lock.';



CREATE OR REPLACE FUNCTION "public"."distribute_pipe_round_robin"("p_pipe_type" "text", "p_organization_id" "uuid", "p_member_ids" "uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_last_assigned UUID;
  v_last_idx      INT;
  v_arr_len       INT;
BEGIN
  -- Serialize concurrent callers for the same pipe + org.
  PERFORM pg_advisory_xact_lock(
    hashtext('pipe_dist:' || p_pipe_type || ':' || p_organization_id::text)
  );

  v_arr_len := array_length(p_member_ids, 1);
  IF v_arr_len IS NULL OR v_arr_len = 0 THEN
    RETURN NULL;
  END IF;

  -- Find who was last assigned in this pipe (most recent record by created_at).
  -- Unified query: pipeline_entries JOIN pipelines by slug.
  SELECT COALESCE((pe.metadata->>'responsible_id')::uuid, pe.assigned_to) INTO v_last_assigned
  FROM public.pipeline_entries pe
  JOIN public.pipelines pip ON pip.id = pe.pipeline_id AND pip.slug = p_pipe_type AND pip.type = 'system'
  WHERE pe.organization_id = p_organization_id
    AND COALESCE((pe.metadata->>'responsible_id')::uuid, pe.assigned_to) = ANY(p_member_ids)
  ORDER BY pe.created_at DESC
  LIMIT 1;

  -- No previous assignment -> pick first member.
  IF v_last_assigned IS NULL THEN
    RETURN p_member_ids[1];
  END IF;

  -- Find position of last assigned member in the array.
  v_last_idx := NULL;
  FOR i IN 1..v_arr_len LOOP
    IF p_member_ids[i] = v_last_assigned THEN
      v_last_idx := i;
      EXIT;
    END IF;
  END LOOP;

  -- If last assigned member is no longer in the pool, start from first.
  IF v_last_idx IS NULL THEN
    RETURN p_member_ids[1];
  END IF;

  -- Next in rotation (wrap around to 1 if at end).
  IF v_last_idx >= v_arr_len THEN
    RETURN p_member_ids[1];
  ELSE
    RETURN p_member_ids[v_last_idx + 1];
  END IF;
END;
$$;


ALTER FUNCTION "public"."distribute_pipe_round_robin"("p_pipe_type" "text", "p_organization_id" "uuid", "p_member_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."distribute_pipe_round_robin"("p_pipe_type" "text", "p_organization_id" "uuid", "p_member_ids" "uuid"[]) IS 'Sequential round-robin for pipes via pipeline_entries. Finds last assigned member and picks the next in rotation order. Serialized by advisory lock.';



CREATE OR REPLACE FUNCTION "public"."enforce_ai_state_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_allowed BOOLEAN;
  v_bypass TEXT;
BEGIN
  -- Bypass via custom GUC (set por sync trigger ou contextos privilegiados)
  v_bypass := current_setting('app.bypass_ai_state_enforce', true);
  IF v_bypass = 'true' THEN
    -- Atualiza timestamp mesmo no bypass (consistência)
    NEW.ai_state_updated_at := now();
    RETURN NEW;
  END IF;

  -- Skip se ai_state não mudou
  IF OLD.ai_state IS NOT DISTINCT FROM NEW.ai_state THEN
    RETURN NEW;
  END IF;

  v_allowed := (OLD.ai_state::TEXT, NEW.ai_state::TEXT) IN (
    ('AI_ACTIVE',        'AI_PAUSED_MANUAL'),
    ('AI_ACTIVE',        'WAITING_HUMAN'),
    ('AI_PAUSED_MANUAL', 'AI_ACTIVE'),
    ('AI_PAUSED_MANUAL', 'HUMAN_ACTIVE'),
    ('WAITING_HUMAN',    'HUMAN_ACTIVE'),
    ('WAITING_HUMAN',    'AI_ACTIVE'),
    ('HUMAN_ACTIVE',     'HANDOFF_BACK'),
    ('HUMAN_ACTIVE',     'AI_PAUSED_MANUAL'),
    ('HANDOFF_BACK',     'AI_ACTIVE')
  );

  IF NOT v_allowed THEN
    RAISE EXCEPTION
      'ai_state transition not allowed: % -> %. Valid transitions defined in enforce_ai_state_transition().',
      OLD.ai_state, NEW.ai_state;
  END IF;

  NEW.ai_state_updated_at := now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_ai_state_transition"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_ai_state_transition"() IS 'Valida transições FSM ai_state. Bypass via SET LOCAL app.bypass_ai_state_enforce = ''true'' (usado por sync_ai_state_from_preferences). Hotfix 2026-04-26.';



CREATE OR REPLACE FUNCTION "public"."enforce_closed_at_on_final_stage"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.stage_key IN ('vendido', 'perdido') AND NEW.closed_at IS NULL THEN
    NEW.closed_at := NOW();
  END IF;
  IF NEW.stage_key NOT IN ('vendido', 'perdido')
     AND OLD IS NOT NULL
     AND OLD.stage_key IN ('vendido', 'perdido') THEN
    NEW.closed_at := NULL;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_closed_at_on_final_stage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_copilot_agent_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_quota JSONB;
BEGIN
  -- Lock org row to serialize concurrent inserts
  PERFORM 1 FROM public.organizations WHERE id = NEW.organization_id FOR UPDATE;

  -- Resolve quota (includes current usage count)
  v_quota := public.org_resolve_quota(NEW.organization_id, 'max_copilot_agents');

  -- Enforce: block if not unlimited AND at or over limit
  IF NOT (v_quota->>'is_unlimited')::BOOLEAN
     AND NOT (v_quota->>'can_add')::BOOLEAN
  THEN
    RAISE EXCEPTION 'Limite de agentes Copilot atingido. Uso: %/%. Contrate mais ou contate o administrador.',
      (v_quota->>'current_usage')::INTEGER,
      (v_quota->>'effective_limit')::INTEGER
    USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_copilot_agent_limit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_feature_on_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_feature text := TG_ARGV[0];
BEGIN
  IF NOT public.org_has_feature(NEW.organization_id, v_feature) THEN
    RAISE EXCEPTION 'feature_locked: % indisponível no plano da organização', v_feature
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_feature_on_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_seat_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_quota JSONB;
BEGIN
  -- Masters nunca são bloqueados pelo limite de seats
  IF public.is_master_user(NEW.user_id) THEN
    RETURN NEW;
  END IF;

  -- Só checa quando ativando um membro (is_active false → true) ou criando ativo
  IF NEW.is_active = true AND (TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND OLD.is_active = false)) THEN
    -- Lock na org para serializar ativações concorrentes
    PERFORM 1 FROM public.organizations WHERE id = NEW.organization_id FOR UPDATE;

    -- Unified quota resolution
    v_quota := public.org_resolve_quota(NEW.organization_id, 'max_users');

    IF NOT (v_quota->>'is_unlimited')::BOOLEAN
       AND NOT (v_quota->>'can_add')::BOOLEAN
    THEN
      RAISE EXCEPTION 'Limite de seats atingido. Seats pagos: %, membros ativos: %.',
        (v_quota->>'effective_limit')::INTEGER,
        (v_quota->>'current_usage')::INTEGER
      USING ERRCODE = 'P0001';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_seat_limit"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_seat_limit"() IS 'Trigger que impede ativação de membros além dos seats pagos na org.';



CREATE OR REPLACE FUNCTION "public"."enforce_support_ticket_gestor_author"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.author_gestor_id IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1
        FROM public.gestores g
        JOIN public.gestor_organizations go ON go.gestor_id = g.id
        WHERE g.id = NEW.author_gestor_id
          AND g.user_id = auth.uid()
          AND g.is_active = true
          AND go.organization_id = NEW.organization_id
      ) THEN
        RAISE EXCEPTION 'author_gestor_id deve ser o gestor autenticado, vinculado a organization_id do chamado'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.author_gestor_id IS DISTINCT FROM OLD.author_gestor_id
     AND NEW.author_gestor_id IS NOT NULL THEN
    RAISE EXCEPTION 'o gestor autor de um chamado nao muda'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_support_ticket_gestor_author"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_support_ticket_rate_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  limite   CONSTANT INTEGER := 5;
  abertos  INTEGER;
  mais_antigo TIMESTAMPTZ;
  tz       TEXT;
BEGIN
  IF NEW.author_user_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF public.is_master_user(NEW.author_user_id) THEN
    RETURN NEW;
  END IF;

  SELECT count(*), min(created_at)
    INTO abertos, mais_antigo
    FROM public.support_tickets
   WHERE author_user_id = NEW.author_user_id
     AND created_at > now() - interval '1 hour';

  IF abertos >= limite THEN
    SELECT coalesce(o.timezone, 'America/Sao_Paulo') INTO tz
      FROM public.organizations o WHERE o.id = NEW.organization_id;

    RAISE EXCEPTION 'rate_limit_chamados:%',
      to_char((mais_antigo + interval '1 hour') AT TIME ZONE tz, 'HH24:MI')
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_support_ticket_rate_limit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_support_ticket_write_rules"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  is_staff    BOOLEAN := public.is_master_user();
  is_internal BOOLEAN := public.support_clock_is_internal();
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.severidade IS NOT NULL AND NOT is_staff THEN
      RAISE EXCEPTION 'severidade e definida pelo suporte, nao pelo cliente' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.defect_url IS NOT NULL AND NOT is_staff THEN
      RAISE EXCEPTION 'defect_url e definida pelo suporte' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.support_context IS DISTINCT FROM OLD.support_context THEN
    RAISE EXCEPTION 'support_context e imutavel' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.author_user_id IS DISTINCT FROM OLD.author_user_id
     AND NEW.author_user_id IS NOT NULL THEN
    RAISE EXCEPTION 'o autor de um chamado nao muda' USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
    RAISE EXCEPTION 'o dono de um chamado nao muda' USING ERRCODE = 'check_violation';
  END IF;

  IF NOT is_staff THEN
    IF NEW.severidade IS DISTINCT FROM OLD.severidade THEN
      RAISE EXCEPTION 'severidade e definida pelo suporte, nao pelo cliente' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.tipo IS DISTINCT FROM OLD.tipo THEN
      RAISE EXCEPTION 'a triagem do tipo e do suporte' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.defect_url IS DISTINCT FROM OLD.defect_url THEN
      RAISE EXCEPTION 'defect_url e definida pelo suporte' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.assigned_master_user_id IS DISTINCT FROM OLD.assigned_master_user_id THEN
      RAISE EXCEPTION 'atribuicao e do suporte' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF NOT is_internal THEN
    IF NEW.first_response_at    IS DISTINCT FROM OLD.first_response_at
       OR NEW.resolved_at       IS DISTINCT FROM OLD.resolved_at
       OR NEW.awaiting_since    IS DISTINCT FROM OLD.awaiting_since
       OR NEW.awaiting_customer_ms IS DISTINCT FROM OLD.awaiting_customer_ms
       OR NEW.reopen_count      IS DISTINCT FROM OLD.reopen_count THEN
      RAISE EXCEPTION 'o relogio de um chamado e mantido pelo banco' USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN

    IF OLD.status = 'fechado' THEN
      RAISE EXCEPTION 'chamado fechado e terminal: abra um novo' USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.status = 'fechado' THEN
      IF NOT is_internal THEN
        RAISE EXCEPTION 'o fechamento e automatico, 7 dias apos resolvido' USING ERRCODE = 'check_violation';
      END IF;
      IF OLD.status <> 'resolvido' THEN
        RAISE EXCEPTION 'so um chamado resolvido fecha sozinho' USING ERRCODE = 'check_violation';
      END IF;
    END IF;

    IF NOT is_staff AND NOT is_internal THEN
      IF NOT (OLD.status = 'resolvido' AND NEW.status = 'aberto') THEN
        RAISE EXCEPTION 'o cliente so pode reabrir um chamado resolvido' USING ERRCODE = 'check_violation';
      END IF;
    END IF;

    IF NEW.status = 'aguardando_cliente' THEN
      NEW.awaiting_since := now();
    ELSIF OLD.status = 'aguardando_cliente' AND OLD.awaiting_since IS NOT NULL THEN
      NEW.awaiting_customer_ms :=
        OLD.awaiting_customer_ms
        + (EXTRACT(EPOCH FROM (now() - OLD.awaiting_since)) * 1000)::BIGINT;
      NEW.awaiting_since := NULL;
    END IF;

    IF NEW.status = 'resolvido' AND OLD.status <> 'resolvido' THEN
      NEW.resolved_at := now();
    ELSIF NEW.status = 'aberto' AND OLD.status = 'resolvido' THEN
      NEW.reopen_count := OLD.reopen_count + 1;
      NEW.resolved_at := NULL;
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_support_ticket_write_rules"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_whatsapp_instance_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_quota JSONB;
BEGIN
  -- Lock org row to serialize concurrent inserts
  PERFORM 1 FROM public.organizations WHERE id = NEW.organization_id FOR UPDATE;

  -- Resolve quota (includes current usage count)
  v_quota := public.org_resolve_quota(NEW.organization_id, 'max_whatsapp_instances');

  -- Enforce: block if not unlimited AND at or over limit
  IF NOT (v_quota->>'is_unlimited')::BOOLEAN
     AND NOT (v_quota->>'can_add')::BOOLEAN
  THEN
    RAISE EXCEPTION 'Limite de instâncias WhatsApp atingido. Uso: %/%. Contrate mais ou contate o administrador.',
      (v_quota->>'current_usage')::INTEGER,
      (v_quota->>'effective_limit')::INTEGER
    USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_whatsapp_instance_limit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_acoes_do_dia_webhooks"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  ev TEXT;
  payload JSONB;
  org_id UUID;
BEGIN
  IF NEW.lead_id IS NOT NULL THEN
    org_id := (SELECT organization_id FROM public.leads WHERE id = NEW.lead_id LIMIT 1);
  ELSE
    org_id := (SELECT organization_id FROM public.team_members WHERE user_id = NEW.user_id AND is_active = true LIMIT 1);
  END IF;
  IF org_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    ev := 'acao_dia.created';
  ELSIF TG_OP = 'UPDATE' AND (OLD.is_completed IS DISTINCT FROM NEW.is_completed AND NEW.is_completed = true) THEN
    ev := 'acao_dia.completed';
  ELSE
    RETURN NEW;  /* outros updates não disparam evento */
  END IF;
  payload := jsonb_build_object(
    'event', ev,
    'timestamp', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'data', jsonb_build_object(
      'id', NEW.id,
      'user_id', NEW.user_id,
      'lead_id', NEW.lead_id,
      'title', NEW.title,
      'description', NEW.description,
      'is_completed', NEW.is_completed,
      'completed_at', NEW.completed_at,
      'confirmacao_id', NEW.confirmacao_id,
      'follow_up_id', NEW.follow_up_id,
      'proposta_id', NEW.proposta_id
    )
  );
  PERFORM enqueue_webhook_deliveries_for_org(org_id, ev, payload);
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enqueue_acoes_do_dia_webhooks"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_campaign_dispatch_webhooks"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  ev TEXT;
  payload JSONB;
BEGIN
  IF TG_OP = 'INSERT' THEN
    ev := 'campaign_dispatch.scheduled';
    payload := jsonb_build_object(
      'event', ev,
      'timestamp', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
      'data', jsonb_build_object(
        'id', NEW.id,
        'organization_id', NEW.organization_id,
        'campanha_id', NEW.campanha_id,
        'template_id', NEW.template_id,
        'scheduled_at', NEW.scheduled_at,
        'status', NEW.status
      )
    );
    PERFORM enqueue_webhook_deliveries_for_org(NEW.organization_id, ev, payload);
  ELSIF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status
    AND NEW.status IN ('completed', 'failed', 'cancelled') THEN
    ev := 'campaign_dispatch.completed';
    payload := jsonb_build_object(
      'event', ev,
      'timestamp', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
      'data', jsonb_build_object(
        'id', NEW.id,
        'organization_id', NEW.organization_id,
        'campanha_id', NEW.campanha_id,
        'status', NEW.status,
        'total_leads', NEW.total_leads,
        'sent_count', NEW.sent_count,
        'failed_count', NEW.failed_count
      )
    );
    PERFORM enqueue_webhook_deliveries_for_org(NEW.organization_id, ev, payload);
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enqueue_campaign_dispatch_webhooks"() OWNER TO "postgres";


