CREATE OR REPLACE FUNCTION "public"."export_lead_data"("p_lead_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_org_id uuid;
  v_result jsonb;
BEGIN
  SELECT tm.organization_id INTO v_org_id
  FROM team_members tm WHERE tm.user_id = auth.uid() AND tm.role = 'admin' LIMIT 1;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized: admin role required';
  END IF;

  SELECT jsonb_build_object(
    'lead', row_to_json(l),
    'tags', COALESCE((
      SELECT jsonb_agg(t.name)
      FROM lead_tags lt JOIN tags t ON t.id = lt.tag_id
      WHERE lt.lead_id = p_lead_id
    ), '[]'::jsonb),
    'history', COALESCE((
      SELECT jsonb_agg(row_to_json(lh) ORDER BY lh.created_at)
      FROM lead_history lh WHERE lh.lead_id = p_lead_id
    ), '[]'::jsonb),
    'conversations', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'conversation', row_to_json(c),
        'messages', COALESCE((
          SELECT jsonb_agg(row_to_json(cm) ORDER BY cm.created_at)
          FROM conversation_messages cm WHERE cm.conversation_id = c.id
        ), '[]'::jsonb)
      ))
      FROM conversations c WHERE c.lead_id = p_lead_id
    ), '[]'::jsonb),
    'consents', COALESCE((
      SELECT jsonb_agg(row_to_json(cr))
      FROM consent_records cr WHERE cr.lead_id = p_lead_id
    ), '[]'::jsonb),
    'exported_at', now(),
    'exported_by', auth.uid()
  ) INTO v_result
  FROM leads l
  WHERE l.id = p_lead_id AND l.organization_id = v_org_id;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."export_lead_data"("p_lead_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."find_duplicate_leads"("p_organization_id" "uuid") RETURNS TABLE("lead_a_id" "uuid", "lead_a_name" "text", "lead_a_phone" "text", "lead_a_email" "text", "lead_a_company" "text", "lead_b_id" "uuid", "lead_b_name" "text", "lead_b_phone" "text", "lead_b_email" "text", "lead_b_company" "text", "match_type" "text", "similarity" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  PERFORM public.assert_org_access(p_organization_id);

  RETURN QUERY
  WITH pairs AS (
    SELECT
      a.id AS a_id, a.name AS a_name, a.phone AS a_phone, a.email AS a_email, a.company AS a_company,
      b.id AS b_id, b.name AS b_name, b.phone AS b_phone, b.email AS b_email, b.company AS b_company,
      'phone'::text AS match_type,
      1.0::numeric  AS sim,
      1 AS priority
    FROM public.leads a
    JOIN public.leads b
      ON b.organization_id = a.organization_id
     AND a.id < b.id
     AND a.normalized_phone IS NOT NULL
     AND a.normalized_phone <> ''
     AND a.normalized_phone = b.normalized_phone
     AND b.deleted_at IS NULL
    WHERE a.organization_id = p_organization_id
      AND a.deleted_at IS NULL

    UNION ALL

    SELECT
      a.id, a.name, a.phone, a.email, a.company,
      b.id, b.name, b.phone, b.email, b.company,
      'email'::text, 1.0::numeric, 2
    FROM public.leads a
    JOIN public.leads b
      ON b.organization_id = a.organization_id
     AND a.id < b.id
     AND a.email IS NOT NULL
     AND a.email <> ''
     AND lower(a.email) = lower(b.email)
     AND b.deleted_at IS NULL
    WHERE a.organization_id = p_organization_id
      AND a.deleted_at IS NULL

    UNION ALL

    SELECT
      a.id, a.name, a.phone, a.email, a.company,
      b.id, b.name, b.phone, b.email, b.company,
      'name'::text,
      round(similarity(a.name, b.name)::numeric, 2),
      3
    FROM public.leads a
    JOIN public.leads b
      ON b.organization_id = a.organization_id
     AND a.id < b.id
     AND a.name % b.name
     AND similarity(a.name, b.name) >= 0.6
     AND b.deleted_at IS NULL
     AND length(btrim(b.name)) >= 4
    WHERE a.organization_id = p_organization_id
      AND a.deleted_at IS NULL
      AND a.name IS NOT NULL
      AND length(btrim(a.name)) >= 4
  )
  SELECT DISTINCT ON (p.a_id, p.b_id)
    p.a_id, p.a_name, p.a_phone, p.a_email, p.a_company,
    p.b_id, p.b_name, p.b_phone, p.b_email, p.b_company,
    p.match_type, p.sim
  FROM pairs p
  ORDER BY p.a_id, p.b_id, p.priority ASC;
END;
$$;


ALTER FUNCTION "public"."find_duplicate_leads"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."find_leads_no_reply"("p_organization_id" "uuid", "p_cutoff" timestamp with time zone, "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT DISTINCT l.id
  FROM public.leads l
  JOIN public.conversations c ON c.lead_id = l.id
  WHERE l.organization_id = p_organization_id
    AND c.last_message_at < p_cutoff
    AND c.last_message_at IS NOT NULL
    AND (l.ai_disabled IS NULL OR l.ai_disabled = false)
    AND NOT EXISTS (
      SELECT 1 FROM public.whatsapp_messages wm
      WHERE wm.lead_id = l.id
        AND wm.direction = 'incoming'
        AND wm.created_at > p_cutoff
    )
  ORDER BY l.id
  LIMIT p_limit;
$$;


ALTER FUNCTION "public"."find_leads_no_reply"("p_organization_id" "uuid", "p_cutoff" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fire_workflow_trigger"("p_organization_id" "uuid", "p_trigger_type" "text", "p_lead_id" "uuid", "p_context" "jsonb" DEFAULT '{}'::"jsonb", "p_triggered_by_execution_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_workflow RECORD;
  v_count INT := 0;
  v_parent_depth SMALLINT := 0;
  v_new_depth SMALLINT;
  v_window INT;
  v_dedup_key TEXT;
  v_inserted uuid;
  MAX_CHAIN_DEPTH CONSTANT SMALLINT := 5;
BEGIN
  IF p_triggered_by_execution_id IS NOT NULL THEN
    SELECT chain_depth INTO v_parent_depth
    FROM public.workflow_executions
    WHERE id = p_triggered_by_execution_id;
    v_parent_depth := COALESCE(v_parent_depth, 0);
  END IF;

  v_new_depth := v_parent_depth + 1;

  IF v_new_depth > MAX_CHAIN_DEPTH THEN
    RAISE NOTICE 'fire_workflow_trigger blocked: chain_depth % > %',
      v_new_depth, MAX_CHAIN_DEPTH;
    RETURN 0;
  END IF;

  -- 300s dedup window for stage_changed (re-dispatching the same lead within
  -- 5min is never intended); 60s for everything else.
  v_window := CASE WHEN p_trigger_type = 'stage_changed' THEN 300 ELSE 60 END;
  v_dedup_key := p_trigger_type
    || ':' || substr(md5(COALESCE(p_context, '{}'::jsonb)::text), 1, 16)
    || ':' || floor(extract(epoch FROM now()) / v_window)::text;

  FOR v_workflow IN
    SELECT id, trigger_config
    FROM public.workflows
    WHERE organization_id = p_organization_id
      AND trigger_type = p_trigger_type
      AND is_active = true
  LOOP
    IF NOT matches_workflow_trigger_config(p_trigger_type, v_workflow.trigger_config, p_context) THEN
      CONTINUE;
    END IF;

    INSERT INTO public.workflow_executions (
      workflow_id, organization_id, lead_id, status, context,
      triggered_by_execution_id, chain_depth, trigger_dedup_key
    ) VALUES (
      v_workflow.id, p_organization_id, p_lead_id, 'running',
      p_context || jsonb_build_object(
        'trigger_type', p_trigger_type,
        'trigger_config', v_workflow.trigger_config
      ),
      p_triggered_by_execution_id, v_new_depth, v_dedup_key
    )
    ON CONFLICT (workflow_id, lead_id, trigger_dedup_key) DO NOTHING
    RETURNING id INTO v_inserted;

    IF v_inserted IS NOT NULL THEN
      v_count := v_count + 1;
      v_inserted := NULL;
    END IF;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."fire_workflow_trigger"("p_organization_id" "uuid", "p_trigger_type" "text", "p_lead_id" "uuid", "p_context" "jsonb", "p_triggered_by_execution_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fire_workflow_trigger"("p_organization_id" "uuid", "p_trigger_type" "text", "p_lead_id" "uuid", "p_context" "jsonb", "p_triggered_by_execution_id" "uuid") IS 'Canonical trigger RPC: chain_depth guard (max 5) + trigger_config in context. p_triggered_by_execution_id defaults NULL for retrocompat with PG triggers that call with 4 args. Consolidated 2026-05-12.';



CREATE OR REPLACE FUNCTION "public"."fn_auto_assign_lead_default_pipe"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_pipeline_id uuid;
  v_stage_exists boolean;
BEGIN
  -- (0) Cal.com: lead já entra em confirmacao (reunião agendada) — nunca semear whatsapp/novo.
  IF NEW.origin = 'cal' THEN
    RETURN NULL;
  END IF;

  -- (1) já está em pipeline_entries? skip
  IF EXISTS (
    SELECT 1 FROM public.pipeline_entries
    WHERE lead_id = NEW.id
    LIMIT 1
  ) THEN
    RETURN NULL;
  END IF;

  -- (2) já está em custom_pipe_entries? skip
  IF EXISTS (
    SELECT 1 FROM public.custom_pipe_entries
    WHERE lead_id = NEW.id
    LIMIT 1
  ) THEN
    RETURN NULL;
  END IF;

  -- (3) org tem pipeline system whatsapp ativo?
  SELECT id
    INTO v_pipeline_id
  FROM public.pipelines
  WHERE organization_id = NEW.organization_id
    AND type = 'system'
    AND slug = 'whatsapp'
    AND is_active = true
  LIMIT 1;

  IF v_pipeline_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- (4) stage 'novo' existe e está ativo nesse pipeline?
  SELECT EXISTS (
    SELECT 1 FROM public.pipeline_stages
    WHERE organization_id = NEW.organization_id
      AND pipeline_type = 'whatsapp'
      AND stage_key = 'novo'
      AND is_active = true
  ) INTO v_stage_exists;

  IF NOT v_stage_exists THEN
    RETURN NULL;
  END IF;

  -- (5) cria entry whatsapp/novo
  INSERT INTO public.pipeline_entries (
    organization_id,
    pipeline_id,
    lead_id,
    stage_key,
    entered_at,
    stage_changed_at
  ) VALUES (
    NEW.organization_id,
    v_pipeline_id,
    NEW.id,
    'novo',
    NOW(),
    NOW()
  );

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_auto_assign_lead_default_pipe"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_auto_assign_lead_default_pipe"() IS 'Fallback que coloca lead órfão em whatsapp/novo no COMMIT da transação. Acionado por trg_auto_assign_lead_default_pipe (CONSTRAINT TRIGGER DEFERRABLE INITIALLY DEFERRED). Multi-tenancy: usa NEW.organization_id exclusivamente, jamais cruza orgs.';



CREATE OR REPLACE FUNCTION "public"."fn_backfill_parse_sale_value"("p_raw" "text") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE v numeric;
BEGIN
  v := NULLIF(p_raw, '')::numeric;
  IF v IS NULL OR v < 0 THEN RETURN NULL; END IF;
  RETURN v;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_backfill_parse_sale_value"("p_raw" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_backfill_parse_sale_value"("p_raw" "text") IS 'U2 / ADR-0017 §7 — parse honesto de metadata->>sale_value: ausente/vazio/malformado/negativo → NULL (nunca 0).';



CREATE OR REPLACE FUNCTION "public"."fn_backfill_state_sales"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE v_inserted integer;
BEGIN
  INSERT INTO public.sale_events
    (organization_id, lead_id, pipeline_id, stage_key, stage_event_id, event_type, reversed_event_id, sold_at, sale_value, currency, revenue_stream, sale_responsible_id, pre_sale_responsible_id, actor, source)
  SELECT
    pe.organization_id, pe.lead_id, pe.pipeline_id, pe.stage_key, se.id,
    CASE WHEN public.metric_stage_role(pe.organization_id, pe.pipeline_id, pe.stage_key) = 'won' THEN 'sale' ELSE 'sale_lost' END,
    NULL,
    COALESCE(pe.stage_changed_at, pe.entered_at, pe.created_at),
    public.fn_backfill_parse_sale_value(pe.metadata->>'sale_value'),
    CASE WHEN COALESCE(upper(pe.metadata->>'currency'), '') ~ '^[A-Z]{3}$' THEN upper(pe.metadata->>'currency') ELSE 'BRL' END,
    CASE WHEN EXISTS (SELECT 1 FROM public.upsell_clients uc WHERE uc.organization_id = pe.organization_id AND uc.lead_id = pe.lead_id AND uc.is_active) THEN 'carteira' ELSE 'novo_negocio' END,
    COALESCE(l.sale_responsible_id, l.closer_id),
    l.pre_sale_responsible_id, NULL, 'backfill'
  FROM public.pipeline_entries pe
  JOIN public.leads l ON l.id = pe.lead_id AND l.organization_id = pe.organization_id
  LEFT JOIN LATERAL (
    SELECT e.id FROM public.pipeline_stage_events e
    WHERE e.lead_id = pe.lead_id AND e.pipeline_id = pe.pipeline_id
    ORDER BY e.occurred_at DESC, e.created_at DESC LIMIT 1
  ) se ON true
  WHERE pe.lead_id IS NOT NULL
    AND public.metric_stage_role(pe.organization_id, pe.pipeline_id, pe.stage_key) IN ('won', 'lost')
    AND NOT EXISTS (
      SELECT 1 FROM public.sale_events s
      WHERE s.lead_id = pe.lead_id AND s.pipeline_id = pe.pipeline_id AND s.event_type IN ('sale', 'sale_lost')
        AND NOT EXISTS (SELECT 1 FROM public.sale_events r WHERE r.event_type = 'sale_reversed' AND r.reversed_event_id = s.id)
    );
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  RETURN v_inserted;
END;
$_$;


ALTER FUNCTION "public"."fn_backfill_state_sales"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_backfill_state_sales"() IS 'U2 / ADR-0017 §7 — backfill governado de venda por estado atual. 1 sale/sale_lost por entry viva parada em won/lost, ancorado no stage_changed_at real. Idempotente. Re-executável por ops.';



CREATE OR REPLACE FUNCTION "public"."fn_call_log_to_history"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.lead_id IS NOT NULL THEN
    INSERT INTO lead_history (lead_id, organization_id, action, description, source, metadata, created_by)
    VALUES (
      NEW.lead_id,
      NEW.organization_id,
      'call_logged',
      CASE NEW.direction
        WHEN 'outbound' THEN 'Ligação realizada'
        ELSE 'Ligação recebida'
      END || ' — ' || NEW.outcome,
      'manual',
      jsonb_build_object(
        'direction', NEW.direction,
        'outcome', NEW.outcome,
        'duration_seconds', NEW.duration_seconds,
        'phone_number', NEW.phone_number
      ),
      NEW.user_id
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_call_log_to_history"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_capture_meeting_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_slug text;
  v_meeting_date timestamptz;
  v_presale uuid;
  v_prev public.meeting_events%ROWTYPE;
  v_prev_open boolean;
  v_entering_booked boolean := false;
  v_booked_id uuid;
BEGIN
  SELECT p.slug INTO v_slug FROM public.pipelines p WHERE p.id = NEW.pipeline_id;

  v_meeting_date := NULLIF(NEW.metadata->>'meeting_date', '')::timestamptz;

  SELECT COALESCE(
    NULLIF(NEW.metadata->>'pre_sale_responsible_id', '')::uuid,
    l.pre_sale_responsible_id,
    NULLIF(NEW.metadata->>'sdr_id', '')::uuid,
    l.sdr_id
  ) INTO v_presale
  FROM public.leads l WHERE l.id = NEW.lead_id;

  SELECT * INTO v_prev FROM public.meeting_events me
  WHERE me.lead_id = NEW.lead_id
    AND me.organization_id = NEW.organization_id
    AND me.event_type = 'meeting_booked'
  ORDER BY me.occurred_at DESC
  LIMIT 1;

  v_prev_open := v_prev.id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.meeting_events h
    WHERE h.event_type = 'meeting_held' AND h.booked_event_id = v_prev.id
  );

  -- BOOKED ──────────────────────────────────────────────────────────────────
  IF (v_slug = 'confirmacao' AND TG_OP = 'INSERT')
     OR (NEW.stage_key = 'agendado' AND (TG_OP = 'INSERT' OR OLD.stage_key IS DISTINCT FROM NEW.stage_key)) THEN
    v_entering_booked := true;
  END IF;

  IF v_entering_booked THEN
    IF v_prev_open AND (
         v_meeting_date IS NULL OR v_prev.meeting_date IS NULL
         OR abs(EXTRACT(EPOCH FROM (v_meeting_date - v_prev.meeting_date))) <= 30 * 86400
       ) THEN
      -- reschedule of the same meeting: update date, do not count again
      UPDATE public.meeting_events
      SET meeting_date = COALESCE(v_meeting_date, meeting_date),
          metadata = metadata || jsonb_build_object('last_reschedule_at', now(), 'last_source_entry_id', NEW.id)
      WHERE id = v_prev.id;
    ELSE
      INSERT INTO public.meeting_events
        (organization_id, lead_id, event_type, pre_sale_responsible_id, meeting_date, occurred_at, source, source_entry_id)
      VALUES
        (NEW.organization_id, NEW.lead_id, 'meeting_booked', v_presale, v_meeting_date, now(),
         'pipeline:' || COALESCE(v_slug, '?'), NEW.id);
    END IF;
  END IF;

  -- RESCHEDULE without stage change (meeting_date edited in place) ──────────
  IF TG_OP = 'UPDATE'
     AND NEW.stage_key = OLD.stage_key
     AND (OLD.metadata->>'meeting_date') IS DISTINCT FROM (NEW.metadata->>'meeting_date')
     AND v_meeting_date IS NOT NULL
     AND v_prev_open THEN
    IF v_prev.meeting_date IS NOT NULL
       AND abs(EXTRACT(EPOCH FROM (v_meeting_date - v_prev.meeting_date))) > 30 * 86400 THEN
      INSERT INTO public.meeting_events
        (organization_id, lead_id, event_type, pre_sale_responsible_id, meeting_date, occurred_at, source, source_entry_id)
      VALUES
        (NEW.organization_id, NEW.lead_id, 'meeting_booked', v_presale, v_meeting_date, now(),
         'pipeline:' || COALESCE(v_slug, '?') || ':reschedule', NEW.id);
    ELSE
      UPDATE public.meeting_events
      SET meeting_date = v_meeting_date,
          metadata = metadata || jsonb_build_object('last_reschedule_at', now())
      WHERE id = v_prev.id;
    END IF;
  END IF;

  -- HELD ────────────────────────────────────────────────────────────────────
  IF NEW.stage_key = 'compareceu'
     AND (TG_OP = 'INSERT' OR OLD.stage_key IS DISTINCT FROM NEW.stage_key) THEN
    v_booked_id := v_prev.id;
    IF v_booked_id IS NULL THEN
      -- held without a recorded booking: create the implicit booked event first
      INSERT INTO public.meeting_events
        (organization_id, lead_id, event_type, pre_sale_responsible_id, meeting_date, occurred_at, source, source_entry_id)
      VALUES
        (NEW.organization_id, NEW.lead_id, 'meeting_booked', v_presale, v_meeting_date, now(),
         'pipeline:' || COALESCE(v_slug, '?') || ':implicit', NEW.id)
      RETURNING id INTO v_booked_id;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM public.meeting_events h
      WHERE h.event_type = 'meeting_held' AND h.booked_event_id = v_booked_id
    ) THEN
      INSERT INTO public.meeting_events
        (organization_id, lead_id, event_type, booked_event_id, pre_sale_responsible_id, meeting_date, occurred_at, source, source_entry_id)
      VALUES
        (NEW.organization_id, NEW.lead_id, 'meeting_held', v_booked_id,
         COALESCE(v_prev.pre_sale_responsible_id, v_presale),
         COALESCE(v_meeting_date, v_prev.meeting_date), now(),
         'pipeline:' || COALESCE(v_slug, '?'), NEW.id);
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_capture_meeting_event"() OWNER TO "postgres";


