CREATE OR REPLACE FUNCTION "public"."fn_capture_sale_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_from_role public.stage_role; v_to_role public.stage_role;
  v_meta jsonb; v_sale_value numeric; v_currency text;
  v_sale_resp uuid; v_pre_resp uuid; v_stream text; v_original public.sale_events%ROWTYPE;
BEGIN
  v_from_role := public.metric_stage_role(NEW.organization_id, NEW.pipeline_id, NEW.from_stage_key);
  v_to_role := public.metric_stage_role(NEW.organization_id, NEW.pipeline_id, NEW.to_stage_key);
  IF v_from_role IS DISTINCT FROM 'won' AND v_to_role IS DISTINCT FROM 'won' AND v_to_role IS DISTINCT FROM 'lost' THEN
    RETURN NEW;
  END IF;
  IF v_from_role = 'won' AND v_to_role IS DISTINCT FROM 'won' THEN
    SELECT s.* INTO v_original FROM public.sale_events s
    WHERE s.lead_id = NEW.lead_id AND s.pipeline_id = NEW.pipeline_id AND s.event_type = 'sale'
      AND NOT EXISTS (SELECT 1 FROM public.sale_events r WHERE r.event_type = 'sale_reversed' AND r.reversed_event_id = s.id)
    ORDER BY s.sold_at DESC, s.created_at DESC LIMIT 1;
    IF FOUND THEN
      INSERT INTO public.sale_events
        (organization_id, lead_id, pipeline_id, stage_key, stage_event_id, event_type, reversed_event_id, sold_at, sale_value, currency, revenue_stream, sale_responsible_id, pre_sale_responsible_id, actor, source)
      VALUES
        (NEW.organization_id, NEW.lead_id, NEW.pipeline_id, NEW.to_stage_key, NEW.id, 'sale_reversed', v_original.id, now(),
         v_original.sale_value, v_original.currency, v_original.revenue_stream, v_original.sale_responsible_id, v_original.pre_sale_responsible_id, NEW.actor, 'trigger');
    END IF;
  END IF;
  IF (v_to_role = 'won' AND v_from_role IS DISTINCT FROM 'won') OR (v_to_role = 'lost' AND v_from_role IS DISTINCT FROM 'lost') THEN
    SELECT pe.metadata INTO v_meta FROM public.pipeline_entries pe WHERE pe.id = NEW.entry_id;
    BEGIN
      v_sale_value := NULLIF(v_meta->>'sale_value', '')::numeric;
    EXCEPTION WHEN OTHERS THEN v_sale_value := NULL;
    END;
    v_currency := COALESCE(NULLIF(upper(v_meta->>'currency'), ''), 'BRL');
    IF v_currency !~ '^[A-Z]{3}$' THEN v_currency := 'BRL'; END IF;
    SELECT COALESCE(l.sale_responsible_id, l.closer_id), l.pre_sale_responsible_id
      INTO v_sale_resp, v_pre_resp
    FROM public.leads l WHERE l.id = NEW.lead_id AND l.organization_id = NEW.organization_id;
    v_stream := CASE WHEN EXISTS (
        SELECT 1 FROM public.upsell_clients uc WHERE uc.organization_id = NEW.organization_id AND uc.lead_id = NEW.lead_id AND uc.is_active
      ) THEN 'carteira' ELSE 'novo_negocio' END;
    INSERT INTO public.sale_events
      (organization_id, lead_id, pipeline_id, stage_key, stage_event_id, event_type, reversed_event_id, sold_at, sale_value, currency, revenue_stream, sale_responsible_id, pre_sale_responsible_id, actor, source)
    VALUES
      (NEW.organization_id, NEW.lead_id, NEW.pipeline_id, NEW.to_stage_key, NEW.id,
       CASE WHEN v_to_role = 'won' THEN 'sale' ELSE 'sale_lost' END,
       NULL, now(), v_sale_value, v_currency, v_stream, v_sale_resp, v_pre_resp, NEW.actor, 'trigger');
  END IF;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."fn_capture_sale_event"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_capture_sale_event"() IS 'ADR-0017 §2-4 / #993 — deriva sale/sale_lost/sale_reversed de cada evento ao vivo do caderno de etapa.';



CREATE OR REPLACE FUNCTION "public"."fn_deal_won_populate_lead_products"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.won = true AND (OLD.won IS DISTINCT FROM true) AND NEW.source_lead_id IS NOT NULL THEN
    INSERT INTO public.lead_products (
      lead_id, product_id, organization_id,
      source, source_deal_id,
      quantity_total, revenue_total,
      first_purchased_at, last_purchased_at,
      purchase_count, status
    )
    SELECT
      NEW.source_lead_id,
      di.product_id,
      NEW.organization_id,
      'deal',
      NEW.id,
      di.quantity,
      di.total,
      COALESCE(NEW.closed_at, now()),
      COALESCE(NEW.closed_at, now()),
      1,
      'active'
    FROM public.deal_items di
    WHERE di.deal_id = NEW.id
      AND di.product_id IS NOT NULL
    ON CONFLICT (lead_id, product_id, organization_id)
    DO UPDATE SET
      source = 'deal',
      source_deal_id = NEW.id,
      quantity_total = lead_products.quantity_total + EXCLUDED.quantity_total,
      revenue_total = lead_products.revenue_total + EXCLUDED.revenue_total,
      last_purchased_at = EXCLUDED.last_purchased_at,
      purchase_count = lead_products.purchase_count + 1,
      avg_cycle_days = CASE
        WHEN lead_products.purchase_count >= 1
          AND lead_products.first_purchased_at IS NOT NULL
        THEN EXTRACT(EPOCH FROM (EXCLUDED.last_purchased_at - lead_products.first_purchased_at))::integer
             / 86400
             / (lead_products.purchase_count + 1)
        ELSE NULL
      END,
      status = 'active',
      updated_at = now();
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_deal_won_populate_lead_products"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_email_to_history"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_action text;
  v_description text;
  v_preview text;
BEGIN
  IF NEW.lead_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.lead_history
    WHERE lead_id = NEW.lead_id
      AND metadata->>'channel' = 'email'
      AND metadata->>'message_id' = NEW.message_id
  ) THEN
    RETURN NEW;
  END IF;

  v_action := CASE WHEN NEW.is_outbound THEN 'email_sent' ELSE 'email_received' END;
  v_preview := COALESCE(NEW.subject, substring(COALESCE(NEW.snippet, NEW.body_text, '') from 1 for 80), '');
  v_description := CASE WHEN NEW.is_outbound THEN 'Email enviado' ELSE 'Email recebido' END
    || CASE WHEN length(v_preview) > 0 THEN ': ' || v_preview ELSE '' END;

  INSERT INTO public.lead_history (
    lead_id, organization_id, action, description, source, metadata, created_at
  )
  VALUES (
    NEW.lead_id,
    NEW.organization_id,
    v_action,
    v_description,
    'system',
    jsonb_build_object(
      'channel', 'email',
      'message_id', NEW.message_id,
      'direction', CASE WHEN NEW.is_outbound THEN 'sent' ELSE 'received' END,
      'thread_id', NEW.thread_id,
      'from_address', NEW.from_address,
      'subject', NEW.subject,
      'email_account_id', NEW.email_account_id
    ),
    COALESCE(NEW.sent_at, NEW.created_at, now())
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_email_to_history"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_email_to_history"() IS 'PRD #284 F5.2 — espelha emails pra lead_history. Idempotente via message_id em metadata.';



CREATE OR REPLACE FUNCTION "public"."fn_funnel_flow_step"("p_role" "text", "p_reached" integer, "p_cohort_size" integer, "p_prev" integer) RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT jsonb_build_object(
    'role', p_role, 'reached_count', p_reached,
    'conversion_from_top', CASE WHEN p_cohort_size > 0 THEN round(p_reached::numeric / p_cohort_size * 100, 1) ELSE NULL END,
    'conversion_from_prev', CASE WHEN p_prev IS NULL OR p_prev = 0 THEN NULL ELSE round(p_reached::numeric / p_prev * 100, 1) END
  );
$$;


