CREATE OR REPLACE FUNCTION "public"."fn_human_pause_on_manual_send"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_phone     text;
  v_duration  integer;
  v_lead_id   uuid;
  v_conv_id   uuid;
  v_agent_id  uuid;
BEGIN
  IF NEW.direction != 'outgoing'
     OR COALESCE(NEW.sent_source, 'manual') != 'manual'
     OR COALESCE(NEW.sent_by_ai, false) = true
  THEN
    RETURN NEW;
  END IF;

  v_phone := public.normalize_brazilian_phone(NEW.phone_number);
  IF v_phone IS NULL OR length(v_phone) = 0 THEN
    RETURN NEW;
  END IF;

  v_lead_id := NEW.lead_id;
  IF v_lead_id IS NULL THEN
    SELECT id INTO v_lead_id
    FROM public.leads
    WHERE organization_id = NEW.organization_id
      AND normalized_phone = v_phone
      AND deleted_at IS NULL
    ORDER BY created_at DESC
    LIMIT 1;
  END IF;

  IF v_lead_id IS NOT NULL THEN
    SELECT id, agent_id INTO v_conv_id, v_agent_id
    FROM public.conversations
    WHERE lead_id = v_lead_id
      AND organization_id = NEW.organization_id
    ORDER BY created_at DESC
    LIMIT 1;
  END IF;

  IF v_agent_id IS NOT NULL THEN
    SELECT human_pause_duration_minutes
    INTO v_duration
    FROM public.copilot_agents
    WHERE id = v_agent_id
      AND human_pause_enabled = true;
  ELSE
    SELECT human_pause_duration_minutes
    INTO v_duration
    FROM public.copilot_agents
    WHERE organization_id = NEW.organization_id
      AND human_pause_enabled = true
    ORDER BY is_active DESC, created_at DESC
    LIMIT 1;
  END IF;

  IF v_duration IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.phone_ai_preferences (organization_id, normalized_phone, human_paused_until)
  VALUES (NEW.organization_id, v_phone, now() + (v_duration * interval '1 minute'))
  ON CONFLICT (organization_id, normalized_phone)
  DO UPDATE SET human_paused_until = EXCLUDED.human_paused_until,
                updated_at = now();

  IF v_conv_id IS NOT NULL THEN
    UPDATE public.conversations
    SET human_paused_until = now() + (v_duration * interval '1 minute'),
        updated_at = now()
    WHERE id = v_conv_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_human_pause_on_manual_send"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_lead_comment_mentions"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mention uuid;
  v_old_set uuid[] := COALESCE(OLD.mentions, '{}');
  v_lead_name text;
  v_actor_name text;
BEGIN
  -- Skip if mentions is empty or unchanged on update
  IF NEW.mentions IS NULL OR array_length(NEW.mentions, 1) IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT name INTO v_lead_name FROM public.leads WHERE id = NEW.lead_id;
  SELECT full_name INTO v_actor_name
  FROM public.profiles WHERE id = NEW.author_user_id;

  FOREACH v_mention IN ARRAY NEW.mentions LOOP
    -- Skip if mention was already there on UPDATE (idempotente)
    IF TG_OP = 'UPDATE' AND v_mention = ANY(v_old_set) THEN
      CONTINUE;
    END IF;

    -- Skip self-mention
    IF v_mention = NEW.author_user_id THEN
      CONTINUE;
    END IF;

    -- Skip if user is not a team_member of the org (cross-org guard)
    IF NOT EXISTS (
      SELECT 1 FROM public.team_members
      WHERE user_id = v_mention
        AND organization_id = NEW.organization_id
        AND is_active = true
    ) THEN
      CONTINUE;
    END IF;

    INSERT INTO public.notifications (
      organization_id, user_id, type, title, description, lead_id, link
    )
    VALUES (
      NEW.organization_id,
      v_mention,
      'mention',
      COALESCE(v_actor_name, 'Alguém') || ' mencionou você',
      'No lead ' || COALESCE(v_lead_name, 'sem nome'),
      NEW.lead_id,
      '/leads?leadId=' || NEW.lead_id::text || '&comment=' || NEW.id::text
    );
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_lead_comment_mentions"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_lead_comment_mentions"() IS 'PRD #284 — emite notification por @mention. Skip self-mention, cross-org, e mentions já existentes em UPDATE.';



