CREATE OR REPLACE FUNCTION "public"."fn_log_pipeline_stage_change_history"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_slug       text;
  v_type       text;
  v_pipe_name  text;
  v_stage_name text;
BEGIN
  IF NEW.stage_key IS NOT DISTINCT FROM OLD.stage_key THEN
    RETURN NEW;
  END IF;

  IF auth.uid() IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT slug, type, name INTO v_slug, v_type, v_pipe_name
  FROM pipelines WHERE id = NEW.pipeline_id;

  IF v_type = 'custom' THEN
    SELECT name INTO v_stage_name FROM custom_pipeline_stages
     WHERE pipeline_id = NEW.pipeline_id AND stage_key = NEW.stage_key LIMIT 1;
  ELSE
    SELECT name INTO v_stage_name FROM pipeline_stages
     WHERE organization_id = NEW.organization_id
       AND pipeline_type = v_slug AND stage_key = NEW.stage_key LIMIT 1;
  END IF;

  INSERT INTO lead_history (
    lead_id, organization_id, action, description, source, created_by,
    metadata, entity_type, entity_id
  ) VALUES (
    NEW.lead_id,
    NEW.organization_id,
    'stage_changed',
    'Etapa alterada para "' || COALESCE(v_stage_name, NEW.stage_key)
      || '" no funil ' || COALESCE(v_pipe_name, COALESCE(v_slug, 'pipeline')) || ' (automação)',
    'automation',
    NULL,
    jsonb_build_object(
      'pipeline_id', NEW.pipeline_id,
      'pipe_slug', v_slug,
      'to_stage', NEW.stage_key,
      'from_stage', OLD.stage_key,
      'via', 'pipeline_entries_trigger'
    ),
    'lead',
    NEW.lead_id
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_log_pipeline_stage_change_history"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_pipeline_stage_events_block_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'pipeline_stage_events é append-only (ADR-0017): UPDATE proibido — corrija com evento novo' USING ERRCODE = 'P0001';
  END IF;
  IF EXISTS (SELECT 1 FROM public.leads WHERE id = OLD.lead_id)
     AND EXISTS (SELECT 1 FROM public.organizations WHERE id = OLD.organization_id)
     AND EXISTS (SELECT 1 FROM public.pipelines WHERE id = OLD.pipeline_id) THEN
    RAISE EXCEPTION 'pipeline_stage_events é append-only (ADR-0017): DELETE proibido — eventos só caem em cascade de lead/pipeline/org' USING ERRCODE = 'P0001';
  END IF;
  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."fn_pipeline_stage_events_block_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_pipeline_stages_guard_money_role"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.stage_role IS DISTINCT FROM 'won' AND NEW.stage_role IS DISTINCT FROM 'lost' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.stage_role IS NOT DISTINCT FROM NEW.stage_role THEN
    RETURN NEW;
  END IF;
  IF coalesce(auth.role(), '') = 'service_role'
     OR current_user = 'service_role'
     OR coalesce((SELECT rolsuper FROM pg_roles WHERE rolname = current_user), false)
     OR public.is_master_user()
     OR NEW.organization_id IN (SELECT public.get_my_admin_organization_ids()) THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'access_denied: stage_role % é dinheiro (ADR-0017 §1) — só admin da org ou master pode definir/alterar won/lost', NEW.stage_role USING ERRCODE = 'P0001';
END;
$$;


ALTER FUNCTION "public"."fn_pipeline_stages_guard_money_role"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_pipeline_stages_guard_money_role"() IS 'ADR-0017 §1 / FIX-4 — barra escrita de stage_role won/lost (dinheiro) por membro não-admin. Libera backend/master/admin da org.';



