CREATE OR REPLACE FUNCTION "public"."get_dormant_winback_candidates"("p_organization_id" "uuid", "p_segments" "text"[]) RETURNS TABLE("lead_id" "uuid", "carteira_segment" "text", "last_order_at" timestamp with time zone, "last_inbound_at" timestamp with time zone, "last_outbound_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT uc.lead_id, uc.segment, uc.last_order_at,
    (SELECT max(wm.timestamp) FROM whatsapp_messages wm
       WHERE wm.lead_id=uc.lead_id AND wm.organization_id=p_organization_id AND wm.direction='incoming'),
    (SELECT max(wm.timestamp) FROM whatsapp_messages wm
       WHERE wm.lead_id=uc.lead_id AND wm.organization_id=p_organization_id AND wm.direction='outgoing')
  FROM upsell_clients uc
  WHERE uc.organization_id = p_organization_id
    AND uc.lead_id IS NOT NULL
    AND uc.segment = ANY(p_segments);
$$;


