CREATE OR REPLACE FUNCTION "public"."get_email_thread"("p_thread_id" "text") RETURNS TABLE("id" "uuid", "message_id" "text", "from_address" "text", "from_name" "text", "to_addresses" "jsonb", "cc_addresses" "jsonb", "subject" "text", "body_html" "text", "body_text" "text", "snippet" "text", "sent_at" timestamp with time zone, "is_outbound" boolean, "has_attachments" boolean, "read_at" timestamp with time zone, "open_count" integer, "click_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    e.id, e.message_id, e.from_address, e.from_name,
    e.to_addresses, e.cc_addresses, e.subject,
    e.body_html, e.body_text, e.snippet,
    e.sent_at, e.is_outbound, e.has_attachments,
    e.read_at, e.open_count, e.click_count
  FROM emails e
  WHERE e.thread_id = p_thread_id
    AND e.organization_id IN (
      SELECT tm.organization_id FROM team_members tm WHERE tm.user_id = auth.uid()
    )
  ORDER BY e.sent_at ASC;
END;
$$;


ALTER FUNCTION "public"."get_email_thread"("p_thread_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_filtered_lead_ids"("p_pipeline_type" "text", "p_stage_key" "text" DEFAULT NULL::"text", "p_search" "text" DEFAULT NULL::"text", "p_responsible_id" "uuid" DEFAULT NULL::"uuid", "p_tag_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_qualification_tier" "text"[] DEFAULT NULL::"text"[], "p_pre_qualification_tier" "text"[] DEFAULT NULL::"text"[], "p_origin" "text"[] DEFAULT NULL::"text"[], "p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT pe.lead_id
  FROM public.pipeline_entries pe
  JOIN public.pipelines p
    ON p.id = pe.pipeline_id
   AND p.type = 'system'
   AND p.slug = p_pipeline_type
  JOIN public.leads l
    ON l.id = pe.lead_id
   AND l.deleted_at IS NULL
  WHERE pe.lead_id IS NOT NULL
    -- Tenancy: orgs do chamador (helper) OU a org pedida quando master.
    AND (
      pe.organization_id IN (SELECT public.get_my_organization_ids())
      OR (p_organization_id IS NOT NULL
          AND public.is_master_user()
          AND pe.organization_id = p_organization_id)
    )
    -- Optional stage scope: NULL = whole pipeline (every stage).
    AND (p_stage_key IS NULL OR pe.stage_key = p_stage_key)
    -- Search filter (mirrors get_pipeline_page: name / phone / company).
    AND (p_search IS NULL OR p_search = '' OR (
      l.name    ILIKE '%' || p_search || '%'
      OR l.phone   ILIKE '%' || p_search || '%'
      OR l.company ILIKE '%' || p_search || '%'
    ))
    -- Responsible filter (dual fields: entry metadata + lead columns).
    AND (p_responsible_id IS NULL OR (
      (pe.metadata->>'pre_sale_responsible_id')::UUID = p_responsible_id
      OR (pe.metadata->>'sale_responsible_id')::UUID = p_responsible_id
      OR l.pre_sale_responsible_id = p_responsible_id
      OR l.sale_responsible_id = p_responsible_id
    ))
    -- Tag filter (intersection: lead must have ALL specified tags).
    AND (p_tag_ids IS NULL OR array_length(p_tag_ids, 1) IS NULL OR NOT EXISTS (
      SELECT unnest(p_tag_ids)
      EXCEPT
      SELECT lt.tag_id FROM public.lead_tags lt WHERE lt.lead_id = l.id
    ))
    -- Qualification tier (sale-side) — text membership, NULL/empty = all.
    AND (p_qualification_tier IS NULL OR array_length(p_qualification_tier, 1) IS NULL
      OR l.qualification_tier::text = ANY(p_qualification_tier))
    -- Pre-qualification tier — text membership, NULL/empty = all.
    AND (p_pre_qualification_tier IS NULL OR array_length(p_pre_qualification_tier, 1) IS NULL
      OR l.pre_qualification_tier::text = ANY(p_pre_qualification_tier))
    -- Origin — text membership, NULL/empty = all.
    AND (p_origin IS NULL OR array_length(p_origin, 1) IS NULL
      OR l.origin::text = ANY(p_origin));
$$;


ALTER FUNCTION "public"."get_filtered_lead_ids"("p_pipeline_type" "text", "p_stage_key" "text", "p_search" "text", "p_responsible_id" "uuid", "p_tag_ids" "uuid"[], "p_qualification_tier" "text"[], "p_pre_qualification_tier" "text"[], "p_origin" "text"[], "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_followup_eligible_leads"("p_organization_id" "uuid", "p_trigger_delay_hours" integer, "p_trigger_delay_minutes" integer) RETURNS TABLE("lead_id" "uuid", "last_outgoing_at" timestamp with time zone, "phone_number" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH last_msg AS (
    SELECT
      wm.lead_id,
      wm.phone_number,
      wm.direction,
      wm.timestamp,
      ROW_NUMBER() OVER (PARTITION BY wm.lead_id ORDER BY wm.timestamp DESC) AS rn
    FROM whatsapp_messages wm
    WHERE wm.organization_id = p_organization_id
      AND wm.lead_id IS NOT NULL
      AND wm.phone_number IS NOT NULL
      AND wm.phone_number != ''
  )
  SELECT
    lm.lead_id,
    lm.timestamp AS last_outgoing_at,
    lm.phone_number
  FROM last_msg lm
  JOIN public.leads l ON l.id = lm.lead_id
  WHERE lm.rn = 1
    AND lm.direction = 'outgoing'
    AND l.ai_disabled IS NOT TRUE
    AND (NOW() - lm.timestamp) >= (
      (p_trigger_delay_hours || ' hours')::interval +
      (p_trigger_delay_minutes || ' minutes')::interval
    );
$$;


ALTER FUNCTION "public"."get_followup_eligible_leads"("p_organization_id" "uuid", "p_trigger_delay_hours" integer, "p_trigger_delay_minutes" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_followup_eligible_leads"("p_organization_id" "uuid", "p_trigger_delay_hours" integer, "p_trigger_delay_minutes" integer) IS 'Leads cuja última mensagem é nossa, delay de follow-up atingido, e ai_disabled IS NOT TRUE';



CREATE OR REPLACE FUNCTION "public"."get_funnel_conversion"("p_pipeline_type" "text", "p_start_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("stage_id" "uuid", "stage_name" "text", "stage_order" integer, "total_entered" bigint, "total_current" bigint, "conversion_rate" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  WITH org_check AS (
    SELECT tm.organization_id FROM team_members tm WHERE tm.user_id = auth.uid() LIMIT 1
  ),
  stage_counts AS (
    SELECT
      ps.id AS sid,
      ps.name AS sname,
      ps.position,
      COUNT(DISTINCT lh.lead_id) FILTER (
        WHERE lh.action = 'stage_changed'
        AND (p_start_date IS NULL OR lh.created_at >= p_start_date)
        AND (p_end_date IS NULL OR lh.created_at <= p_end_date)
      ) AS entered
    FROM pipeline_stages ps
    CROSS JOIN org_check oc
    LEFT JOIN lead_history lh ON lh.metadata->>'to_stage_id' = ps.id::text
      AND lh.organization_id = oc.organization_id
    WHERE ps.pipeline_type = p_pipeline_type
      AND ps.organization_id = oc.organization_id
    GROUP BY ps.id, ps.name, ps.position
  )
  SELECT
    sc.sid,
    sc.sname,
    sc.position,
    sc.entered,
    sc.entered,
    CASE
      WHEN LAG(sc.entered) OVER (ORDER BY sc.position) > 0
      THEN ROUND(sc.entered::numeric / LAG(sc.entered) OVER (ORDER BY sc.position) * 100, 1)
      ELSE 100.0
    END AS conv_rate
  FROM stage_counts sc
  ORDER BY sc.position;
END;
$$;


ALTER FUNCTION "public"."get_funnel_conversion"("p_pipeline_type" "text", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_funnel_flow"("p_org_id" "uuid", "p_pipeline_id" "uuid", "p_period" "text", "p_ref" "date" DEFAULT NULL::"date", "p_start" "date" DEFAULT NULL::"date", "p_end" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_bounds tstzrange; v_cohort_size integer;
  v_reached_open integer; v_reached_book integer; v_reached_held integer; v_reached_won integer;
  v_lost_count integer; v_pre_cutover boolean;
BEGIN
  PERFORM public.assert_org_access(p_org_id);
  IF p_pipeline_id IS NULL THEN
    RAISE EXCEPTION 'get_funnel_flow: p_pipeline_id é obrigatório (funil é por-pipeline)' USING ERRCODE = '22023';
  END IF;
  v_bounds := public.metric_period_bounds(p_org_id, p_period, p_ref, p_start, p_end);
  WITH pipe_events AS (
    SELECT e.lead_id, e.from_stage_key, e.occurred_at,
      public.metric_stage_role(p_org_id, p_pipeline_id, e.to_stage_key) AS role
    FROM public.pipeline_stage_events e
    WHERE e.organization_id = p_org_id AND e.pipeline_id = p_pipeline_id
  ),
  entry AS (
    SELECT pe.lead_id, COALESCE(min(pe.occurred_at) FILTER (WHERE pe.from_stage_key IS NULL), min(pe.occurred_at)) AS entry_at
    FROM pipe_events pe GROUP BY pe.lead_id
  ),
  cohort AS (SELECT en.lead_id FROM entry en WHERE en.entry_at <@ v_bounds),
  lead_reach AS (
    SELECT pe.lead_id,
      max(CASE pe.role WHEN 'meeting_booked' THEN 1 WHEN 'meeting_held' THEN 2 WHEN 'won' THEN 3 ELSE 0 END) AS max_rank,
      bool_or(pe.role = 'lost') AS ever_lost
    FROM pipe_events pe JOIN cohort c ON c.lead_id = pe.lead_id GROUP BY pe.lead_id
  )
  SELECT count(*),
    count(*) FILTER (WHERE lr.max_rank >= 0), count(*) FILTER (WHERE lr.max_rank >= 1),
    count(*) FILTER (WHERE lr.max_rank >= 2), count(*) FILTER (WHERE lr.max_rank >= 3),
    count(*) FILTER (WHERE lr.ever_lost)
  INTO v_cohort_size, v_reached_open, v_reached_book, v_reached_held, v_reached_won, v_lost_count
  FROM lead_reach lr;
  v_cohort_size := COALESCE(v_cohort_size, 0); v_reached_open := COALESCE(v_reached_open, 0);
  v_reached_book := COALESCE(v_reached_book, 0); v_reached_held := COALESCE(v_reached_held, 0);
  v_reached_won := COALESCE(v_reached_won, 0); v_lost_count := COALESCE(v_lost_count, 0);
  v_pre_cutover := lower(v_bounds) < '2026-12-01T00:00:00Z'::timestamptz;
  RETURN jsonb_build_object(
    'period', jsonb_build_object('name', p_period, 'start', lower(v_bounds), 'end', upper(v_bounds)),
    'pipeline_id', p_pipeline_id, 'cohort_size', v_cohort_size, 'lost_count', v_lost_count,
    'pre_cutover_caveat', v_pre_cutover,
    'steps', jsonb_build_array(
      public.fn_funnel_flow_step('open', v_reached_open, v_cohort_size, NULL),
      public.fn_funnel_flow_step('meeting_booked', v_reached_book, v_cohort_size, v_reached_open),
      public.fn_funnel_flow_step('meeting_held', v_reached_held, v_cohort_size, v_reached_book),
      public.fn_funnel_flow_step('won', v_reached_won, v_cohort_size, v_reached_held)
    ),
    'lost', jsonb_build_object('role', 'lost', 'lost_count', v_lost_count,
      'conversion_from_top', CASE WHEN v_cohort_size > 0 THEN round(v_lost_count::numeric / v_cohort_size * 100, 1) ELSE NULL END)
  );
END;
$$;


ALTER FUNCTION "public"."get_funnel_flow"("p_org_id" "uuid", "p_pipeline_id" "uuid", "p_period" "text", "p_ref" "date", "p_start" "date", "p_end" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_funnel_flow"("p_org_id" "uuid", "p_pipeline_id" "uuid", "p_period" "text", "p_ref" "date", "p_start" "date", "p_end" "date") IS 'ADR-0017 §1,§5,§7,§8 / #996 — leitor canônico de FUNIL coorte/fluxo (SP-3). Lê SÓ pipeline_stage_events.';



CREATE OR REPLACE FUNCTION "public"."get_funnel_health"("p_org_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_origins" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total int := 0;
  v_avaliados int := 0;
  v_bons int := 0;
  v_reuniao int := 0;
  v_compareceram int := 0;
  v_compraram int := 0;
  v_tiers jsonb := '{}'::jsonb;
  v_depth jsonb := '{}'::jsonb;
  v_sellers jsonb := '[]'::jsonb;
  v_cycles jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.assert_org_access(p_org_id);

  WITH cohort AS (
    SELECT id,
           created_at,
           COALESCE(qualification_tier, pre_qualification_tier) AS tier_efetivo,
           (qualification_tier IS NOT NULL) AS has_final,
           -- Pré-vendas canônico com fallback legado (ADR-0007)
           COALESCE(pre_sale_responsible_id, sdr_id, responsible_id) AS tm_id
    FROM leads
    WHERE organization_id = p_org_id
           AND NOT public.lead_excluded_from_metrics(id, p_org_id)
      AND deleted_at IS NULL
      AND created_at >= p_start_date
      AND created_at <= p_end_date
      AND (p_origins IS NULL OR cardinality(p_origins) = 0 OR origin::text = ANY(p_origins))
  ),
  meetings AS (
    -- "ever reached": events count at ANY time, deduped per lead
    SELECT me.lead_id,
           bool_or(me.event_type = 'meeting_booked') AS booked,
           bool_or(me.event_type = 'meeting_held') AS held,
           min(me.occurred_at) FILTER (WHERE me.event_type = 'meeting_held') AS first_held_at
    FROM meeting_events me
    WHERE me.organization_id = p_org_id
      AND me.lead_id IN (SELECT id FROM cohort)
    GROUP BY me.lead_id
  ),
  vendas AS (
    -- mirrors the pipe_propostas view: system pipeline slug 'propostas'.
    -- sold_at = quando fechou (closed_at; fallback stage_changed_at/created_at)
    SELECT pe.lead_id,
           min(COALESCE(pe.closed_at, pe.stage_changed_at, pe.created_at)) AS sold_at
    FROM pipeline_entries pe
    JOIN pipelines pip
      ON pip.id = pe.pipeline_id AND pip.slug = 'propostas' AND pip.type = 'system' -- metric-lint-allow: corpo reproduzido de prod (funnel_health), type=system pre-existente
    WHERE pe.organization_id = p_org_id
      AND pe.stage_key = 'vendido'
      AND pe.lead_id IN (SELECT id FROM cohort)
    GROUP BY pe.lead_id
  ),
  enriched AS (
    SELECT c.id,
           c.created_at,
           c.tier_efetivo,
           c.has_final,
           c.tm_id,
           COALESCE(m.booked, false) AS booked,
           COALESCE(m.held, false) AS held,
           (v.lead_id IS NOT NULL) AS sold,
           v.sold_at,
           m.first_held_at
    FROM cohort c
    LEFT JOIN meetings m ON m.lead_id = c.id
    LEFT JOIN vendas v ON v.lead_id = c.id
  )
  SELECT COUNT(*),
         COUNT(*) FILTER (WHERE e.tier_efetivo IS NOT NULL),
         COUNT(*) FILTER (WHERE e.tier_efetivo IN ('prata', 'ouro', 'diamante')),
         COUNT(*) FILTER (WHERE e.booked),
         COUNT(*) FILTER (WHERE e.held),
         COUNT(*) FILTER (WHERE e.sold),
         jsonb_build_object(
           'diamante', COUNT(*) FILTER (WHERE e.tier_efetivo = 'diamante'),
           'ouro', COUNT(*) FILTER (WHERE e.tier_efetivo = 'ouro'),
           'prata', COUNT(*) FILTER (WHERE e.tier_efetivo = 'prata'),
           'bronze', COUNT(*) FILTER (WHERE e.tier_efetivo = 'bronze'),
           'desqualificado', COUNT(*) FILTER (WHERE e.tier_efetivo = 'desqualificado')
         ),
         jsonb_build_object(
           'pre_only', COUNT(*) FILTER (WHERE e.tier_efetivo IS NOT NULL AND NOT e.has_final),
           'final', COUNT(*) FILTER (WHERE e.has_final)
         ),
         (
           SELECT COALESCE(
             jsonb_agg(
               jsonb_build_object(
                 'team_member_id', s.tm_id,
                 'name', s.name,
                 'vinculados', s.vinculados,
                 'avaliados', s.avaliados,
                 'bons', s.bons,
                 'reuniao', s.reuniao,
                 'compareceram', s.compareceram,
                 'compraram', s.compraram
               )
               ORDER BY s.vinculados DESC, s.name NULLS LAST
             ),
             '[]'::jsonb
           )
           FROM (
             SELECT e2.tm_id,
                    tm.name,
                    COUNT(*) AS vinculados,
                    COUNT(*) FILTER (WHERE e2.tier_efetivo IS NOT NULL) AS avaliados,
                    COUNT(*) FILTER (WHERE e2.tier_efetivo IN ('prata', 'ouro', 'diamante')) AS bons,
                    COUNT(*) FILTER (WHERE e2.booked) AS reuniao,
                    COUNT(*) FILTER (WHERE e2.held) AS compareceram,
                    COUNT(*) FILTER (WHERE e2.sold) AS compraram
             FROM enriched e2
             LEFT JOIN team_members tm ON tm.id = e2.tm_id
             GROUP BY e2.tm_id, tm.name
           ) s
         ),
         (
           -- Ciclos médios em dias, sobre as vendas da coorte. meeting_* só
           -- considera vendas com reunião realizada registrada.
           SELECT jsonb_build_object(
             'sales_count', COUNT(*),
             'lead_to_sale_days',
               ROUND((AVG(EXTRACT(EPOCH FROM (x.sold_at - x.created_at)) / 86400))::numeric, 1),
             'meeting_sales_count', COUNT(*) FILTER (WHERE x.first_held_at IS NOT NULL),
             'meeting_to_sale_days',
               ROUND((AVG(EXTRACT(EPOCH FROM (x.sold_at - x.first_held_at)) / 86400)
                 FILTER (WHERE x.first_held_at IS NOT NULL))::numeric, 1),
             'lead_to_meeting_days',
               ROUND((AVG(EXTRACT(EPOCH FROM (x.first_held_at - x.created_at)) / 86400)
                 FILTER (WHERE x.first_held_at IS NOT NULL))::numeric, 1)
           )
           FROM enriched x
           WHERE x.sold
         )
  INTO v_total, v_avaliados, v_bons, v_reuniao, v_compareceram, v_compraram, v_tiers, v_depth, v_sellers, v_cycles
  FROM enriched e;

  RETURN jsonb_build_object(
    'cohort_total', v_total,
    'stages', jsonb_build_object(
      'entraram', v_total,
      'avaliados', v_avaliados,
      'bons', v_bons,
      'reuniao', v_reuniao,
      'compareceram', v_compareceram,
      'compraram', v_compraram
    ),
    'tiers', v_tiers,
    'depth', v_depth,
    'sellers', v_sellers,
    'cycles', v_cycles
  );
END;
$$;


ALTER FUNCTION "public"."get_funnel_health"("p_org_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_origins" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_funnel_health_stage_leads"("p_org_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_stage" "text", "p_origins" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result jsonb := '[]'::jsonb;
BEGIN
  PERFORM public.assert_org_access(p_org_id);

  IF p_stage NOT IN ('entraram', 'avaliados', 'bons', 'reuniao', 'compareceram', 'compraram') THEN
    RAISE EXCEPTION 'invalid_stage: %', p_stage USING ERRCODE = 'P0001';
  END IF;

  WITH cohort AS (
    SELECT l.id,
           l.name,
           l.company,
           l.created_at,
           COALESCE(l.qualification_tier, l.pre_qualification_tier) AS tier,
           COALESCE(l.pre_sale_responsible_id, l.sdr_id, l.responsible_id) AS tm_id
    FROM leads l
    WHERE l.organization_id = p_org_id
           AND NOT public.lead_excluded_from_metrics(l.id, p_org_id)
      AND l.deleted_at IS NULL
      AND l.created_at >= p_start_date
      AND l.created_at <= p_end_date
      AND (p_origins IS NULL OR cardinality(p_origins) = 0 OR l.origin::text = ANY(p_origins))
  ),
  meetings AS (
    SELECT me.lead_id,
           bool_or(me.event_type = 'meeting_booked') AS booked,
           bool_or(me.event_type = 'meeting_held') AS held,
           max(me.meeting_date) FILTER (WHERE me.event_type = 'meeting_booked') AS meeting_date,
           max(me.occurred_at) FILTER (WHERE me.event_type = 'meeting_held') AS held_at
    FROM meeting_events me
    WHERE me.organization_id = p_org_id
      AND me.lead_id IN (SELECT id FROM cohort)
    GROUP BY me.lead_id
  ),
  propostas AS (
    -- entry mais recente do lead em Orçamentos (estado atual no funil de fechamento)
    SELECT DISTINCT ON (pe.lead_id)
           pe.lead_id,
           pe.stage_key AS proposta_stage,
           (pe.metadata ->> 'sale_value')::numeric AS sale_value
    FROM pipeline_entries pe
    JOIN pipelines pip
      ON pip.id = pe.pipeline_id AND pip.slug = 'propostas' AND pip.type = 'system' -- metric-lint-allow: corpo reproduzido de prod (funnel_health), type=system pre-existente
    WHERE pe.organization_id = p_org_id
      AND pe.lead_id IN (SELECT id FROM cohort)
    ORDER BY pe.lead_id, pe.created_at DESC
  ),
  whatsapp_pos AS (
    -- posição atual no funil de Oportunidades (stage_key cru; o front humaniza)
    SELECT DISTINCT ON (pe.lead_id)
           pe.lead_id,
           pe.stage_key AS whatsapp_stage
    FROM pipeline_entries pe
    JOIN pipelines pip
      ON pip.id = pe.pipeline_id AND pip.slug = 'whatsapp' AND pip.type = 'system' -- metric-lint-allow: corpo reproduzido de prod (funnel_health), type=system pre-existente
    WHERE pe.organization_id = p_org_id
      AND pe.lead_id IN (SELECT id FROM cohort)
    ORDER BY pe.lead_id, pe.created_at DESC
  ),
  enriched AS (
    SELECT c.*,
           w.whatsapp_stage,
           COALESCE(m.booked, false) AS booked,
           COALESCE(m.held, false) AS held,
           m.meeting_date,
           m.held_at,
           p.proposta_stage,
           p.sale_value,
           (p.proposta_stage = 'vendido') IS TRUE AS sold,
           tm.name AS pre_vendas
    FROM cohort c
    LEFT JOIN meetings m ON m.lead_id = c.id
    LEFT JOIN propostas p ON p.lead_id = c.id
    LEFT JOIN team_members tm ON tm.id = c.tm_id
    LEFT JOIN whatsapp_pos w ON w.lead_id = c.id
  ),
  filtered AS (
    SELECT *
    FROM enriched e
    WHERE CASE p_stage
      WHEN 'entraram' THEN true
      WHEN 'avaliados' THEN e.tier IS NOT NULL
      WHEN 'bons' THEN e.tier IN ('prata', 'ouro', 'diamante')
      WHEN 'reuniao' THEN e.booked
      WHEN 'compareceram' THEN e.held
      WHEN 'compraram' THEN e.sold
    END
    ORDER BY e.created_at DESC
    LIMIT 500
  )
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', f.id,
        'name', f.name,
        'company', f.company,
        'tier', f.tier,
        'created_at', f.created_at,
        'pre_vendas', f.pre_vendas,
        'proposta_stage', f.proposta_stage,
        'sale_value', f.sale_value,
        'meeting_date', f.meeting_date,
        'held_at', f.held_at,
        'whatsapp_stage', f.whatsapp_stage
      )
      ORDER BY f.created_at DESC
    ),
    '[]'::jsonb
  )
  INTO v_result
  FROM filtered f;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_funnel_health_stage_leads"("p_org_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_stage" "text", "p_origins" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_help_article_feedback_summaries"() RETURNS TABLE("article_id" "uuid", "helpful_up" integer, "helpful_down" integer, "reasons" "text"[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    f.article_id,
    count(*) FILTER (WHERE f.helpful)::int        AS helpful_up,
    count(*) FILTER (WHERE NOT f.helpful)::int     AS helpful_down,
    COALESCE(
      array_agg(f.reason ORDER BY f.updated_at DESC)
        FILTER (WHERE f.reason IS NOT NULL AND btrim(f.reason) <> ''),
      ARRAY[]::text[]
    ) AS reasons
  FROM public.help_article_feedback f
  JOIN public.help_articles a ON a.id = f.article_id
  WHERE
    (a.organization_id IS NULL AND public.is_master_user())
    OR (a.organization_id = public.get_user_organization_id() AND public.is_user_admin())
  GROUP BY f.article_id;
$$;


ALTER FUNCTION "public"."get_help_article_feedback_summaries"() OWNER TO "postgres";


