CREATE OR REPLACE FUNCTION "public"."get_import_batches"("p_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "file_name" "text", "total_rows" integer, "imported_count" integer, "skipped_count" integer, "error_count" integer, "rolled_back" boolean, "rolled_back_at" timestamp with time zone, "created_at" timestamp with time zone, "created_by_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    ib.id, ib.file_name, ib.total_rows,
    ib.imported_count, ib.skipped_count, ib.error_count,
    ib.rolled_back, ib.rolled_back_at, ib.created_at,
    COALESCE(
      (SELECT tm.name FROM team_members tm WHERE tm.user_id = ib.created_by LIMIT 1),
      'Sistema'
    ) AS created_by_name
  FROM import_batches ib
  WHERE ib.organization_id IN (
    SELECT tm2.organization_id FROM team_members tm2 WHERE tm2.user_id = auth.uid()
  )
  ORDER BY ib.created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_import_batches"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_jobs_overview"("interval_param" "text" DEFAULT '24 hours'::"text") RETURNS json
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.is_master_user() THEN
    RAISE EXCEPTION 'Forbidden: master access required';
  END IF;

  RETURN (
    SELECT json_build_object(
      'total',       COUNT(*),
      'success',     COUNT(*) FILTER (WHERE status = 'success'),
      'failed',      COUNT(*) FILTER (WHERE status = 'failed'),
      'dead_letter', COUNT(*) FILTER (WHERE status = 'dead_letter'),
      'retrying',    COUNT(*) FILTER (WHERE status = 'retrying'),
      'running',     COUNT(*) FILTER (WHERE status = 'running')
    )
    FROM public.automation_jobs
    WHERE created_at > NOW() - interval_param::INTERVAL
  );
END;
$$;


