CREATE OR REPLACE FUNCTION "public"."get_lead_ai_status"("p_lead_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_lead_org_id UUID;
  v_is_member BOOLEAN;
  v_result JSONB;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('ai_disabled', false);
  END IF;

  -- Get lead's org and ai_disabled in one query
  SELECT organization_id, ai_disabled, ai_disabled_at, ai_disabled_by
  INTO v_lead_org_id
  FROM public.leads
  WHERE id = p_lead_id;

  IF v_lead_org_id IS NULL THEN
    RETURN jsonb_build_object('ai_disabled', false);
  END IF;

  -- Verify user belongs to the lead's org
  SELECT EXISTS (
    SELECT 1 FROM public.team_members
    WHERE user_id = v_user_id
      AND organization_id = v_lead_org_id
      AND is_active = true
  ) INTO v_is_member;

  IF NOT v_is_member THEN
    RETURN jsonb_build_object('ai_disabled', false);
  END IF;

  -- Return the ai_disabled status
  SELECT jsonb_build_object(
    'ai_disabled', COALESCE(l.ai_disabled, false),
    'ai_disabled_at', l.ai_disabled_at,
    'ai_disabled_by', l.ai_disabled_by
  ) INTO v_result
  FROM public.leads l
  WHERE l.id = p_lead_id;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_lead_ai_status"("p_lead_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_lead_ai_status"("p_lead_id" "uuid") IS 'Returns ai_disabled status for a lead. Bypasses RLS so any org member can check.';



CREATE OR REPLACE FUNCTION "public"."get_lead_field_changes"("p_lead_id" "uuid", "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "entity_type" "text", "entity_id" "uuid", "field_name" "text", "old_value" "text", "new_value" "text", "changed_by" "uuid", "changed_at" timestamp with time zone, "user_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    fc.id, fc.entity_type, fc.entity_id,
    fc.field_name, fc.old_value, fc.new_value,
    fc.changed_by, fc.changed_at,
    COALESCE(
      (SELECT tm.name FROM team_members tm WHERE tm.user_id = fc.changed_by LIMIT 1),
      'Sistema'
    ) AS user_name
  FROM field_changes fc
  WHERE fc.entity_id = p_lead_id
    AND fc.entity_type = 'lead'
    AND fc.organization_id IN (
      SELECT tm2.organization_id FROM team_members tm2 WHERE tm2.user_id = auth.uid()
    )
  ORDER BY fc.changed_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_lead_field_changes"("p_lead_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_lead_write_instance"("p_lead_id" "uuid") RETURNS TABLE("instance_id" "uuid", "instance_name" "text", "owner_team_member_id" "uuid", "responsible_user_id" "uuid", "error_code" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_resp_tm_id uuid;
BEGIN
  SELECT l.organization_id, l.responsible_user_id
    INTO v_org_id, v_resp_tm_id
  FROM public.leads l
  WHERE l.id = p_lead_id;

  IF v_org_id IS NULL THEN
    RETURN QUERY SELECT NULL::uuid, NULL::text, NULL::uuid, NULL::uuid, 'LEAD_NOT_FOUND'::text;
    RETURN;
  END IF;

  IF v_resp_tm_id IS NULL THEN
    RETURN QUERY SELECT NULL::uuid, NULL::text, NULL::uuid, NULL::uuid, 'NO_RESPONSIBLE'::text;
    RETURN;
  END IF;

  RETURN QUERY
  SELECT wi.id, wi.instance_name, wi.owner_team_member_id, v_resp_tm_id, NULL::text
  FROM public.whatsapp_instances wi
  WHERE wi.organization_id = v_org_id
    AND wi.owner_team_member_id = v_resp_tm_id
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN QUERY SELECT NULL::uuid, NULL::text, NULL::uuid, v_resp_tm_id, 'NO_INSTANCE'::text;
  END IF;
END;
$$;


ALTER FUNCTION "public"."get_lead_write_instance"("p_lead_id" "uuid") OWNER TO "postgres";


