CREATE OR REPLACE FUNCTION "public"."get_leads_by_uf"("p_uf" character, "p_limit" integer DEFAULT 60, "p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "name" "text", "company" "text", "phone" "text", "uf_source" "text", "is_client" boolean, "sold_value" numeric, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE v_org_id uuid;
BEGIN
  v_org_id := resolve_org_for_rpc(p_org_id);
  IF v_org_id IS NULL THEN RETURN; END IF;
  RETURN QUERY
  SELECT l.id, l.name, l.company, l.phone, l.uf_source,
    EXISTS (SELECT 1 FROM pipe_propostas pp WHERE pp.lead_id = l.id AND pp.status = 'vendido'),
    COALESCE((SELECT SUM(pp.sale_value) FROM pipe_propostas pp WHERE pp.lead_id = l.id AND pp.status = 'vendido'), 0)::numeric,
    l.created_at
  FROM leads l
  WHERE l.organization_id = v_org_id AND l.deleted_at IS NULL AND l.uf = p_uf
  ORDER BY 7 DESC, l.created_at DESC
  LIMIT p_limit;
END; $$;


ALTER FUNCTION "public"."get_leads_by_uf"("p_uf" character, "p_limit" integer, "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_leads_no_response_from_lead"("p_organization_id" "uuid", "p_delay_hours" integer, "p_delay_minutes" integer, "p_pipe_type" "text" DEFAULT NULL::"text", "p_filter_stages" "text"[] DEFAULT NULL::"text"[]) RETURNS TABLE("lead_id" "uuid", "last_outgoing_at" timestamp with time zone, "phone_number" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH last_msg AS (
    SELECT
      wm.lead_id,
      wm.phone_number,
      wm.direction,
      wm.timestamp,
      ROW_NUMBER() OVER (PARTITION BY wm.lead_id ORDER BY wm.timestamp DESC) AS rn
    FROM whatsapp_messages wm
    WHERE wm.organization_id = p_organization_id
      AND wm.lead_id IS NOT NULL
      AND wm.phone_number IS NOT NULL
  )
  SELECT
    lm.lead_id,
    lm.timestamp AS last_outgoing_at,
    lm.phone_number
  FROM last_msg lm
  INNER JOIN leads l ON l.id = lm.lead_id
  WHERE lm.rn = 1
    AND lm.direction = 'outgoing'
    AND (NOW() - lm.timestamp) >= (
      (p_delay_hours || ' hours')::interval +
      (p_delay_minutes || ' minutes')::interval
    )
    AND (p_pipe_type IS NULL OR (
      CASE p_pipe_type
        WHEN 'whatsapp' THEN l.pipe_whatsapp IS NOT NULL
        WHEN 'confirmacao' THEN EXISTS (
          SELECT 1 FROM pipeline_entries pe
          JOIN pipelines pip ON pip.id = pe.pipeline_id AND pip.slug = 'confirmacao' AND pip.type = 'system'
          WHERE pe.lead_id = l.id
        )
        WHEN 'propostas' THEN EXISTS (
          SELECT 1 FROM pipeline_entries pe
          JOIN pipelines pip ON pip.id = pe.pipeline_id AND pip.slug = 'propostas' AND pip.type = 'system'
          WHERE pe.lead_id = l.id
        )
        ELSE TRUE
      END
    ))
    AND (p_filter_stages IS NULL OR array_length(p_filter_stages, 1) IS NULL OR (
      CASE p_pipe_type
        WHEN 'whatsapp' THEN l.pipe_whatsapp::text = ANY(p_filter_stages)
        WHEN 'confirmacao' THEN EXISTS (
          SELECT 1 FROM pipeline_entries pe
          JOIN pipelines pip ON pip.id = pe.pipeline_id AND pip.slug = 'confirmacao' AND pip.type = 'system'
          WHERE pe.lead_id = l.id AND pe.stage_key = ANY(p_filter_stages)
        )
        WHEN 'propostas' THEN EXISTS (
          SELECT 1 FROM pipeline_entries pe
          JOIN pipelines pip ON pip.id = pe.pipeline_id AND pip.slug = 'propostas' AND pip.type = 'system'
          WHERE pe.lead_id = l.id AND pe.stage_key = ANY(p_filter_stages)
        )
        ELSE TRUE
      END
    ));
$$;


ALTER FUNCTION "public"."get_leads_no_response_from_lead"("p_organization_id" "uuid", "p_delay_hours" integer, "p_delay_minutes" integer, "p_pipe_type" "text", "p_filter_stages" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_leads_not_confirmed"("p_organization_id" "uuid", "p_hours_before_meeting" integer, "p_minutes_before_meeting" integer, "p_filter_stages" "text"[] DEFAULT NULL::"text"[]) RETURNS TABLE("lead_id" "uuid", "meeting_date" timestamp with time zone, "confirmacao_id" "uuid", "current_status" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    pe.lead_id,
    (pe.metadata->>'meeting_date')::timestamptz AS meeting_date,
    pe.id AS confirmacao_id,
    pe.stage_key AS current_status
  FROM pipeline_entries pe
  JOIN pipelines pip ON pip.id = pe.pipeline_id AND pip.slug = 'confirmacao' AND pip.type = 'system'
  INNER JOIN leads l ON l.id = pe.lead_id AND l.organization_id = p_organization_id
  WHERE (pe.metadata->>'meeting_date')::timestamptz IS NOT NULL
    -- Reuniao esta no futuro mas dentro da janela de alerta
    AND (pe.metadata->>'meeting_date')::timestamptz > NOW()
    AND (pe.metadata->>'meeting_date')::timestamptz <= NOW() + (
      (p_hours_before_meeting || ' hours')::interval +
      (p_minutes_before_meeting || ' minutes')::interval
    )
    -- Status indica que NAO confirmou ainda
    AND pe.stage_key NOT IN ('compareceu', 'perdido')
    AND (pe.metadata->>'is_confirmed') IS DISTINCT FROM 'true'
    -- Filtro opcional por etapas
    AND (p_filter_stages IS NULL OR array_length(p_filter_stages, 1) IS NULL
         OR pe.stage_key = ANY(p_filter_stages));
$$;


ALTER FUNCTION "public"."get_leads_not_confirmed"("p_organization_id" "uuid", "p_hours_before_meeting" integer, "p_minutes_before_meeting" integer, "p_filter_stages" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_leads_team_no_response"("p_organization_id" "uuid", "p_delay_hours" integer, "p_delay_minutes" integer, "p_pipe_type" "text" DEFAULT NULL::"text", "p_filter_stages" "text"[] DEFAULT NULL::"text"[]) RETURNS TABLE("lead_id" "uuid", "last_incoming_at" timestamp with time zone, "phone_number" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH last_msg AS (
    SELECT
      wm.lead_id,
      wm.phone_number,
      wm.direction,
      wm.timestamp,
      ROW_NUMBER() OVER (PARTITION BY wm.lead_id ORDER BY wm.timestamp DESC) AS rn
    FROM whatsapp_messages wm
    WHERE wm.organization_id = p_organization_id
      AND wm.lead_id IS NOT NULL
      AND wm.phone_number IS NOT NULL
  )
  SELECT
    lm.lead_id,
    lm.timestamp AS last_incoming_at,
    lm.phone_number
  FROM last_msg lm
  INNER JOIN leads l ON l.id = lm.lead_id
  WHERE lm.rn = 1
    AND lm.direction = 'incoming'
    AND (NOW() - lm.timestamp) >= (
      (p_delay_hours || ' hours')::interval +
      (p_delay_minutes || ' minutes')::interval
    )
    -- Filtro opcional por pipe_type
    AND (p_pipe_type IS NULL OR (
      CASE p_pipe_type
        WHEN 'whatsapp' THEN l.pipe_whatsapp IS NOT NULL
        WHEN 'confirmacao' THEN EXISTS (
          SELECT 1 FROM pipeline_entries pe
          JOIN pipelines pip ON pip.id = pe.pipeline_id AND pip.slug = 'confirmacao' AND pip.type = 'system'
          WHERE pe.lead_id = l.id
        )
        WHEN 'propostas' THEN EXISTS (
          SELECT 1 FROM pipeline_entries pe
          JOIN pipelines pip ON pip.id = pe.pipeline_id AND pip.slug = 'propostas' AND pip.type = 'system'
          WHERE pe.lead_id = l.id
        )
        ELSE TRUE
      END
    ))
    -- Filtro opcional por etapas especificas
    AND (p_filter_stages IS NULL OR array_length(p_filter_stages, 1) IS NULL OR (
      CASE p_pipe_type
        WHEN 'whatsapp' THEN l.pipe_whatsapp::text = ANY(p_filter_stages)
        WHEN 'confirmacao' THEN EXISTS (
          SELECT 1 FROM pipeline_entries pe
          JOIN pipelines pip ON pip.id = pe.pipeline_id AND pip.slug = 'confirmacao' AND pip.type = 'system'
          WHERE pe.lead_id = l.id AND pe.stage_key = ANY(p_filter_stages)
        )
        WHEN 'propostas' THEN EXISTS (
          SELECT 1 FROM pipeline_entries pe
          JOIN pipelines pip ON pip.id = pe.pipeline_id AND pip.slug = 'propostas' AND pip.type = 'system'
          WHERE pe.lead_id = l.id AND pe.stage_key = ANY(p_filter_stages)
        )
        ELSE TRUE
      END
    ));
$$;


ALTER FUNCTION "public"."get_leads_team_no_response"("p_organization_id" "uuid", "p_delay_hours" integer, "p_delay_minutes" integer, "p_pipe_type" "text", "p_filter_stages" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_meeting_reminder_candidates"("p_organization_id" "uuid", "p_stage_keys" "text"[]) RETURNS TABLE("lead_id" "uuid", "whatsapp_stage" "text", "meeting_date" timestamp with time zone, "last_inbound_at" timestamp with time zone, "last_outbound_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH wf AS (
    SELECT pe.lead_id, pe.stage_key, (pe.metadata->>'scheduled_date')::timestamptz AS meeting_date
    FROM pipeline_entries pe
    JOIN pipelines p ON p.id = pe.pipeline_id AND p.slug = 'whatsapp' AND p.type = 'system'
    WHERE pe.organization_id = p_organization_id
      AND pe.stage_key = ANY(p_stage_keys)
      AND pe.metadata->>'scheduled_date' IS NOT NULL
      AND (pe.metadata->>'scheduled_date')::timestamptz > now()
  )
  SELECT w.lead_id, w.stage_key, w.meeting_date,
    (SELECT max(wm.timestamp) FROM whatsapp_messages wm
       WHERE wm.lead_id=w.lead_id AND wm.organization_id=p_organization_id AND wm.direction='incoming'),
    (SELECT max(wm.timestamp) FROM whatsapp_messages wm
       WHERE wm.lead_id=w.lead_id AND wm.organization_id=p_organization_id AND wm.direction='outgoing')
  FROM wf w;
$$;


