CREATE OR REPLACE FUNCTION "public"."get_meta_cloud_credentials"("p_instance_id" "uuid") RETURNS TABLE("meta_waba_id" "text", "meta_phone_number_id" "text", "meta_access_token" "text", "organization_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.role() != 'service_role' THEN
    RAISE EXCEPTION 'Permission denied' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    s.meta_waba_id,
    s.meta_phone_number_id,
    s.meta_access_token,
    s.organization_id
  FROM public.whatsapp_instance_secrets s
  WHERE s.instance_id = p_instance_id;
END;
$$;


