COMMENT ON FUNCTION "public"."get_next_campaign_sdr"("p_campaign_id" "uuid") IS 'Returns team_member_id to assign to the next lead in the campaign (round_robin, random, or single). Used by front when adding lead with auto-distribute.';



CREATE OR REPLACE FUNCTION "public"."get_next_pipe_closer"("p_pipe_type" "text", "p_organization_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rule_id UUID;
  v_mode TEXT;
  v_assigned_to UUID;
  v_member_ids UUID[];
  v_count BIGINT;
  v_next_index INT;
BEGIN
  SELECT id, closer_mode, closer_assigned_to
    INTO v_rule_id, v_mode, v_assigned_to
  FROM public.pipe_distribution_rules
  WHERE organization_id = p_organization_id
    AND pipe_type = p_pipe_type
  LIMIT 1;

  IF v_rule_id IS NULL OR v_mode IS NULL THEN
    RETURN NULL;
  END IF;

  IF v_mode = 'single' AND v_assigned_to IS NOT NULL THEN
    RETURN v_assigned_to;
  END IF;

  SELECT ARRAY_AGG(pdm.team_member_id ORDER BY pdm.created_at, pdm.team_member_id)
    INTO v_member_ids
  FROM public.pipe_distribution_members pdm
  WHERE pdm.rule_id = v_rule_id
    AND pdm.role = 'closer';

  IF v_member_ids IS NULL OR array_length(v_member_ids, 1) IS NULL OR array_length(v_member_ids, 1) = 0 THEN
    RETURN NULL;
  END IF;

  IF v_mode = 'random' THEN
    RETURN v_member_ids[1 + floor(random() * array_length(v_member_ids, 1))::int];
  END IF;

  IF v_mode = 'round_robin' THEN
    -- Count records with closer_id set in pipeline_entries for this pipe slug
    SELECT count(*) INTO v_count
    FROM public.pipeline_entries pe
    JOIN public.pipelines pip ON pip.id = pe.pipeline_id AND pip.slug = p_pipe_type AND pip.type = 'system'
    WHERE pe.organization_id = p_organization_id
      AND (pe.metadata->>'closer_id')::uuid IS NOT NULL;

    v_next_index := (COALESCE(v_count, 0) % array_length(v_member_ids, 1)) + 1;
    RETURN v_member_ids[v_next_index];
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."get_next_pipe_closer"("p_pipe_type" "text", "p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_next_pipe_closer"("p_pipe_type" "text", "p_organization_id" "uuid") IS 'Retorna team_member_id do proximo Closer a atribuir no pipe via pipeline_entries (round_robin, random ou single).';



CREATE OR REPLACE FUNCTION "public"."get_next_pipe_sdr"("p_pipe_type" "text", "p_organization_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rule_id     UUID;
  v_mode        TEXT;
  v_assigned_to UUID;
  v_member_ids  UUID[];
BEGIN
  SELECT id, sdr_mode, sdr_assigned_to
    INTO v_rule_id, v_mode, v_assigned_to
  FROM public.pipe_distribution_rules
  WHERE organization_id = p_organization_id
    AND pipe_type = p_pipe_type
  LIMIT 1;

  IF v_rule_id IS NULL OR v_mode IS NULL THEN
    RETURN NULL;
  END IF;

  IF v_mode = 'single' AND v_assigned_to IS NOT NULL THEN
    RETURN v_assigned_to;
  END IF;

  -- Unified pool: all members for this rule, no role filter
  SELECT ARRAY_AGG(pdm.team_member_id ORDER BY pdm.created_at, pdm.team_member_id)
    INTO v_member_ids
  FROM public.pipe_distribution_members pdm
  WHERE pdm.rule_id = v_rule_id;

  IF v_member_ids IS NULL OR array_length(v_member_ids, 1) IS NULL THEN
    RETURN NULL;
  END IF;

  IF v_mode = 'random' THEN
    RETURN v_member_ids[1 + floor(random() * array_length(v_member_ids, 1))::int];
  END IF;

  IF v_mode = 'round_robin' THEN
    RETURN public.distribute_pipe_round_robin(p_pipe_type, p_organization_id, v_member_ids);
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."get_next_pipe_sdr"("p_pipe_type" "text", "p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_next_pipe_sdr"("p_pipe_type" "text", "p_organization_id" "uuid") IS 'Retorna team_member_id do próximo SDR a atribuir no pipe (round_robin, random ou single).';



CREATE OR REPLACE FUNCTION "public"."get_next_round_robin_member"("p_workflow_id" "uuid", "p_node_id" "text", "p_organization_id" "uuid", "p_member_ids" "uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_member_count integer;
  v_last_index integer;
  v_next_index integer;
  v_chosen_id uuid;
BEGIN
  v_member_count := array_length(p_member_ids, 1);
  IF v_member_count IS NULL OR v_member_count = 0 THEN
    RETURN NULL;
  END IF;

  -- Advisory lock to serialize concurrent calls for same workflow+node
  PERFORM pg_advisory_xact_lock(hashtext(p_workflow_id::text || '::' || p_node_id));

  -- Get or create state
  SELECT last_member_index INTO v_last_index
  FROM workflow_round_robin_state
  WHERE workflow_id = p_workflow_id AND node_id = p_node_id;

  IF NOT FOUND THEN
    v_last_index := -1;
    INSERT INTO workflow_round_robin_state (organization_id, workflow_id, node_id, last_member_index)
    VALUES (p_organization_id, p_workflow_id, p_node_id, -1);
  END IF;

  -- Next in sequence
  v_next_index := (v_last_index + 1) % v_member_count;
  v_chosen_id := p_member_ids[v_next_index + 1]; -- PG arrays are 1-indexed

  -- Update state
  UPDATE workflow_round_robin_state
  SET last_member_index = v_next_index, updated_at = now()
  WHERE workflow_id = p_workflow_id AND node_id = p_node_id;

  RETURN v_chosen_id;
END;
$$;


ALTER FUNCTION "public"."get_next_round_robin_member"("p_workflow_id" "uuid", "p_node_id" "text", "p_organization_id" "uuid", "p_member_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_operations_overview"("interval_param" "text" DEFAULT '24 hours'::"text") RETURNS json
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE WHEN public.is_master_user() THEN (
    SELECT json_build_object(
      'jobs_success', COUNT(*) FILTER (WHERE status = 'success'),
      'jobs_error',   COUNT(*) FILTER (WHERE status = 'error'),
      'jobs_total',   COUNT(*),
      'orgs_active',  COUNT(DISTINCT organization_id)
    ) FROM public.runtime_logs WHERE created_at > NOW() - interval_param::INTERVAL
  ) ELSE json_build_object('error','access_denied') END;
$$;


