ALTER FUNCTION "public"."get_phone_ai_status"("p_phone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_phone_ai_status"("p_phone" "text") IS 'Lê ai_disabled por telefone. Prioridade: phone_ai_preferences > leads (lead mais recente) > default(false). Retorna source indicando origem da resposta.';



CREATE OR REPLACE FUNCTION "public"."get_phone_ai_status"("p_phone" "text", "p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID; v_org_id UUID; v_normalized TEXT; v_ai_disabled BOOLEAN;
  v_source TEXT; v_lead_id UUID; v_is_member BOOLEAN; v_is_master BOOLEAN;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT EXISTS (SELECT 1 FROM public.master_users WHERE user_id = v_user_id AND is_active = true) INTO v_is_master;
  IF p_organization_id IS NOT NULL THEN
    IF v_is_master THEN
      v_org_id := p_organization_id;
    ELSE
      SELECT EXISTS (SELECT 1 FROM public.team_members WHERE user_id = v_user_id AND organization_id = p_organization_id AND is_active = true) INTO v_is_member;
      IF NOT v_is_member THEN RAISE EXCEPTION 'User is not an active member of organization %', p_organization_id; END IF;
      v_org_id := p_organization_id;
    END IF;
  ELSE
    SELECT organization_id INTO v_org_id FROM public.team_members WHERE user_id = v_user_id AND is_active = true LIMIT 1;
    IF v_org_id IS NULL THEN RAISE EXCEPTION 'User is not a member of any organization'; END IF;
  END IF;
  v_normalized := public.normalize_brazilian_phone(p_phone);
  IF v_normalized IS NULL OR length(v_normalized) = 0 THEN
    RETURN jsonb_build_object('ai_disabled', false, 'source', 'invalid_phone', 'normalized_phone', NULL);
  END IF;
  SELECT ai_disabled INTO v_ai_disabled FROM public.phone_ai_preferences WHERE organization_id = v_org_id AND normalized_phone = v_normalized;
  IF FOUND THEN v_source := 'preference';
  ELSE
    SELECT id, ai_disabled INTO v_lead_id, v_ai_disabled FROM public.leads WHERE organization_id = v_org_id AND normalized_phone = v_normalized ORDER BY created_at DESC LIMIT 1;
    IF FOUND THEN v_source := 'lead'; ELSE v_ai_disabled := false; v_source := 'default'; END IF;
  END IF;
  RETURN jsonb_build_object('ai_disabled', v_ai_disabled, 'source', v_source, 'organization_id', v_org_id, 'normalized_phone', v_normalized, 'lead_id', v_lead_id);
END; $$;


ALTER FUNCTION "public"."get_phone_ai_status"("p_phone" "text", "p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_phone_ai_status"("p_phone" "text", "p_organization_id" "uuid") IS 'H1 2026-04-26: aceita p_organization_id opcional. Frontend canônico passa org explicita pra evitar bug multi-org.';



CREATE OR REPLACE FUNCTION "public"."get_pipeline_page"("p_pipeline_slug" "text", "p_stage_id" "text", "p_org_id" "uuid", "p_page_size" integer DEFAULT 20, "p_cursor" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_search" "text" DEFAULT NULL::"text", "p_responsible_id" "uuid" DEFAULT NULL::"uuid", "p_tag_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_origins" "text"[] DEFAULT NULL::"text"[], "p_rating_min" integer DEFAULT NULL::integer, "p_rating_max" integer DEFAULT NULL::integer, "p_calor_min" integer DEFAULT NULL::integer, "p_calor_max" integer DEFAULT NULL::integer, "p_urgency" "text" DEFAULT NULL::"text", "p_product_type" "text" DEFAULT NULL::"text", "p_meeting_after" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_meeting_before" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_period_after" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_period_before" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_closed_status_keys" "text"[] DEFAULT NULL::"text"[], "p_updated_before" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_overdue_exclude_status_keys" "text"[] DEFAULT NULL::"text"[], "p_status_keys" "text"[] DEFAULT NULL::"text"[], "p_scheduled" boolean DEFAULT NULL::boolean, "p_qualification_tier" "text"[] DEFAULT NULL::"text"[], "p_pre_qualification_tier" "text"[] DEFAULT NULL::"text"[]) RETURNS TABLE("id" "uuid", "pipeline_id" "uuid", "lead_id" "uuid", "stage_key" "text", "assigned_to" "uuid", "notes" "text", "metadata" "jsonb", "entered_at" timestamp with time zone, "stage_changed_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "lead" "jsonb")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
DECLARE v_pipeline_id UUID;
BEGIN
  SELECT p.id INTO v_pipeline_id FROM public.pipelines p WHERE p.slug=p_pipeline_slug AND p.type='system' AND p.organization_id=p_org_id;
  IF v_pipeline_id IS NULL THEN RETURN; END IF;
  RETURN QUERY
  SELECT pe.id, pe.pipeline_id, pe.lead_id, pe.stage_key, pe.assigned_to, pe.notes, pe.metadata,
    pe.entered_at, pe.stage_changed_at, pe.created_at, pe.updated_at,
    jsonb_build_object(
      'id', l.id, 'name', l.name, 'company', l.company, 'email', l.email, 'phone', l.phone,
      'rating', l.rating, 'origin', l.origin, 'segment', l.segment, 'faturamento', l.faturamento,
      'urgency', l.urgency, 'notes', l.notes, 'compromisso_date', l.compromisso_date,
      'ai_disabled', l.ai_disabled, 'avatar_url', l.avatar_url,
      'pre_qualification_tier', l.pre_qualification_tier, 'qualification_tier', l.qualification_tier,
      'sdr_id', l.sdr_id, 'closer_id', l.closer_id, 'responsible_id', l.responsible_id,
      'pre_sale_responsible_id', l.pre_sale_responsible_id, 'sale_responsible_id', l.sale_responsible_id,
      'responsible', CASE WHEN tm_resp.id IS NOT NULL THEN jsonb_build_object('id', tm_resp.id, 'name', tm_resp.name, 'avatar_url', tm_resp.avatar_url) ELSE NULL END,
      'sdr', CASE WHEN tm_sdr.id IS NOT NULL THEN jsonb_build_object('id', tm_sdr.id, 'name', tm_sdr.name, 'avatar_url', tm_sdr.avatar_url) ELSE NULL END,
      'closer', CASE WHEN tm_closer.id IS NOT NULL THEN jsonb_build_object('id', tm_closer.id, 'name', tm_closer.name, 'avatar_url', tm_closer.avatar_url) ELSE NULL END,
      'pre_sale_responsible', CASE WHEN tm_pre.id IS NOT NULL THEN jsonb_build_object('id', tm_pre.id, 'name', tm_pre.name, 'avatar_url', tm_pre.avatar_url) ELSE NULL END,
      'sale_responsible', CASE WHEN tm_sale.id IS NOT NULL THEN jsonb_build_object('id', tm_sale.id, 'name', tm_sale.name, 'avatar_url', tm_sale.avatar_url) ELSE NULL END,
      'lead_tags', COALESCE((SELECT jsonb_agg(jsonb_build_object('tag', jsonb_build_object('id', t.id, 'name', t.name, 'color', t.color))) FROM public.lead_tags lt JOIN public.tags t ON t.id = lt.tag_id WHERE lt.lead_id = l.id), '[]'::jsonb)
    ) AS lead
  FROM public.pipeline_entries pe
  JOIN public.leads l ON l.id = pe.lead_id
  LEFT JOIN public.team_members tm_resp ON tm_resp.id = l.responsible_id
  LEFT JOIN public.team_members tm_sdr ON tm_sdr.id = l.sdr_id
  LEFT JOIN public.team_members tm_closer ON tm_closer.id = l.closer_id
  LEFT JOIN public.team_members tm_pre ON tm_pre.id = l.pre_sale_responsible_id
  LEFT JOIN public.team_members tm_sale ON tm_sale.id = l.sale_responsible_id
  WHERE pe.pipeline_id = v_pipeline_id AND pe.stage_key = p_stage_id AND pe.organization_id = p_org_id
    AND pe.lead_id IS NOT NULL AND (p_cursor IS NULL OR pe.created_at < p_cursor)
    AND (p_search IS NULL OR p_search = '' OR (l.name ILIKE '%' || p_search || '%' OR l.phone ILIKE '%' || p_search || '%' OR l.company ILIKE '%' || p_search || '%'))
    AND (p_responsible_id IS NULL OR ((pe.metadata->>'pre_sale_responsible_id')::UUID = p_responsible_id OR (pe.metadata->>'sale_responsible_id')::UUID = p_responsible_id OR l.pre_sale_responsible_id = p_responsible_id OR l.sale_responsible_id = p_responsible_id))
    AND (p_tag_ids IS NULL OR array_length(p_tag_ids, 1) IS NULL OR NOT EXISTS (SELECT unnest(p_tag_ids) EXCEPT SELECT lt2.tag_id FROM public.lead_tags lt2 WHERE lt2.lead_id = l.id))
    AND (p_qualification_tier IS NULL OR array_length(p_qualification_tier, 1) IS NULL OR l.qualification_tier::text = ANY(p_qualification_tier))
    AND (p_pre_qualification_tier IS NULL OR array_length(p_pre_qualification_tier, 1) IS NULL OR l.pre_qualification_tier::text = ANY(p_pre_qualification_tier))
    AND (p_origins IS NULL OR array_length(p_origins, 1) IS NULL OR l.origin::TEXT = ANY(p_origins))
    AND (p_rating_min IS NULL OR COALESCE(l.rating, 0) >= p_rating_min)
    AND (p_rating_max IS NULL OR COALESCE(l.rating, 0) <= p_rating_max)
    AND (p_calor_min IS NULL OR COALESCE(NULLIF(pe.metadata->>'calor', '')::INT, 5) >= p_calor_min)
    AND (p_calor_max IS NULL OR COALESCE(NULLIF(pe.metadata->>'calor', '')::INT, 5) <= p_calor_max)
    AND (p_urgency IS NULL OR l.urgency = p_urgency)
    AND (p_product_type IS NULL OR pe.metadata->>'product_type' = p_product_type)
    AND (p_meeting_after IS NULL OR NULLIF(pe.metadata->>'meeting_date', '')::TIMESTAMPTZ >= p_meeting_after)
    AND (p_meeting_before IS NULL OR NULLIF(pe.metadata->>'meeting_date', '')::TIMESTAMPTZ <= p_meeting_before)
    AND (p_period_after IS NULL OR (CASE WHEN p_closed_status_keys IS NOT NULL AND pe.stage_key = ANY(p_closed_status_keys) THEN COALESCE(NULLIF(pe.metadata->>'metrics_period_at', '')::TIMESTAMPTZ, pe.updated_at) ELSE pe.created_at END) >= p_period_after)
    AND (p_period_before IS NULL OR (CASE WHEN p_closed_status_keys IS NOT NULL AND pe.stage_key = ANY(p_closed_status_keys) THEN COALESCE(NULLIF(pe.metadata->>'metrics_period_at', '')::TIMESTAMPTZ, pe.updated_at) ELSE pe.created_at END) <= p_period_before)
    AND (p_updated_before IS NULL OR (pe.updated_at <= p_updated_before AND (p_overdue_exclude_status_keys IS NULL OR pe.stage_key <> ALL(p_overdue_exclude_status_keys))))
    AND (p_status_keys IS NULL OR array_length(p_status_keys, 1) IS NULL OR pe.stage_key = ANY(p_status_keys))
    AND (NOT COALESCE(p_scheduled, FALSE) OR EXISTS (SELECT 1 FROM public.scheduled_user_messages sm WHERE sm.lead_id = l.id AND sm.organization_id = p_org_id AND sm.status = 'scheduled'))
  ORDER BY pe.created_at DESC LIMIT p_page_size;
END;
$$;


ALTER FUNCTION "public"."get_pipeline_page"("p_pipeline_slug" "text", "p_stage_id" "text", "p_org_id" "uuid", "p_page_size" integer, "p_cursor" timestamp with time zone, "p_search" "text", "p_responsible_id" "uuid", "p_tag_ids" "uuid"[], "p_origins" "text"[], "p_rating_min" integer, "p_rating_max" integer, "p_calor_min" integer, "p_calor_max" integer, "p_urgency" "text", "p_product_type" "text", "p_meeting_after" timestamp with time zone, "p_meeting_before" timestamp with time zone, "p_period_after" timestamp with time zone, "p_period_before" timestamp with time zone, "p_closed_status_keys" "text"[], "p_updated_before" timestamp with time zone, "p_overdue_exclude_status_keys" "text"[], "p_status_keys" "text"[], "p_scheduled" boolean, "p_qualification_tier" "text"[], "p_pre_qualification_tier" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pipeline_stage_counts"("p_pipeline_slug" "text", "p_org_id" "uuid", "p_search" "text" DEFAULT NULL::"text", "p_responsible_id" "uuid" DEFAULT NULL::"uuid", "p_tag_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_origins" "text"[] DEFAULT NULL::"text"[], "p_rating_min" integer DEFAULT NULL::integer, "p_rating_max" integer DEFAULT NULL::integer, "p_calor_min" integer DEFAULT NULL::integer, "p_calor_max" integer DEFAULT NULL::integer, "p_urgency" "text" DEFAULT NULL::"text", "p_product_type" "text" DEFAULT NULL::"text", "p_meeting_after" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_meeting_before" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_period_after" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_period_before" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_closed_status_keys" "text"[] DEFAULT NULL::"text"[], "p_updated_before" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_overdue_exclude_status_keys" "text"[] DEFAULT NULL::"text"[], "p_status_keys" "text"[] DEFAULT NULL::"text"[], "p_scheduled" boolean DEFAULT NULL::boolean, "p_qualification_tier" "text"[] DEFAULT NULL::"text"[], "p_pre_qualification_tier" "text"[] DEFAULT NULL::"text"[]) RETURNS TABLE("stage_key" "text", "cnt" bigint)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
DECLARE v_pipeline_id UUID;
BEGIN
  SELECT p.id INTO v_pipeline_id FROM public.pipelines p WHERE p.slug=p_pipeline_slug AND p.type='system' AND p.organization_id=p_org_id;
  IF v_pipeline_id IS NULL THEN RETURN; END IF;
  RETURN QUERY
  SELECT pe.stage_key, COUNT(*)::BIGINT AS cnt
  FROM public.pipeline_entries pe
  JOIN public.leads l ON l.id = pe.lead_id
  WHERE pe.pipeline_id = v_pipeline_id AND pe.organization_id = p_org_id AND pe.lead_id IS NOT NULL
    AND (p_search IS NULL OR p_search = '' OR (l.name ILIKE '%' || p_search || '%' OR l.phone ILIKE '%' || p_search || '%' OR l.company ILIKE '%' || p_search || '%'))
    AND (p_responsible_id IS NULL OR ((pe.metadata->>'pre_sale_responsible_id')::UUID = p_responsible_id OR (pe.metadata->>'sale_responsible_id')::UUID = p_responsible_id OR l.pre_sale_responsible_id = p_responsible_id OR l.sale_responsible_id = p_responsible_id))
    AND (p_tag_ids IS NULL OR array_length(p_tag_ids, 1) IS NULL OR NOT EXISTS (SELECT unnest(p_tag_ids) EXCEPT SELECT lt2.tag_id FROM public.lead_tags lt2 WHERE lt2.lead_id = l.id))
    AND (p_qualification_tier IS NULL OR array_length(p_qualification_tier, 1) IS NULL OR l.qualification_tier::text = ANY(p_qualification_tier))
    AND (p_pre_qualification_tier IS NULL OR array_length(p_pre_qualification_tier, 1) IS NULL OR l.pre_qualification_tier::text = ANY(p_pre_qualification_tier))
    AND (p_origins IS NULL OR array_length(p_origins, 1) IS NULL OR l.origin::TEXT = ANY(p_origins))
    AND (p_rating_min IS NULL OR COALESCE(l.rating, 0) >= p_rating_min)
    AND (p_rating_max IS NULL OR COALESCE(l.rating, 0) <= p_rating_max)
    AND (p_calor_min IS NULL OR COALESCE(NULLIF(pe.metadata->>'calor', '')::INT, 5) >= p_calor_min)
    AND (p_calor_max IS NULL OR COALESCE(NULLIF(pe.metadata->>'calor', '')::INT, 5) <= p_calor_max)
    AND (p_urgency IS NULL OR l.urgency = p_urgency)
    AND (p_product_type IS NULL OR pe.metadata->>'product_type' = p_product_type)
    AND (p_meeting_after IS NULL OR NULLIF(pe.metadata->>'meeting_date', '')::TIMESTAMPTZ >= p_meeting_after)
    AND (p_meeting_before IS NULL OR NULLIF(pe.metadata->>'meeting_date', '')::TIMESTAMPTZ <= p_meeting_before)
    AND (p_period_after IS NULL OR (CASE WHEN p_closed_status_keys IS NOT NULL AND pe.stage_key = ANY(p_closed_status_keys) THEN COALESCE(NULLIF(pe.metadata->>'metrics_period_at', '')::TIMESTAMPTZ, pe.updated_at) ELSE pe.created_at END) >= p_period_after)
    AND (p_period_before IS NULL OR (CASE WHEN p_closed_status_keys IS NOT NULL AND pe.stage_key = ANY(p_closed_status_keys) THEN COALESCE(NULLIF(pe.metadata->>'metrics_period_at', '')::TIMESTAMPTZ, pe.updated_at) ELSE pe.created_at END) <= p_period_before)
    AND (p_updated_before IS NULL OR (pe.updated_at <= p_updated_before AND (p_overdue_exclude_status_keys IS NULL OR pe.stage_key <> ALL(p_overdue_exclude_status_keys))))
    AND (p_status_keys IS NULL OR array_length(p_status_keys, 1) IS NULL OR pe.stage_key = ANY(p_status_keys))
    AND (NOT COALESCE(p_scheduled, FALSE) OR EXISTS (SELECT 1 FROM public.scheduled_user_messages sm WHERE sm.lead_id = l.id AND sm.organization_id = p_org_id AND sm.status = 'scheduled'))
  GROUP BY pe.stage_key;
END;
$$;


ALTER FUNCTION "public"."get_pipeline_stage_counts"("p_pipeline_slug" "text", "p_org_id" "uuid", "p_search" "text", "p_responsible_id" "uuid", "p_tag_ids" "uuid"[], "p_origins" "text"[], "p_rating_min" integer, "p_rating_max" integer, "p_calor_min" integer, "p_calor_max" integer, "p_urgency" "text", "p_product_type" "text", "p_meeting_after" timestamp with time zone, "p_meeting_before" timestamp with time zone, "p_period_after" timestamp with time zone, "p_period_before" timestamp with time zone, "p_closed_status_keys" "text"[], "p_updated_before" timestamp with time zone, "p_overdue_exclude_status_keys" "text"[], "p_status_keys" "text"[], "p_scheduled" boolean, "p_qualification_tier" "text"[], "p_pre_qualification_tier" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pipeline_velocity"("p_pipeline_type" "text", "p_start_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_result jsonb;
BEGIN
  SELECT tm.organization_id INTO v_org_id
  FROM team_members tm WHERE tm.user_id = auth.uid() LIMIT 1;

  IF v_org_id IS NULL THEN RETURN '{}'::jsonb; END IF;

  -- Velocity = (num_deals * win_rate * avg_value) / avg_cycle_days
  WITH won_deals AS (
    SELECT
      COUNT(*) AS num_won,
      COALESCE(AVG((pe.metadata->>'sale_value')::numeric), 0) AS avg_value
    FROM pipeline_entries pe
    JOIN pipelines pip ON pip.id = pe.pipeline_id AND pip.slug = COALESCE(p_pipeline_type, 'propostas') AND pip.type = 'system'
    WHERE pe.organization_id = v_org_id
      AND pe.stage_key = 'vendido'
      AND (p_start_date IS NULL OR pe.created_at >= p_start_date)
      AND (p_end_date IS NULL OR pe.created_at <= p_end_date)
  ),
  all_deals AS (
    SELECT COUNT(*) AS total
    FROM pipeline_entries pe
    JOIN pipelines pip ON pip.id = pe.pipeline_id AND pip.slug = COALESCE(p_pipeline_type, 'propostas') AND pip.type = 'system'
    WHERE pe.organization_id = v_org_id
      AND pe.stage_key IN ('vendido', 'perdido')
      AND (p_start_date IS NULL OR pe.created_at >= p_start_date)
      AND (p_end_date IS NULL OR pe.created_at <= p_end_date)
  )
  SELECT jsonb_build_object(
    'num_won', COALESCE(w.num_won, 0),
    'total_closed', COALESCE(a.total, 0),
    'win_rate', CASE WHEN a.total > 0 THEN ROUND(w.num_won::numeric / a.total * 100, 1) ELSE 0 END,
    'avg_deal_value', ROUND(w.avg_value::numeric, 2)
  ) INTO v_result
  FROM won_deals w, all_deals a;

  RETURN COALESCE(v_result, '{}'::jsonb);
END;
$$;


ALTER FUNCTION "public"."get_pipeline_velocity"("p_pipeline_type" "text", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_portfolio_clients"("p_org_id" "uuid", "p_filter" "text" DEFAULT 'all'::"text", "p_search" "text" DEFAULT ''::"text", "p_sort_by" "text" DEFAULT 'name'::"text", "p_sort_dir" "text" DEFAULT 'asc'::"text", "p_page" integer DEFAULT 1, "p_page_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_offset       INT := (p_page - 1) * p_page_size;
  v_total        INT;
  v_rows         JSONB;
  v_allowed_sorts TEXT[] := ARRAY[
    'name', 'health_score', 'avg_ticket', 'days_since_last_order',
    'next_order_expected', 'lifetime_value', 'order_count', 'churn_probability'
  ];
  v_sort         TEXT;
  v_dir          TEXT;
  v_where        TEXT;
BEGIN
  PERFORM public.assert_org_access(p_org_id);
  PERFORM assert_org_member(p_org_id);

  IF p_sort_by = ANY(v_allowed_sorts) THEN
    v_sort := p_sort_by;
  ELSE
    v_sort := 'name';
  END IF;

  IF lower(p_sort_dir) = 'desc' THEN
    v_dir := 'DESC';
  ELSE
    v_dir := 'ASC';
  END IF;

  v_where := format('organization_id = %L AND is_active = true', p_org_id);

  IF p_search IS NOT NULL AND p_search <> '' THEN
    v_where := v_where || format(
      ' AND (name ILIKE %L OR company ILIKE %L)',
      '%' || p_search || '%',
      '%' || p_search || '%'
    );
  END IF;

  IF p_filter = 'overdue' THEN
    v_where := v_where
      || ' AND days_since_last_order IS NOT NULL'
      || ' AND reorder_cycle_days IS NOT NULL'
      || ' AND days_since_last_order > reorder_cycle_days * 1.15';
  ELSIF p_filter = 'expected' THEN
    v_where := v_where
      || ' AND next_order_expected IS NOT NULL'
      || ' AND next_order_expected >= NOW()'
      || ' AND next_order_expected <= NOW() + INTERVAL ''7 days''';
  ELSIF p_filter IN ('ouro', 'prata', 'novo', 'resgate', 'dormindo') THEN
    v_where := v_where || format(' AND segment = %L', p_filter);
  END IF;

  EXECUTE format('SELECT COUNT(*)::int FROM upsell_clients WHERE %s', v_where)
    INTO v_total;

  EXECUTE format(
    $q$
    SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
    FROM (
      SELECT id, name, company, phone, health_score, health_status, segment,
             avg_ticket, days_since_last_order, reorder_cycle_days,
             next_order_expected, order_count, lifetime_value, lead_id, trend,
             churn_probability
      FROM upsell_clients
      WHERE %s
      ORDER BY %I %s NULLS LAST
      LIMIT %s OFFSET %s
    ) t
    $q$,
    v_where, v_sort, v_dir, p_page_size, v_offset
  ) INTO v_rows;

  RETURN jsonb_build_object(
    'rows',        COALESCE(v_rows, '[]'::jsonb),
    'total',       v_total,
    'page',        p_page,
    'page_size',   p_page_size,
    'total_pages', GREATEST(CEIL(v_total::numeric / p_page_size)::int, 1)
  );
EXCEPTION
  WHEN OTHERS THEN
    IF SQLERRM = 'access_denied' THEN
      RETURN jsonb_build_object(
        'rows', '[]'::jsonb, 'total', 0,
        'page', p_page, 'page_size', p_page_size, 'total_pages', 1
      );
    END IF;
    RAISE;
END;
$_$;


ALTER FUNCTION "public"."get_portfolio_clients"("p_org_id" "uuid", "p_filter" "text", "p_search" "text", "p_sort_by" "text", "p_sort_dir" "text", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_portfolio_kpis"("p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM public.assert_org_access(p_org_id);
  PERFORM assert_org_member(p_org_id);

  RETURN (
    SELECT jsonb_build_object(
      'total_clients',      COUNT(*)::int,
      'total_recurring',    COALESCE(SUM(
                              avg_ticket * (30.0 / GREATEST(COALESCE(reorder_cycle_days, 30), 1))
                            ), 0)::numeric,
      'overdue_count',      COUNT(*) FILTER (
                              WHERE days_since_last_order IS NOT NULL
                                AND reorder_cycle_days IS NOT NULL
                                AND days_since_last_order > reorder_cycle_days * 1.15
                            )::int,
      'overdue_revenue',    COALESCE(SUM(avg_ticket) FILTER (
                              WHERE days_since_last_order IS NOT NULL
                                AND reorder_cycle_days IS NOT NULL
                                AND days_since_last_order > reorder_cycle_days * 1.15
                            ), 0)::numeric,
      'avg_health',         COALESCE(ROUND(AVG(health_score)), 0)::int,
      'avg_ticket',         CASE WHEN COUNT(*) > 0
                              THEN ROUND(COALESCE(SUM(avg_ticket), 0) / COUNT(*))::numeric
                              ELSE 0
                            END,
      'expected_this_week', COUNT(*) FILTER (
                              WHERE next_order_expected IS NOT NULL
                                AND next_order_expected >= NOW()
                                AND next_order_expected <= NOW() + INTERVAL '7 days'
                            )::int,
      'segment_counts',     jsonb_build_object(
                              'ouro',     COUNT(*) FILTER (WHERE segment = 'ouro')::int,
                              'prata',    COUNT(*) FILTER (WHERE segment = 'prata')::int,
                              'novo',     COUNT(*) FILTER (WHERE segment = 'novo')::int,
                              'resgate',  COUNT(*) FILTER (WHERE segment = 'resgate')::int,
                              'dormindo', COUNT(*) FILTER (WHERE segment = 'dormindo')::int
                            )
    )
    FROM upsell_clients
    WHERE organization_id = p_org_id
      AND is_active = true
  );
EXCEPTION
  WHEN OTHERS THEN
    IF SQLERRM = 'access_denied' THEN RETURN NULL; END IF;
    RAISE;
END;
$$;


ALTER FUNCTION "public"."get_portfolio_kpis"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_portfolio_trends"("p_org_id" "uuid", "p_months" integer DEFAULT 6) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result JSONB;
  v_revenue JSONB;
  v_health JSONB;
  v_retention JSONB;
  v_churn JSONB;
  v_segments JSONB;
  v_start_date DATE;
BEGIN
  PERFORM public.assert_org_access(p_org_id);
  v_start_date := date_trunc('month', CURRENT_DATE - (p_months || ' months')::interval)::date;

  -- 1. Revenue monthly (approved vs pending)
  SELECT COALESCE(jsonb_agg(row_data ORDER BY month), '[]'::jsonb)
  INTO v_revenue
  FROM (
    SELECT jsonb_build_object(
      'month', to_char(date_trunc('month', o.sold_at), 'YYYY-MM'),
      'approved', COALESCE(SUM(o.sale_value) FILTER (WHERE o.approval_status = 'approved'), 0),
      'pending', COALESCE(SUM(o.sale_value) FILTER (WHERE o.approval_status = 'pending'), 0)
    ) AS row_data,
    date_trunc('month', o.sold_at) AS month
    FROM upsell_orders o
    JOIN upsell_clients c ON c.id = o.client_id
    WHERE c.organization_id = p_org_id
      AND o.sold_at >= v_start_date
    GROUP BY date_trunc('month', o.sold_at)
  ) sub;

  -- 2. Health daily (last 30 days, org-wide average)
  SELECT COALESCE(jsonb_agg(row_data ORDER BY d), '[]'::jsonb)
  INTO v_health
  FROM (
    SELECT jsonb_build_object(
      'date', s.snapshot_date::text,
      'avg_score', ROUND(AVG(s.health_score))
    ) AS row_data,
    s.snapshot_date AS d
    FROM client_health_snapshots s
    WHERE s.organization_id = p_org_id
      AND s.snapshot_date >= CURRENT_DATE - 30
    GROUP BY s.snapshot_date
  ) sub;

  -- 3. Retention monthly (M1 retention per cohort from view)
  SELECT COALESCE(jsonb_agg(row_data ORDER BY cm), '[]'::jsonb)
  INTO v_retention
  FROM (
    SELECT jsonb_build_object(
      'month', to_char(cohort_month, 'YYYY-MM'),
      'rate', CASE WHEN SUM(total_clients) > 0
        THEN ROUND(SUM(active_clients)::numeric / SUM(total_clients) * 100)
        ELSE 0
      END
    ) AS row_data,
    cohort_month AS cm
    FROM portfolio_retention_cohorts
    WHERE organization_id = p_org_id
      AND month_offset = 1
      AND cohort_month >= v_start_date
    GROUP BY cohort_month
  ) sub;

  -- 4. Churn summary (clients with churn_probability > 50)
  SELECT jsonb_build_object(
    'count', COUNT(*)::int,
    'total_value', COALESCE(SUM(avg_ticket), 0)::numeric
  )
  INTO v_churn
  FROM upsell_clients
  WHERE organization_id = p_org_id
    AND is_active = true
    AND churn_probability > 50;

  -- 5. Segment monthly (from snapshots)
  SELECT COALESCE(jsonb_agg(row_data ORDER BY m), '[]'::jsonb)
  INTO v_segments
  FROM (
    SELECT jsonb_build_object(
      'month', to_char(date_trunc('month', s.snapshot_date), 'YYYY-MM'),
      'ouro', COUNT(*) FILTER (WHERE s.segment = 'ouro'),
      'prata', COUNT(*) FILTER (WHERE s.segment = 'prata'),
      'novo', COUNT(*) FILTER (WHERE s.segment = 'novo'),
      'resgate', COUNT(*) FILTER (WHERE s.segment = 'resgate'),
      'dormindo', COUNT(*) FILTER (WHERE s.segment = 'dormindo')
    ) AS row_data,
    date_trunc('month', s.snapshot_date) AS m
    FROM client_health_snapshots s
    WHERE s.organization_id = p_org_id
      AND s.snapshot_date >= v_start_date
    GROUP BY date_trunc('month', s.snapshot_date)
  ) sub;

  v_result := jsonb_build_object(
    'revenue_monthly', v_revenue,
    'health_daily', v_health,
    'retention_monthly', v_retention,
    'churn_summary', v_churn,
    'segment_monthly', v_segments
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_portfolio_trends"("p_org_id" "uuid", "p_months" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_product_ranking"("p_org_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE result JSONB;
BEGIN
  PERFORM public.assert_org_access(p_org_id);
  SELECT COALESCE(jsonb_agg(row_to_json(ranked) ORDER BY ranked.total_value DESC), '[]'::jsonb)
  INTO result
  FROM (
    SELECT p.id AS product_id, p.name AS product_name, p.type AS product_type,
      COUNT(DISTINCT ppi.pipe_proposta_id) AS qty_sold,
      SUM(COALESCE(ppi.sale_value, 0)) AS total_value,
      CASE WHEN COUNT(DISTINCT ppi.pipe_proposta_id) > 0
        THEN ROUND(SUM(COALESCE(ppi.sale_value, 0)) / COUNT(DISTINCT ppi.pipe_proposta_id), 2) ELSE 0 END AS ticket_medio
    FROM pipe_proposta_items ppi
    JOIN pipe_propostas pp ON pp.id = ppi.pipe_proposta_id
    JOIN products p ON p.id = ppi.product_id
    WHERE pp.organization_id = p_org_id AND pp.status = 'vendido'
      AND COALESCE(pp.metrics_period_at, pp.closed_at) >= p_start_date
      AND COALESCE(pp.metrics_period_at, pp.closed_at) <= p_end_date
    GROUP BY p.id, p.name, p.type ORDER BY total_value DESC LIMIT 10
  ) ranked;
  RETURN result;
END; $$;


ALTER FUNCTION "public"."get_product_ranking"("p_org_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_productivity_activity"("p_org_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_seller" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_novos       int := 0;
  v_marcadas    int := 0;
  v_realizadas  int := 0;
  v_vendido     int := 0;
BEGIN
  PERFORM public.assert_org_access(p_org_id);

  SELECT count(*) INTO v_novos
  FROM public.leads l
  WHERE l.organization_id = p_org_id
    AND l.deleted_at IS NULL
    AND l.created_at >= p_from
    AND l.created_at <= p_to
    AND (p_seller IS NULL OR COALESCE(l.responsible_id, l.sdr_id) = p_seller);

  SELECT count(*) INTO v_marcadas
  FROM public.meeting_events me
  WHERE me.organization_id = p_org_id
    AND me.event_type = 'meeting_booked'
    AND me.occurred_at >= p_from
    AND me.occurred_at <= p_to
    AND (p_seller IS NULL OR me.pre_sale_responsible_id = p_seller);

  SELECT count(*) INTO v_realizadas
  FROM public.meeting_events me
  WHERE me.organization_id = p_org_id
    AND me.event_type = 'meeting_held'
    AND me.meeting_date IS NOT NULL
    AND me.meeting_date >= p_from
    AND me.meeting_date <= p_to
    AND (p_seller IS NULL OR me.pre_sale_responsible_id = p_seller);

  SELECT count(*) INTO v_vendido
  FROM (
    SELECT
      pe.lead_id,
      COALESCE(l.sale_responsible_id, l.closer_id, (pe.metadata->>'closer_id')::uuid) AS closer_id,
      COALESCE(
        (
          SELECT min(lh.created_at)
          FROM public.lead_history lh
          WHERE lh.lead_id = pe.lead_id
            AND lh.organization_id = p_org_id
            AND (
                 (lh.action = 'stage_changed' AND lh.metadata->>'to_stage' = 'vendido')
              OR (lh.action = 'proposal_status_changed' AND lh.description ILIKE '%vendido%')
            )
        ),
        pe.closed_at,
        pe.stage_changed_at
      ) AS sold_at
    FROM public.pipeline_entries pe
    JOIN public.pipelines pip
      ON pip.id = pe.pipeline_id AND pip.slug = 'propostas' AND pip.type = 'system'
    JOIN public.leads l
      ON l.id = pe.lead_id AND l.deleted_at IS NULL
    WHERE pe.organization_id = p_org_id
      AND pe.stage_key = 'vendido'
  ) s
  WHERE s.sold_at IS NOT NULL
    AND s.sold_at >= p_from
    AND s.sold_at <= p_to
    AND (p_seller IS NULL OR s.closer_id = p_seller);

  RETURN jsonb_build_object(
    'novos_leads',         v_novos,
    'reunioes_marcadas',   v_marcadas,
    'reunioes_realizadas', v_realizadas,
    'vendido',             v_vendido,
    'from',                p_from,
    'to',                  p_to,
    'seller',              p_seller
  );
END;
$$;


ALTER FUNCTION "public"."get_productivity_activity"("p_org_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_seller" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_productivity_activity_by_seller"("p_org_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  result jsonb;
BEGIN
  PERFORM public.assert_org_access(p_org_id);

  WITH members AS (
    SELECT tm.id, tm.name, tm.metric_type::text AS metric_type
    FROM public.team_members tm
    WHERE tm.organization_id = p_org_id
      AND tm.is_active = true
  ),
  marcadas AS (
    SELECT me.pre_sale_responsible_id AS sid, count(*) AS c
    FROM public.meeting_events me
    WHERE me.organization_id = p_org_id
      AND me.event_type = 'meeting_booked'
      AND me.occurred_at >= p_from AND me.occurred_at <= p_to
      AND me.pre_sale_responsible_id IS NOT NULL
    GROUP BY 1
  ),
  realizadas AS (
    SELECT me.pre_sale_responsible_id AS sid, count(*) AS c
    FROM public.meeting_events me
    WHERE me.organization_id = p_org_id
      AND me.event_type = 'meeting_held'
      AND me.meeting_date IS NOT NULL
      AND me.meeting_date >= p_from AND me.meeting_date <= p_to
      AND me.pre_sale_responsible_id IS NOT NULL
    GROUP BY 1
  ),
  novos AS (
    SELECT COALESCE(l.responsible_id, l.sdr_id) AS sid, count(*) AS c
    FROM public.leads l
    WHERE l.organization_id = p_org_id
      AND l.deleted_at IS NULL
      AND l.created_at >= p_from AND l.created_at <= p_to
      AND COALESCE(l.responsible_id, l.sdr_id) IS NOT NULL
    GROUP BY 1
  ),
  vendido AS (
    SELECT s.closer_id AS sid, count(*) AS c
    FROM (
      SELECT
        pe.lead_id,
        COALESCE(l.sale_responsible_id, l.closer_id, (pe.metadata->>'closer_id')::uuid) AS closer_id,
        COALESCE(
          (
            SELECT min(lh.created_at)
            FROM public.lead_history lh
            WHERE lh.lead_id = pe.lead_id
              AND lh.organization_id = p_org_id
              AND (
                   (lh.action = 'stage_changed' AND lh.metadata->>'to_stage' = 'vendido')
                OR (lh.action = 'proposal_status_changed' AND lh.description ILIKE '%vendido%')
              )
          ),
          pe.closed_at,
          pe.stage_changed_at
        ) AS sold_at
      FROM public.pipeline_entries pe
      JOIN public.pipelines pip
        ON pip.id = pe.pipeline_id AND pip.slug = 'propostas' AND pip.type = 'system'
      JOIN public.leads l
        ON l.id = pe.lead_id AND l.deleted_at IS NULL
      WHERE pe.organization_id = p_org_id
        AND pe.stage_key = 'vendido'
    ) s
    WHERE s.sold_at IS NOT NULL
      AND s.sold_at >= p_from AND s.sold_at <= p_to
      AND s.closer_id IS NOT NULL
    GROUP BY 1
  )
  SELECT COALESCE(
    jsonb_agg(
      to_jsonb(t)
      ORDER BY t.reunioes_realizadas DESC, t.reunioes_marcadas DESC, t.vendido DESC
    ),
    '[]'::jsonb
  )
  INTO result
  FROM (
    SELECT
      m.id                        AS seller_id,
      m.name                      AS seller_name,
      m.metric_type               AS metric_type,
      COALESCE(n.c, 0)::int       AS novos_leads,
      COALESCE(mk.c, 0)::int      AS reunioes_marcadas,
      COALESCE(r.c, 0)::int       AS reunioes_realizadas,
      COALESCE(v.c, 0)::int       AS vendido
    FROM members m
    LEFT JOIN marcadas   mk ON mk.sid = m.id
    LEFT JOIN realizadas r  ON r.sid  = m.id
    LEFT JOIN novos      n  ON n.sid  = m.id
    LEFT JOIN vendido    v  ON v.sid  = m.id
    WHERE COALESCE(mk.c,0) + COALESCE(r.c,0) + COALESCE(v.c,0) + COALESCE(n.c,0) > 0
  ) t;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_productivity_activity_by_seller"("p_org_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_productivity_activity_leads"("p_org_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_count_type" "text", "p_seller" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rows jsonb := '[]'::jsonb;
BEGIN
  PERFORM public.assert_org_access(p_org_id);

  IF p_count_type = 'novos_leads' THEN
    SELECT COALESCE(jsonb_agg(r ORDER BY (r->>'action_at') DESC), '[]'::jsonb) INTO v_rows
    FROM (
      SELECT jsonb_build_object(
               'lead_id',     l.id,
               'lead_name',   l.name,
               'company',     l.company,
               'seller_id',   tm.id,
               'seller_name', tm.name,
               'action_at',   l.created_at
             ) AS r
      FROM public.leads l
      LEFT JOIN public.team_members tm ON tm.id = COALESCE(l.responsible_id, l.sdr_id)
      WHERE l.organization_id = p_org_id
        AND l.deleted_at IS NULL
        AND l.created_at >= p_from
        AND l.created_at <= p_to
        AND (p_seller IS NULL OR COALESCE(l.responsible_id, l.sdr_id) = p_seller)
    ) q;

  ELSIF p_count_type = 'reunioes_marcadas' THEN
    SELECT COALESCE(jsonb_agg(r ORDER BY (r->>'action_at') DESC), '[]'::jsonb) INTO v_rows
    FROM (
      SELECT jsonb_build_object(
               'lead_id',     l.id,
               'lead_name',   l.name,
               'company',     l.company,
               'seller_id',   tm.id,
               'seller_name', tm.name,
               'action_at',   me.occurred_at
             ) AS r
      FROM public.meeting_events me
      JOIN public.leads l ON l.id = me.lead_id
      LEFT JOIN public.team_members tm ON tm.id = me.pre_sale_responsible_id
      WHERE me.organization_id = p_org_id
        AND me.event_type = 'meeting_booked'
        AND me.occurred_at >= p_from
        AND me.occurred_at <= p_to
        AND (p_seller IS NULL OR me.pre_sale_responsible_id = p_seller)
    ) q;

  ELSIF p_count_type = 'reunioes_realizadas' THEN
    SELECT COALESCE(jsonb_agg(r ORDER BY (r->>'action_at') DESC), '[]'::jsonb) INTO v_rows
    FROM (
      SELECT jsonb_build_object(
               'lead_id',     l.id,
               'lead_name',   l.name,
               'company',     l.company,
               'seller_id',   tm.id,
               'seller_name', tm.name,
               'action_at',   me.meeting_date
             ) AS r
      FROM public.meeting_events me
      JOIN public.leads l ON l.id = me.lead_id
      LEFT JOIN public.team_members tm ON tm.id = me.pre_sale_responsible_id
      WHERE me.organization_id = p_org_id
        AND me.event_type = 'meeting_held'
        AND me.meeting_date IS NOT NULL
        AND me.meeting_date >= p_from
        AND me.meeting_date <= p_to
        AND (p_seller IS NULL OR me.pre_sale_responsible_id = p_seller)
    ) q;

  ELSIF p_count_type = 'vendido' THEN
    SELECT COALESCE(jsonb_agg(r ORDER BY (r->>'action_at') DESC), '[]'::jsonb) INTO v_rows
    FROM (
      SELECT jsonb_build_object(
               'lead_id',     s.lead_id,
               'lead_name',   s.lead_name,
               'company',     s.company,
               'seller_id',   tm.id,
               'seller_name', tm.name,
               'action_at',   s.sold_at
             ) AS r
      FROM (
        SELECT
          pe.lead_id,
          l.name    AS lead_name,
          l.company AS company,
          COALESCE(l.sale_responsible_id, l.closer_id, (pe.metadata->>'closer_id')::uuid) AS closer_id,
          COALESCE(
            (
              SELECT min(lh.created_at)
              FROM public.lead_history lh
              WHERE lh.lead_id = pe.lead_id
                AND lh.organization_id = p_org_id
                AND (
                     (lh.action = 'stage_changed' AND lh.metadata->>'to_stage' = 'vendido')
                  OR (lh.action = 'proposal_status_changed' AND lh.description ILIKE '%vendido%')
                )
            ),
            pe.closed_at,
            pe.stage_changed_at
          ) AS sold_at
        FROM public.pipeline_entries pe
        JOIN public.pipelines pip
          ON pip.id = pe.pipeline_id AND pip.slug = 'propostas' AND pip.type = 'system'
        JOIN public.leads l
          ON l.id = pe.lead_id AND l.deleted_at IS NULL
        WHERE pe.organization_id = p_org_id
          AND pe.stage_key = 'vendido'
      ) s
      LEFT JOIN public.team_members tm ON tm.id = s.closer_id
      WHERE s.sold_at IS NOT NULL
        AND s.sold_at >= p_from
        AND s.sold_at <= p_to
        AND (p_seller IS NULL OR s.closer_id = p_seller)
    ) q;

  ELSE
    RAISE EXCEPTION 'invalid p_count_type: %', p_count_type USING ERRCODE = 'P0001';
  END IF;

  RETURN v_rows;
END;
$$;


ALTER FUNCTION "public"."get_productivity_activity_leads"("p_org_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_count_type" "text", "p_seller" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_proposal_no_reply_candidates"("p_organization_id" "uuid", "p_stage_keys" "text"[]) RETURNS TABLE("lead_id" "uuid", "propostas_stage" "text", "last_inbound_at" timestamp with time zone, "last_outbound_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH prop AS (
    SELECT pe.lead_id, pe.stage_key
    FROM pipeline_entries pe
    JOIN pipelines p ON p.id = pe.pipeline_id AND p.slug = 'propostas' AND p.type = 'system'
    WHERE pe.organization_id = p_organization_id
      AND pe.stage_key = ANY(p_stage_keys)
  )
  SELECT
    pr.lead_id,
    pr.stage_key AS propostas_stage,
    (SELECT max(wm.timestamp) FROM whatsapp_messages wm
       WHERE wm.lead_id = pr.lead_id AND wm.organization_id = p_organization_id
         AND wm.direction = 'incoming') AS last_inbound_at,
    (SELECT max(wm.timestamp) FROM whatsapp_messages wm
       WHERE wm.lead_id = pr.lead_id AND wm.organization_id = p_organization_id
         AND wm.direction = 'outgoing') AS last_outbound_at
  FROM prop pr;
$$;


ALTER FUNCTION "public"."get_proposal_no_reply_candidates"("p_organization_id" "uuid", "p_stage_keys" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_proposal_no_reply_candidates"("p_organization_id" "uuid", "p_stage_keys" "text"[]) IS 'Leads in the proposal_no_reply trigger stages for an org, with last inbound/outbound message timestamps. Consumed by the situation follow-up worker (ADR-0006).';



CREATE OR REPLACE FUNCTION "public"."get_ranking"("p_org_id" "uuid", "p_period" "text", "p_ref" "date" DEFAULT NULL::"date", "p_start" "date" DEFAULT NULL::"date", "p_end" "date" DEFAULT NULL::"date", "p_pipeline_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_bounds tstzrange; v_rev_total numeric; v_cnt_total integer;
  v_ranking jsonb; v_unattr_rev numeric; v_unattr_cnt integer;
BEGIN
  PERFORM public.assert_org_access(p_org_id);
  v_bounds := public.metric_period_bounds(p_org_id, p_period, p_ref, p_start, p_end);

  SELECT COALESCE(SUM(w.sale_value), 0), COUNT(*)
  INTO v_rev_total, v_cnt_total
  FROM public.sale_events w
  WHERE w.organization_id = p_org_id AND w.event_type = 'sale' AND w.sold_at <@ v_bounds
    AND (p_pipeline_id IS NULL OR w.pipeline_id = p_pipeline_id)
    AND NOT EXISTS (SELECT 1 FROM public.sale_events r WHERE r.event_type = 'sale_reversed' AND r.reversed_event_id = w.id);

  WITH g AS (
    SELECT w.sale_responsible_id, COALESCE(SUM(w.sale_value), 0) AS revenue, COUNT(*)::int AS sale_count
    FROM public.sale_events w
    WHERE w.organization_id = p_org_id AND w.event_type = 'sale' AND w.sold_at <@ v_bounds
      AND (p_pipeline_id IS NULL OR w.pipeline_id = p_pipeline_id)
      AND NOT EXISTS (SELECT 1 FROM public.sale_events r WHERE r.event_type = 'sale_reversed' AND r.reversed_event_id = w.id)
    GROUP BY w.sale_responsible_id
  )
  SELECT
    (SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'member_id', ranked.sale_responsible_id, 'revenue', ranked.revenue, 'sale_count', ranked.sale_count, 'rank', ranked.rnk,
        'revenue_share', CASE WHEN v_rev_total > 0 THEN round(ranked.revenue / v_rev_total * 100, 2) ELSE 0 END
      ) ORDER BY ranked.rnk), '[]'::jsonb)
      FROM (
        SELECT g2.sale_responsible_id, g2.revenue, g2.sale_count,
          row_number() OVER (ORDER BY g2.revenue DESC, g2.sale_count DESC) AS rnk
        FROM g g2 WHERE g2.sale_responsible_id IS NOT NULL
      ) ranked),
    COALESCE(SUM(g.revenue) FILTER (WHERE g.sale_responsible_id IS NULL), 0),
    COALESCE(SUM(g.sale_count) FILTER (WHERE g.sale_responsible_id IS NULL), 0)::int
  INTO v_ranking, v_unattr_rev, v_unattr_cnt
  FROM g;

  RETURN jsonb_build_object(
    'period', jsonb_build_object('name', p_period, 'start', lower(v_bounds), 'end', upper(v_bounds)),
    'pipeline_id', p_pipeline_id, 'revenue_total', v_rev_total, 'sale_count_total', v_cnt_total,
    'ranking', v_ranking,
    'unattributed', jsonb_build_object('revenue', v_unattr_rev, 'sale_count', v_unattr_cnt)
  );
END;
$$;


ALTER FUNCTION "public"."get_ranking"("p_org_id" "uuid", "p_period" "text", "p_ref" "date", "p_start" "date", "p_end" "date", "p_pipeline_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_ranking"("p_org_id" "uuid", "p_period" "text", "p_ref" "date", "p_start" "date", "p_end" "date", "p_pipeline_id" "uuid") IS 'ADR-0017 §2-5,§8 / #997 — leaderboard canônico de venda. RESSALVA custom-pipeline (FIX-6): shape custom-agnóstico, mas custom_pipeline_stages sem governança de stage_role → venda custom não emite sale_event e não aparece até essa governança chegar. Extensão: metric_stage_role.';



CREATE OR REPLACE FUNCTION "public"."get_ranking_data"("p_month" integer, "p_year" integer, "p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id UUID;
  v_start_ts TIMESTAMPTZ;
  v_end_ts TIMESTAMPTZ;
  v_sales_ranking JSONB;
  v_meetings_ranking JSONB;
BEGIN
  IF p_organization_id IS NOT NULL THEN
    v_org_id := p_organization_id;
  ELSE
    SELECT tm.organization_id INTO v_org_id
    FROM public.team_members tm WHERE tm.user_id = auth.uid() AND tm.is_active = true
    LIMIT 1;
  END IF;

  IF v_org_id IS NULL THEN
    RETURN jsonb_build_object('salesRanking', '[]'::jsonb, 'meetingsRanking', '[]'::jsonb);
  END IF;

  v_start_ts := make_timestamptz(p_year, p_month, 1, 0, 0, 0, 'UTC');
  v_end_ts := ((make_date(p_year, p_month, 1) + interval '1 month' - interval '1 day')::date + time '23:59:59.999') AT TIME ZONE 'UTC';

  WITH sales_agg AS (
    SELECT COALESCE(pp.sale_responsible_id, pp.responsible_id, pp.closer_id) AS member_id,
           SUM(COALESCE(pp.sale_value, 0))::numeric AS total_value,
           COUNT(*)::int AS conversions
    FROM public.pipe_propostas pp
    WHERE pp.organization_id = v_org_id
      AND pp.status = 'vendido'
      AND COALESCE(pp.sale_responsible_id, pp.responsible_id, pp.closer_id) IS NOT NULL
      AND (
        (pp.metrics_period_at IS NOT NULL AND pp.metrics_period_at >= v_start_ts AND pp.metrics_period_at <= v_end_ts)
        OR (pp.metrics_period_at IS NULL AND COALESCE(pp.closed_at, pp.updated_at) >= v_start_ts AND COALESCE(pp.closed_at, pp.updated_at) <= v_end_ts)
      )
    GROUP BY 1
  ),
  sales_data AS (
    SELECT tm.id, tm.name, tm.job_title, COALESCE(tm.metric_type, 'sales') AS metric_type,
      COALESCE(sa.total_value, 0) AS total_value,
      COALESCE(sa.conversions, 0) AS conversions,
      (SELECT g.target_value FROM public.goals g
       WHERE g.organization_id = v_org_id AND g.team_member_id = tm.id
         AND g.month = p_month AND g.year = p_year AND g.type = 'vendas'
       ORDER BY g.created_at DESC LIMIT 1) AS goal_target
    FROM public.team_members tm
    LEFT JOIN sales_agg sa ON sa.member_id = tm.id
    WHERE tm.organization_id = v_org_id AND tm.is_active = true
      AND (tm.metric_type = 'sales' OR tm.metric_type IS NULL)
  ),
  sales_sorted AS (
    SELECT id, name, job_title, metric_type, total_value, conversions, goal_target,
      ROW_NUMBER() OVER (ORDER BY total_value DESC) AS pos
    FROM sales_data
  )
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', id, 'name', name, 'job_title', job_title, 'metric_type', metric_type,
      'value', total_value, 'conversions', conversions,
      'goal', COALESCE(goal_target, 0),
      'goalProgress', CASE WHEN goal_target IS NOT NULL AND goal_target > 0
        THEN ROUND((total_value / goal_target) * 100)::int ELSE 0 END,
      'position', pos::int, 'role', 'Vendas'
    ) ORDER BY pos
  ), '[]'::jsonb) INTO v_sales_ranking
  FROM sales_sorted;

  -- Reuniões — event-sourced (ADR-0007): held no período da reunião,
  -- booked no período da marcação, atribuição canônica = pré-vendas (snapshot)
  WITH held_agg AS (
    SELECT me.pre_sale_responsible_id AS member_id, COUNT(*)::int AS total_meetings
    FROM public.meeting_events me
    WHERE me.organization_id = v_org_id
      AND me.event_type = 'meeting_held'
      AND me.pre_sale_responsible_id IS NOT NULL
      AND COALESCE(me.meeting_date, me.occurred_at) >= v_start_ts
      AND COALESCE(me.meeting_date, me.occurred_at) <= v_end_ts
    GROUP BY 1
  ),
  booked_agg AS (
    SELECT me.pre_sale_responsible_id AS member_id, COUNT(*)::int AS total_booked
    FROM public.meeting_events me
    WHERE me.organization_id = v_org_id
      AND me.event_type = 'meeting_booked'
      AND me.pre_sale_responsible_id IS NOT NULL
      AND me.occurred_at >= v_start_ts
      AND me.occurred_at <= v_end_ts
    GROUP BY 1
  ),
  meetings_data AS (
    SELECT tm.id, tm.name, tm.job_title, COALESCE(tm.metric_type, 'meetings') AS metric_type,
      0::numeric AS total_value,
      COALESCE(ha.total_meetings, 0) AS meetings,
      COALESCE(ba.total_booked, 0) AS meetings_booked,
      (SELECT g.target_value FROM public.goals g
       WHERE g.organization_id = v_org_id AND g.team_member_id = tm.id
         AND g.month = p_month AND g.year = p_year
         AND g.type IN ('reunioes_realizadas', 'reunioes')
       ORDER BY CASE g.type WHEN 'reunioes_realizadas' THEN 0 ELSE 1 END, g.created_at DESC
       LIMIT 1) AS goal_target,
      (SELECT g.target_value FROM public.goals g
       WHERE g.organization_id = v_org_id AND g.team_member_id = tm.id
         AND g.month = p_month AND g.year = p_year AND g.type = 'reunioes_marcadas'
       ORDER BY g.created_at DESC LIMIT 1) AS goal_booked_target
    FROM public.team_members tm
    LEFT JOIN held_agg ha ON ha.member_id = tm.id
    LEFT JOIN booked_agg ba ON ba.member_id = tm.id
    WHERE tm.organization_id = v_org_id AND tm.is_active = true
      AND tm.metric_type = 'meetings'
  ),
  meetings_sorted AS (
    SELECT *, ROW_NUMBER() OVER (ORDER BY meetings DESC, meetings_booked DESC) AS pos
    FROM meetings_data
  )
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', id, 'name', name, 'job_title', job_title, 'metric_type', metric_type,
      'value', total_value,
      'meetings', meetings,
      'meetingsBooked', meetings_booked,
      'goal', COALESCE(goal_target, 0),
      'goalProgress', CASE WHEN goal_target IS NOT NULL AND goal_target > 0
        THEN ROUND((meetings::numeric / goal_target) * 100)::int ELSE 0 END,
      'goalBooked', COALESCE(goal_booked_target, 0),
      'goalBookedProgress', CASE WHEN goal_booked_target IS NOT NULL AND goal_booked_target > 0
        THEN ROUND((meetings_booked::numeric / goal_booked_target) * 100)::int ELSE 0 END,
      'position', pos::int, 'role', 'Reuniões'
    ) ORDER BY pos
  ), '[]'::jsonb) INTO v_meetings_ranking
  FROM meetings_sorted;

  RETURN jsonb_build_object('salesRanking', v_sales_ranking, 'meetingsRanking', v_meetings_ranking);
END;
$$;


ALTER FUNCTION "public"."get_ranking_data"("p_month" integer, "p_year" integer, "p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_ranking_data"("p_month" integer, "p_year" integer, "p_organization_id" "uuid") IS 'Rankings. Sales: COALESCE(sale_responsible_id, closer_id, responsible_id) from pipeline_entries metadata (slug=propostas, stage=vendido). Meetings: COALESCE(pre_sale_responsible_id, sdr_id) ONLY from metadata (slug=confirmacao, stage=compareceu). Meetings DOES NOT fall back to responsible_id or closer_id — meeting attendance credit belongs to the SDR. Updated 2026-05-18.';



CREATE OR REPLACE FUNCTION "public"."get_recent_items"("p_limit" integer DEFAULT 10, "p_entity_type" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "entity_type" "text", "entity_id" "uuid", "entity_label" "text", "viewed_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  SELECT ri.id, ri.entity_type, ri.entity_id, ri.entity_label, ri.viewed_at
  FROM recent_items ri
  WHERE ri.user_id = auth.uid()
    AND (p_entity_type IS NULL OR ri.entity_type = p_entity_type)
  ORDER BY ri.viewed_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_recent_items"("p_limit" integer, "p_entity_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_revenue_at_risk"("p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM public.assert_org_access(p_org_id);
  PERFORM assert_org_member(p_org_id);

  RETURN (
    WITH risk_windows AS (
      SELECT
        c.id,
        c.name,
        c.segment,
        c.avg_ticket,
        c.next_order_expected,
        c.health_score,
        c.churn_probability,
        CASE
          WHEN c.next_order_expected::date <= CURRENT_DATE + 7 THEN '7d'
          WHEN c.next_order_expected::date <= CURRENT_DATE + 14 THEN '14d'
          WHEN c.next_order_expected::date <= CURRENT_DATE + 30 THEN '30d'
          ELSE NULL
        END AS risk_window
      FROM upsell_clients c
      WHERE c.organization_id = p_org_id
        AND c.is_active = true
        AND c.next_order_expected IS NOT NULL
        AND c.next_order_expected::date <= CURRENT_DATE + 30
        AND c.avg_ticket IS NOT NULL
    )
    SELECT jsonb_build_object(
      'windows', jsonb_build_object(
        '7d', jsonb_build_object(
          'total', COALESCE(SUM(avg_ticket) FILTER (WHERE risk_window = '7d' OR next_order_expected::date <= CURRENT_DATE + 7), 0),
          'count', COUNT(*) FILTER (WHERE risk_window = '7d' OR next_order_expected::date <= CURRENT_DATE + 7),
          'ouro_total', COALESCE(SUM(avg_ticket) FILTER (WHERE (risk_window = '7d' OR next_order_expected::date <= CURRENT_DATE + 7) AND segment = 'ouro'), 0)
        ),
        '14d', jsonb_build_object(
          'total', COALESCE(SUM(avg_ticket) FILTER (WHERE next_order_expected::date <= CURRENT_DATE + 14), 0),
          'count', COUNT(*) FILTER (WHERE next_order_expected::date <= CURRENT_DATE + 14),
          'ouro_total', COALESCE(SUM(avg_ticket) FILTER (WHERE next_order_expected::date <= CURRENT_DATE + 14 AND segment = 'ouro'), 0)
        ),
        '30d', jsonb_build_object(
          'total', COALESCE(SUM(avg_ticket), 0),
          'count', COUNT(*),
          'ouro_total', COALESCE(SUM(avg_ticket) FILTER (WHERE segment = 'ouro'), 0)
        )
      ),
      'top_risk_clients', (
        SELECT jsonb_agg(jsonb_build_object(
          'id', sub.id,
          'name', sub.name,
          'segment', sub.segment,
          'avg_ticket', sub.avg_ticket,
          'next_order_expected', sub.next_order_expected,
          'churn_probability', sub.churn_probability
        ) ORDER BY sub.avg_ticket DESC)
        FROM (
          SELECT * FROM risk_windows
          WHERE segment = 'ouro'
          ORDER BY avg_ticket DESC
          LIMIT 5
        ) sub
      )
    )
    FROM risk_windows
  );
EXCEPTION
  WHEN OTHERS THEN
    IF SQLERRM = 'access_denied' THEN RETURN NULL; END IF;
    RAISE;
END;
$$;


ALTER FUNCTION "public"."get_revenue_at_risk"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_revenue_attribution"("p_start_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("origin" "text", "lead_count" bigint, "won_count" bigint, "total_revenue" numeric, "avg_deal_value" numeric, "conversion_rate" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
BEGIN
  SELECT tm.organization_id INTO v_org_id
  FROM team_members tm WHERE tm.user_id = auth.uid() LIMIT 1;

  IF v_org_id IS NULL THEN RETURN; END IF;

  RETURN QUERY
  SELECT
    COALESCE(l.origin, 'unknown') AS origin,
    COUNT(DISTINCT l.id) AS lead_count,
    COUNT(DISTINCT pe.id) FILTER (WHERE pe.stage_key = 'vendido') AS won_count,
    COALESCE(SUM((pe.metadata->>'sale_value')::numeric) FILTER (WHERE pe.stage_key = 'vendido'), 0)::numeric AS total_revenue,
    COALESCE(AVG((pe.metadata->>'sale_value')::numeric) FILTER (WHERE pe.stage_key = 'vendido'), 0)::numeric AS avg_deal_value,
    CASE
      WHEN COUNT(DISTINCT l.id) > 0
      THEN ROUND(COUNT(DISTINCT pe.id) FILTER (WHERE pe.stage_key = 'vendido')::numeric / COUNT(DISTINCT l.id) * 100, 1)
      ELSE 0
    END AS conversion_rate
  FROM leads l
  LEFT JOIN pipeline_entries pe ON pe.lead_id = l.id
    AND EXISTS (
      SELECT 1 FROM pipelines pip
      WHERE pip.id = pe.pipeline_id AND pip.slug = 'propostas' AND pip.type = 'system'
    )
    AND (p_start_date IS NULL OR pe.created_at >= p_start_date)
    AND (p_end_date IS NULL OR pe.created_at <= p_end_date)
  WHERE l.organization_id = v_org_id
    AND l.deleted_at IS NULL
    AND (p_start_date IS NULL OR l.created_at >= p_start_date)
    AND (p_end_date IS NULL OR l.created_at <= p_end_date)
  GROUP BY l.origin
  ORDER BY total_revenue DESC;
END;
$$;


ALTER FUNCTION "public"."get_revenue_attribution"("p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_sales_cycle_analysis"("p_pipeline_type" "text" DEFAULT NULL::"text", "p_start_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("from_stage" "text", "to_stage" "text", "avg_hours" numeric, "median_hours" numeric, "transition_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE v_org_id uuid;
BEGIN
  v_org_id := resolve_org_for_rpc(p_org_id);
  IF v_org_id IS NULL THEN RETURN; END IF;
  RETURN QUERY
  WITH ev AS (
    SELECT lh.lead_id, lh.created_at,
      COALESCE(NULLIF(lh.metadata->>'to_stage',''), substring(lh.description from 'para "([^"]+)"')) AS to_s,
      COALESCE(NULLIF(lh.metadata->>'pipeline',''), substring(lh.description from '(?:no|na) ((?:Funil|Pipe) .+)$')) AS pipe_label
    FROM lead_history lh
    WHERE lh.organization_id = v_org_id
      AND lh.action IN ('stage_changed','proposal_status_changed')
      AND (p_start_date IS NULL OR lh.created_at >= p_start_date)
      AND (p_end_date IS NULL OR lh.created_at <= p_end_date)
  ),
  seq AS (
    SELECT e.to_s, e.pipe_label,
      LAG(e.to_s) OVER (PARTITION BY e.lead_id ORDER BY e.created_at) AS from_s,
      EXTRACT(EPOCH FROM (e.created_at - LAG(e.created_at) OVER (PARTITION BY e.lead_id ORDER BY e.created_at)))/3600.0 AS hours_diff
    FROM ev e WHERE e.to_s IS NOT NULL
  )
  SELECT s.from_s, s.to_s, ROUND(AVG(s.hours_diff)::numeric,1),
    ROUND((PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY s.hours_diff))::numeric,1), COUNT(*)
  FROM seq s
  WHERE s.from_s IS NOT NULL AND s.from_s <> s.to_s AND s.hours_diff IS NOT NULL AND s.hours_diff > 0
    AND (p_pipeline_type IS NULL
      OR s.pipe_label ILIKE '%'||p_pipeline_type||'%'
      OR (p_pipeline_type='whatsapp' AND s.pipe_label ILIKE '%WhatsApp%')
      OR (p_pipeline_type='confirmacao' AND s.pipe_label ILIKE '%Confirma%')
      OR (p_pipeline_type='propostas' AND s.pipe_label ILIKE '%Proposta%'))
  GROUP BY s.from_s, s.to_s ORDER BY COUNT(*) DESC LIMIT 12;
END; $_$;


ALTER FUNCTION "public"."get_sales_cycle_analysis"("p_pipeline_type" "text", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_sales_metrics"("p_org_id" "uuid", "p_period" "text", "p_ref" "date" DEFAULT NULL::"date", "p_start" "date" DEFAULT NULL::"date", "p_end" "date" DEFAULT NULL::"date", "p_pipeline_id" "uuid" DEFAULT NULL::"uuid", "p_filter_member_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_bounds tstzrange;
  v_rev_total numeric; v_rev_novo numeric; v_rev_carteira numeric;
  v_cnt_won integer; v_cnt_novo integer; v_cnt_carteira integer; v_cnt_lost integer;
  v_by_closer jsonb; v_unattr_rev numeric; v_unattr_cnt integer;
BEGIN
  PERFORM public.assert_org_access(p_org_id);
  v_bounds := public.metric_period_bounds(p_org_id, p_period, p_ref, p_start, p_end);

  SELECT
    COALESCE(SUM(w.sale_value), 0),
    COALESCE(SUM(w.sale_value) FILTER (WHERE w.revenue_stream = 'novo_negocio'), 0),
    COALESCE(SUM(w.sale_value) FILTER (WHERE w.revenue_stream = 'carteira'), 0),
    COUNT(*),
    COUNT(*) FILTER (WHERE w.revenue_stream = 'novo_negocio'),
    COUNT(*) FILTER (WHERE w.revenue_stream = 'carteira')
  INTO v_rev_total, v_rev_novo, v_rev_carteira, v_cnt_won, v_cnt_novo, v_cnt_carteira
  FROM public.sale_events w
  WHERE w.organization_id = p_org_id AND w.event_type = 'sale' AND w.sold_at <@ v_bounds
    AND (p_pipeline_id IS NULL OR w.pipeline_id = p_pipeline_id)
    AND (p_filter_member_id IS NULL OR w.sale_responsible_id = p_filter_member_id)
    AND NOT EXISTS (SELECT 1 FROM public.sale_events r WHERE r.event_type = 'sale_reversed' AND r.reversed_event_id = w.id);

  SELECT COUNT(*) INTO v_cnt_lost
  FROM public.sale_events se
  WHERE se.organization_id = p_org_id AND se.event_type = 'sale_lost' AND se.sold_at <@ v_bounds
    AND (p_pipeline_id IS NULL OR se.pipeline_id = p_pipeline_id)
    AND (p_filter_member_id IS NULL OR se.sale_responsible_id = p_filter_member_id);

  SELECT
    COALESCE(jsonb_agg(jsonb_build_object('member_id', g.sale_responsible_id, 'revenue', g.revenue, 'sale_count', g.sale_count)
      ORDER BY g.revenue DESC, g.sale_count DESC) FILTER (WHERE g.sale_responsible_id IS NOT NULL), '[]'::jsonb),
    COALESCE(SUM(g.revenue) FILTER (WHERE g.sale_responsible_id IS NULL), 0),
    COALESCE(SUM(g.sale_count) FILTER (WHERE g.sale_responsible_id IS NULL), 0)::int
  INTO v_by_closer, v_unattr_rev, v_unattr_cnt
  FROM (
    SELECT w.sale_responsible_id, COALESCE(SUM(w.sale_value), 0) AS revenue, COUNT(*)::int AS sale_count
    FROM public.sale_events w
    WHERE w.organization_id = p_org_id AND w.event_type = 'sale' AND w.sold_at <@ v_bounds
      AND (p_pipeline_id IS NULL OR w.pipeline_id = p_pipeline_id)
      AND (p_filter_member_id IS NULL OR w.sale_responsible_id = p_filter_member_id)
      AND NOT EXISTS (SELECT 1 FROM public.sale_events r WHERE r.event_type = 'sale_reversed' AND r.reversed_event_id = w.id)
    GROUP BY w.sale_responsible_id
  ) g;

  RETURN jsonb_build_object(
    'period', jsonb_build_object('name', p_period, 'start', lower(v_bounds), 'end', upper(v_bounds)),
    'pipeline_id', p_pipeline_id, 'filter_member_id', p_filter_member_id,
    'revenue_total', v_rev_total,
    'revenue_by_stream', jsonb_build_object(
      'novo_negocio', jsonb_build_object('revenue', v_rev_novo, 'sale_count', v_cnt_novo),
      'carteira', jsonb_build_object('revenue', v_rev_carteira, 'sale_count', v_cnt_carteira)),
    'won_count', v_cnt_won, 'lost_count', v_cnt_lost,
    'ticket_medio', CASE WHEN v_cnt_won > 0 THEN round(v_rev_total / v_cnt_won, 2) ELSE NULL END,
    'by_closer', v_by_closer,
    'unattributed', jsonb_build_object('revenue', v_unattr_rev, 'sale_count', v_unattr_cnt)
  );
END;
$$;


ALTER FUNCTION "public"."get_sales_metrics"("p_org_id" "uuid", "p_period" "text", "p_ref" "date", "p_start" "date", "p_end" "date", "p_pipeline_id" "uuid", "p_filter_member_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_sales_metrics"("p_org_id" "uuid", "p_period" "text", "p_ref" "date", "p_start" "date", "p_end" "date", "p_pipeline_id" "uuid", "p_filter_member_id" "uuid") IS 'ADR-0017 §2-5,§8 / #995 — leitor canônico de venda (SP-3). Lê SÓ sale_events, líquido de estorno.';



CREATE OR REPLACE FUNCTION "public"."get_segment_benchmark"("p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_segment TEXT; v_org_count BIGINT; result JSONB;
  v_start TIMESTAMPTZ; v_end TIMESTAMPTZ;
BEGIN
  PERFORM public.assert_org_access(p_org_id);
  v_start := DATE_TRUNC('month', NOW());
  v_end := (DATE_TRUNC('month', NOW()) + INTERVAL '1 month' - INTERVAL '1 second');

  SELECT l.segment INTO v_segment
  FROM leads l
  WHERE l.organization_id = p_org_id AND l.segment IS NOT NULL AND l.segment != ''
  GROUP BY l.segment ORDER BY COUNT(*) DESC LIMIT 1;

  IF v_segment IS NULL THEN
    RETURN jsonb_build_object('available', false, 'reason', 'no_segment_data');
  END IF;

  SELECT COUNT(DISTINCT o.id) INTO v_org_count
  FROM organizations o
  JOIN leads l ON l.organization_id = o.id
  WHERE l.segment = v_segment AND o.id != p_org_id;

  IF v_org_count < 2 THEN
    RETURN jsonb_build_object('available', false, 'reason', 'insufficient_peers', 'segment', v_segment);
  END IF;

  WITH peer_orgs AS (
    SELECT DISTINCT o.id AS org_id
    FROM organizations o
    JOIN leads l ON l.organization_id = o.id
    WHERE l.segment = v_segment AND o.id != p_org_id
  ), peer_metrics AS (
    SELECT po.org_id,
      (SELECT COUNT(*)
       FROM leads l
       WHERE l.organization_id = po.org_id
         AND COALESCE(l.metrics_period_at, l.created_at) >= v_start
         AND COALESCE(l.metrics_period_at, l.created_at) <= v_end
      ) AS leads,
      (SELECT COUNT(*)
       FROM pipeline_entries pe
       JOIN pipelines pip ON pip.id = pe.pipeline_id AND pip.slug = 'propostas' AND pip.type = 'system'
       WHERE pe.organization_id = po.org_id
         AND pe.stage_key = 'vendido'
         AND COALESCE((pe.metadata->>'metrics_period_at')::timestamptz, pe.closed_at) >= v_start
         AND COALESCE((pe.metadata->>'metrics_period_at')::timestamptz, pe.closed_at) <= v_end
      ) AS vendas,
      (SELECT COALESCE(SUM((pe.metadata->>'sale_value')::numeric), 0)
       FROM pipeline_entries pe
       JOIN pipelines pip ON pip.id = pe.pipeline_id AND pip.slug = 'propostas' AND pip.type = 'system'
       WHERE pe.organization_id = po.org_id
         AND pe.stage_key = 'vendido'
         AND COALESCE((pe.metadata->>'metrics_period_at')::timestamptz, pe.closed_at) >= v_start
         AND COALESCE((pe.metadata->>'metrics_period_at')::timestamptz, pe.closed_at) <= v_end
      ) AS revenue,
      (SELECT COUNT(*)
       FROM team_members tm
       WHERE tm.organization_id = po.org_id AND tm.is_active = true
      ) AS team_size
    FROM peer_orgs po
  )
  SELECT jsonb_build_object(
    'available', true,
    'segment', v_segment,
    'peerCount', v_org_count,
    'avgTicketMedio', CASE WHEN SUM(vendas) > 0 THEN ROUND(SUM(revenue) / SUM(vendas), 2) ELSE 0 END,
    'avgLeadsPerSeller', CASE WHEN SUM(team_size) > 0 THEN ROUND(SUM(leads)::NUMERIC / SUM(team_size), 1) ELSE 0 END,
    'avgConversionRate', CASE WHEN SUM(leads) > 0 THEN ROUND((SUM(vendas)::NUMERIC / SUM(leads)) * 100, 1) ELSE 0 END
  ) INTO result FROM peer_metrics;

  RETURN result;
END; $$;


ALTER FUNCTION "public"."get_segment_benchmark"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_seller_activity_scores"("p_org_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE result JSONB;
BEGIN
  PERFORM public.assert_org_access(p_org_id);
  WITH seller_metrics AS (
    SELECT tm.id, tm.name, tm.role, (tm.metric_type)::TEXT AS metric_type,
      (SELECT COUNT(*)
       FROM leads l
       WHERE l.organization_id = p_org_id
         AND (l.sdr_id = tm.id OR l.closer_id = tm.id)
         AND COALESCE(l.metrics_period_at, l.created_at) >= p_start_date
         AND COALESCE(l.metrics_period_at, l.created_at) <= p_end_date
      ) AS leads_movimentados,
      (SELECT COUNT(*)
       FROM follow_ups fu
       WHERE fu.organization_id = p_org_id
         AND fu.assigned_to = tm.id
         AND fu.completed_at IS NOT NULL
         AND fu.completed_at >= p_start_date
         AND fu.completed_at <= p_end_date
      ) AS followups_completos,
      (SELECT COUNT(*)
       FROM pipeline_entries pe
       JOIN pipelines pip ON pip.id = pe.pipeline_id AND pip.slug = 'confirmacao' AND pip.type = 'system'
       WHERE pe.organization_id = p_org_id
         AND ((pe.metadata->>'sdr_id')::uuid = tm.id OR (pe.metadata->>'closer_id')::uuid = tm.id)
         AND pe.stage_key = 'compareceu'
         AND COALESCE((pe.metadata->>'metrics_period_at')::timestamptz, pe.created_at) >= p_start_date
         AND COALESCE((pe.metadata->>'metrics_period_at')::timestamptz, pe.created_at) <= p_end_date
      ) AS reunioes_realizadas,
      (SELECT COUNT(*)
       FROM pipeline_entries pe
       JOIN pipelines pip ON pip.id = pe.pipeline_id AND pip.slug = 'propostas' AND pip.type = 'system'
       WHERE pe.organization_id = p_org_id
         AND (pe.metadata->>'closer_id')::uuid = tm.id
         AND COALESCE((pe.metadata->>'metrics_period_at')::timestamptz, pe.created_at) >= p_start_date
         AND COALESCE((pe.metadata->>'metrics_period_at')::timestamptz, pe.created_at) <= p_end_date
      ) AS propostas_enviadas,
      (SELECT COUNT(*)
       FROM pipeline_entries pe
       JOIN pipelines pip ON pip.id = pe.pipeline_id AND pip.slug = 'propostas' AND pip.type = 'system'
       WHERE pe.organization_id = p_org_id
         AND (pe.metadata->>'closer_id')::uuid = tm.id
         AND pe.stage_key = 'vendido'
         AND COALESCE((pe.metadata->>'metrics_period_at')::timestamptz, pe.closed_at) >= p_start_date
         AND COALESCE((pe.metadata->>'metrics_period_at')::timestamptz, pe.closed_at) <= p_end_date
      ) AS vendas_fechadas
    FROM team_members tm WHERE tm.organization_id = p_org_id AND tm.is_active = true
  ), scored AS (
    SELECT sm.*,
      (sm.leads_movimentados * 10 + sm.followups_completos * 15 + sm.reunioes_realizadas * 20 + sm.propostas_enviadas * 25 + sm.vendas_fechadas * 30) AS score_bruto
    FROM seller_metrics sm
  )
  SELECT jsonb_agg(jsonb_build_object(
    'id', s.id, 'name', s.name, 'role', s.role, 'metricType', s.metric_type,
    'leads', s.leads_movimentados, 'followups', s.followups_completos,
    'reunioes', s.reunioes_realizadas, 'propostas', s.propostas_enviadas,
    'vendas', s.vendas_fechadas, 'scoreBruto', s.score_bruto,
    'scoreNormalizado', CASE WHEN (SELECT MAX(score_bruto) FROM scored) > 0
      THEN ROUND((s.score_bruto::NUMERIC / (SELECT MAX(score_bruto) FROM scored)) * 100) ELSE 0 END
  ) ORDER BY s.score_bruto DESC) INTO result FROM scored s;
  RETURN COALESCE(result, '[]'::jsonb);
END; $$;


ALTER FUNCTION "public"."get_seller_activity_scores"("p_org_id" "uuid", "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_stage_lead_ids"("p_pipeline_type" "text", "p_stage_key" "text", "p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  SELECT pe.lead_id
  FROM public.pipeline_entries pe
  JOIN public.pipelines p
    ON p.id = pe.pipeline_id
   AND p.type = 'system'
   AND p.slug = p_pipeline_type
  JOIN public.leads l
    ON l.id = pe.lead_id
   AND l.deleted_at IS NULL
  WHERE pe.stage_key = p_stage_key
    AND pe.lead_id IS NOT NULL
    -- Tenancy: orgs do chamador (helper) OU a org pedida quando master.
    AND (
      pe.organization_id IN (SELECT public.get_my_organization_ids())
      OR (p_organization_id IS NOT NULL
          AND public.is_master_user()
          AND pe.organization_id = p_organization_id)
    );
$$;


ALTER FUNCTION "public"."get_stage_lead_ids"("p_pipeline_type" "text", "p_stage_key" "text", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_trash_leads"("p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "name" "text", "company" "text", "email" "text", "phone" "text", "deleted_at" timestamp with time zone, "deleted_by" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_org_id uuid;
BEGIN
  IF public.is_master_user() THEN
    -- master: scope to the org shadowed in the UI (NULL = all orgs)
    v_org_id := p_org_id;
  ELSE
    -- members: always own org; p_org_id is ignored (no cross-tenant peeking)
    SELECT organization_id INTO v_org_id
    FROM public.team_members
    WHERE user_id = auth.uid() AND is_active = true
    LIMIT 1;

    IF v_org_id IS NULL THEN
      RAISE EXCEPTION 'No active organization membership';
    END IF;
  END IF;

  RETURN QUERY
  SELECT l.id, l.name, l.company, l.email, l.phone, l.deleted_at, l.deleted_by
  FROM public.leads l
  WHERE (v_org_id IS NULL OR l.organization_id = v_org_id)
    AND l.deleted_at IS NOT NULL
  ORDER BY l.deleted_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_trash_leads"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_uazapi_credentials"("p_instance_id" "uuid") RETURNS TABLE("uazapi_token" "text", "uazapi_instance_id" "text", "webhook_secret" "text", "organization_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Guarda: só service_role pode chamar esta função
  IF auth.role() != 'service_role' THEN
    RAISE EXCEPTION 'Permission denied' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    s.uazapi_token,
    s.uazapi_instance_id,
    s.webhook_secret,
    s.organization_id
  FROM public.whatsapp_instance_secrets s
  WHERE s.instance_id = p_instance_id;
END;
$$;


