CREATE OR REPLACE FUNCTION "public"."get_uf_heatmap"("p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("uf" character, "leads_count" bigint, "clients_count" bigint, "total_sold" numeric, "unmapped_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE v_org_id uuid; v_unmapped bigint;
BEGIN
  v_org_id := resolve_org_for_rpc(p_org_id);
  IF v_org_id IS NULL THEN RETURN; END IF;
  SELECT count(*) INTO v_unmapped FROM leads l
  WHERE l.organization_id = v_org_id AND l.deleted_at IS NULL AND l.uf IS NULL;
  RETURN QUERY
  SELECT l.uf, count(*)::bigint,
    count(*) FILTER (WHERE EXISTS (SELECT 1 FROM pipe_propostas pp WHERE pp.lead_id = l.id AND pp.status = 'vendido'))::bigint,
    COALESCE(SUM((SELECT SUM(pp.sale_value) FROM pipe_propostas pp WHERE pp.lead_id = l.id AND pp.status = 'vendido')), 0)::numeric,
    v_unmapped
  FROM leads l
  WHERE l.organization_id = v_org_id AND l.deleted_at IS NULL AND l.uf IS NOT NULL
  GROUP BY l.uf;
END; $$;


ALTER FUNCTION "public"."get_uf_heatmap"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_unified_conversations"("p_channel" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50) RETURNS TABLE("lead_id" "uuid", "lead_name" "text", "lead_phone" "text", "lead_email" "text", "channel" "text", "last_message" "text", "last_direction" "text", "last_sender" "text", "last_sent_at" timestamp with time zone, "unread_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  WITH ranked AS (
    SELECT
      uim.lead_id,
      uim.channel::text,
      uim.content,
      uim.direction,
      uim.sender_name,
      uim.sent_at,
      ROW_NUMBER() OVER (PARTITION BY uim.lead_id, uim.channel ORDER BY uim.sent_at DESC) AS rn
    FROM unified_inbox_messages uim
    WHERE uim.organization_id IN (
      SELECT tm.organization_id FROM team_members tm WHERE tm.user_id = auth.uid()
    )
    AND (p_channel IS NULL OR uim.channel::text = p_channel)
    AND uim.lead_id IS NOT NULL
  )
  SELECT
    r.lead_id,
    l.name AS lead_name,
    l.phone AS lead_phone,
    l.email AS lead_email,
    r.channel,
    r.content AS last_message,
    r.direction AS last_direction,
    r.sender_name AS last_sender,
    r.sent_at AS last_sent_at,
    0::bigint AS unread_count
  FROM ranked r
  JOIN leads l ON l.id = r.lead_id
  WHERE r.rn = 1
  ORDER BY r.sent_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_unified_conversations"("p_channel" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_unread_counts"("p_instance_ids" "uuid"[]) RETURNS TABLE("instance_id" "uuid", "normalized_phone" "text", "unread" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT m.instance_id, m.normalized_phone, count(*)::int AS unread
  FROM public.whatsapp_messages m
  LEFT JOIN public.conversation_read_state rs
    ON  rs.organization_id = m.organization_id
    AND rs.user_id         = auth.uid()
    AND rs.conversation_key = 'whatsapp:' || m.instance_id::text || ':' || m.normalized_phone
  WHERE m.organization_id IN (SELECT get_my_organization_ids())
    AND m.instance_id = ANY (p_instance_ids)
    AND m.direction = 'incoming' AND m.deleted_at IS NULL AND m.is_group = false
    AND m."timestamp" > now() - interval '30 days'
    AND m."timestamp" > COALESCE(rs.last_read_at, now() - interval '7 days')
  GROUP BY m.instance_id, m.normalized_phone;
$$;


ALTER FUNCTION "public"."get_unread_counts"("p_instance_ids" "uuid"[]) OWNER TO "postgres";


