CREATE OR REPLACE FUNCTION "public"."get_usage_by_org"("interval_param" "text" DEFAULT '7 days'::"text") RETURNS TABLE("organization_id" "uuid", "organization_name" "text", "total_events" bigint, "leads_criados" bigint, "cards_movidos" bigint, "mensagens_enviadas" bigint, "ultima_atividade" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT o.id, o.name, COUNT(*) AS total_events,
    COUNT(*) FILTER (WHERE u.event_type = 'lead_created') AS leads_criados,
    COUNT(*) FILTER (WHERE u.event_type = 'card_moved') AS cards_movidos,
    COUNT(*) FILTER (WHERE u.event_type = 'message_sent') AS mensagens_enviadas,
    MAX(u.created_at) AS ultima_atividade
  FROM public.usage_events u JOIN public.organizations o ON o.id = u.organization_id
  WHERE public.is_master_user() AND u.created_at > NOW() - interval_param::INTERVAL
  GROUP BY o.id, o.name ORDER BY ultima_atividade DESC;
$$;


