CREATE OR REPLACE FUNCTION "public"."get_vendedor_ranking"("p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM public.assert_org_access(p_org_id);
  PERFORM assert_org_member(p_org_id);

  RETURN (
    SELECT COALESCE(jsonb_agg(row_data ORDER BY sort_health DESC), '[]'::jsonb)
    FROM (
      SELECT
        ROUND(AVG(c.health_score)) AS sort_health,
        jsonb_build_object(
          'closer_id', tm.id,
          'name', tm.name,
          'role', tm.role,
          'total_clients', COUNT(c.id),
          'avg_health', ROUND(AVG(c.health_score)),
          'avg_churn', ROUND(AVG(c.churn_probability)),
          'avg_ticket', ROUND(AVG(c.avg_ticket)::numeric, 2),
          'total_revenue', SUM(c.lifetime_value),
          'on_time_pct', ROUND(
            COUNT(*) FILTER (
              WHERE c.days_since_last_order <= c.reorder_cycle_days
            )::numeric / NULLIF(COUNT(*) FILTER (WHERE c.reorder_cycle_days > 0), 0) * 100
          ),
          'segments', jsonb_build_object(
            'ouro', COUNT(*) FILTER (WHERE c.segment = 'ouro'),
            'prata', COUNT(*) FILTER (WHERE c.segment = 'prata'),
            'novo', COUNT(*) FILTER (WHERE c.segment = 'novo'),
            'resgate', COUNT(*) FILTER (WHERE c.segment = 'resgate'),
            'dormindo', COUNT(*) FILTER (WHERE c.segment = 'dormindo')
          )
        ) AS row_data
      FROM team_members tm
      JOIN upsell_clients c ON c.id = tm.id AND c.is_active = true
      WHERE c.organization_id = p_org_id
        AND tm.is_active = true
      GROUP BY tm.id, tm.name, tm.role
      HAVING COUNT(c.id) > 0
    ) sub
  );
EXCEPTION
  WHEN OTHERS THEN
    IF SQLERRM = 'access_denied' THEN RETURN '[]'::jsonb; END IF;
    RAISE;
END;
$$;


ALTER FUNCTION "public"."get_vendedor_ranking"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_whatsapp_conversation_list"("p_org" "uuid", "p_instance" "uuid", "p_limit" integer DEFAULT 50, "p_before" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("phone_number" "text", "normalized_phone" "text", "push_name" "text", "last_message" "text", "last_message_time" timestamp with time zone, "last_message_direction" "text", "last_message_sent_source" "text", "lead_id" "uuid", "is_group" boolean, "conversation_id" "uuid", "archived_at" timestamp with time zone, "unread_count" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 1000);
BEGIN
  -- Acesso: team_member ativo da org OU master ativo (ghost cross-org).
  IF p_org IS NULL OR (NOT (p_org IN (SELECT get_my_organization_ids())) AND NOT is_master_user()) THEN
    RAISE EXCEPTION 'forbidden: org not accessible' USING ERRCODE = '42501';
  END IF;
  IF p_instance IS NULL THEN
    RAISE EXCEPTION 'instance required' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH page AS (
    SELECT s.phone_number, s.normalized_phone, s.last_push_name, s.last_message, s.last_message_time,
           s.last_message_direction, s.last_message_sent_source, s.lead_id, s.is_group
    FROM whatsapp_conversation_summary s
    WHERE s.organization_id = p_org AND s.instance_id = p_instance
      AND (p_before IS NULL OR s.last_message_time < p_before)
    ORDER BY s.last_message_time DESC
    LIMIT v_limit
  ),
  read_state AS (
    SELECT split_part(rs.conversation_key, ':', 3) AS np, rs.last_read_at
    FROM conversation_read_state rs
    WHERE rs.organization_id = p_org AND rs.user_id = v_uid
      AND rs.conversation_key LIKE 'whatsapp:' || p_instance::text || ':%'
  ),
  conv AS (
    SELECT c.normalized_phone AS np, c.id, c.archived_at, c.deleted_at
    FROM whatsapp_conversations c
    WHERE c.organization_id = p_org AND c.instance_id = p_instance AND c.normalized_phone IS NOT NULL
  ),
  unread AS (
    SELECT m.normalized_phone AS np, count(*)::integer AS cnt
    FROM whatsapp_messages m
    LEFT JOIN read_state r ON r.np = m.normalized_phone
    WHERE m.organization_id = p_org AND m.instance_id = p_instance
      AND m.direction = 'incoming' AND m.deleted_at IS NULL AND m.is_group = false
      AND m."timestamp" > now() - interval '30 days'
      AND m."timestamp" > COALESCE(r.last_read_at, now() - interval '7 days')
    GROUP BY m.normalized_phone
  )
  SELECT p.phone_number, p.normalized_phone, p.last_push_name, p.last_message, p.last_message_time,
         p.last_message_direction, p.last_message_sent_source, p.lead_id, p.is_group,
         conv.id, conv.archived_at, coalesce(u.cnt, 0)
  FROM page p
  LEFT JOIN conv   ON conv.np = p.normalized_phone
  LEFT JOIN unread u ON u.np  = p.normalized_phone
  WHERE conv.deleted_at IS NULL
  ORDER BY p.last_message_time DESC;
END;
$$;


ALTER FUNCTION "public"."get_whatsapp_conversation_list"("p_org" "uuid", "p_instance" "uuid", "p_limit" integer, "p_before" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_whatsapp_situation_candidates"("p_organization_id" "uuid", "p_stage_keys" "text"[]) RETURNS TABLE("lead_id" "uuid", "whatsapp_stage" "text", "stage_changed_at" timestamp with time zone, "last_inbound_at" timestamp with time zone, "last_outbound_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH wf AS (
    SELECT pe.lead_id, pe.stage_key, pe.stage_changed_at
    FROM pipeline_entries pe
    JOIN pipelines p ON p.id = pe.pipeline_id AND p.slug = 'whatsapp' AND p.type = 'system'
    WHERE pe.organization_id = p_organization_id
      AND pe.stage_key = ANY(p_stage_keys)
  )
  SELECT
    w.lead_id,
    w.stage_key AS whatsapp_stage,
    w.stage_changed_at,
    (SELECT max(wm.timestamp) FROM whatsapp_messages wm
       WHERE wm.lead_id = w.lead_id AND wm.organization_id = p_organization_id
         AND wm.direction = 'incoming') AS last_inbound_at,
    (SELECT max(wm.timestamp) FROM whatsapp_messages wm
       WHERE wm.lead_id = w.lead_id AND wm.organization_id = p_organization_id
         AND wm.direction = 'outgoing') AS last_outbound_at
  FROM wf w;
$$;


ALTER FUNCTION "public"."get_whatsapp_situation_candidates"("p_organization_id" "uuid", "p_stage_keys" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_whatsapp_situation_candidates"("p_organization_id" "uuid", "p_stage_keys" "text"[]) IS 'Leads in given Oportunidades (whatsapp) stages with last in/out message + stage_changed_at. Consumed by the situation follow-up worker (ADR-0006) for new_lead_no_reply, qualified_no_meeting, cold_reengage, no_show_rebook.';



CREATE OR REPLACE FUNCTION "public"."get_win_loss_analysis"("p_start_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("loss_reason" "text", "count" bigint, "total_value" numeric, "pct" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_org_id uuid; v_total bigint;
BEGIN
  v_org_id := resolve_org_for_rpc(p_org_id);
  IF v_org_id IS NULL THEN RETURN; END IF;
  SELECT COUNT(*) INTO v_total
  FROM pipeline_entries pe
  JOIN pipelines pip ON pip.id = pe.pipeline_id AND pip.slug = 'propostas' AND pip.type = 'system'
  WHERE pe.organization_id = v_org_id AND pe.stage_key = 'perdido'
    AND (p_start_date IS NULL OR pe.created_at >= p_start_date)
    AND (p_end_date IS NULL OR pe.created_at <= p_end_date);
  RETURN QUERY
  SELECT COALESCE(pe.metadata->>'loss_reason', 'Nao informado'),
    COUNT(*),
    COALESCE(SUM((pe.metadata->>'sale_value')::numeric), 0)::numeric,
    CASE WHEN v_total > 0 THEN ROUND(COUNT(*)::numeric / v_total * 100, 1) ELSE 0 END
  FROM pipeline_entries pe
  JOIN pipelines pip ON pip.id = pe.pipeline_id AND pip.slug = 'propostas' AND pip.type = 'system'
  WHERE pe.organization_id = v_org_id AND pe.stage_key = 'perdido'
    AND (p_start_date IS NULL OR pe.created_at >= p_start_date)
    AND (p_end_date IS NULL OR pe.created_at <= p_end_date)
  GROUP BY pe.metadata->>'loss_reason'
  ORDER BY COUNT(*) DESC;
END; $$;


ALTER FUNCTION "public"."get_win_loss_analysis"("p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_workflow_node_stats"("p_workflow_id" "uuid") RETURNS TABLE("node_id" "text", "executions_count" bigint, "success_count" bigint, "error_count" bigint, "avg_duration_ms" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_org_id uuid;
BEGIN
  SELECT tm.organization_id INTO v_org_id
  FROM team_members tm WHERE tm.user_id = auth.uid() LIMIT 1;

  IF v_org_id IS NULL THEN RETURN; END IF;

  RETURN QUERY
  SELECT
    wes.node_id::text,
    COUNT(*) AS executions_count,
    COUNT(*) FILTER (WHERE wes.status = 'completed') AS success_count,
    COUNT(*) FILTER (WHERE wes.status = 'error') AS error_count,
    ROUND(AVG(EXTRACT(EPOCH FROM (wes.completed_at - wes.started_at)) * 1000)::numeric, 0) AS avg_duration_ms
  FROM workflow_execution_steps wes
  JOIN workflow_executions we ON we.id = wes.execution_id
  WHERE we.workflow_id = p_workflow_id
    AND we.organization_id = v_org_id
  GROUP BY wes.node_id;
END;
$$;


ALTER FUNCTION "public"."get_workflow_node_stats"("p_workflow_id" "uuid") OWNER TO "postgres";


