CREATE OR REPLACE FUNCTION "public"."is_responsible_in_same_org"("p_sdr_id" "uuid", "p_closer_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
