CREATE OR REPLACE FUNCTION "public"."is_user_responsible_in_any_pipe"("p_lead_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tm_ids uuid[];
BEGIN
  SELECT array_agg(id) INTO v_tm_ids
  FROM public.team_members
  WHERE user_id = auth.uid()
    AND is_active = true;

  IF v_tm_ids IS NULL THEN
    RETURN false;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.pipeline_entries pe
    WHERE pe.lead_id = p_lead_id
      AND (
        pe.assigned_to = ANY(v_tm_ids)
        OR (pe.metadata->>'sdr_id')::uuid = ANY(v_tm_ids)
        OR (pe.metadata->>'responsible_id')::uuid = ANY(v_tm_ids)
        OR (pe.metadata->>'closer_id')::uuid = ANY(v_tm_ids)
        OR (pe.metadata->>'pre_sale_responsible_id')::uuid = ANY(v_tm_ids)
        OR (pe.metadata->>'sale_responsible_id')::uuid = ANY(v_tm_ids)
      )
  );
END;
$$;


ALTER FUNCTION "public"."is_user_responsible_in_any_pipe"("p_lead_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."is_user_responsible_in_any_pipe"("p_lead_id" "uuid") IS 'Returns true if current user appears as responsible in any pipe for the lead. Checks dual fields (pre_sale_responsible_id, sale_responsible_id) and legacy fields (responsible_id, sdr_id, closer_id) for backward compatibility.';



