CREATE OR REPLACE FUNCTION "public"."lead_excluded_from_metrics"("p_lead_id" "uuid", "p_org_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    COALESCE(
      (SELECT (o.feature_flags ->> 'exclude_custom_pipe_leads_from_metrics')::boolean
         FROM organizations o WHERE o.id = p_org_id),
      false
    )
    AND EXISTS (
      SELECT 1 FROM custom_pipe_entries cpe
      WHERE cpe.lead_id = p_lead_id AND cpe.organization_id = p_org_id
    )
    AND NOT EXISTS (
      SELECT 1 FROM pipe_whatsapp pw
      WHERE pw.lead_id = p_lead_id AND pw.organization_id = p_org_id
    )
    AND NOT EXISTS (
      SELECT 1 FROM pipe_confirmacao pc
      WHERE pc.lead_id = p_lead_id AND pc.organization_id = p_org_id
    )
    AND NOT EXISTS (
      SELECT 1 FROM pipe_propostas pp
      WHERE pp.lead_id = p_lead_id AND pp.organization_id = p_org_id
    );
$$;


ALTER FUNCTION "public"."lead_excluded_from_metrics"("p_lead_id" "uuid", "p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."lead_excluded_from_metrics"("p_lead_id" "uuid", "p_org_id" "uuid") IS 'True when the org opted in (feature_flags.exclude_custom_pipe_leads_from_metrics) and the lead lives only in a custom pipeline (no system pipe). Used by lead-level analytics RPCs to keep prospecting-only leads out of the org metrics. Flag term short-circuits so orgs without the flag pay nothing.';



