CREATE OR REPLACE FUNCTION "public"."leads_derive_uf_from_ddd"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  derived char(2);
BEGIN
  IF (NEW.uf IS NULL OR NEW.uf_source = 'ddd') THEN
    derived := public.uf_from_ddd(COALESCE(NEW.phone_digits, NEW.phone));
    IF derived IS NOT NULL THEN
      NEW.uf := derived;
      NEW.uf_source := 'ddd';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


