CREATE OR REPLACE FUNCTION "public"."link_agent_to_instance"("p_agent_id" "uuid", "p_instance_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_org UUID; v_agent_org UUID; v_instance_org UUID;
BEGIN
  v_user_org := public.get_user_organization_id();
  SELECT organization_id INTO v_agent_org FROM public.copilot_agents WHERE id = p_agent_id;
  SELECT organization_id INTO v_instance_org FROM public.whatsapp_instances WHERE id = p_instance_id;
  IF v_agent_org IS NULL OR v_instance_org IS NULL THEN RAISE EXCEPTION 'Agent or instance not found'; END IF;
  IF v_agent_org != v_user_org OR v_instance_org != v_user_org THEN RAISE EXCEPTION 'Cross-tenant operation denied'; END IF;
  UPDATE public.copilot_agents SET whatsapp_instance_id = NULL WHERE whatsapp_instance_id = p_instance_id AND organization_id = v_user_org;
  UPDATE public.whatsapp_instances SET copilot_agent_id = NULL WHERE copilot_agent_id = p_agent_id AND organization_id = v_user_org;
  UPDATE public.copilot_agents SET whatsapp_instance_id = p_instance_id WHERE id = p_agent_id AND organization_id = v_user_org;
  UPDATE public.whatsapp_instances SET copilot_agent_id = p_agent_id WHERE id = p_instance_id AND organization_id = v_user_org;
END;
$$;


ALTER FUNCTION "public"."link_agent_to_instance"("p_agent_id" "uuid", "p_instance_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_expired_whatsapp_media"("p_older_than_days" integer DEFAULT 30, "p_limit" integer DEFAULT 200) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT COALESCE(
    jsonb_agg(jsonb_build_object(
      'path', name,
      'size', COALESCE((metadata ->> 'size')::bigint, 0)
    )),
    '[]'::jsonb
  )
  FROM (
    SELECT name, metadata
    FROM storage.objects
    WHERE bucket_id = 'media'
      AND name LIKE 'whatsapp-media/%'
      AND created_at < now() - make_interval(days => GREATEST(p_older_than_days, 0))
    ORDER BY created_at ASC
    LIMIT LEAST(GREATEST(p_limit, 0), 5000)
  ) s;
$$;


ALTER FUNCTION "public"."list_expired_whatsapp_media"("p_older_than_days" integer, "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_expired_whatsapp_media"("p_older_than_days" integer, "p_limit" integer) IS 'Lists media bucket objects under whatsapp-media/ older than N days as a jsonb array (single row — avoids the PostgREST 1000-row cap). p_limit hard-capped at 5000. service_role only (edge function whatsapp-media-retention).';



CREATE OR REPLACE FUNCTION "public"."log_activity"("p_type" "text", "p_subject" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_contact_id" "uuid" DEFAULT NULL::"uuid", "p_company_id" "uuid" DEFAULT NULL::"uuid", "p_deal_id" "uuid" DEFAULT NULL::"uuid", "p_lead_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id UUID;
  v_id UUID;
BEGIN
  v_org_id := public.get_user_organization_id();
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'No organization context';
  END IF;

  INSERT INTO public.activities (
    organization_id, type, subject, description,
    contact_id, company_id, deal_id, lead_id,
    owner_id, metadata
  ) VALUES (
    v_org_id, p_type, p_subject, p_description,
    p_contact_id, p_company_id, p_deal_id, p_lead_id,
    auth.uid(), p_metadata
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."log_activity"("p_type" "text", "p_subject" "text", "p_description" "text", "p_contact_id" "uuid", "p_company_id" "uuid", "p_deal_id" "uuid", "p_lead_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_lead_deletion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_type     text;
  v_row      jsonb;
  v_actor    uuid;
  v_role     text;
  v_claims   text;
  v_snapshot jsonb;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_type := 'hard';
  ELSIF TG_OP = 'UPDATE' THEN
    -- só a transição NULL -> NOT NULL conta como soft-delete
    IF OLD.deleted_at IS NOT NULL OR NEW.deleted_at IS NULL THEN
      RETURN COALESCE(NEW, OLD);
    END IF;
    v_type := 'soft';
  ELSE
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- estado final do lead (soft=NEW c/ deleted_at; hard=OLD)
  v_row := to_jsonb(COALESCE(NEW, OLD));

  v_actor := COALESCE(
    (to_jsonb(COALESCE(NEW, OLD))->>'deleted_by')::uuid,
    auth.uid()
  );

  BEGIN
    v_claims := current_setting('request.jwt.claims', true);
    IF v_claims IS NOT NULL AND v_claims <> '' THEN
      v_role := (v_claims::jsonb)->>'role';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_role := NULL;
  END;

  -- snapshot: lead + filhos-chave (ainda presentes no BEFORE DELETE / no soft UPDATE)
  v_snapshot := jsonb_build_object(
    'lead', v_row,
    'conversations',    COALESCE((SELECT jsonb_agg(to_jsonb(c))  FROM public.conversations    c  WHERE c.lead_id  = OLD.id), '[]'::jsonb),
    'lead_history',     COALESCE((SELECT jsonb_agg(to_jsonb(h))  FROM public.lead_history     h  WHERE h.lead_id  = OLD.id), '[]'::jsonb),
    'meetings',         COALESCE((SELECT jsonb_agg(to_jsonb(m))  FROM public.meetings         m  WHERE m.lead_id  = OLD.id), '[]'::jsonb),
    'pipeline_entries', COALESCE((SELECT jsonb_agg(to_jsonb(pe)) FROM public.pipeline_entries pe WHERE pe.lead_id = OLD.id), '[]'::jsonb),
    'lead_tags',        COALESCE((SELECT jsonb_agg(to_jsonb(lt)) FROM public.lead_tags        lt WHERE lt.lead_id = OLD.id), '[]'::jsonb)
  );

  INSERT INTO public.deleted_leads_log (
    organization_id, lead_id, lead_name, lead_phone, lead_email,
    delete_type, deleted_by, actor_role, snapshot
  ) VALUES (
    OLD.organization_id, OLD.id, OLD.name, OLD.phone, OLD.email,
    v_type, v_actor, v_role, v_snapshot
  );

  RETURN COALESCE(NEW, OLD);
EXCEPTION WHEN OTHERS THEN
  -- nunca bloquear o delete por causa de falha no log
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."log_lead_deletion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_permission_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_changed_by_role TEXT := 'system';
  v_org_id UUID;
  v_perm_key TEXT;
  v_role TEXT;
  v_old BOOLEAN;
  v_new BOOLEAN;
BEGIN
  v_user_id := auth.uid();

  -- Identify acting role
  IF v_user_id IS NULL THEN
    v_changed_by_role := 'system';
  ELSIF EXISTS (SELECT 1 FROM public.master_users mu WHERE mu.user_id = v_user_id AND mu.is_active = true) THEN
    v_changed_by_role := 'master';
  ELSIF EXISTS (
    SELECT 1 FROM public.team_members tm
    WHERE tm.user_id = v_user_id AND tm.role = 'admin' AND tm.is_active = true
  ) THEN
    v_changed_by_role := 'admin';
  ELSE
    -- Member toggling somehow — still log but flag as system (RLS should have stopped it).
    v_changed_by_role := 'system';
  END IF;

  IF TG_TABLE_NAME = 'organization_role_permissions' THEN
    IF (TG_OP = 'INSERT') THEN
      v_org_id   := NEW.organization_id;
      v_perm_key := NEW.permission_key;
      v_role     := NEW.role;
      v_old      := NULL;
      v_new      := NEW.enabled;
    ELSIF (TG_OP = 'UPDATE') THEN
      IF OLD.enabled IS NOT DISTINCT FROM NEW.enabled THEN
        RETURN NEW;
      END IF;
      v_org_id   := NEW.organization_id;
      v_perm_key := NEW.permission_key;
      v_role     := NEW.role;
      v_old      := OLD.enabled;
      v_new      := NEW.enabled;
    ELSIF (TG_OP = 'DELETE') THEN
      v_org_id   := OLD.organization_id;
      v_perm_key := OLD.permission_key;
      v_role     := OLD.role;
      v_old      := OLD.enabled;
      v_new      := NULL;
    END IF;
  ELSIF TG_TABLE_NAME = 'feature_permissions' THEN
    -- feature_permissions is global (no organization_id). Use NULL org_id
    -- placeholder via a sentinel: skip logging for non-default_value changes.
    IF (TG_OP = 'UPDATE') THEN
      IF OLD.default_value IS NOT DISTINCT FROM NEW.default_value THEN
        RETURN NEW;
      END IF;
      -- Find an org_id to associate (the active acting user's first org).
      SELECT organization_id INTO v_org_id
      FROM public.team_members
      WHERE user_id = v_user_id
      LIMIT 1;
      IF v_org_id IS NULL THEN
        -- No org to attribute — skip rather than insert NULL FK
        RETURN NEW;
      END IF;
      v_perm_key := NEW.key;
      v_role     := 'member';
      v_old      := OLD.default_value;
      v_new      := NEW.default_value;
    ELSE
      RETURN COALESCE(NEW, OLD);
    END IF;
  END IF;

  INSERT INTO public.permission_audit_log(
    organization_id, changed_by_user_id, changed_by_role,
    table_name, permission_key, role, old_enabled, new_enabled
  ) VALUES (
    v_org_id, v_user_id, v_changed_by_role,
    TG_TABLE_NAME, v_perm_key, v_role, v_old, v_new
  );

  RETURN COALESCE(NEW, OLD);
EXCEPTION
  WHEN OTHERS THEN
    -- Never block a permission toggle because audit logging failed.
    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."log_permission_change"() OWNER TO "postgres";


