CREATE OR REPLACE FUNCTION "public"."mark_conversation_read"("p_instance_id" "uuid", "p_normalized_phone" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_key text := 'whatsapp:' || p_instance_id::text || ':' || p_normalized_phone;
BEGIN
  SELECT organization_id INTO v_org FROM whatsapp_instances WHERE id = p_instance_id;
  -- Acesso: team_member ativo da org OU master ativo (ghost cross-org).
  IF v_org IS NULL OR (NOT (v_org IN (SELECT get_my_organization_ids())) AND NOT is_master_user()) THEN
    RAISE EXCEPTION 'forbidden: instance not accessible' USING ERRCODE = '42501';
  END IF;

  INSERT INTO conversation_read_state
    (organization_id, user_id, conversation_key, last_read_at, updated_at)
  VALUES (v_org, auth.uid(), v_key, now(), now())
  ON CONFLICT (organization_id, user_id, conversation_key)
  DO UPDATE SET last_read_at = now(), updated_at = now();
END;
$$;


ALTER FUNCTION "public"."mark_conversation_read"("p_instance_id" "uuid", "p_normalized_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."master_add_user"("_email" "text", "_notes" "text" DEFAULT 'Adicionado via função'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_target_user_id UUID;
  v_new_master_id UUID;
BEGIN
  -- Verificar se quem está executando é master
  IF NOT public.is_master_user() THEN
    RAISE EXCEPTION 'Acesso negado: apenas usuarios master podem adicionar novos masters';
  END IF;

  -- Buscar user_id pelo email
  SELECT id INTO v_target_user_id
  FROM auth.users
  WHERE email = _email;

  IF v_target_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuario com email % nao encontrado', _email;
  END IF;

  -- Inserir como master
  INSERT INTO public.master_users (user_id, granted_by, notes, permissions)
  VALUES (
    v_target_user_id,
    auth.uid(),
    _notes,
    '{"all": true}'::jsonb
  )
  RETURNING id INTO v_new_master_id;

  -- Log da ação
  INSERT INTO public.master_audit_logs (master_user_id, user_id, action, target_type, target_id, details)
  SELECT 
    m.id,
    auth.uid(),
    'MASTER_ADD',
    'user',
    v_target_user_id,
    jsonb_build_object('email', _email, 'notes', _notes)
  FROM public.master_users m 
  WHERE m.user_id = auth.uid();

  RETURN v_new_master_id;
END;
$$;


