CREATE OR REPLACE FUNCTION "public"."master_get_org_sales_summary"("p_org_id" "uuid", "p_start" "date", "p_end" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_num_vendas    integer := 0;
  v_receita_total numeric := 0;
  v_ticket_medio  numeric := 0;
  v_sale_values   numeric[] := '{}';
  v_start         timestamptz;
  v_end           timestamptz;
BEGIN
  -- Gate de acesso: SÓ master. Sem fallback por org membership (master não tem).
  IF NOT public.is_master_user() THEN
    RAISE EXCEPTION 'forbidden: master only';
  END IF;

  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'p_org_id is required';
  END IF;

  -- Bordas por created_at do lead: [p_start 00:00, p_end+1dia) — dia inclusivo.
  v_start := p_start::timestamptz;
  v_end   := (p_end + 1)::timestamptz;

  WITH cohort AS (
    -- Leads criados no período, não-deletados (espelha o cohort da Saúde).
    SELECT id
    FROM public.leads
    WHERE organization_id = p_org_id
      AND deleted_at IS NULL
      AND created_at >= v_start
      AND created_at <  v_end
  ),
  vendas AS (
    -- Coorte que virou venda: entry 'vendido' no pipe SYSTEM 'propostas'.
    -- Um row por lead (a contagem = distinct cohort leads que venderam).
    SELECT pe.lead_id,
           MAX(COALESCE((pe.metadata ->> 'sale_value')::numeric, 0)) AS sale_value
    FROM public.pipeline_entries pe
    JOIN public.pipelines pip
      ON pip.id = pe.pipeline_id AND pip.slug = 'propostas' AND pip.type = 'system'
    WHERE pe.organization_id = p_org_id
      AND pe.stage_key = 'vendido'
      AND pe.lead_id IN (SELECT id FROM cohort)
    GROUP BY pe.lead_id
  )
  SELECT
    COUNT(*)::integer,
    COALESCE(SUM(sale_value), 0),
    COALESCE(array_agg(sale_value), '{}')
  INTO v_num_vendas, v_receita_total, v_sale_values
  FROM vendas;

  IF v_num_vendas > 0 THEN
    v_ticket_medio := v_receita_total / v_num_vendas;
  END IF;

  RETURN jsonb_build_object(
    'num_vendas',    v_num_vendas,
    'receita_total', v_receita_total,
    'ticket_medio',  v_ticket_medio,
    'sale_values',   to_jsonb(v_sale_values),
    'period_start',  p_start,
    'period_end',    p_end
  );
END;
$$;


ALTER FUNCTION "public"."master_get_org_sales_summary"("p_org_id" "uuid", "p_start" "date", "p_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."master_override_billing"("_org_id" "uuid", "_plan" "text", "_reason" "text", "_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_master_id UUID;
BEGIN
  IF NOT public.is_master_user() THEN
    RAISE EXCEPTION 'Acesso negado: apenas usuarios master podem executar esta acao';
  END IF;

  -- Buscar ID do master
  SELECT id INTO v_master_id FROM public.master_users WHERE user_id = auth.uid();

  -- Atualizar organizacao
  UPDATE public.organizations SET
    subscription_status = 'active',
    subscription_plan = _plan,
    subscription_expires_at = COALESCE(_expires_at, NOW() + INTERVAL '100 years'),
    billing_override = true,
    billing_override_reason = _reason,
    billing_override_by = auth.uid(),
    billing_override_at = NOW(),
    updated_at = NOW()
  WHERE id = _org_id;

  -- Log da acao
  INSERT INTO public.master_audit_logs (master_user_id, user_id, action, target_type, target_id, details)
  VALUES (
    v_master_id,
    auth.uid(),
    'BILLING_OVERRIDE',
    'organization',
    _org_id,
    jsonb_build_object(
      'plan', _plan,
      'reason', _reason,
      'expires_at', _expires_at
    )
  );
END;
$$;


