CREATE OR REPLACE FUNCTION "public"."match_onboarding_templates"("p_org_id" "uuid", "p_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_answers jsonb;
  v_results jsonb := '[]'::jsonb;
  v_row record;
  v_match boolean;
  v_key text;
  v_allowed_values jsonb;
  v_actual_value jsonb;
  v_path_parts text[];
BEGIN
  SELECT onboarding_answers INTO v_answers
  FROM organizations WHERE id = p_org_id;

  IF v_answers IS NULL THEN
    v_answers := '{}'::jsonb;
  END IF;

  IF p_type = 'pipeline' THEN
    FOR v_row IN
      SELECT * FROM onboarding_pipeline_templates
      WHERE is_active = true
      ORDER BY priority DESC, created_at ASC
    LOOP
      v_match := true;
      IF v_row.match_criteria IS NOT NULL AND v_row.match_criteria != '{}'::jsonb THEN
        FOR v_key, v_allowed_values IN
          SELECT * FROM jsonb_each(v_row.match_criteria)
        LOOP
          v_path_parts := string_to_array(v_key, '.');
          v_actual_value := v_answers;
          FOR i IN 1..array_length(v_path_parts, 1) LOOP
            v_actual_value := v_actual_value -> v_path_parts[i];
          END LOOP;
          IF v_actual_value IS NULL OR NOT (v_allowed_values ? (v_actual_value #>> '{}')) THEN
            v_match := false;
            EXIT;
          END IF;
        END LOOP;
      END IF;
      IF v_match THEN
        v_results := v_results || jsonb_build_object(
          'id', v_row.id,
          'name', v_row.name,
          'description', v_row.description,
          'icon', v_row.icon,
          'color', v_row.color,
          'default_pipelines_config', v_row.default_pipelines_config,
          'custom_pipelines', v_row.custom_pipelines,
          'priority', v_row.priority
        );
      END IF;
    END LOOP;
  ELSIF p_type = 'automation' THEN
    FOR v_row IN
      SELECT * FROM onboarding_automation_templates
      WHERE is_active = true
      ORDER BY created_at ASC
    LOOP
      v_match := true;
      IF v_row.match_criteria IS NOT NULL AND v_row.match_criteria != '{}'::jsonb THEN
        FOR v_key, v_allowed_values IN
          SELECT * FROM jsonb_each(v_row.match_criteria)
        LOOP
          v_path_parts := string_to_array(v_key, '.');
          v_actual_value := v_answers;
          FOR i IN 1..array_length(v_path_parts, 1) LOOP
            v_actual_value := v_actual_value -> v_path_parts[i];
          END LOOP;
          IF v_actual_value IS NULL OR NOT (v_allowed_values ? (v_actual_value #>> '{}')) THEN
            v_match := false;
            EXIT;
          END IF;
        END LOOP;
      END IF;
      IF v_match THEN
        v_results := v_results || jsonb_build_object(
          'id', v_row.id,
          'name', v_row.name,
          'description', v_row.description,
          'type', v_row.type,
          'icon', v_row.icon,
          'trigger_type', v_row.trigger_type,
          'customizable_fields', v_row.customizable_fields
        );
      END IF;
    END LOOP;
  END IF;

  RETURN v_results;
END;
$$;


ALTER FUNCTION "public"."match_onboarding_templates"("p_org_id" "uuid", "p_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."matches_workflow_trigger_config"("p_trigger_type" "text", "p_config" "jsonb", "p_context" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_stages JSONB;
  v_to_stage TEXT;
BEGIN
  CASE p_trigger_type

  WHEN 'stage_changed' THEN
    IF p_config->>'pipe_type' IS NOT NULL AND p_config->>'pipe_type' != ''
       AND p_context->>'pipe_type' IS NOT NULL
       AND p_config->>'pipe_type' != p_context->>'pipe_type'
    THEN RETURN FALSE; END IF;

    IF p_config->>'pipeline_id' IS NOT NULL AND p_config->>'pipeline_id' != ''
       AND p_context->>'pipeline_id' IS NOT NULL
       AND p_config->>'pipeline_id' != p_context->>'pipeline_id'
    THEN RETURN FALSE; END IF;

    IF p_config->>'from_stage' IS NOT NULL AND p_config->>'from_stage' != ''
       AND p_context->>'from_stage' IS NOT NULL
       AND p_config->>'from_stage' != p_context->>'from_stage'
    THEN RETURN FALSE; END IF;

    v_stages := p_config->'stages';
    v_to_stage := p_context->>'to_stage';
    IF v_stages IS NOT NULL AND jsonb_array_length(v_stages) > 0 AND v_to_stage IS NOT NULL THEN
      IF NOT v_stages ? v_to_stage THEN RETURN FALSE; END IF;
    ELSIF p_config->>'to_stage' IS NOT NULL AND p_config->>'to_stage' != ''
          AND v_to_stage IS NOT NULL
          AND p_config->>'to_stage' != v_to_stage
    THEN RETURN FALSE; END IF;

    RETURN TRUE;

  WHEN 'field_changed' THEN
    IF p_config->>'field_name' IS NOT NULL AND p_config->>'field_name' != ''
       AND p_context->>'field_name' IS NOT NULL
       AND p_config->>'field_name' != p_context->>'field_name'
    THEN RETURN FALSE; END IF;
    RETURN TRUE;

  WHEN 'lead_created' THEN
    IF p_config->>'filter_origin' IS NOT NULL AND p_config->>'filter_origin' != ''
       AND p_context->>'origin' IS NOT NULL
       AND p_config->>'filter_origin' != p_context->>'origin'
    THEN RETURN FALSE; END IF;

    IF p_config->>'filter_pipe' IS NOT NULL AND p_config->>'filter_pipe' != ''
       AND COALESCE(p_context->>'pipe', p_context->>'pipe_type') IS NOT NULL
       AND p_config->>'filter_pipe' != COALESCE(p_context->>'pipe', p_context->>'pipe_type')
    THEN RETURN FALSE; END IF;

    RETURN TRUE;

  WHEN 'tag_added' THEN
    IF p_config->>'tag_name' IS NOT NULL AND p_config->>'tag_name' != ''
       AND p_context->>'tag_name' IS NOT NULL
       AND lower(p_config->>'tag_name') != lower(p_context->>'tag_name')
    THEN RETURN FALSE; END IF;
    RETURN TRUE;

  WHEN 'score_reached' THEN
    IF COALESCE((p_config->>'min_score')::int, 0) > 0
       AND COALESCE((p_context->>'score')::int, 0) < (p_config->>'min_score')::int
    THEN RETURN FALSE; END IF;
    RETURN TRUE;

  ELSE
    RETURN TRUE;
  END CASE;
END;
$$;


ALTER FUNCTION "public"."matches_workflow_trigger_config"("p_trigger_type" "text", "p_config" "jsonb", "p_context" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_exec_readonly_sql"("p_sql" "text", "p_max_rows" integer DEFAULT 1000) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_result jsonb;
  v_clean text := btrim(p_sql);
  v_rows int := greatest(1, least(coalesce(p_max_rows, 1000), 5000));
BEGIN
  -- 1. master-only
  IF NOT public.is_master_user() THEN
    RAISE EXCEPTION 'mcp_exec_readonly_sql: master only';
  END IF;

  -- 2. parse guard (mirror of the edge-side isReadOnlySql)
  v_clean := btrim(regexp_replace(v_clean, ';+\s*$', ''));  -- strip a trailing ';'
  IF v_clean = '' THEN
    RAISE EXCEPTION 'empty query';
  END IF;
  IF position(';' IN v_clean) > 0 THEN
    RAISE EXCEPTION 'only a single statement is allowed';
  END IF;
  IF lower(v_clean) !~ '^(select|with)\s' THEN
    RAISE EXCEPTION 'only SELECT / WITH read-only queries are allowed';
  END IF;

  -- 3+4+5. contained execution.
  -- The function is OWNED BY mcp_readonly (see ALTER below) and SECURITY DEFINER, so the whole
  -- body already runs AS mcp_readonly — no SET ROLE (which Postgres forbids inside a
  -- security-definer function). The role's SELECT-only grants + secret-table revokes are the wall.
  SET LOCAL TRANSACTION READ ONLY;
  SET LOCAL statement_timeout = '5000';

  EXECUTE format(
    'SELECT coalesce(jsonb_agg(t), ''[]''::jsonb) FROM (SELECT * FROM (%s) _q LIMIT %s) t',
    v_clean,
    v_rows
  )
  INTO v_result;

  RETURN v_result;
END
$_$;


ALTER FUNCTION "public"."mcp_exec_readonly_sql"("p_sql" "text", "p_max_rows" integer) OWNER TO "mcp_readonly";


COMMENT ON FUNCTION "public"."mcp_exec_readonly_sql"("p_sql" "text", "p_max_rows" integer) IS 'Torque MCP db.read_sql — runs a single read-only SELECT as mcp_readonly in a READ ONLY txn. Master-only.';



CREATE OR REPLACE FUNCTION "public"."merge_leads"("p_keep_lead_id" "uuid", "p_merge_lead_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE
  v_keep_org   uuid;
  v_merge_org  uuid;
  r            RECORD;
  v_other_cols text;
  v_pred       text;
  v_sql        text;
BEGIN
  IF p_keep_lead_id IS NULL OR p_merge_lead_id IS NULL THEN
    RAISE EXCEPTION 'merge_leads: ids obrigatórios' USING ERRCODE = 'P0001';
  END IF;

  IF p_keep_lead_id = p_merge_lead_id THEN
    RAISE EXCEPTION 'merge_leads: não é possível mesclar um lead nele mesmo'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT organization_id INTO v_keep_org  FROM public.leads WHERE id = p_keep_lead_id;
  SELECT organization_id INTO v_merge_org FROM public.leads WHERE id = p_merge_lead_id;

  IF v_keep_org IS NULL OR v_merge_org IS NULL THEN
    RAISE EXCEPTION 'merge_leads: lead não encontrado' USING ERRCODE = 'P0002';
  END IF;

  IF v_keep_org <> v_merge_org THEN
    RAISE EXCEPTION 'merge_leads: leads de organizações diferentes não podem ser mesclados'
      USING ERRCODE = 'P0001';
  END IF;

  PERFORM public.assert_org_access(v_keep_org);

  FOR r IN
    SELECT
      n.nspname                 AS table_schema,
      c.relname                 AS table_name,
      c.oid                     AS table_oid,
      fka.attname               AS fk_col,
      fka.attnum                AS fk_attnum,
      idx.indkey::text          AS indkey_txt,
      (idx.indpred IS NOT NULL) AS is_partial,
      pg_get_expr(idx.indpred, idx.indrelid) AS pred_expr
    FROM pg_constraint fk
    JOIN pg_class     c   ON c.oid  = fk.conrelid
    JOIN pg_namespace n   ON n.oid  = c.relnamespace
    JOIN pg_class     rc  ON rc.oid = fk.confrelid
    JOIN pg_namespace rn  ON rn.oid = rc.relnamespace
    JOIN pg_attribute rka ON rka.attrelid = fk.confrelid AND rka.attnum = fk.confkey[1]
    JOIN pg_attribute fka ON fka.attrelid = fk.conrelid  AND fka.attnum = fk.conkey[1]
    JOIN pg_index     idx ON idx.indrelid = fk.conrelid
                         AND idx.indisunique
                         AND idx.indisvalid
                         AND idx.indislive
    WHERE fk.contype = 'f'
      AND rn.nspname = 'public'
      AND rc.relname = 'leads'
      AND rka.attname = 'id'
      AND array_length(fk.conkey, 1) = 1
      AND n.nspname = 'public'
      AND c.relname <> 'leads'
      AND fka.attnum = ANY (string_to_array(idx.indkey::text, ' ')::smallint[])
      AND 0 <> ALL (string_to_array(idx.indkey::text, ' ')::smallint[])
  LOOP
    SELECT string_agg(quote_ident(a.attname), ', ' ORDER BY k.ord)
      INTO v_other_cols
    FROM unnest(string_to_array(r.indkey_txt, ' ')::smallint[]) WITH ORDINALITY AS k(attnum, ord)
    JOIN pg_attribute a ON a.attrelid = r.table_oid AND a.attnum = k.attnum
    WHERE k.attnum <> r.fk_attnum;

    v_pred := CASE WHEN r.is_partial THEN ' AND (' || r.pred_expr || ')' ELSE '' END;

    IF v_other_cols IS NULL THEN
      v_sql := format(
        'DELETE FROM %I.%I t WHERE t.%I = $1%s '
        'AND EXISTS (SELECT 1 FROM %I.%I s WHERE s.%I = $2%s)',
        r.table_schema, r.table_name, r.fk_col, v_pred,
        r.table_schema, r.table_name, r.fk_col, v_pred);
    ELSE
      v_sql := format(
        'DELETE FROM %I.%I t WHERE t.%I = $1%s '
        'AND (%s) IN (SELECT %s FROM %I.%I s WHERE s.%I = $2%s)',
        r.table_schema, r.table_name, r.fk_col, v_pred,
        v_other_cols, v_other_cols,
        r.table_schema, r.table_name, r.fk_col, v_pred);
    END IF;

    EXECUTE v_sql USING p_merge_lead_id, p_keep_lead_id;
  END LOOP;

  FOR r IN
    SELECT DISTINCT
      tc.table_schema,
      tc.table_name,
      kcu.column_name
    FROM information_schema.table_constraints tc
    JOIN information_schema.key_column_usage kcu
      ON tc.constraint_name = kcu.constraint_name
     AND tc.table_schema = kcu.table_schema
    JOIN information_schema.constraint_column_usage ccu
      ON tc.constraint_name = ccu.constraint_name
     AND tc.table_schema = ccu.table_schema
    WHERE tc.constraint_type = 'FOREIGN KEY'
      AND ccu.table_schema = 'public'
      AND ccu.table_name = 'leads'
      AND ccu.column_name = 'id'
      AND tc.table_schema = 'public'
      AND tc.table_name <> 'leads'
  LOOP
    v_sql := format(
      'UPDATE %I.%I SET %I = $1 WHERE %I = $2',
      r.table_schema, r.table_name, r.column_name, r.column_name
    );
    EXECUTE v_sql USING p_keep_lead_id, p_merge_lead_id;
  END LOOP;

  WITH ranked AS (
    SELECT
      id,
      ROW_NUMBER() OVER (
        PARTITION BY workflow_id, lead_id
        ORDER BY started_at ASC, id ASC
      ) AS rn
    FROM public.workflow_executions
    WHERE status IN ('pending', 'processing', 'waiting')
      AND lead_id = p_keep_lead_id
  )
  UPDATE public.workflow_executions we
     SET status = 'cancelled',
         error = COALESCE(we.error, '') || ' [auto-cancelled: lead merge]',
         completed_at = now()
    FROM ranked r
   WHERE we.id = r.id
     AND r.rn > 1;

  DELETE FROM public.leads WHERE id = p_merge_lead_id;
END;
$_$;


ALTER FUNCTION "public"."merge_leads"("p_keep_lead_id" "uuid", "p_merge_lead_id" "uuid") OWNER TO "postgres";


