CREATE OR REPLACE FUNCTION "public"."metric_period_bounds"("p_org_id" "uuid", "p_period" "text", "p_ref" "date" DEFAULT NULL::"date", "p_start" "date" DEFAULT NULL::"date", "p_end" "date" DEFAULT NULL::"date") RETURNS "tstzrange"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_tz text; v_ref date; v_start_local date; v_end_local date;
BEGIN
  SELECT o.timezone INTO v_tz FROM public.organizations o WHERE o.id = p_org_id;
  IF v_tz IS NULL THEN
    RAISE EXCEPTION 'metric_period_bounds: organization % not found', p_org_id USING ERRCODE = 'P0002';
  END IF;
  v_ref := COALESCE(p_ref, (now() AT TIME ZONE v_tz)::date);
  CASE p_period
    WHEN 'day' THEN v_start_local := v_ref; v_end_local := v_ref + 1;
    WHEN 'week' THEN v_start_local := date_trunc('week', v_ref::timestamp)::date; v_end_local := v_start_local + 7;
    WHEN 'month' THEN v_start_local := date_trunc('month', v_ref::timestamp)::date; v_end_local := (date_trunc('month', v_ref::timestamp) + interval '1 month')::date;
    WHEN 'range' THEN
      IF p_start IS NULL OR p_end IS NULL THEN RAISE EXCEPTION 'metric_period_bounds: period ''range'' requires p_start and p_end' USING ERRCODE = '22023'; END IF;
      IF p_end < p_start THEN RAISE EXCEPTION 'metric_period_bounds: p_end (%) before p_start (%)', p_end, p_start USING ERRCODE = '22023'; END IF;
      v_start_local := p_start; v_end_local := p_end + 1;
    ELSE RAISE EXCEPTION 'metric_period_bounds: unknown period "%" (expected day|week|month|range)', p_period USING ERRCODE = '22023';
  END CASE;
  RETURN tstzrange(v_start_local::timestamp AT TIME ZONE v_tz, v_end_local::timestamp AT TIME ZONE v_tz, '[)');
END;
$$;


ALTER FUNCTION "public"."metric_period_bounds"("p_org_id" "uuid", "p_period" "text", "p_ref" "date", "p_start" "date", "p_end" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."metric_period_bounds"("p_org_id" "uuid", "p_period" "text", "p_ref" "date", "p_start" "date", "p_end" "date") IS 'ADR-0017 §5 / #989: resolves a NAMED period (day|week|month|range) into a half-open [start,end) tstzrange cut in the organization''s timezone. The single source of period boundaries — frontend and RPCs must never compute period cuts themselves.';



CREATE OR REPLACE FUNCTION "public"."metric_stage_role"("p_organization_id" "uuid", "p_pipeline_id" "uuid", "p_stage_key" "text") RETURNS "public"."stage_role"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN p.type = 'custom' THEN (
      SELECT cps.stage_role FROM public.custom_pipeline_stages cps
      WHERE cps.pipeline_id = p.id AND cps.organization_id = p.organization_id AND cps.stage_key = p_stage_key
    )
    ELSE (
      SELECT ps.stage_role FROM public.pipeline_stages ps
      WHERE ps.organization_id = p.organization_id AND ps.pipeline_type = p.slug AND ps.stage_key = p_stage_key
    )
  END
  FROM public.pipelines p
  WHERE p.id = p_pipeline_id AND p.organization_id = p_organization_id AND p_stage_key IS NOT NULL
$$;


ALTER FUNCTION "public"."metric_stage_role"("p_organization_id" "uuid", "p_pipeline_id" "uuid", "p_stage_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."metric_stage_role"("p_organization_id" "uuid", "p_pipeline_id" "uuid", "p_stage_key" "text") IS 'ADR-0017 §1 / #993 / U1 — dispatch por pipelines.type: custom → custom_pipeline_stages, system → pipeline_stages. NULL = nenhum governa (≙ open). Ponto único de extensão.';



CREATE OR REPLACE FUNCTION "public"."migrate_follow_ups_to_activities"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id UUID;
  v_count INT := 0;
BEGIN
  v_org_id := public.get_user_organization_id();
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'No organization context';
  END IF;

  INSERT INTO public.activities (
    organization_id, type, subject, description, lead_id,
    owner_id, assigned_to, due_date, completed_at,
    source, created_at, metadata
  )
  SELECT
    f.organization_id,
    'task',
    f.title,
    f.description,
    f.lead_id,
    f.created_by,
    (SELECT tm.id FROM public.team_members tm WHERE tm.user_id = f.assigned_to AND tm.organization_id = f.organization_id LIMIT 1),
    f.due_date,
    f.completed_at,
    'migration',
    f.created_at,
    jsonb_build_object('original_follow_up_id', f.id, 'type', f.type, 'priority', f.priority)
  FROM public.follow_ups f
  WHERE f.organization_id = v_org_id
    AND NOT EXISTS (
      SELECT 1 FROM public.activities a
      WHERE a.metadata->>'original_follow_up_id' = f.id::TEXT
        AND a.organization_id = v_org_id
    );

  GET DIAGNOSTICS v_count = ROW_COUNT;

  RETURN jsonb_build_object('migrated_count', v_count);
END;
$$;


ALTER FUNCTION "public"."migrate_follow_ups_to_activities"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."migrate_leads_to_contacts_companies"("p_batch_size" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id UUID;
  v_lead RECORD;
  v_company_id UUID;
  v_contact_id UUID;
  v_migrated INT := 0;
  v_company_count INT := 0;
  v_contact_count INT := 0;
BEGIN
  -- Resolve caller org
  v_org_id := public.get_user_organization_id();
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'No organization found for current user';
  END IF;

  FOR v_lead IN
    SELECT id, name, email, phone, normalized_phone, company
    FROM public.leads
    WHERE organization_id = v_org_id
      AND contact_id IS NULL
      AND deleted_at IS NULL
    ORDER BY created_at
    LIMIT p_batch_size
  LOOP
    v_company_id := NULL;

    -- Upsert company if lead has company text
    IF v_lead.company IS NOT NULL AND TRIM(v_lead.company) <> '' THEN
      -- Try to find existing company first (functional index match)
      SELECT id INTO v_company_id
      FROM public.companies
      WHERE organization_id = v_org_id
        AND LOWER(TRIM(name)) = LOWER(TRIM(v_lead.company));

      IF v_company_id IS NULL THEN
        INSERT INTO public.companies (organization_id, name)
          VALUES (v_org_id, TRIM(v_lead.company))
          RETURNING id INTO v_company_id;
        v_company_count := v_company_count + 1;
      END IF;
    END IF;

    -- Insert contact
    INSERT INTO public.contacts (
      organization_id, company_id, name, email, phone,
      normalized_phone, source, source_lead_id
    ) VALUES (
      v_org_id, v_company_id, v_lead.name, v_lead.email, v_lead.phone,
      v_lead.normalized_phone, 'migration', v_lead.id
    )
    RETURNING id INTO v_contact_id;

    v_contact_count := v_contact_count + 1;

    -- Link back to lead
    UPDATE public.leads
    SET contact_id = v_contact_id,
        company_entity_id = v_company_id
    WHERE id = v_lead.id;

    v_migrated := v_migrated + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'migrated_count', v_migrated,
    'company_count', v_company_count,
    'contact_count', v_contact_count
  );
END;
$$;


ALTER FUNCTION "public"."migrate_leads_to_contacts_companies"("p_batch_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_br_mobile"("digits" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT CASE
    -- 13 digits with 55: standard BR mobile, keep as is
    WHEN length(digits) = 13 AND left(digits, 2) = '55' THEN digits
    -- 12 digits starting with 55: missing 9th digit → insert after DDD
    WHEN length(digits) = 12 AND left(digits, 2) = '55'
    THEN left(digits, 4) || '9' || substr(digits, 5)
    -- 11 digits (DDD + 9 + 8): add country code
    WHEN length(digits) = 11 AND substr(digits, 3, 1) = '9'
    THEN '55' || digits
    -- 10 digits (DDD + 8): add country code + 9th digit
    WHEN length(digits) = 10
    THEN '55' || left(digits, 2) || '9' || substr(digits, 3)
    ELSE digits
  END;
$$;


ALTER FUNCTION "public"."normalize_br_mobile"("digits" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_brazilian_phone"("phone" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  cleaned TEXT;
BEGIN
  -- Se nulo ou vazio, retornar nulo
  IF phone IS NULL OR phone = '' THEN
    RETURN NULL;
  END IF;

  -- Remove tudo que não é dígito
  cleaned := regexp_replace(phone, '\D', '', 'g');

  -- Se vazio após limpeza, retornar nulo
  IF cleaned = '' THEN
    RETURN NULL;
  END IF;

  -- Remover prefixo internacional +55 ou 55 se presente (12+ dígitos)
  IF length(cleaned) >= 12 AND left(cleaned, 2) = '55' THEN
    cleaned := substring(cleaned from 3);
  END IF;

  -- Adicionar 9 se número celular de 8 dígitos (DDD + 8 dígitos = 10 dígitos)
  -- Celulares brasileiros: DDD(2) + 9(1) + número(8) = 11 dígitos
  IF length(cleaned) = 10 THEN
    -- Inserir 9 após o DDD
    cleaned := left(cleaned, 2) || '9' || substring(cleaned from 3);
  END IF;

  -- Formato final: 11 dígitos (DDD + 9 + 8 dígitos) para celular brasileiro
  -- Ou 10 dígitos para fixo (DDD + 8 dígitos)
  RETURN cleaned;
END;
$$;


ALTER FUNCTION "public"."normalize_brazilian_phone"("phone" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."normalize_brazilian_phone"("phone" "text") IS 'Normaliza telefone brasileiro removendo formatação e padronizando para 11 dígitos (celular) ou 10 (fixo)';



