CREATE OR REPLACE FUNCTION "public"."notify_support_ticket_reply"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  t RECORD;
BEGIN
  IF NEW.is_internal THEN
    RETURN NEW;
  END IF;

  SELECT id, organization_id, author_user_id, title
    INTO t
    FROM public.support_tickets
   WHERE id = NEW.ticket_id;

  IF public.is_master_user(NEW.author_user_id) THEN
    IF t.author_user_id IS NULL THEN
      RETURN NEW;
    END IF;
    IF t.author_user_id = NEW.author_user_id THEN
      RETURN NEW;
    END IF;

    INSERT INTO public.notifications (organization_id, user_id, type, title, description, entity_id)
    VALUES (
      t.organization_id,
      t.author_user_id,
      'support_ticket_reply',
      'O suporte respondeu seu chamado',
      left(t.title, 120),
      t.id
    );
  ELSE
    INSERT INTO public.notifications (organization_id, user_id, type, title, description, entity_id)
    SELECT
      t.organization_id,
      mu.user_id,
      'support_ticket_customer_reply',
      'Cliente respondeu um chamado',
      left(t.title, 120),
      t.id
    FROM public.master_users mu
    WHERE mu.is_active
      AND mu.user_id IS NOT NULL
      AND mu.user_id <> NEW.author_user_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_support_ticket_reply"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."org_check_limit"("p_org_id" "uuid", "p_limit_key" "text") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_org RECORD;
  v_plan_limits JSONB;
BEGIN
  -- Master sempre tem ilimitado
  IF public.is_master_user() THEN
    RETURN -1;
  END IF;

  -- Buscar org com overrides
  SELECT o.limit_overrides, o.subscription_plan
  INTO v_org
  FROM public.organizations o
  WHERE o.id = p_org_id;

  -- 1. Verificar override de limite na org
  IF v_org.limit_overrides IS NOT NULL AND v_org.limit_overrides ? p_limit_key THEN
    RETURN (v_org.limit_overrides ->> p_limit_key)::INTEGER;
  END IF;

  -- 2. Verificar limite no plano da org
  SELECT sp.limits INTO v_plan_limits
  FROM public.subscription_plans sp
  WHERE sp.name = v_org.subscription_plan;

  IF v_plan_limits IS NOT NULL AND v_plan_limits ? p_limit_key THEN
    RETURN (v_plan_limits ->> p_limit_key)::INTEGER;
  END IF;

  -- 3. Default: 0 (sem acesso)
  RETURN 0;
END;
$$;


ALTER FUNCTION "public"."org_check_limit"("p_org_id" "uuid", "p_limit_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."org_check_limit"("p_org_id" "uuid", "p_limit_key" "text") IS 'Retorna o limite de um recurso para uma org. -1 = ilimitado, 0 = sem acesso.';



CREATE OR REPLACE FUNCTION "public"."org_get_features_and_limits"("p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_features     JSONB := '{}';
  v_limits       JSONB := '{}';
  v_plan_features JSONB;
  v_plan_limits  JSONB;
  v_org          RECORD;
  v_override     RECORD;
  v_flag         RECORD;
  v_quota_row    RECORD;
  v_quota_keys   TEXT[] := ARRAY['max_whatsapp_instances', 'max_users', 'max_copilot_agents'];
BEGIN
  -- Master: tudo habilitado e ilimitado (unchanged)
  IF public.is_master_user() THEN
    FOR v_flag IN SELECT key FROM public.feature_flags LOOP
      v_features := v_features || jsonb_build_object(v_flag.key, true);
    END LOOP;
    RETURN jsonb_build_object(
      'features', v_features,
      'limits', '{"max_leads":-1,"max_users":-1,"max_campaigns":-1,"max_copilot_agents":-1,"max_whatsapp_instances":-1,"max_funnels":-1,"max_documents_per_agent":-1}'::JSONB,
      'plan_name', 'master'
    );
  END IF;

  -- Buscar plano da org
  SELECT o.subscription_plan, o.limit_overrides,
         COALESCE(sp.features, '{}') AS plan_features,
         COALESCE(sp.limits, '{}') AS plan_limits
  INTO v_org
  FROM public.organizations o
  LEFT JOIN public.subscription_plans sp ON sp.name = o.subscription_plan
  WHERE o.id = p_org_id;

  v_plan_features := COALESCE(v_org.plan_features, '{}');
  v_plan_limits := COALESCE(v_org.plan_limits, '{}');

  -- Montar features: plano base
  v_features := v_plan_features;

  -- Aplicar overrides de features (organization_features)
  FOR v_override IN
    SELECT feature_key, enabled
    FROM public.organization_features
    WHERE organization_id = p_org_id
      AND (expires_at IS NULL OR expires_at > NOW())
  LOOP
    v_features := v_features || jsonb_build_object(v_override.feature_key, v_override.enabled);
  END LOOP;

  -- Para features nao presentes no plano, usar default_enabled
  FOR v_flag IN
    SELECT key, default_enabled FROM public.feature_flags
    WHERE NOT (v_features ? key)
  LOOP
    v_features := v_features || jsonb_build_object(v_flag.key, v_flag.default_enabled);
  END LOOP;

  -- Montar limites: plano base + overrides (non-quota limits)
  v_limits := v_plan_limits;
  IF v_org.limit_overrides IS NOT NULL AND v_org.limit_overrides != '{}'::JSONB THEN
    v_limits := v_limits || v_org.limit_overrides;
  END IF;

  -- Override quota-managed resources with org_quotas.effective_limit
  FOR v_quota_row IN
    SELECT oq.resource_key, oq.effective_limit
    FROM public.org_quotas oq
    WHERE oq.organization_id = p_org_id
      AND oq.resource_key = ANY(v_quota_keys)
  LOOP
    v_limits := v_limits || jsonb_build_object(v_quota_row.resource_key, v_quota_row.effective_limit);
  END LOOP;

  RETURN jsonb_build_object(
    'features', v_features,
    'limits', v_limits,
    'plan_name', COALESCE(v_org.subscription_plan, 'free')
  );
END;
$$;


ALTER FUNCTION "public"."org_get_features_and_limits"("p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."org_get_features_and_limits"("p_org_id" "uuid") IS 'Retorna todas as features e limites de uma org em uma unica chamada (otimizado para frontend)';



CREATE OR REPLACE FUNCTION "public"."org_get_seat_usage"("p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_quota    JSONB;
  v_plan_name TEXT;
BEGIN
  PERFORM public.assert_org_access(p_org_id);
  -- Use unified quota resolution
  v_quota := public.org_resolve_quota(p_org_id, 'max_users');

  -- Get plan name for backward compat
  SELECT COALESCE(sp.name, o.subscription_plan, 'free')
  INTO v_plan_name
  FROM public.organizations o
  LEFT JOIN public.org_subscriptions os ON os.organization_id = o.id AND os.cancelled_at IS NULL
  LEFT JOIN public.subscription_plans sp ON sp.id = os.plan_id
  WHERE o.id = p_org_id;

  -- Return same shape as before
  RETURN jsonb_build_object(
    'paid_seats',     (v_quota->>'effective_limit')::INTEGER,
    'active_members', (v_quota->>'current_usage')::INTEGER,
    'plan_name',      COALESCE(v_plan_name, 'unknown'),
    'is_unlimited',   (v_quota->>'is_unlimited')::BOOLEAN,
    'can_add',        (v_quota->>'can_add')::BOOLEAN,
    'remaining',      (v_quota->>'remaining')::INTEGER
  );
END;
$$;


ALTER FUNCTION "public"."org_get_seat_usage"("p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."org_get_seat_usage"("p_org_id" "uuid") IS 'Retorna uso de seats: paid_seats, active_members, can_add, remaining. -1 em paid_seats/remaining = ilimitado.';



CREATE OR REPLACE FUNCTION "public"."org_get_subscription_status"("p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org RECORD;
  v_overdue_since TIMESTAMPTZ;
  v_grace_remaining INTEGER;
BEGIN
  PERFORM public.assert_org_access(p_org_id);
  SELECT
    subscription_status,
    subscription_plan,
    subscription_expires_at,
    billing_override
  INTO v_org
  FROM public.organizations
  WHERE id = p_org_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'status', 'expired',
      'is_valid', false,
      'days_remaining', 0,
      'grace_remaining', 0
    );
  END IF;

  -- Se overdue, calcular dias de graça restantes
  IF v_org.subscription_status = 'overdue' THEN
    SELECT MIN(created_at)
    INTO v_overdue_since
    FROM public.payment_history
    WHERE organization_id = p_org_id
      AND status = 'overdue';

    IF v_overdue_since IS NOT NULL THEN
      v_grace_remaining := GREATEST(7 - EXTRACT(DAY FROM NOW() - v_overdue_since)::INTEGER, 0);
    ELSE
      v_grace_remaining := 7;
    END IF;
  ELSE
    v_grace_remaining := NULL;
  END IF;

  RETURN jsonb_build_object(
    'status',            v_org.subscription_status,
    'plan',              v_org.subscription_plan,
    'expires_at',        v_org.subscription_expires_at,
    'billing_override',  COALESCE(v_org.billing_override, false),
    'is_valid',          v_org.subscription_status IN ('active', 'trial', 'overdue')
                           OR COALESCE(v_org.billing_override, false),
    'days_remaining',    CASE
                           WHEN v_org.subscription_expires_at IS NOT NULL
                             THEN GREATEST(EXTRACT(DAY FROM v_org.subscription_expires_at - NOW())::INTEGER, 0)
                           ELSE NULL
                         END,
    'grace_remaining',   v_grace_remaining,
    'is_overdue',        v_org.subscription_status = 'overdue',
    'is_blocked',        v_org.subscription_status IN ('suspended', 'cancelled', 'expired')
                           AND NOT COALESCE(v_org.billing_override, false)
  );
END;
$$;


