CREATE OR REPLACE FUNCTION "public"."pipe_whatsapp_update_fn"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  UPDATE public.pipeline_entries SET
    stage_key   = NEW.status,
    assigned_to = COALESCE(NEW.responsible_id, NEW.sdr_id),
    metadata    = COALESCE(metadata, '{}'::jsonb)
                  || jsonb_build_object(
                       'responsible_id', NEW.responsible_id,
                       'sdr_id',         NEW.sdr_id,
                       'pre_sale_responsible_id', NEW.pre_sale_responsible_id,
                       'sale_responsible_id', NEW.sale_responsible_id,
                       'scheduled_date', NEW.scheduled_date
                     ),
    notes       = NEW.notes,
    updated_at  = now()
  WHERE id = OLD.id;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."pipe_whatsapp_update_fn"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pipeline_entries_snapshot_responsibles"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_lead leads%ROWTYPE;
  v_slug text;
BEGIN
  IF NEW.lead_id IS NULL THEN RETURN NEW; END IF;

  SELECT p.slug INTO v_slug FROM pipelines p WHERE p.id = NEW.pipeline_id;
  IF v_slug IS DISTINCT FROM 'propostas' THEN RETURN NEW; END IF;

  IF COALESCE(
       NULLIF(NEW.metadata->>'sale_responsible_id', ''),
       NULLIF(NEW.metadata->>'pre_sale_responsible_id', ''),
       NULLIF(NEW.metadata->>'closer_id', ''),
       NULLIF(NEW.metadata->>'responsible_id', '')
     ) IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_lead FROM leads WHERE id = NEW.lead_id;
  IF NOT FOUND THEN RETURN NEW; END IF;

  NEW.metadata := COALESCE(NEW.metadata, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
    'sale_responsible_id',     COALESCE(v_lead.sale_responsible_id, v_lead.closer_id, v_lead.responsible_id),
    'pre_sale_responsible_id', COALESCE(v_lead.pre_sale_responsible_id, v_lead.sdr_id, v_lead.responsible_id),
    'closer_id',               v_lead.closer_id,
    'responsible_id',          v_lead.responsible_id
  ));
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."pipeline_entries_snapshot_responsibles"() OWNER TO "postgres";


