CREATE OR REPLACE FUNCTION "public"."process_overdue_subscriptions"("p_grace_days" integer DEFAULT 7) RETURNS TABLE("organization_id" "uuid", "org_name" "text", "days_overdue" integer, "new_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH overdue_orgs AS (
    SELECT
      o.id,
      o.name,
      COALESCE(
        (SELECT EXTRACT(DAY FROM NOW() - MIN(ph.created_at))::INTEGER
         FROM public.payment_history ph
         WHERE ph.organization_id = o.id
           AND ph.status = 'overdue'
        ),
        0
      ) AS overdue_days
    FROM public.organizations o
    WHERE o.subscription_status = 'overdue'
  )
  UPDATE public.organizations org
  SET
    subscription_status = 'suspended',
    updated_at = NOW()
  FROM overdue_orgs oo
  WHERE org.id = oo.id
    AND oo.overdue_days >= p_grace_days
  RETURNING org.id, oo.name, oo.overdue_days, 'suspended'::TEXT;
END;
$$;


ALTER FUNCTION "public"."process_overdue_subscriptions"("p_grace_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."process_overdue_subscriptions"("p_grace_days" integer) IS 'Transiciona orgs overdue → suspended após grace period (default 7 dias). Retorna lista de orgs transicionadas.';



