CREATE OR REPLACE FUNCTION "public"."recalc_upsell_client_metrics"("p_client_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_org_id        uuid;
  v_org_default   int;
  v_order_count   int;
  v_total         numeric;
  v_avg           numeric;
  v_last          timestamptz;
  v_cycle         int;
  v_days_since    int;
  v_next          timestamptz;
  v_now           timestamptz := now();
BEGIN
  IF p_client_id IS NULL THEN
    RETURN;
  END IF;

  SELECT organization_id INTO v_org_id
  FROM upsell_clients WHERE id = p_client_id
  FOR UPDATE;

  IF v_org_id IS NULL THEN
    RETURN;
  END IF;

  SELECT COALESCE(default_reorder_cycle_days, 30) INTO v_org_default
  FROM organizations WHERE id = v_org_id;
  v_org_default := COALESCE(v_org_default, 30);

  SELECT count(*), COALESCE(sum(sale_value), 0), max(sold_at)
    INTO v_order_count, v_total, v_last
  FROM upsell_orders
  WHERE client_id = p_client_id
    AND approval_status = 'approved';

  v_avg := CASE
             WHEN v_order_count > 0 AND v_total > 0 THEN v_total / v_order_count
             ELSE NULL
           END;

  IF v_order_count < 2 THEN
    v_cycle := v_org_default;
  ELSE
    SELECT GREATEST(1, round(avg(gap_days))::int)
      INTO v_cycle
    FROM (
      SELECT EXTRACT(EPOCH FROM (
               sold_at - lag(sold_at) OVER (ORDER BY sold_at)
             )) / 86400.0 AS gap_days
      FROM upsell_orders
      WHERE client_id = p_client_id
        AND approval_status = 'approved'
    ) g
    WHERE gap_days IS NOT NULL;
    v_cycle := COALESCE(v_cycle, v_org_default);
  END IF;

  v_days_since := CASE
                    WHEN v_last IS NULL THEN 999
                    ELSE GREATEST(0, round(EXTRACT(EPOCH FROM (v_now - v_last)) / 86400.0)::int)
                  END;

  v_next := CASE
              WHEN v_last IS NULL THEN NULL
              ELSE v_last + (v_cycle || ' days')::interval
            END;

  UPDATE upsell_clients SET
    order_count           = v_order_count,
    lifetime_value        = v_total,
    avg_ticket            = v_avg,
    last_order_at         = v_last,
    reorder_cycle_days    = v_cycle,
    days_since_last_order = v_days_since,
    next_order_expected   = v_next,
    updated_at            = v_now
  WHERE id = p_client_id;
END;
$$;


ALTER FUNCTION "public"."recalc_upsell_client_metrics"("p_client_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_ban_signal"("p_instance_id" "uuid", "p_code" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_org_id            uuid;
  v_prev_at           timestamptz;
  v_prev_count        integer;
  v_prev_state        text;
  v_prev_qu           timestamptz;
  v_new_count         integer;
  v_should_quarantine boolean;
  v_new_state         text;
  v_quarantine_until  timestamptz;
BEGIN
  SELECT wi.organization_id INTO v_org_id
  FROM public.whatsapp_instances wi
  WHERE wi.id = p_instance_id;
  IF v_org_id IS NULL THEN
    RETURN;
  END IF;

  SELECT last_ban_signal_at, ban_signal_count_24h, state, quarantine_until
    INTO v_prev_at, v_prev_count, v_prev_state, v_prev_qu
  FROM public.whatsapp_instance_reputation
  WHERE instance_id = p_instance_id;

  IF v_prev_at IS NOT NULL AND v_prev_at > now() - interval '24 hours' THEN
    v_new_count := COALESCE(v_prev_count, 0) + 1;
  ELSE
    v_new_count := 1;
  END IF;

  v_should_quarantine := (p_code = 463) OR (v_new_count >= 3);

  IF v_should_quarantine THEN
    v_new_state := 'quarantined';
    v_quarantine_until := now() + CASE WHEN p_code = 463
                                       THEN interval '24 hours'
                                       ELSE interval '1 hour' END;
  ELSE
    v_new_state := COALESCE(v_prev_state, 'healthy');
    v_quarantine_until := v_prev_qu;
  END IF;

  INSERT INTO public.whatsapp_instance_reputation (
    instance_id, organization_id, state, quarantine_until,
    last_ban_signal_at, ban_signal_count_24h, updated_at
  )
  VALUES (
    p_instance_id, v_org_id, v_new_state, v_quarantine_until,
    now(), v_new_count, now()
  )
  ON CONFLICT (instance_id) DO UPDATE SET
    state                = EXCLUDED.state,
    quarantine_until     = EXCLUDED.quarantine_until,
    last_ban_signal_at   = EXCLUDED.last_ban_signal_at,
    ban_signal_count_24h = EXCLUDED.ban_signal_count_24h,
    organization_id      = EXCLUDED.organization_id,
    updated_at           = now();
END;
$$;


ALTER FUNCTION "public"."record_ban_signal"("p_instance_id" "uuid", "p_code" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_ban_signal"("p_instance_id" "uuid", "p_code" integer) IS 'Record a ban-ish provider signal (463/429) for a number and advance its reputation. Rolling 24h count; 463 OR 3rd-in-24h -> quarantined (24h for 463, 1h otherwise). service_role only, best-effort. Never un-quarantines.';



CREATE OR REPLACE FUNCTION "public"."record_oraculo_usage"("p_user_id" "uuid", "p_org_id" "uuid", "p_question" "text", "p_response" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_used INTEGER; v_limit INTEGER := 3;
BEGIN
  SELECT COUNT(*) INTO v_used FROM oraculo_usage
  WHERE user_id = p_user_id
    AND created_at >= DATE_TRUNC('day', NOW() AT TIME ZONE 'UTC')
    AND created_at < DATE_TRUNC('day', NOW() AT TIME ZONE 'UTC') + INTERVAL '1 day';
  IF v_used >= v_limit THEN
    RETURN jsonb_build_object('error', 'limit_exceeded', 'used', v_used, 'remaining', 0);
  END IF;
  INSERT INTO oraculo_usage (user_id, organization_id, question, response) VALUES (p_user_id, p_org_id, p_question, p_response);
  RETURN jsonb_build_object('used', v_used + 1, 'remaining', v_limit - v_used - 1);
END; $$;


ALTER FUNCTION "public"."record_oraculo_usage"("p_user_id" "uuid", "p_org_id" "uuid", "p_question" "text", "p_response" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_demo_data"("p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_caller_id    uuid  := auth.uid();
  v_is_admin     boolean;
  v_tag_id       uuid;
  v_leads_deleted int  := 0;
BEGIN
  -- ── Guard: caller deve ser admin da org ────────────────────────────────────
  SELECT EXISTS (
    SELECT 1 FROM public.team_members
    WHERE user_id = v_caller_id
      AND organization_id = p_org_id
      AND role = 'admin'
  ) INTO v_is_admin;

  IF NOT v_is_admin THEN
    RAISE EXCEPTION 'insufficient_privilege: apenas admin pode remover dados demo'
      USING ERRCODE = '42501';
  END IF;

  -- ── Buscar tag demo ─────────────────────────────────────────────────────────
  SELECT id INTO v_tag_id
  FROM public.tags
  WHERE organization_id = p_org_id AND name = 'demo';

  IF v_tag_id IS NULL THEN
    RETURN jsonb_build_object('removed', 0, 'reason', 'no_demo_tag');
  END IF;

  -- ── Deletar leads com watermark [DEMO] + tag demo ──────────────────────────
  -- Ordem respeita FK: lead_tags cascade via ON DELETE CASCADE em leads,
  -- mas deletar explicitamente para garantir.

  -- lead_tags primeiro (embora cascade, explícito é mais seguro em seeds)
  DELETE FROM public.lead_tags
  WHERE tag_id = v_tag_id
    AND lead_id IN (
      SELECT id FROM public.leads
      WHERE organization_id = p_org_id
        AND name LIKE '[DEMO]%'
    );

  -- Leads com watermark
  DELETE FROM public.leads
  WHERE organization_id = p_org_id
    AND name LIKE '[DEMO]%';

  GET DIAGNOSTICS v_leads_deleted = ROW_COUNT;

  -- ── Deletar pipeline demo ───────────────────────────────────────────────────
  DELETE FROM public.custom_pipelines
  WHERE organization_id = p_org_id
    AND slug = 'demo-pipeline';

  RETURN jsonb_build_object(
    'removed',      v_leads_deleted,
    'pipeline',     'demo-pipeline'
  );
END;
$$;


ALTER FUNCTION "public"."remove_demo_data"("p_org_id" "uuid") OWNER TO "postgres";


