CREATE OR REPLACE FUNCTION "public"."resolve_wait_response"("p_lead_id" "uuid", "p_organization_id" "uuid", "p_channel" "text" DEFAULT 'any'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_count INT := 0;
  v_exec RECORD;
BEGIN
  FOR v_exec IN
    SELECT id, current_node_id, context
    FROM public.workflow_executions
    WHERE lead_id = p_lead_id
      AND organization_id = p_organization_id
      AND status = 'waiting_response'
    FOR UPDATE SKIP LOCKED
  LOOP
    -- Check channel match: if node configured specific channel, only match that
    -- The channel config is stored in the workflow definition, not in executions.
    -- For simplicity, resolve all waiting executions for this lead.
    -- The executor will verify channel match if needed.
    UPDATE public.workflow_executions
    SET
      status = 'running',
      next_run_at = NOW(),
      updated_at = NOW(),
      context = COALESCE(v_exec.context, '{}'::jsonb)
        || jsonb_build_object(
          '_wait_resolved', 'replied',
          '_replied_at', NOW()::text,
          '_reply_channel', p_channel
        )
    WHERE id = v_exec.id;

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."resolve_wait_response"("p_lead_id" "uuid", "p_organization_id" "uuid", "p_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_wait_response_by_phone"("p_phone" "text", "p_organization_id" "uuid", "p_channel" "text" DEFAULT 'whatsapp'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total INT := 0;
  v_lead RECORD;
  v_norm TEXT;
  v_normalized_br TEXT;
BEGIN
  IF p_phone IS NULL OR length(p_phone) < 8 OR p_organization_id IS NULL THEN
    RETURN 0;
  END IF;

  -- Normalize incoming phone: digits only. WhatsApp JIDs come as
  -- "5511999...@s.whatsapp.net"; webhook may also pass formatted strings.
  v_norm := regexp_replace(p_phone, '[^0-9]', '', 'g');
  IF length(v_norm) < 8 THEN
    RETURN 0;
  END IF;

  -- 1) Exact match on phone_digits (uses idx_leads_org_phone_digits).
  -- Resolve all matches: noisy data can carry the same phone on multiple leads.
  FOR v_lead IN
    SELECT id
    FROM public.leads
    WHERE organization_id = p_organization_id
      AND phone_digits = v_norm
      AND phone_digits != ''
  LOOP
    v_total := v_total + COALESCE(
      public.resolve_wait_response(v_lead.id, p_organization_id, p_channel),
      0
    );
  END LOOP;

  -- 2) BR mobile normalization match (handles 9th-digit prefix variance).
  -- Skip if length too short to be a BR mobile.
  IF v_total = 0 AND length(v_norm) >= 10 THEN
    v_normalized_br := normalize_br_mobile(v_norm);

    FOR v_lead IN
      SELECT id
      FROM public.leads
      WHERE organization_id = p_organization_id
        AND phone_digits != ''
        AND length(phone_digits) >= 10
        AND normalize_br_mobile(phone_digits) = v_normalized_br
    LOOP
      v_total := v_total + COALESCE(
        public.resolve_wait_response(v_lead.id, p_organization_id, p_channel),
        0
      );
    END LOOP;
  END IF;

  -- 3) Suffix match on last 11 digits (fallback for legacy / DDI variants).
  -- Guard: requires >= 11 digits on both sides to avoid false positives
  -- on short numbers that share a tail.
  IF v_total = 0 AND length(v_norm) >= 11 THEN
    FOR v_lead IN
      SELECT id
      FROM public.leads
      WHERE organization_id = p_organization_id
        AND phone_digits != ''
        AND length(phone_digits) >= 11
        AND right(phone_digits, 11) = right(v_norm, 11)
    LOOP
      v_total := v_total + COALESCE(
        public.resolve_wait_response(v_lead.id, p_organization_id, p_channel),
        0
      );
    END LOOP;
  END IF;

  RETURN v_total;
END;
$$;


ALTER FUNCTION "public"."resolve_wait_response_by_phone"("p_phone" "text", "p_organization_id" "uuid", "p_channel" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_wait_response_by_phone"("p_phone" "text", "p_organization_id" "uuid", "p_channel" "text") IS 'Phone-keyed variant of resolve_wait_response. Called by WhatsApp/SZ-Chat webhooks on incoming message to advance workflow executions waiting on a reply. Uses 3-tier match cascade (exact phone_digits â†’ normalize_br_mobile â†’ right-11 suffix) to handle BR mobile 9-prefix variance.';



CREATE OR REPLACE FUNCTION "public"."restore_lead"("p_lead_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_org_id uuid;
BEGIN
  IF public.is_master_user() THEN
    v_org_id := NULL;
  ELSE
    SELECT organization_id INTO v_org_id
    FROM public.team_members
    WHERE user_id = auth.uid() AND is_active = true
    LIMIT 1;

    IF v_org_id IS NULL THEN
      RAISE EXCEPTION 'No active organization membership';
    END IF;
  END IF;

  UPDATE public.leads
  SET deleted_at = NULL, deleted_by = NULL
  WHERE id = p_lead_id
    AND (v_org_id IS NULL OR organization_id = v_org_id)
    AND deleted_at IS NOT NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lead not found in trash';
  END IF;
END;
$$;


ALTER FUNCTION "public"."restore_lead"("p_lead_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_leads_bulk"("p_lead_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_org_id uuid;
  v_count integer;
BEGIN
  IF public.is_master_user() THEN
    v_org_id := NULL;
  ELSE
    SELECT organization_id INTO v_org_id
    FROM public.team_members
    WHERE user_id = auth.uid() AND is_active = true
    LIMIT 1;

    IF v_org_id IS NULL THEN
      RAISE EXCEPTION 'No active organization membership';
    END IF;
  END IF;

  UPDATE public.leads
  SET deleted_at = NULL, deleted_by = NULL
  WHERE id = ANY(p_lead_ids)
    AND (v_org_id IS NULL OR organization_id = v_org_id)
    AND deleted_at IS NOT NULL;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."restore_leads_bulk"("p_lead_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rollback_import_batch"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_batch import_batches;
  v_deleted_count int;
BEGIN
  SELECT * INTO v_batch FROM import_batches WHERE id = p_batch_id;

  IF v_batch IS NULL THEN
    RETURN jsonb_build_object('error', 'Batch not found');
  END IF;

  IF v_batch.rolled_back THEN
    RETURN jsonb_build_object('error', 'Batch already rolled back');
  END IF;

  -- Verify caller belongs to same org
  IF NOT EXISTS (
    SELECT 1 FROM team_members
    WHERE user_id = auth.uid() AND organization_id = v_batch.organization_id
  ) THEN
    RETURN jsonb_build_object('error', 'Unauthorized');
  END IF;

  -- Soft-delete leads (set deleted_at if column exists, otherwise hard delete pipe entries and mark batch)
  UPDATE leads
  SET deleted_at = now()
  WHERE import_batch_id = p_batch_id
    AND deleted_at IS NULL;

  GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

  -- Mark batch as rolled back
  UPDATE import_batches
  SET rolled_back = true,
      rolled_back_at = now(),
      rolled_back_by = auth.uid()
  WHERE id = p_batch_id;

  RETURN jsonb_build_object(
    'success', true,
    'deleted_count', v_deleted_count
  );
END;
$$;


ALTER FUNCTION "public"."rollback_import_batch"("p_batch_id" "uuid") OWNER TO "postgres";


