CREATE OR REPLACE FUNCTION "public"."schedule_pipe_rule_steps_from_position"("p_organization_id" "uuid", "p_pipe_type" "text", "p_rule_id" "uuid", "p_pipe_record_id" "uuid", "p_lead_id" "uuid", "p_whatsapp_instance_id" "uuid", "p_from_position" integer DEFAULT 0) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  step_rec RECORD;
  cumul_minutes INTEGER := 0;
  sched_at TIMESTAMPTZ;
  v_scheduled_any BOOLEAN := false;
BEGIN
  FOR step_rec IN
    SELECT id, action_type, template_id, delay_minutes, position,
           wait_timeout_minutes, timeout_action, timeout_target_stage_id, timeout_template_id,
           target_stage_id, sdr_assignment_mode, target_sdr_id
    FROM public.pipe_dispatch_rule_steps
    WHERE rule_id = p_rule_id
      AND position >= p_from_position
    ORDER BY position
  LOOP
    cumul_minutes := cumul_minutes + step_rec.delay_minutes;
    sched_at := now() + (cumul_minutes || ' minutes')::interval;

    IF step_rec.action_type = 'send_template' THEN
      INSERT INTO public.scheduled_pipe_messages (
        organization_id, pipe_type, rule_id, pipe_record_id, lead_id, template_id,
        whatsapp_instance_id, scheduled_at, status, action_type, step_position
      ) VALUES (
        p_organization_id, p_pipe_type, p_rule_id, p_pipe_record_id, p_lead_id, step_rec.template_id,
        p_whatsapp_instance_id, sched_at, 'scheduled', 'send_template', step_rec.position
      );
      v_scheduled_any := true;

    ELSIF step_rec.action_type = 'wait_response' THEN
      INSERT INTO public.scheduled_pipe_messages (
        organization_id, pipe_type, rule_id, pipe_record_id, lead_id,
        whatsapp_instance_id, scheduled_at, status, action_type, step_position,
        waiting_since, wait_timeout_at,
        timeout_action, timeout_target_stage_id, timeout_template_id
      ) VALUES (
        p_organization_id, p_pipe_type, p_rule_id, p_pipe_record_id, p_lead_id,
        p_whatsapp_instance_id, sched_at, 'scheduled', 'wait_response', step_rec.position,
        NULL, NULL,
        step_rec.timeout_action, step_rec.timeout_target_stage_id, step_rec.timeout_template_id
      );
      v_scheduled_any := true;
      EXIT; -- barrier

    ELSIF step_rec.action_type = 'change_stage' THEN
      INSERT INTO public.scheduled_pipe_messages (
        organization_id, pipe_type, rule_id, pipe_record_id, lead_id,
        whatsapp_instance_id, scheduled_at, status, action_type, step_position,
        target_stage_id
      ) VALUES (
        p_organization_id, p_pipe_type, p_rule_id, p_pipe_record_id, p_lead_id,
        p_whatsapp_instance_id, sched_at, 'scheduled', 'change_stage', step_rec.position,
        step_rec.target_stage_id
      );
      v_scheduled_any := true;

    ELSIF step_rec.action_type = 'assign_sdr' THEN
      INSERT INTO public.scheduled_pipe_messages (
        organization_id, pipe_type, rule_id, pipe_record_id, lead_id,
        whatsapp_instance_id, scheduled_at, status, action_type, step_position,
        sdr_assignment_mode, target_sdr_id
      ) VALUES (
        p_organization_id, p_pipe_type, p_rule_id, p_pipe_record_id, p_lead_id,
        p_whatsapp_instance_id, sched_at, 'scheduled', 'assign_sdr', step_rec.position,
        step_rec.sdr_assignment_mode, step_rec.target_sdr_id
      );
      v_scheduled_any := true;

    ELSIF step_rec.action_type = 'cancel_sequence' THEN
      INSERT INTO public.scheduled_pipe_messages (
        organization_id, pipe_type, rule_id, pipe_record_id, lead_id,
        whatsapp_instance_id, scheduled_at, status, action_type, step_position
      ) VALUES (
        p_organization_id, p_pipe_type, p_rule_id, p_pipe_record_id, p_lead_id,
        p_whatsapp_instance_id, sched_at, 'scheduled', 'cancel_sequence', step_rec.position
      );
      v_scheduled_any := true;

    END IF;
  END LOOP;

  RETURN v_scheduled_any;
END;
$$;


ALTER FUNCTION "public"."schedule_pipe_rule_steps_from_position"("p_organization_id" "uuid", "p_pipe_type" "text", "p_rule_id" "uuid", "p_pipe_record_id" "uuid", "p_lead_id" "uuid", "p_whatsapp_instance_id" "uuid", "p_from_position" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."schedule_rule_steps_from_position"("p_campanha_id" "uuid", "p_rule_id" "uuid", "p_campanha_lead_id" "uuid", "p_lead_id" "uuid", "p_whatsapp_instance_id" "uuid", "p_from_position" integer DEFAULT 0) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  step_rec RECORD;
  cumul_minutes INTEGER := 0;
  sched_at TIMESTAMPTZ;
  v_scheduled_any BOOLEAN := false;
BEGIN
  FOR step_rec IN
    SELECT id, action_type, template_id, delay_minutes, position,
           wait_timeout_minutes, timeout_action, timeout_target_stage_id, timeout_template_id,
           target_stage_id, sdr_assignment_mode, target_sdr_id
    FROM public.campanha_dispatch_rule_steps
    WHERE rule_id = p_rule_id
      AND position >= p_from_position
    ORDER BY position
  LOOP
    cumul_minutes := cumul_minutes + step_rec.delay_minutes;
    sched_at := now() + (cumul_minutes || ' minutes')::interval;

    IF step_rec.action_type = 'send_template' THEN
      INSERT INTO public.scheduled_campaign_messages (
        campanha_id, rule_id, campanha_lead_id, lead_id, template_id,
        whatsapp_instance_id, scheduled_at, status, action_type, step_position
      ) VALUES (
        p_campanha_id, p_rule_id, p_campanha_lead_id, p_lead_id, step_rec.template_id,
        p_whatsapp_instance_id, sched_at, 'scheduled', 'send_template', step_rec.position
      );
      v_scheduled_any := true;

    ELSIF step_rec.action_type = 'wait_response' THEN
      INSERT INTO public.scheduled_campaign_messages (
        campanha_id, rule_id, campanha_lead_id, lead_id,
        whatsapp_instance_id, scheduled_at, status, action_type, step_position,
        waiting_since, wait_timeout_at,
        timeout_action, timeout_target_stage_id, timeout_template_id
      ) VALUES (
        p_campanha_id, p_rule_id, p_campanha_lead_id, p_lead_id,
        p_whatsapp_instance_id, sched_at, 'scheduled', 'wait_response', step_rec.position,
        NULL, NULL,  -- preenchidos quando o worker processar
        step_rec.timeout_action, step_rec.timeout_target_stage_id, step_rec.timeout_template_id
      );
      v_scheduled_any := true;
      -- BARREIRA: parar de agendar steps após wait_response
      EXIT;

    ELSIF step_rec.action_type = 'change_stage' THEN
      INSERT INTO public.scheduled_campaign_messages (
        campanha_id, rule_id, campanha_lead_id, lead_id,
        whatsapp_instance_id, scheduled_at, status, action_type, step_position,
        target_stage_id
      ) VALUES (
        p_campanha_id, p_rule_id, p_campanha_lead_id, p_lead_id,
        p_whatsapp_instance_id, sched_at, 'scheduled', 'change_stage', step_rec.position,
        step_rec.target_stage_id
      );
      v_scheduled_any := true;

    ELSIF step_rec.action_type = 'assign_sdr' THEN
      INSERT INTO public.scheduled_campaign_messages (
        campanha_id, rule_id, campanha_lead_id, lead_id,
        whatsapp_instance_id, scheduled_at, status, action_type, step_position,
        sdr_assignment_mode, target_sdr_id
      ) VALUES (
        p_campanha_id, p_rule_id, p_campanha_lead_id, p_lead_id,
        p_whatsapp_instance_id, sched_at, 'scheduled', 'assign_sdr', step_rec.position,
        step_rec.sdr_assignment_mode, step_rec.target_sdr_id
      );
      v_scheduled_any := true;

    ELSIF step_rec.action_type = 'cancel_sequence' THEN
      INSERT INTO public.scheduled_campaign_messages (
        campanha_id, rule_id, campanha_lead_id, lead_id,
        whatsapp_instance_id, scheduled_at, status, action_type, step_position
      ) VALUES (
        p_campanha_id, p_rule_id, p_campanha_lead_id, p_lead_id,
        p_whatsapp_instance_id, sched_at, 'scheduled', 'cancel_sequence', step_rec.position
      );
      v_scheduled_any := true;

    END IF;
  END LOOP;

  RETURN v_scheduled_any;
END;
$$;


ALTER FUNCTION "public"."schedule_rule_steps_from_position"("p_campanha_id" "uuid", "p_rule_id" "uuid", "p_campanha_lead_id" "uuid", "p_lead_id" "uuid", "p_whatsapp_instance_id" "uuid", "p_from_position" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."schedule_rule_steps_from_position"("p_campanha_id" "uuid", "p_rule_id" "uuid", "p_campanha_lead_id" "uuid", "p_lead_id" "uuid", "p_whatsapp_instance_id" "uuid", "p_from_position" integer) IS 'Agenda steps de uma regra a partir de uma posição. Para ao encontrar wait_response (barreira). Usada por triggers de campanha_leads e resposta do lead.';



CREATE OR REPLACE FUNCTION "public"."search_messages"("p_org_id" "uuid", "p_query" "text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "phone_number" "text", "content" "text", "direction" "text", "timestamp" timestamp with time zone, "instance_id" "uuid", "lead_id" "uuid", "headline" "text", "rank" real)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tsquery tsquery;
BEGIN
  -- ── Guard 1: autenticação ──────────────────────────────────────────────────
  -- auth.uid() retorna NULL quando não autenticado (service_role ou anon).
  -- Se chamado por service_role sem JWT, uid() = NULL — rejeitado aqui.
  -- Crons internos devem chamar via RPC com JWT válido ou não usar esta função.
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'access_denied: authentication required'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- ── Guard 2: pertencimento à org ───────────────────────────────────────────
  -- Verifica que o usuário é membro ativo da org requisitada.
  -- is_active = true: previne acesso por membros desativados.
  -- Isso impede que um membro de org A passe p_org_id de org B e veja mensagens.
  IF NOT EXISTS (
    SELECT 1
    FROM public.team_members tm
    WHERE tm.user_id        = auth.uid()
      AND tm.organization_id = p_org_id
      AND tm.is_active       = true
  ) THEN
    RAISE EXCEPTION 'access_denied: user is not an active member of organization %', p_org_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- ── Guard 3: query mínima ──────────────────────────────────────────────────
  -- Rejeitar queries vazias ou muito curtas que gerariam scan massivo.
  IF length(trim(coalesce(p_query, ''))) < 3 THEN
    RAISE EXCEPTION 'query_too_short: minimum 3 characters required'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  -- ── Guard 4: limit razoável ────────────────────────────────────────────────
  -- Proteger contra limit=999999 acidental ou malicioso.
  IF p_limit > 100 THEN
    RAISE EXCEPTION 'limit_too_large: maximum is 100'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  -- ── Parsear query uma vez ──────────────────────────────────────────────────
  -- websearch_to_tsquery aceita sintaxe humana:
  --   "proposta OR contrato" → proposta | contrato
  --   "proposta contrato"    → proposta & contrato (AND implícito)
  --   '"proposta final"'     → frase exata
  -- Retorna NULL para query inválida (ex: query toda de stop words).
  -- Se NULL, não retornar resultados (não falhar).
  v_tsquery := websearch_to_tsquery('portuguese', p_query);

  IF v_tsquery IS NULL THEN
    RETURN;
  END IF;

  -- ── Query principal ────────────────────────────────────────────────────────
  RETURN QUERY
  SELECT
    m.id,
    m.phone_number,
    m.content,
    m.direction,
    m."timestamp",
    m.instance_id,
    m.lead_id,
    -- headline: fragmento com o termo destacado em <mark>...</mark>
    -- MaxWords/MinWords controlam o tamanho do snippet
    -- HighlightAll=false: não destacar cada ocorrência no texto completo
    ts_headline(
      'portuguese',
      coalesce(m.content, ''),
      v_tsquery,
      'StartSel=<mark>,StopSel=</mark>,MaxWords=20,MinWords=5,HighlightAll=false'
    ) AS headline,
    ts_rank(m.search_tsv, v_tsquery) AS rank
  FROM public.whatsapp_messages m
  WHERE m.organization_id = p_org_id
    AND m.search_tsv @@ v_tsquery
  ORDER BY
    ts_rank(m.search_tsv, v_tsquery) DESC,
    m."timestamp" DESC
  LIMIT  p_limit
  OFFSET p_offset;
END;
$$;


ALTER FUNCTION "public"."search_messages"("p_org_id" "uuid", "p_query" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_messages"("p_org_id" "uuid", "p_query" "text", "p_limit" integer, "p_offset" integer) IS 'Full-text search de mensagens WhatsApp por organização. SECURITY DEFINER — aplica guards próprios: (1) auth.uid() não nulo, (2) usuário é membro ativo da org, (3) query >= 3 chars, (4) limit <= 100. Retorna id, phone_number, content, direction, timestamp, instance_id, lead_id, headline (HTML com <mark>), rank. headline é seguro para dangerouslySetInnerHTML: ts_headline escapa conteúdo original, injeta apenas <mark>. Chamado por useMessageSearch (debounce 300ms) e CommandGroupMessages (⌘K).';



CREATE OR REPLACE FUNCTION "public"."seed_conversation_read_state"("p_entries" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_uid   uuid := auth.uid();
  v_count integer := 0;
BEGIN
  IF v_uid IS NULL OR p_entries IS NULL OR jsonb_typeof(p_entries) <> 'array' THEN
    RETURN 0;
  END IF;

  INSERT INTO conversation_read_state (organization_id, user_id, conversation_key, last_read_at, updated_at)
  SELECT s.organization_id,
         v_uid,
         'whatsapp:' || s.instance_id::text || ':' || s.normalized_phone,
         to_timestamp(((e->>'t')::numeric) / 1000.0),
         now()
  FROM jsonb_array_elements(p_entries) e
  JOIN whatsapp_conversation_summary s
    ON s.normalized_phone = (e->>'phone')
   AND s.organization_id IN (SELECT get_my_organization_ids())
  WHERE (e->>'t') ~ '^[0-9]+$'
  ON CONFLICT (organization_id, user_id, conversation_key)
  DO UPDATE SET
    last_read_at = greatest(conversation_read_state.last_read_at, EXCLUDED.last_read_at),
    updated_at   = now();

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END $_$;


ALTER FUNCTION "public"."seed_conversation_read_state"("p_entries" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_demo_data"("p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_caller_id    uuid  := auth.uid();
  v_is_admin     boolean;
  v_tag_id       uuid;
  v_pipeline_id  uuid;
  v_leads_created int  := 0;
  v_lead_id      uuid;
  i              int;
  v_already_seeded boolean;
BEGIN
  -- ── Guard: caller deve ser admin da org ────────────────────────────────────
  SELECT EXISTS (
    SELECT 1 FROM public.team_members
    WHERE user_id = v_caller_id
      AND organization_id = p_org_id
      AND role = 'admin'
  ) INTO v_is_admin;

  IF NOT v_is_admin THEN
    RAISE EXCEPTION 'insufficient_privilege: apenas admin pode popular dados demo'
      USING ERRCODE = '42501';
  END IF;

  -- ── Guard: idempotente — já foi semeado? ───────────────────────────────────
  SELECT EXISTS (
    SELECT 1 FROM public.leads l
    JOIN public.lead_tags lt ON lt.lead_id = l.id
    JOIN public.tags t ON t.id = lt.tag_id
    WHERE l.organization_id = p_org_id
      AND t.name = 'demo'
      AND t.organization_id = p_org_id
    LIMIT 1
  ) INTO v_already_seeded;

  IF v_already_seeded THEN
    RETURN jsonb_build_object(
      'already_seeded', true,
      'leads', 0
    );
  END IF;

  -- ── 1. Tag demo ─────────────────────────────────────────────────────────────
  INSERT INTO public.tags (organization_id, name, color)
  VALUES (p_org_id, 'demo', '#facc15')
  ON CONFLICT (name, organization_id) DO NOTHING
  RETURNING id INTO v_tag_id;

  IF v_tag_id IS NULL THEN
    SELECT id INTO v_tag_id
    FROM public.tags
    WHERE organization_id = p_org_id AND name = 'demo';
  END IF;

  -- ── 2. Pipeline demo ────────────────────────────────────────────────────────
  INSERT INTO public.custom_pipelines (
    organization_id,
    name,
    slug,
    description,
    color
  )
  VALUES (
    p_org_id,
    'Demo Pipeline',
    'demo-pipeline',
    'Pipeline criado automaticamente com dados de demonstração',
    '#facc15'
  )
  ON CONFLICT (organization_id, slug) DO NOTHING
  RETURNING id INTO v_pipeline_id;

  IF v_pipeline_id IS NULL THEN
    SELECT id INTO v_pipeline_id
    FROM public.custom_pipelines
    WHERE organization_id = p_org_id AND slug = 'demo-pipeline';
  END IF;

  -- ── 3. 10 leads fake ────────────────────────────────────────────────────────
  FOR i IN 1..10 LOOP
    INSERT INTO public.leads (
      organization_id,
      name,
      company,
      phone,
      email,
      origin,
      rating
    ) VALUES (
      p_org_id,
      '[DEMO] Lead ' || i || ' — ' || (ARRAY[
        'João Silva', 'Maria Oliveira', 'Carlos Santos', 'Ana Costa',
        'Pedro Lima', 'Fernanda Rocha', 'Ricardo Mendes', 'Juliana Alves',
        'Marcos Pereira', 'Patrícia Souza'
      ])[i],
      (ARRAY[
        'Distribuidora Alpha', 'Metalúrgica Beta', 'Logística Gamma',
        'Comércio Delta', 'Fábrica Epsilon', 'Transportes Zeta',
        'Indústria Eta', 'Atacado Theta', 'Importadora Iota', 'Serviços Kappa'
      ])[i],
      '+55 11 99999-90' || LPAD(i::text, 2, '0'),
      'demo' || i || '@torquecrm-demo.com',
      'outro',
      CASE WHEN i <= 3 THEN 5 WHEN i <= 6 THEN 3 ELSE 1 END
    )
    RETURNING id INTO v_lead_id;

    -- Associar tag demo ao lead
    INSERT INTO public.lead_tags (lead_id, tag_id)
    VALUES (v_lead_id, v_tag_id)
    ON CONFLICT DO NOTHING;

    v_leads_created := v_leads_created + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'already_seeded', false,
    'leads',       v_leads_created,
    'tag_id',      v_tag_id,
    'pipeline_id', v_pipeline_id
  );
END;
$$;


