CREATE OR REPLACE FUNCTION "public"."set_instance_owner"("p_instance_id" "uuid", "p_new_owner_team_member_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_prev uuid;
  v_caller uuid := auth.uid();
  v_caller_role text;
  v_audit_id uuid;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;

  SELECT wi.organization_id, wi.owner_team_member_id
    INTO v_org_id, v_prev
  FROM public.whatsapp_instances wi
  WHERE wi.id = p_instance_id;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'INSTANCE_NOT_FOUND';
  END IF;

  -- Autorização: master OU admin da org
  IF NOT public.is_master_user(v_caller) THEN
    SELECT tm.role INTO v_caller_role
    FROM public.team_members tm
    WHERE tm.user_id = v_caller
      AND tm.organization_id = v_org_id
      AND tm.is_active = true
    LIMIT 1;

    IF v_caller_role IS NULL OR v_caller_role <> 'admin' THEN
      RAISE EXCEPTION 'FORBIDDEN: only admin/master can change instance owner';
    END IF;
  END IF;

  -- Valida novo owner pertence à mesma org e está ativo (quando não-NULL)
  IF p_new_owner_team_member_id IS NOT NULL THEN
    PERFORM 1
    FROM public.team_members tm
    WHERE tm.id = p_new_owner_team_member_id
      AND tm.organization_id = v_org_id
      AND tm.is_active = true;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'INVALID_OWNER: team_member not in org or inactive';
    END IF;
  END IF;

  UPDATE public.whatsapp_instances
  SET owner_team_member_id = p_new_owner_team_member_id,
      updated_at = NOW()
  WHERE id = p_instance_id;

  INSERT INTO public.whatsapp_instance_owner_history (
    instance_id,
    organization_id,
    previous_owner_id,
    new_owner_id,
    changed_by,
    reason
  )
  VALUES (
    p_instance_id,
    v_org_id,
    v_prev,
    p_new_owner_team_member_id,
    v_caller,
    p_reason
  )
  RETURNING id INTO v_audit_id;

  RETURN v_audit_id;
END;
$$;


ALTER FUNCTION "public"."set_instance_owner"("p_instance_id" "uuid", "p_new_owner_team_member_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_instance_owner"("p_instance_id" "uuid", "p_new_owner_team_member_id" "uuid", "p_reason" "text") IS 'Troca owner_team_member_id da instância + grava auditoria. Apenas admin da org ou master.';



CREATE OR REPLACE FUNCTION "public"."set_instance_reputation"("p_instance_id" "uuid", "p_state" "text", "p_quarantine_until" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_org_id uuid;
BEGIN
  IF p_state NOT IN ('healthy', 'warming', 'quarantined') THEN
    RAISE EXCEPTION 'invalid reputation state: %', p_state;
  END IF;

  SELECT wi.organization_id INTO v_org_id
  FROM public.whatsapp_instances wi
  WHERE wi.id = p_instance_id;
  IF v_org_id IS NULL THEN
    RETURN;
  END IF;

  INSERT INTO public.whatsapp_instance_reputation (
    instance_id, organization_id, state, quarantine_until, warmup_started_at, updated_at
  )
  VALUES (
    p_instance_id, v_org_id, p_state, p_quarantine_until,
    CASE WHEN p_state = 'warming' THEN now() ELSE NULL END, now()
  )
  ON CONFLICT (instance_id) DO UPDATE SET
    state             = EXCLUDED.state,
    quarantine_until  = EXCLUDED.quarantine_until,
    warmup_started_at = CASE
                          WHEN EXCLUDED.state = 'warming'
                               AND public.whatsapp_instance_reputation.warmup_started_at IS NULL
                            THEN now()
                          ELSE public.whatsapp_instance_reputation.warmup_started_at
                        END,
    updated_at        = now();
END;
$$;


ALTER FUNCTION "public"."set_instance_reputation"("p_instance_id" "uuid", "p_state" "text", "p_quarantine_until" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_instance_reputation"("p_instance_id" "uuid", "p_state" "text", "p_quarantine_until" timestamp with time zone) IS 'Upsert a number reputation state (healthy/warming/quarantined) + quarantine_until. Used by recovery jobs / warm-up start. service_role only.';



