CREATE OR REPLACE FUNCTION "public"."support_attachment_is_coherent"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  comment_ticket   UUID;
  comment_internal BOOLEAN;
  path_internal    BOOLEAN;
BEGIN
  IF NEW.comment_id IS NOT NULL THEN
    SELECT ticket_id, is_internal INTO comment_ticket, comment_internal
      FROM public.support_ticket_comments WHERE id = NEW.comment_id;
    IF comment_ticket IS DISTINCT FROM NEW.ticket_id THEN
      RAISE EXCEPTION 'o comentario do anexo pertence a outro chamado' USING ERRCODE = 'check_violation';
    END IF;
    IF comment_internal IS DISTINCT FROM NEW.is_internal THEN
      RAISE EXCEPTION 'a visibilidade do anexo nao bate com a do comentario' USING ERRCODE = 'check_violation';
    END IF;
  ELSIF NEW.is_internal THEN
    RAISE EXCEPTION 'anexo interno exige um comentario interno' USING ERRCODE = 'check_violation';
  END IF;

  path_internal := split_part(NEW.path, '/', 2) = 'internal';
  IF path_internal IS DISTINCT FROM NEW.is_internal THEN
    RAISE EXCEPTION 'o caminho do anexo nao corresponde a sua visibilidade' USING ERRCODE = 'check_violation';
  END IF;

  IF split_part(NEW.path, '/', 1) <> NEW.ticket_id::text THEN
    RAISE EXCEPTION 'o caminho do anexo nao comeca pelo chamado' USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END; $$;


ALTER FUNCTION "public"."support_attachment_is_coherent"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."support_attachment_within_limits"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  no_chamado    INTEGER;
  no_comentario INTEGER;
BEGIN
  SELECT count(*) INTO no_chamado
    FROM public.support_ticket_attachments WHERE ticket_id = NEW.ticket_id;
  IF no_chamado >= 20 THEN
    RAISE EXCEPTION 'este chamado ja tem 20 anexos' USING ERRCODE = 'check_violation';
  END IF;

  SELECT count(*) INTO no_comentario
    FROM public.support_ticket_attachments
   WHERE ticket_id = NEW.ticket_id
     AND comment_id IS NOT DISTINCT FROM NEW.comment_id;
  IF no_comentario >= 5 THEN
    RAISE EXCEPTION 'sao no maximo 5 anexos por mensagem' USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END; $$;


ALTER FUNCTION "public"."support_attachment_within_limits"() OWNER TO "postgres";


