CREATE OR REPLACE FUNCTION "public"."sweep_copilot_queue"("p_lease_seconds" integer DEFAULT 120) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_worker_url text;
  v_secret_val text;
  v_batch text;
  v_count int := 0;
BEGIN
  SELECT value INTO v_worker_url FROM cron_config WHERE key = 'copilot_batch_processor_url';
  SELECT value INTO v_secret_val FROM cron_config WHERE key = 'cron_secret';
  IF v_worker_url IS NULL OR v_worker_url = '' THEN RETURN 0; END IF;

  FOR v_batch IN
    SELECT DISTINCT batch_key
    FROM copilot_message_queue
    WHERE batch_key IS NOT NULL
      AND (
        (status = 'pending' AND next_attempt_at IS NOT NULL AND next_attempt_at <= now())
        OR
        (status = 'processing' AND claimed_at IS NOT NULL
          AND claimed_at < now() - make_interval(secs => p_lease_seconds))
        OR
        (status = 'pending' AND next_attempt_at IS NULL
          AND queued_at < now() - interval '30 seconds')
      )
  LOOP
    PERFORM net.http_post(
      url := v_worker_url,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'x-cron-secret', COALESCE(v_secret_val, '')
      ),
      body := jsonb_build_object('batch_key', v_batch, 'force_drain', true)
    );
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."sweep_copilot_queue"("p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_ai_state_from_preferences"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_target_state public.ai_takeover_state_enum;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF OLD.ai_disabled IS NOT DISTINCT FROM NEW.ai_disabled THEN
      RETURN NEW;
    END IF;
  END IF;

  v_target_state := CASE
    WHEN NEW.ai_disabled THEN 'AI_PAUSED_MANUAL'::public.ai_takeover_state_enum
    ELSE 'AI_ACTIVE'::public.ai_takeover_state_enum
  END;

  -- Bypass enforce_ai_state_transition via custom GUC (não requer superuser).
  PERFORM set_config('app.bypass_ai_state_enforce', 'true', true);

  UPDATE public.conversations c
  SET ai_state = v_target_state,
      ai_state_updated_at = now(),
      ai_state_updated_by = NEW.set_by
  FROM public.leads l
  WHERE c.lead_id = l.id
    AND l.organization_id = NEW.organization_id
    AND l.normalized_phone = NEW.normalized_phone
    AND CASE
      WHEN NEW.ai_disabled THEN c.ai_state IN ('AI_ACTIVE', 'HANDOFF_BACK', 'WAITING_HUMAN')
      ELSE c.ai_state IN ('AI_PAUSED_MANUAL')
    END;

  -- Limpa GUC pra não vazar pro resto da transação
  PERFORM set_config('app.bypass_ai_state_enforce', 'false', true);

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_ai_state_from_preferences"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_ai_state_from_preferences"() IS 'F4 + hotfix 2026-04-26: bypass enforce_ai_state_transition via custom GUC app.bypass_ai_state_enforce (não requer superuser, ao contrário de session_replication_role que falhava em produção).';



CREATE OR REPLACE FUNCTION "public"."sync_closer_to_lead_from_pipe"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Only sync if the pipe record has a closer_id
  IF NEW.closer_id IS NOT NULL THEN
    UPDATE public.leads
    SET closer_id = NEW.closer_id,
        updated_at = NOW()
    WHERE id = NEW.lead_id
      AND (closer_id IS NULL OR closer_id <> NEW.closer_id);
  END IF;
  RETURN NEW;
END;
$$;


