CREATE OR REPLACE FUNCTION "public"."sync_dual_responsible_to_lead_from_pipe"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Only act when at least one dual field actually changed
  IF (NEW.pre_sale_responsible_id IS DISTINCT FROM OLD.pre_sale_responsible_id)
  OR (NEW.sale_responsible_id     IS DISTINCT FROM OLD.sale_responsible_id)
  THEN
    UPDATE public.leads
    SET
      -- COALESCE: do not overwrite an existing value with NULL from the pipe
      pre_sale_responsible_id = COALESCE(
        NEW.pre_sale_responsible_id,
        pre_sale_responsible_id
      ),
      sale_responsible_id = COALESCE(
        NEW.sale_responsible_id,
        sale_responsible_id
      ),
      updated_at = NOW()
    WHERE id = NEW.lead_id
      AND (
        -- Only write when the lead's field is actually changing
        pre_sale_responsible_id IS DISTINCT FROM COALESCE(NEW.pre_sale_responsible_id, pre_sale_responsible_id)
        OR sale_responsible_id IS DISTINCT FROM COALESCE(NEW.sale_responsible_id, sale_responsible_id)
      );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_dual_responsible_to_lead_from_pipe"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_dual_responsible_to_lead_from_pipe"() IS 'Syncs pre_sale_responsible_id and sale_responsible_id from any pipe table to the parent lead. Uses COALESCE so NULL values in the pipe do not overwrite non-NULL values on the lead.';



CREATE OR REPLACE FUNCTION "public"."sync_lead_ai_to_preferences"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  -- Apenas quando a flag realmente muda
  IF NEW.ai_disabled IS DISTINCT FROM OLD.ai_disabled THEN
    -- Exige normalized_phone para ter chave canônica
    IF NEW.normalized_phone IS NOT NULL AND length(NEW.normalized_phone) > 0 THEN
      INSERT INTO public.phone_ai_preferences (
        organization_id, normalized_phone, ai_disabled, set_by, set_at
      ) VALUES (
        NEW.organization_id,
        NEW.normalized_phone,
        NEW.ai_disabled,
        NEW.ai_disabled_by,  -- Pode ser NULL se o caller não preencheu
        COALESCE(NEW.ai_disabled_at, now())
      )
      ON CONFLICT (organization_id, normalized_phone) DO UPDATE
      SET ai_disabled = EXCLUDED.ai_disabled,
          set_by = COALESCE(EXCLUDED.set_by, public.phone_ai_preferences.set_by),
          set_at = EXCLUDED.set_at;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_lead_ai_to_preferences"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_lead_ai_to_preferences"() IS 'Rede de segurança: sincroniza phone_ai_preferences quando leads.ai_disabled muda por qualquer caminho. Mantém a invariante "fonte única = preferences" mesmo se alguém bypassar as RPCs canônicas.';



CREATE OR REPLACE FUNCTION "public"."sync_org_plan_quotas"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan_id UUID;
  v_limits JSONB;
  v_resource TEXT;
  v_limit_key TEXT;
  v_value INTEGER;
BEGIN
  -- Resolve plan_id se vazio mas subscription_plan presente.
  IF NEW.plan_id IS NULL AND NEW.subscription_plan IS NOT NULL THEN
    SELECT id INTO v_plan_id
    FROM public.subscription_plans
    WHERE name = NEW.subscription_plan
    LIMIT 1;

    IF v_plan_id IS NOT NULL THEN
      -- Atualiza plan_id sem disparar recursão (UPDATE direto via service_role bypassa)
      UPDATE public.organizations SET plan_id = v_plan_id WHERE id = NEW.id;
      NEW.plan_id := v_plan_id;
    END IF;
  END IF;

  -- Sincroniza org_quotas.plan_base usando subscription_plans.limits.
  IF NEW.plan_id IS NOT NULL THEN
    SELECT limits INTO v_limits
    FROM public.subscription_plans
    WHERE id = NEW.plan_id;

    IF v_limits IS NOT NULL THEN
      -- Mapeia cada resource (max_whatsapp_instances, max_copilot_agents, max_users)
      FOR v_resource, v_limit_key IN
        SELECT 'max_whatsapp_instances', 'max_whatsapp_instances'
        UNION ALL SELECT 'max_copilot_agents', 'max_copilot_agents'
        UNION ALL SELECT 'max_users', 'max_users'
      LOOP
        v_value := COALESCE((v_limits->>v_limit_key)::INTEGER, 0);

        INSERT INTO public.org_quotas (organization_id, resource_key, plan_base)
        VALUES (NEW.id, v_resource, v_value)
        ON CONFLICT (organization_id, resource_key) DO UPDATE
        SET plan_base = EXCLUDED.plan_base,
            updated_at = NOW();
      END LOOP;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_org_plan_quotas"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_org_plan_quotas"() IS 'Resolve plan_id via subscription_plan name + provisiona/atualiza org_quotas.plan_base. Trigger AFTER INSERT/UPDATE em organizations. Backfill manual feito 2026-04-28 (45 orgs).';



CREATE OR REPLACE FUNCTION "public"."sync_org_quotas_from_plan"("p_org_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan_limits    JSONB;
  v_resource_key   TEXT;
  v_new_value      INTEGER;
  v_old_value      INTEGER;
  v_resource_keys  TEXT[] := ARRAY['max_whatsapp_instances', 'max_users', 'max_copilot_agents'];
BEGIN
  -- -------------------------------------------------------
  -- 1. Authorization: service_role OR master user
  -- -------------------------------------------------------
  IF current_setting('role', true) != 'service_role'
     AND NOT public.is_master_user()
  THEN
    RAISE EXCEPTION 'sync_org_quotas_from_plan: unauthorized — requires service_role or master user';
  END IF;

  -- -------------------------------------------------------
  -- 2. Resolve the org's current plan limits JSONB
  --    Priority: org_subscriptions → fallback organizations.subscription_plan
  -- -------------------------------------------------------
  SELECT sp.limits
  INTO v_plan_limits
  FROM public.org_subscriptions os
  JOIN public.subscription_plans sp ON sp.id = os.plan_id
  WHERE os.organization_id = p_org_id
    AND os.cancelled_at IS NULL
  LIMIT 1;

  IF v_plan_limits IS NULL THEN
    SELECT sp.limits
    INTO v_plan_limits
    FROM public.organizations o
    JOIN public.subscription_plans sp ON sp.name = o.subscription_plan
    WHERE o.id = p_org_id
    LIMIT 1;
  END IF;

  -- Ultimate fallback: empty JSONB (all plan_base → 0)
  IF v_plan_limits IS NULL THEN
    v_plan_limits := '{}'::JSONB;
  END IF;

  -- -------------------------------------------------------
  -- 3. Loop over resource keys and upsert org_quotas
  -- -------------------------------------------------------
  FOREACH v_resource_key IN ARRAY v_resource_keys
  LOOP
    v_new_value := COALESCE((v_plan_limits ->> v_resource_key)::INTEGER, 0);

    -- Capture old plan_base before upsert (NULL if row doesn't exist yet)
    SELECT oq.plan_base
    INTO v_old_value
    FROM public.org_quotas oq
    WHERE oq.organization_id = p_org_id
      AND oq.resource_key = v_resource_key;

    -- Upsert: preserves purchased_addons and admin_adjustment
    INSERT INTO public.org_quotas (organization_id, resource_key, plan_base)
    VALUES (p_org_id, v_resource_key, v_new_value)
    ON CONFLICT (organization_id, resource_key)
    DO UPDATE SET
      plan_base  = EXCLUDED.plan_base,
      updated_at = NOW();

    -- Audit log only when plan_base actually changed
    IF v_old_value IS DISTINCT FROM v_new_value THEN
      INSERT INTO public.quota_audit_log (
        organization_id,
        resource_key,
        field_changed,
        old_value,
        new_value,
        changed_by,
        change_reason
      ) VALUES (
        p_org_id,
        v_resource_key,
        'plan_base',
        COALESCE(v_old_value, 0),
        v_new_value,
        auth.uid(),
        'plan_sync'
      );
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."sync_org_quotas_from_plan"("p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_org_quotas_from_plan"("p_org_id" "uuid") IS 'Syncs org_quotas.plan_base from the org''s current subscription plan limits. Iterates max_whatsapp_instances, max_users, max_copilot_agents. Preserves purchased_addons and admin_adjustment. Writes quota_audit_log only when plan_base actually changes.';



CREATE OR REPLACE FUNCTION "public"."sync_pipe_confirmacao_from_lead"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.closer_id IS NULL OR NEW.sdr_id IS NULL THEN
    SELECT
      COALESCE(NEW.closer_id, l.closer_id),
      COALESCE(NEW.sdr_id, l.sdr_id)
    INTO NEW.closer_id, NEW.sdr_id
    FROM public.leads l
    WHERE l.id = NEW.lead_id;
  END IF;
  RETURN NEW;
END;
$$;


