CREATE OR REPLACE FUNCTION "public"."sync_pipeline_entry_to_lead_pipe_whatsapp"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_slug TEXT;
BEGIN
  -- Prevent circular trigger execution
  IF pg_trigger_depth() > 1 THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    -- Resolve slug for the deleted entry
    SELECT pip.slug INTO v_slug
    FROM public.pipelines pip
    WHERE pip.id = OLD.pipeline_id AND pip.type = 'system';

    IF v_slug = 'whatsapp' THEN
      UPDATE public.leads SET pipe_whatsapp = NULL WHERE id = OLD.lead_id;
    END IF;

    RETURN OLD;
  END IF;

  -- INSERT or UPDATE
  SELECT pip.slug INTO v_slug
  FROM public.pipelines pip
  WHERE pip.id = NEW.pipeline_id AND pip.type = 'system';

  IF v_slug = 'whatsapp' THEN
    UPDATE public.leads SET pipe_whatsapp = NEW.stage_key WHERE id = NEW.lead_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_pipeline_entry_to_lead_pipe_whatsapp"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_responsible_from_lead_to_pipes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.responsible_id IS DISTINCT FROM OLD.responsible_id THEN
    UPDATE public.pipe_whatsapp
       SET responsible_id = NEW.responsible_id
     WHERE lead_id = NEW.id AND responsible_id IS DISTINCT FROM NEW.responsible_id;

    UPDATE public.pipe_confirmacao
       SET responsible_id = NEW.responsible_id
     WHERE lead_id = NEW.id AND responsible_id IS DISTINCT FROM NEW.responsible_id;

    UPDATE public.pipe_propostas
       SET responsible_id = NEW.responsible_id
     WHERE lead_id = NEW.id AND responsible_id IS DISTINCT FROM NEW.responsible_id;

    UPDATE public.campanha_leads
       SET responsible_id = NEW.responsible_id
     WHERE lead_id = NEW.id AND responsible_id IS DISTINCT FROM NEW.responsible_id;
  END IF;

  IF NEW.closer_id IS DISTINCT FROM OLD.closer_id THEN
    UPDATE public.pipe_confirmacao
       SET closer_id = NEW.closer_id
     WHERE lead_id = NEW.id AND closer_id IS DISTINCT FROM NEW.closer_id;

    UPDATE public.pipe_propostas
       SET closer_id = NEW.closer_id
     WHERE lead_id = NEW.id AND closer_id IS DISTINCT FROM NEW.closer_id;
  END IF;

  IF NEW.sdr_id IS DISTINCT FROM OLD.sdr_id THEN
    UPDATE public.pipe_whatsapp
       SET sdr_id = NEW.sdr_id
     WHERE lead_id = NEW.id AND sdr_id IS DISTINCT FROM NEW.sdr_id;

    UPDATE public.pipe_confirmacao
       SET sdr_id = NEW.sdr_id
     WHERE lead_id = NEW.id AND sdr_id IS DISTINCT FROM NEW.sdr_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_responsible_from_lead_to_pipes"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_responsible_from_lead_to_pipes"() IS 'Reverse sync: leads.{responsible_id,closer_id,sdr_id} → pipe_*. Corrige bug de visibilidade em que o closer/sdr antigo continuava vendo o card após transferência (incidente 2026-04-23).';



