CREATE OR REPLACE FUNCTION "public"."sync_user_roles_from_team_members"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Só sincroniza se tem user_id
  IF NEW.user_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Se o membro foi desativado, remover a role antiga (se não tiver outro team_member ativo com essa role)
  IF NEW.is_active = false AND (TG_OP = 'UPDATE' AND OLD.is_active = true) THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.team_members
      WHERE user_id = NEW.user_id
        AND role = OLD.role
        AND is_active = true
        AND id != NEW.id
    ) THEN
      DELETE FROM public.user_roles
      WHERE user_id = NEW.user_id AND role = OLD.role;
    END IF;
    RETURN NEW;
  END IF;

  -- Se role mudou em UPDATE, remover a role antiga (se não tiver outro team_member ativo com ela)
  IF TG_OP = 'UPDATE' AND OLD.role IS DISTINCT FROM NEW.role THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.team_members
      WHERE user_id = NEW.user_id
        AND role = OLD.role
        AND is_active = true
        AND id != NEW.id
    ) THEN
      DELETE FROM public.user_roles
      WHERE user_id = NEW.user_id AND role = OLD.role;
    END IF;
  END IF;

  -- Upsert da nova role (INSERT ou UPDATE com nova role)
  IF NEW.is_active = true AND NEW.role IS NOT NULL THEN
    INSERT INTO public.user_roles (user_id, role)
    VALUES (NEW.user_id, NEW.role)
    ON CONFLICT (user_id, role) DO NOTHING;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_user_roles_from_team_members"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."system_stage_role"("p_pipeline_type" "text", "p_stage_key" "text") RETURNS "public"."stage_role"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT (
    CASE p_pipeline_type
      WHEN 'whatsapp' THEN
        CASE p_stage_key
          WHEN 'agendado' THEN 'meeting_booked'
          WHEN 'compareceu' THEN 'meeting_held'
          WHEN 'nao_compareceu' THEN 'lost'
          ELSE 'open'
        END
      WHEN 'confirmacao' THEN
        CASE p_stage_key
          WHEN 'reuniao_marcada' THEN 'meeting_booked'
          WHEN 'confirmar_d5' THEN 'meeting_booked'
          WHEN 'confirmar_d3' THEN 'meeting_booked'
          WHEN 'confirmar_d2' THEN 'meeting_booked'
          WHEN 'confirmar_d1' THEN 'meeting_booked'
          WHEN 'confirmacao_no_dia' THEN 'meeting_booked'
          WHEN 'compareceu' THEN 'meeting_held'
          WHEN 'perdido' THEN 'lost'
          ELSE 'open'
        END
      WHEN 'propostas' THEN
        CASE p_stage_key
          WHEN 'vendido' THEN 'won'
          WHEN 'perdido' THEN 'lost'
          ELSE 'open'
        END
      ELSE 'open'
    END
  )::public.stage_role
$$;


ALTER FUNCTION "public"."system_stage_role"("p_pipeline_type" "text", "p_stage_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."system_stage_role"("p_pipeline_type" "text", "p_stage_key" "text") IS 'ADR-0017 §1 / #990 — mapa determinístico stage_key de sistema → stage_role. Fonte única: backfill, trigger de INSERT e classifier (#991) leem daqui. Chaves desconhecidas (custom) → open.';



