CREATE OR REPLACE FUNCTION "public"."trigger_pipe_dispatch_rules"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pipe_type TEXT;
  r RECORD;
  v_org_id UUID;
  v_whatsapp_instance_id UUID;
  v_already_exists BOOLEAN;
  v_scheduled_any BOOLEAN := false;
  v_stage_id UUID;
  v_worker_url TEXT;
  v_secret_val TEXT;
BEGIN
  v_pipe_type := TG_ARGV[0];
  v_org_id := NEW.organization_id;

  IF v_org_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- ON INSERT: buscar rules com trigger_type = 'lead_added'
  IF TG_OP = 'INSERT' THEN
    FOR r IN
      SELECT id, whatsapp_instance_id
      FROM public.pipe_dispatch_rules
      WHERE organization_id = v_org_id
        AND pipe_type = v_pipe_type
        AND is_active = true
        AND trigger_type = 'lead_added'
    LOOP
      IF public.schedule_pipe_rule_steps_from_position(
        v_org_id, v_pipe_type, r.id, NEW.id, NEW.lead_id,
        r.whatsapp_instance_id, 0
      ) THEN
        v_scheduled_any := true;
      END IF;
    END LOOP;

    IF v_scheduled_any THEN
      BEGIN
        SELECT value INTO v_worker_url FROM public.cron_config WHERE key = 'pipe_rule_dispatch_url';
        SELECT value INTO v_secret_val FROM public.cron_config WHERE key = 'cron_secret';
        IF v_worker_url IS NOT NULL AND v_worker_url != '' THEN
          PERFORM net.http_post(
            url := v_worker_url,
            headers := jsonb_build_object(
              'Content-Type', 'application/json',
              'x-cron-secret', COALESCE(v_secret_val, '')
            ),
            body := jsonb_build_object('pipe_type', v_pipe_type, 'organization_id', v_org_id::text)
          );
        END IF;
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;
    END IF;

    RETURN NEW;
  END IF;

  -- ON UPDATE of status: buscar rules com trigger_type = 'lead_moved_to_stage'
  IF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status THEN
    -- Resolver pipeline_stage_id a partir do status (stage_key)
    SELECT id INTO v_stage_id
    FROM public.pipeline_stages
    WHERE organization_id = v_org_id
      AND pipeline_type = v_pipe_type
      AND stage_key = NEW.status::text
      AND is_active = true
    LIMIT 1;

    IF v_stage_id IS NOT NULL THEN
      FOR r IN
        SELECT id, whatsapp_instance_id
        FROM public.pipe_dispatch_rules
        WHERE organization_id = v_org_id
          AND pipe_type = v_pipe_type
          AND is_active = true
          AND trigger_type = 'lead_moved_to_stage'
          AND pipeline_stage_id = v_stage_id
      LOOP
        -- Idempotency: não agendar se já existe para este registro+rule
        SELECT EXISTS (
          SELECT 1 FROM public.scheduled_pipe_messages
          WHERE pipe_record_id = NEW.id
            AND rule_id = r.id
            AND status IN ('scheduled', 'sent', 'waiting_response')
        ) INTO v_already_exists;

        IF v_already_exists THEN
          CONTINUE;
        END IF;

        IF public.schedule_pipe_rule_steps_from_position(
          v_org_id, v_pipe_type, r.id, NEW.id, NEW.lead_id,
          r.whatsapp_instance_id, 0
        ) THEN
          v_scheduled_any := true;
        END IF;
      END LOOP;

      IF v_scheduled_any THEN
        BEGIN
          SELECT value INTO v_worker_url FROM public.cron_config WHERE key = 'pipe_rule_dispatch_url';
          SELECT value INTO v_secret_val FROM public.cron_config WHERE key = 'cron_secret';
          IF v_worker_url IS NOT NULL AND v_worker_url != '' THEN
            PERFORM net.http_post(
              url := v_worker_url,
              headers := jsonb_build_object(
                'Content-Type', 'application/json',
                'x-cron-secret', COALESCE(v_secret_val, '')
              ),
              body := jsonb_build_object('pipe_type', v_pipe_type, 'organization_id', v_org_id::text)
            );
          END IF;
        EXCEPTION WHEN OTHERS THEN
          NULL;
        END;
      END IF;
    END IF;

    RETURN NEW;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."trigger_pipe_dispatch_rules"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."trigger_pipe_dispatch_rules"() IS 'Trigger genérico para pipe dispatch. Recebe pipe_type via TG_ARGV[0]. Resolve stage via pipeline_stages.stage_key.';



CREATE OR REPLACE FUNCTION "public"."trigger_pipe_distribution"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_pipe_type TEXT;
  v_distribution_url TEXT;
  v_secret_val TEXT;
  v_has_rule BOOLEAN;
BEGIN
  IF TG_OP != 'INSERT' THEN
    RETURN NEW;
  END IF;

  IF NEW.organization_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_pipe_type := TG_ARGV[0];

  SELECT EXISTS (
    SELECT 1 FROM public.pipe_distribution_rules
    WHERE organization_id = NEW.organization_id
      AND pipe_type = v_pipe_type
      AND sdr_mode IS NOT NULL
  ) INTO v_has_rule;

  IF NOT v_has_rule THEN
    RETURN NEW;
  END IF;

  IF NEW.responsible_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  BEGIN
    SELECT
      replace(value, 'campaign-rule-dispatch', 'process-pipe-distribution')
    INTO v_distribution_url
    FROM public.cron_config
    WHERE key = 'campaign_rule_dispatch_url';

    SELECT value INTO v_secret_val
    FROM public.cron_config
    WHERE key = 'cron_secret';

    IF v_distribution_url IS NOT NULL AND v_distribution_url != '' THEN
      PERFORM net.http_post(
        url := v_distribution_url,
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'x-cron-secret', COALESCE(v_secret_val, '')
        ),
        body := jsonb_build_object(
          'organizationId', NEW.organization_id::text,
          'leadId', NEW.lead_id::text,
          'pipeRecordId', NEW.id::text,
          'pipeType', v_pipe_type
        ),
        timeout_milliseconds := 15000
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trigger_pipe_distribution"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."trigger_pipe_distribution"() IS 'Calls process-pipe-distribution Edge Function via pg_net when a lead enters a pipe, if pipe_distribution_rules is configured.';



CREATE OR REPLACE FUNCTION "public"."trigger_pipeline_entries_dispatch"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pipe_type TEXT;
  r RECORD;
  v_org_id UUID;
  v_already_exists BOOLEAN;
  v_scheduled_any BOOLEAN := false;
  v_stage_id UUID;
  v_worker_url TEXT;
  v_secret_val TEXT;
BEGIN
  v_org_id := NEW.organization_id;

  IF v_org_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Resolve pipe_type from pipelines table (only system pipelines)
  SELECT pip.slug INTO v_pipe_type
  FROM public.pipelines pip
  WHERE pip.id = NEW.pipeline_id AND pip.type = 'system';

  IF v_pipe_type IS NULL THEN
    RETURN NEW;
  END IF;

  -- ON INSERT: rules with trigger_type = 'lead_added'
  IF TG_OP = 'INSERT' THEN
    FOR r IN
      SELECT id, whatsapp_instance_id
      FROM public.pipe_dispatch_rules
      WHERE organization_id = v_org_id
        AND pipe_type = v_pipe_type
        AND is_active = true
        AND trigger_type = 'lead_added'
    LOOP
      IF public.schedule_pipe_rule_steps_from_position(
        v_org_id, v_pipe_type, r.id, NEW.id, NEW.lead_id,
        r.whatsapp_instance_id, 0
      ) THEN
        v_scheduled_any := true;
      END IF;
    END LOOP;

    IF v_scheduled_any THEN
      BEGIN
        SELECT value INTO v_worker_url FROM public.cron_config WHERE key = 'pipe_rule_dispatch_url';
        SELECT value INTO v_secret_val FROM public.cron_config WHERE key = 'cron_secret';
        IF v_worker_url IS NOT NULL AND v_worker_url != '' THEN
          PERFORM net.http_post(
            url := v_worker_url,
            headers := jsonb_build_object(
              'Content-Type', 'application/json',
              'x-cron-secret', COALESCE(v_secret_val, '')
            ),
            body := jsonb_build_object('pipe_type', v_pipe_type, 'organization_id', v_org_id::text)
          );
        END IF;
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;
    END IF;

    RETURN NEW;
  END IF;

  -- ON UPDATE of stage_key: rules with trigger_type = 'lead_moved_to_stage'
  IF TG_OP = 'UPDATE' AND OLD.stage_key IS DISTINCT FROM NEW.stage_key THEN
    SELECT id INTO v_stage_id
    FROM public.pipeline_stages
    WHERE organization_id = v_org_id
      AND pipeline_type = v_pipe_type
      AND stage_key = NEW.stage_key
      AND is_active = true
    LIMIT 1;

    IF v_stage_id IS NOT NULL THEN
      FOR r IN
        SELECT id, whatsapp_instance_id
        FROM public.pipe_dispatch_rules
        WHERE organization_id = v_org_id
          AND pipe_type = v_pipe_type
          AND is_active = true
          AND trigger_type = 'lead_moved_to_stage'
          AND pipeline_stage_id = v_stage_id
      LOOP
        SELECT EXISTS (
          SELECT 1 FROM public.scheduled_pipe_messages
          WHERE pipe_record_id = NEW.id
            AND rule_id = r.id
            AND status IN ('scheduled', 'sent', 'waiting_response')
        ) INTO v_already_exists;

        IF v_already_exists THEN
          CONTINUE;
        END IF;

        IF public.schedule_pipe_rule_steps_from_position(
          v_org_id, v_pipe_type, r.id, NEW.id, NEW.lead_id,
          r.whatsapp_instance_id, 0
        ) THEN
          v_scheduled_any := true;
        END IF;
      END LOOP;

      IF v_scheduled_any THEN
        BEGIN
          SELECT value INTO v_worker_url FROM public.cron_config WHERE key = 'pipe_rule_dispatch_url';
          SELECT value INTO v_secret_val FROM public.cron_config WHERE key = 'cron_secret';
          IF v_worker_url IS NOT NULL AND v_worker_url != '' THEN
            PERFORM net.http_post(
              url := v_worker_url,
              headers := jsonb_build_object(
                'Content-Type', 'application/json',
                'x-cron-secret', COALESCE(v_secret_val, '')
              ),
              body := jsonb_build_object('pipe_type', v_pipe_type, 'organization_id', v_org_id::text)
            );
          END IF;
        EXCEPTION WHEN OTHERS THEN
          NULL;
        END;
      END IF;
    END IF;

    RETURN NEW;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


