CREATE OR REPLACE FUNCTION "public"."trigger_workflow_field_changed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_fields text[] := ARRAY['company', 'segment', 'urgency', 'faturamento', 'rating', 'email', 'phone', 'name'];
  v_field text;
  v_old_val text;
  v_new_val text;
BEGIN
  FOREACH v_field IN ARRAY v_fields LOOP
    EXECUTE format('SELECT ($1).%I::text, ($2).%I::text', v_field, v_field)
      INTO v_old_val, v_new_val
      USING OLD, NEW;

    IF v_old_val IS DISTINCT FROM v_new_val THEN
      PERFORM public.fire_workflow_trigger(
        NEW.organization_id,
        'field_changed',
        NEW.id,
        jsonb_build_object(
          'trigger', 'field_changed',
          'field_name', v_field,
          'old_value', COALESCE(v_old_val, ''),
          'new_value', COALESCE(v_new_val, '')
        )
      );
    END IF;
  END LOOP;
  RETURN NEW;
END;
$_$;


