CREATE OR REPLACE FUNCTION "public"."trigger_workflow_pipeline_stage_changed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_url TEXT;
  v_secret TEXT;
  v_pipe_type TEXT;
  v_actor_user_id UUID;
  v_actor_member_id UUID;
BEGIN
  SELECT pip.slug INTO v_pipe_type
  FROM public.pipelines pip
  WHERE pip.id = NEW.pipeline_id AND pip.type = 'system';

  IF v_pipe_type IS NULL THEN RETURN NEW; END IF;

  SELECT value INTO v_url FROM public.cron_config WHERE key = 'campaign_rule_dispatch_url';
  SELECT value INTO v_secret FROM public.cron_config WHERE key = 'cron_secret';

  v_url := replace(v_url, 'campaign-rule-dispatch', 'process-workflow-executions');

  IF v_url IS NULL OR v_secret IS NULL THEN RETURN NEW; END IF;

  -- Who moved the card? auth.uid() is the authenticated user performing the
  -- UPDATE; NULL for service_role / cron / automation moves.
  v_actor_user_id := auth.uid();
  IF v_actor_user_id IS NOT NULL THEN
    SELECT id INTO v_actor_member_id
    FROM public.team_members
    WHERE user_id = v_actor_user_id
      AND organization_id = NEW.organization_id
      AND is_active = true
    LIMIT 1;
  END IF;

  PERFORM net.http_post(
    url := v_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-cron-secret', v_secret
    ),
    body := jsonb_build_object(
      'mode', 'fire_trigger',
      'organization_id', NEW.organization_id,
      'trigger_type', 'stage_changed',
      'lead_id', NEW.lead_id,
      'context', jsonb_build_object(
        'trigger', 'stage_changed',
        'pipe_type', v_pipe_type,
        'from_stage', OLD.stage_key,
        'to_stage', NEW.stage_key,
        'changed_by_user_id', v_actor_user_id,
        'changed_by_member_id', v_actor_member_id
      )
    )
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trigger_workflow_pipeline_stage_changed"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."trigger_workflow_pipeline_stage_changed"() IS 'Fires stage_changed workflows via process-workflow-executions. Context carries pipe_type/from_stage/to_stage plus changed_by_user_id + changed_by_member_id (the actor who moved the card; NULL for service_role/automation moves).';



CREATE OR REPLACE FUNCTION "public"."trigger_workflow_proposal_result"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_trigger_type text;
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    SELECT organization_id INTO v_org_id FROM public.leads WHERE id = NEW.lead_id;
    IF v_org_id IS NULL THEN RETURN NEW; END IF;

    IF NEW.status = 'vendido' THEN
      v_trigger_type := 'proposal_accepted';
    ELSIF NEW.status = 'perdido' THEN
      v_trigger_type := 'proposal_lost';
    ELSE
      RETURN NEW;
    END IF;

    PERFORM public.fire_workflow_trigger(
      v_org_id,
      v_trigger_type,
      NEW.lead_id,
      jsonb_build_object(
        'trigger', v_trigger_type,
        'status', NEW.status,
        'previous_status', COALESCE(OLD.status, '')
      )
    );
  END IF;
  RETURN NEW;
END;
$$;


