CREATE OR REPLACE FUNCTION "public"."try_provision_lock"("p_user_id" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- pg_try_advisory_xact_lock returns true if lock acquired, false if already held.
  -- The lock is automatically released at the end of the current transaction.
  RETURN pg_try_advisory_xact_lock(hashtext(p_user_id));
END;
$$;


ALTER FUNCTION "public"."try_provision_lock"("p_user_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."try_provision_lock"("p_user_id" "text") IS 'Attempts to acquire a transactional advisory lock for org provisioning. Returns true if acquired, false if another process holds it. Lock is released automatically at transaction end.';



CREATE OR REPLACE FUNCTION "public"."uf_from_ddd"("p_digits" "text") RETURNS character
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE d text; ddd int;
BEGIN
  IF p_digits IS NULL THEN RETURN NULL; END IF;
  d := regexp_replace(p_digits, '\D', '', 'g');
  IF length(d) >= 12 AND d LIKE '55%' THEN d := substring(d from 3); END IF;
  IF length(d) < 10 THEN RETURN NULL; END IF;
  ddd := substring(d from 1 for 2)::int;
  RETURN CASE
    WHEN ddd BETWEEN 11 AND 19 THEN 'SP'
    WHEN ddd IN (21,22,24) THEN 'RJ'
    WHEN ddd IN (27,28) THEN 'ES'
    WHEN ddd IN (31,32,33,34,35,37,38) THEN 'MG'
    WHEN ddd BETWEEN 41 AND 46 THEN 'PR'
    WHEN ddd IN (47,48,49) THEN 'SC'
    WHEN ddd IN (51,53,54,55) THEN 'RS'
    WHEN ddd = 61 THEN 'DF'
    WHEN ddd IN (62,64) THEN 'GO'
    WHEN ddd = 63 THEN 'TO'
    WHEN ddd IN (65,66) THEN 'MT'
    WHEN ddd = 67 THEN 'MS'
    WHEN ddd = 68 THEN 'AC'
    WHEN ddd = 69 THEN 'RO'
    WHEN ddd IN (71,73,74,75,77) THEN 'BA'
    WHEN ddd = 79 THEN 'SE'
    WHEN ddd IN (81,87) THEN 'PE'
    WHEN ddd = 82 THEN 'AL'
    WHEN ddd = 83 THEN 'PB'
    WHEN ddd = 84 THEN 'RN'
    WHEN ddd IN (85,88) THEN 'CE'
    WHEN ddd IN (86,89) THEN 'PI'
    WHEN ddd IN (91,93,94) THEN 'PA'
    WHEN ddd IN (92,97) THEN 'AM'
    WHEN ddd = 95 THEN 'RR'
    WHEN ddd = 96 THEN 'AP'
    WHEN ddd IN (98,99) THEN 'MA'
    ELSE NULL
  END;
END; $$;


ALTER FUNCTION "public"."uf_from_ddd"("p_digits" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unlink_agent_from_instance"("p_agent_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_org UUID; v_agent_org UUID; v_instance_id UUID;
BEGIN
  v_user_org := public.get_user_organization_id();
  SELECT organization_id, whatsapp_instance_id INTO v_agent_org, v_instance_id FROM public.copilot_agents WHERE id = p_agent_id;
  IF v_agent_org IS NULL THEN RAISE EXCEPTION 'Agent not found'; END IF;
  IF v_agent_org != v_user_org THEN RAISE EXCEPTION 'Cross-tenant operation denied'; END IF;
  UPDATE public.copilot_agents SET whatsapp_instance_id = NULL WHERE id = p_agent_id AND organization_id = v_user_org;
  IF v_instance_id IS NOT NULL THEN
    UPDATE public.whatsapp_instances SET copilot_agent_id = NULL WHERE id = v_instance_id AND organization_id = v_user_org;
  END IF;
END;
$$;


