CREATE OR REPLACE FUNCTION "public"."validate_copilot_move_rules"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  rules JSONB;
  rule JSONB;
  org_id UUID;
  from_pipe TEXT;
  from_stage TEXT;
  to_pipe TEXT;
  to_stage TEXT;
  stage_exists BOOLEAN;
BEGIN
  rules := COALESCE(NEW.move_rules, '[]'::jsonb);
  org_id := NEW.organization_id;

  -- Verificar cada regra
  FOR i IN 0..jsonb_array_length(rules) - 1 LOOP
    rule := rules -> i;

    from_pipe := rule -> 'from' ->> 'pipe';
    from_stage := rule -> 'from' ->> 'stage';
    to_pipe := rule -> 'to' ->> 'pipe';
    to_stage := rule -> 'to' ->> 'stage';

    -- Pular regras incompletas (podem estar sendo editadas na UI)
    IF from_pipe IS NULL OR from_pipe = '' OR from_stage IS NULL OR from_stage = ''
       OR to_pipe IS NULL OR to_pipe = '' OR to_stage IS NULL OR to_stage = '' THEN
      CONTINUE;
    END IF;

    -- Verificar se a etapa de origem existe e está ativa
    SELECT EXISTS(
      SELECT 1 FROM public.pipeline_stages
      WHERE organization_id = org_id
        AND pipeline_type = from_pipe
        AND stage_key = from_stage
        AND is_active = true
    ) INTO stage_exists;

    IF NOT stage_exists THEN
      RAISE EXCEPTION 'Move rule #% referencia etapa de origem inexistente: %.%',
        i + 1, from_pipe, from_stage;
    END IF;

    -- Verificar se a etapa de destino existe e está ativa
    SELECT EXISTS(
      SELECT 1 FROM public.pipeline_stages
      WHERE organization_id = org_id
        AND pipeline_type = to_pipe
        AND stage_key = to_stage
        AND is_active = true
    ) INTO stage_exists;

    IF NOT stage_exists THEN
      RAISE EXCEPTION 'Move rule #% referencia etapa de destino inexistente: %.%',
        i + 1, to_pipe, to_stage;
    END IF;
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_copilot_move_rules"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_coupon"("p_code" "text", "p_plan_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_coupon RECORD;
BEGIN
  -- Buscar cupom pelo código (case-insensitive)
  SELECT *
  INTO v_coupon
  FROM public.coupons
  WHERE UPPER(code) = UPPER(p_code);

  -- Não encontrado
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'valid',       false,
      'discount_pct', 0,
      'coupon_id',   NULL,
      'error',       'COUPON_NOT_FOUND'
    );
  END IF;

  -- Inativo
  IF NOT v_coupon.is_active THEN
    RETURN jsonb_build_object(
      'valid',       false,
      'discount_pct', 0,
      'coupon_id',   v_coupon.id,
      'error',       'COUPON_INACTIVE'
    );
  END IF;

  -- Antes de valid_from
  IF v_coupon.valid_from IS NOT NULL AND NOW() < v_coupon.valid_from THEN
    RETURN jsonb_build_object(
      'valid',       false,
      'discount_pct', 0,
      'coupon_id',   v_coupon.id,
      'error',       'COUPON_NOT_YET_VALID'
    );
  END IF;

  -- Expirado
  IF v_coupon.valid_until IS NOT NULL AND NOW() > v_coupon.valid_until THEN
    RETURN jsonb_build_object(
      'valid',       false,
      'discount_pct', 0,
      'coupon_id',   v_coupon.id,
      'error',       'COUPON_EXPIRED'
    );
  END IF;

  -- Limite de usos atingido
  IF v_coupon.max_uses IS NOT NULL AND v_coupon.current_uses >= v_coupon.max_uses THEN
    RETURN jsonb_build_object(
      'valid',       false,
      'discount_pct', 0,
      'coupon_id',   v_coupon.id,
      'error',       'COUPON_MAX_USES_REACHED'
    );
  END IF;

  -- Não se aplica ao plano (applies_to vazio = aplica a todos)
  IF array_length(v_coupon.applies_to, 1) > 0
    AND NOT (p_plan_slug = ANY(v_coupon.applies_to))
  THEN
    RETURN jsonb_build_object(
      'valid',       false,
      'discount_pct', 0,
      'coupon_id',   v_coupon.id,
      'error',       'COUPON_PLAN_NOT_ELIGIBLE'
    );
  END IF;

  -- Válido
  RETURN jsonb_build_object(
    'valid',       true,
    'discount_pct', v_coupon.discount_pct,
    'coupon_id',   v_coupon.id,
    'error',       NULL
  );
END;
$$;


ALTER FUNCTION "public"."validate_coupon"("p_code" "text", "p_plan_slug" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."validate_coupon"("p_code" "text", "p_plan_slug" "text") IS 'Valida um cupom de desconto para um plano específico. Retorna {valid, discount_pct, coupon_id, error}. Erros: COUPON_NOT_FOUND | COUPON_INACTIVE | COUPON_NOT_YET_VALID | COUPON_EXPIRED | COUPON_MAX_USES_REACHED | COUPON_PLAN_NOT_ELIGIBLE';



CREATE OR REPLACE FUNCTION "public"."validate_organization_timezone"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.is_valid_timezone(NEW.timezone) THEN
    RAISE EXCEPTION 'invalid organization timezone "%" — must be an IANA zone name (see pg_timezone_names)', NEW.timezone USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END;
$$;


