CREATE TABLE IF NOT EXISTS "public"."campanha_dispatch_rule_steps" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "rule_id" "uuid" NOT NULL,
    "template_id" "uuid",
    "delay_minutes" integer DEFAULT 0 NOT NULL,
    "position" integer DEFAULT 0 NOT NULL,
    "action_type" "text" DEFAULT 'send_template'::"text" NOT NULL,
    "wait_timeout_minutes" integer DEFAULT 1440,
    "timeout_action" "text" DEFAULT 'continue'::"text",
    "timeout_target_stage_id" "uuid",
    "timeout_template_id" "uuid",
    "target_stage_id" "uuid",
    "sdr_assignment_mode" "text" DEFAULT 'specific'::"text",
    "target_sdr_id" "uuid",
    CONSTRAINT "campanha_dispatch_rule_steps_delay_minutes_check" CHECK (("delay_minutes" >= 0)),
    CONSTRAINT "chk_step_action_type" CHECK (("action_type" = ANY (ARRAY['send_template'::"text", 'wait_response'::"text", 'change_stage'::"text", 'assign_sdr'::"text", 'cancel_sequence'::"text"]))),
    CONSTRAINT "chk_step_sdr_mode" CHECK ((("sdr_assignment_mode" IS NULL) OR ("sdr_assignment_mode" = ANY (ARRAY['specific'::"text", 'round_robin'::"text"])))),
    CONSTRAINT "chk_step_stage_required" CHECK ((("action_type" <> 'change_stage'::"text") OR ("target_stage_id" IS NOT NULL))),
    CONSTRAINT "chk_step_template_required" CHECK ((("action_type" <> 'send_template'::"text") OR ("template_id" IS NOT NULL))),
    CONSTRAINT "chk_step_timeout_action" CHECK ((("timeout_action" IS NULL) OR ("timeout_action" = ANY (ARRAY['continue'::"text", 'change_stage'::"text", 'send_template'::"text", 'cancel_sequence'::"text"]))))
);


ALTER TABLE "public"."campanha_dispatch_rule_steps" OWNER TO "postgres";


COMMENT ON TABLE "public"."campanha_dispatch_rule_steps" IS 'Cada passo da sequência: template a enviar e delay em minutos em relação ao passo anterior (0 = imediato).';



COMMENT ON COLUMN "public"."campanha_dispatch_rule_steps"."delay_minutes" IS 'Minutos de espera após o passo anterior antes de enviar este (0 = enviar junto com o primeiro).';



COMMENT ON COLUMN "public"."campanha_dispatch_rule_steps"."action_type" IS 'Tipo de ação: send_template, wait_response, change_stage, assign_sdr, cancel_sequence';



COMMENT ON COLUMN "public"."campanha_dispatch_rule_steps"."wait_timeout_minutes" IS 'Para wait_response: minutos até timeout (default 1440 = 24h)';



COMMENT ON COLUMN "public"."campanha_dispatch_rule_steps"."timeout_action" IS 'Para wait_response: ação no timeout (continue, change_stage, send_template, cancel_sequence)';



COMMENT ON COLUMN "public"."campanha_dispatch_rule_steps"."target_stage_id" IS 'Para change_stage: etapa destino';



COMMENT ON COLUMN "public"."campanha_dispatch_rule_steps"."sdr_assignment_mode" IS 'Para assign_sdr: specific ou round_robin';



COMMENT ON COLUMN "public"."campanha_dispatch_rule_steps"."target_sdr_id" IS 'Para assign_sdr com mode=specific: UUID do SDR';



