CREATE TABLE IF NOT EXISTS "public"."campanhas" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "deadline" timestamp with time zone NOT NULL,
    "team_goal" integer DEFAULT 30 NOT NULL,
    "individual_goal" integer DEFAULT 10,
    "bonus_value" numeric DEFAULT 500,
    "is_active" boolean DEFAULT true,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "organization_id" "uuid",
    "campaign_type" "text" DEFAULT 'manual'::"text",
    "agent_id" "uuid",
    "auto_config" "jsonb",
    "lead_distribution_mode" "text",
    "lead_assigned_to" "uuid",
    "investimento_cents" bigint,
    "investimento_updated_at" timestamp with time zone,
    "investimento_source" "text" DEFAULT 'manual'::"text",
    "mkt_incluir_call" boolean DEFAULT true,
    "mkt_incluir_cadastro" boolean DEFAULT true,
    "mkt_call_origins" "text"[],
    "mkt_call_tag_ids" "uuid"[],
    "mkt_cadastro_origins" "text"[],
    "mkt_cadastro_tag_ids" "uuid"[],
    "mkt_ativo" boolean DEFAULT false,
    "mkt_investimento_call_cents" integer,
    "mkt_investimento_cadastro_cents" integer,
    "whatsapp_instance_id" "uuid",
    "closer_distribution_mode" "text",
    "closer_assigned_to" "uuid",
    "objective" "text" DEFAULT 'livre'::"text" NOT NULL,
    "free_target_pipe" "text",
    "free_target_stage" "text",
    CONSTRAINT "campanhas_campaign_type_check" CHECK (("campaign_type" = ANY (ARRAY['automatica'::"text", 'semi_automatica'::"text", 'manual'::"text"]))),
    CONSTRAINT "campanhas_closer_distribution_mode_check" CHECK ((("closer_distribution_mode" IS NULL) OR ("closer_distribution_mode" = ANY (ARRAY['random'::"text", 'round_robin'::"text", 'single'::"text"])))),
    CONSTRAINT "campanhas_investimento_source_check" CHECK ((("investimento_source" IS NULL) OR ("investimento_source" = ANY (ARRAY['manual'::"text", 'api'::"text"])))),
    CONSTRAINT "campanhas_lead_distribution_mode_check" CHECK ((("lead_distribution_mode" IS NULL) OR ("lead_distribution_mode" = ANY (ARRAY['random'::"text", 'round_robin'::"text", 'single'::"text"])))),
    CONSTRAINT "chk_free_target_consistency" CHECK ((("objective" = 'livre'::"text") OR (("free_target_pipe" IS NULL) AND ("free_target_stage" IS NULL)))),
    CONSTRAINT "chk_free_target_pipe" CHECK (("free_target_pipe" = ANY (ARRAY['pipe_whatsapp'::"text", 'pipe_confirmacao'::"text", 'pipe_propostas'::"text"]))),
    CONSTRAINT "chk_objective" CHECK (("objective" = ANY (ARRAY['qualificacao'::"text", 'agendamentos'::"text", 'propostas'::"text", 'livre'::"text"])))
);


ALTER TABLE "public"."campanhas" OWNER TO "postgres";


COMMENT ON COLUMN "public"."campanhas"."campaign_type" IS 'Tipo: automatica (IA), semi_automatica (templates), manual (kanban)';



COMMENT ON COLUMN "public"."campanhas"."agent_id" IS 'Agente Copilot vinculado (apenas para campanhas automaticas)';



COMMENT ON COLUMN "public"."campanhas"."auto_config" IS 'Config de automacao: delay_minutes, send_on_add_lead, working_hours_only, working_hours';



COMMENT ON COLUMN "public"."campanhas"."lead_distribution_mode" IS 'Modo de distribuição: random (aleatório), round_robin (rotativo), single (pessoa específica). Null = manual';



COMMENT ON COLUMN "public"."campanhas"."lead_assigned_to" IS 'Quando lead_distribution_mode=single, ID do team_member que recebe todos os leads';



COMMENT ON COLUMN "public"."campanhas"."investimento_cents" IS 'Investimento na campanha em centavos (ex: 10000 = R$ 100,00). Null = não informado';



COMMENT ON COLUMN "public"."campanhas"."investimento_updated_at" IS 'Última atualização do investimento';



COMMENT ON COLUMN "public"."campanhas"."investimento_source" IS 'Origem do dado: manual (preenchido no sistema) ou api (webhook/integração)';



COMMENT ON COLUMN "public"."campanhas"."mkt_incluir_call" IS 'Se true, campanha entra no dashboard Marketing Call (respeitando config por origem/etiqueta).';



COMMENT ON COLUMN "public"."campanhas"."mkt_incluir_cadastro" IS 'Se true, campanha entra no dashboard Marketing Cadastro (respeitando config por origem/etiqueta).';



COMMENT ON COLUMN "public"."campanhas"."mkt_call_origins" IS 'Origens (lead_origin) que contam para dashboard Marketing Call. Null/empty = não configurado (usa critério global).';



COMMENT ON COLUMN "public"."campanhas"."mkt_call_tag_ids" IS 'IDs de tags: leads com alguma dessas etiquetas contam para Marketing Call.';



COMMENT ON COLUMN "public"."campanhas"."mkt_cadastro_origins" IS 'Origens que contam para dashboard Marketing Cadastro.';



COMMENT ON COLUMN "public"."campanhas"."mkt_cadastro_tag_ids" IS 'IDs de tags que contam para Marketing Cadastro.';



COMMENT ON COLUMN "public"."campanhas"."mkt_ativo" IS 'Se true, campanha aparece na divisão por campanha do Marketing e pode ser configurada (investimento, tipo, origem/etiqueta).';



COMMENT ON COLUMN "public"."campanhas"."mkt_investimento_call_cents" IS 'Investimento em centavos atribuído ao dashboard Marketing Call para esta campanha.';



COMMENT ON COLUMN "public"."campanhas"."mkt_investimento_cadastro_cents" IS 'Investimento em centavos atribuído ao dashboard Marketing Cadastro para esta campanha.';



COMMENT ON COLUMN "public"."campanhas"."whatsapp_instance_id" IS 'Instância WhatsApp usada para disparos da campanha (semi-automática e automática). Se NULL, usa primeira instância ativa da organização.';



COMMENT ON COLUMN "public"."campanhas"."closer_distribution_mode" IS 'Modo de distribuição de Closers: random, round_robin, single, ou NULL (manual).';



COMMENT ON COLUMN "public"."campanhas"."closer_assigned_to" IS 'Closer fixo quando closer_distribution_mode = single.';



COMMENT ON COLUMN "public"."campanhas"."objective" IS 'Strategic campaign objective: qualificacao (→ pipe_whatsapp), agendamentos (→ pipe_confirmacao), propostas (→ pipe_propostas), livre (→ free_target_pipe/stage)';



COMMENT ON COLUMN "public"."campanhas"."free_target_pipe" IS 'Target pipe for livre objective campaigns. Must be NULL for other objectives.';



COMMENT ON COLUMN "public"."campanhas"."free_target_stage" IS 'Target stage/status for livre objective campaigns. Must be NULL for other objectives.';



CREATE TABLE IF NOT EXISTS "public"."channel_messages" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "channel" "public"."channel_type" DEFAULT 'whatsapp'::"public"."channel_type" NOT NULL,
    "instance_id" "uuid",
    "page_id" "text",
    "external_id" "text" NOT NULL,
    "remote_jid" "text",
    "phone_number" "text",
    "sender_id" "text",
    "sender_name" "text",
    "sender_profile_pic" "text",
    "direction" "text" NOT NULL,
    "message_type" "text" DEFAULT 'text'::"text" NOT NULL,
    "content" "text",
    "media_url" "text",
    "status" "text" DEFAULT 'received'::"text",
    "lead_id" "uuid",
    "timestamp" timestamp with time zone DEFAULT "now"() NOT NULL,
