CREATE TABLE IF NOT EXISTS "public"."conversations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "lead_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "agent_id" "uuid" NOT NULL,
    "state" "text" DEFAULT 'NEW_LEAD'::"text" NOT NULL,
    "turn_count" integer DEFAULT 0,
    "last_message_at" timestamp with time zone DEFAULT "now"(),
    "context" "jsonb" DEFAULT '{}'::"jsonb",
    "short_term_memory" "jsonb" DEFAULT '[]'::"jsonb",
    "long_term_memory" "jsonb" DEFAULT '{}'::"jsonb",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "assigned_to" "uuid",
    "ai_state" "public"."ai_takeover_state_enum" DEFAULT 'AI_ACTIVE'::"public"."ai_takeover_state_enum" NOT NULL,
    "ai_state_resume_mode" "text",
    "ai_state_updated_at" timestamp with time zone DEFAULT "now"(),
    "ai_state_updated_by" "uuid",
    "human_paused_until" timestamp with time zone,
    CONSTRAINT "conversations_ai_state_resume_mode_check" CHECK ((("ai_state_resume_mode" IS NULL) OR ("ai_state_resume_mode" = ANY (ARRAY['immediate'::"text", 'after_response'::"text", 'dont_resume'::"text"]))))
)
WITH ("autovacuum_vacuum_scale_factor"='0.05', "autovacuum_analyze_scale_factor"='0.05');


ALTER TABLE "public"."conversations" OWNER TO "postgres";


COMMENT ON TABLE "public"."conversations" IS 'Estado da conversa com cada lead - State Machine para gerenciar fluxo de conversação';



COMMENT ON COLUMN "public"."conversations"."state" IS 'Estado atual da conversa: NEW_LEAD, QUALIFYING, QUALIFIED, SCHEDULING, SCHEDULED, FOLLOW_UP, WAITING_HUMAN, CLOSED_WON, CLOSED_LOST';



COMMENT ON COLUMN "public"."conversations"."context" IS 'Contexto coletado durante a conversa (tamanho empresa, urgência, orçamento, etc.)';



COMMENT ON COLUMN "public"."conversations"."short_term_memory" IS 'Últimas mensagens da conversa (cache para performance)';



COMMENT ON COLUMN "public"."conversations"."long_term_memory" IS 'Fatos importantes extraídos da conversa (persistência)';



COMMENT ON COLUMN "public"."conversations"."assigned_to" IS 'Usuário responsável por esta conversa. NULL = não atribuído (visível para todos). Admins veem todas as conversas.';



COMMENT ON COLUMN "public"."conversations"."ai_state" IS 'FSM de controle takeover IA↔humano. Distinto de conversations.state (FSM copilot). Valores: AI_ACTIVE | AI_PAUSED_MANUAL | WAITING_HUMAN | HUMAN_ACTIVE | HANDOFF_BACK. Transições enforced por trigger trg_enforce_ai_state_transition.';



COMMENT ON COLUMN "public"."conversations"."ai_state_resume_mode" IS 'Modo de retomada da IA quando pausada manualmente. immediate = retoma ao liberar | after_response = retoma após resposta do lead | dont_resume = não retoma automaticamente.';



COMMENT ON COLUMN "public"."conversations"."ai_state_updated_at" IS 'Timestamp da última transição de ai_state. Atualizado automaticamente pelo trigger.';



COMMENT ON COLUMN "public"."conversations"."ai_state_updated_by" IS 'UUID do auth.user que realizou a última transição. NULL = alteração por processo automático (IA/sistema).';



