CREATE TABLE IF NOT EXISTS "public"."copilot_agents" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "created_by" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "template_type" "public"."agent_template_type" DEFAULT 'custom'::"public"."agent_template_type" NOT NULL,
    "personality_tone" "public"."agent_tone" DEFAULT 'profissional'::"public"."agent_tone" NOT NULL,
    "personality_style" "public"."agent_style" DEFAULT 'consultivo'::"public"."agent_style" NOT NULL,
    "personality_energy" "public"."agent_energy" DEFAULT 'moderada'::"public"."agent_energy" NOT NULL,
    "skills" "text"[] DEFAULT '{}'::"text"[],
    "allowed_topics" "text"[] DEFAULT '{}'::"text"[],
    "forbidden_topics" "text"[] DEFAULT '{}'::"text"[],
    "main_objective" "text" NOT NULL,
    "system_prompt" "text",
    "system_prompt_version" integer DEFAULT 1,
    "is_active" boolean DEFAULT false,
    "is_default" boolean DEFAULT false,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "can_qualify_lead" boolean DEFAULT true,
    "can_schedule_meeting" boolean DEFAULT true,
    "can_send_followup" boolean DEFAULT true,
    "can_update_crm" boolean DEFAULT false,
    "can_answer_faq" boolean DEFAULT true,
    "can_create_lead" boolean DEFAULT true,
    "can_transfer_human" boolean DEFAULT true,
    "max_conversation_turns" integer DEFAULT 20,
    "response_delay_ms" integer DEFAULT 1000,
    "llm_model" "text" DEFAULT 'openai/gpt-4.1-mini'::"text" NOT NULL,
    "active_pipes" "jsonb" DEFAULT '[]'::"jsonb",
    "active_stages" "jsonb" DEFAULT '{}'::"jsonb",
    "can_move_cards" boolean DEFAULT false,
    "auto_move_on_qualify" boolean DEFAULT false,
    "auto_move_on_objective" boolean DEFAULT false,
    "move_rules" "jsonb" DEFAULT '[]'::"jsonb",
    "whatsapp_instance_id" "uuid",
    "business_context" "jsonb" DEFAULT '{}'::"jsonb",
    "conversation_style" "jsonb" DEFAULT '{}'::"jsonb",
    "qualification_rules" "jsonb" DEFAULT '{}'::"jsonb",
    "few_shot_examples" "jsonb" DEFAULT '[]'::"jsonb",
    "availability" "jsonb" DEFAULT '{"end": "18:00", "days": ["mon", "tue", "wed", "thu", "fri"], "mode": "always", "start": "09:00", "timezone": "America/Sao_Paulo"}'::"jsonb",
    "response_delay_seconds" integer DEFAULT 0,
    "operation_mode" "text" DEFAULT 'inbound'::"text",
    "activation_triggers" "jsonb",
    "outbound_config" "jsonb",
    "automation_actions" "jsonb",
    "campaign_id" "uuid",
    "template_prompt_override" "text",
    "context_config" "jsonb" DEFAULT '{"include_lead_data": true, "max_history_messages": 10, "include_custom_fields": true, "use_last_conversation": true, "summarize_long_conversations": true}'::"jsonb",
    "anti_patterns" "text"[] DEFAULT '{}'::"text"[],
    "human_transfer_triggers" "text"[] DEFAULT '{}'::"text"[],
    "intent_detection" "jsonb" DEFAULT '{}'::"jsonb",
    "can_update_lead" boolean DEFAULT true,
    "wizard_version" integer DEFAULT 1,
    "attend_unknown_contacts" boolean DEFAULT true,
    "objective_composite" "jsonb",
    "custom_instructions" "text",
    "prompt_hash" "text",
    "routing_stages" "text"[] DEFAULT '{}'::"text"[],
    "llm_temperature_mode" "text" DEFAULT 'balanceado'::"text",
    "routing_origins" "text"[] DEFAULT '{}'::"text"[],
    "routing_segments" "text"[] DEFAULT '{}'::"text"[],
    "natural_messaging_config" "jsonb" DEFAULT '{"enabled": true, "intensity": "natural"}'::"jsonb",
    "tts_config" "jsonb",
    "reasoning_mode" "text" DEFAULT 'always'::"text" NOT NULL,
    "behavior_windows" "jsonb" DEFAULT '[]'::"jsonb",
    "behavior_enforcement" "text" DEFAULT 'hard'::"text",
    "retention_enabled" boolean DEFAULT false,
    "retention_config" "jsonb" DEFAULT '{}'::"jsonb",
    "human_pause_enabled" boolean DEFAULT true,
    "human_pause_duration_minutes" integer DEFAULT 60,
    "handoff_notify_phones" "text"[],
    "handoff_notify_instructions" "text",
    "can_send_document" boolean DEFAULT false,
    "can_transfer_sz_chat" boolean DEFAULT false,
    "finalized_at" timestamp with time zone,
    CONSTRAINT "copilot_agents_behavior_enforcement_check" CHECK (("behavior_enforcement" = ANY (ARRAY['hard'::"text", 'soft'::"text"]))),
    CONSTRAINT "copilot_agents_llm_model_allowlist" CHECK (("llm_model" = 'openai/gpt-4.1-mini'::"text")),
    CONSTRAINT "copilot_agents_llm_temperature_mode_check" CHECK (("llm_temperature_mode" = ANY (ARRAY['criativo'::"text", 'balanceado'::"text", 'preciso'::"text"]))),
    CONSTRAINT "copilot_agents_operation_mode_check" CHECK (("operation_mode" = ANY (ARRAY['inbound'::"text", 'outbound'::"text", 'hybrid'::"text"]))),
    CONSTRAINT "copilot_agents_reasoning_mode_check" CHECK (("reasoning_mode" = ANY (ARRAY['always'::"text", 'actions_only'::"text", 'off'::"text"])))
);


ALTER TABLE "public"."copilot_agents" OWNER TO "postgres";


COMMENT ON TABLE "public"."copilot_agents" IS 'Armazena configurações de agentes de IA personalizáveis para automação de vendas';



COMMENT ON COLUMN "public"."copilot_agents"."system_prompt" IS 'System Prompt gerado automaticamente - cache para performance';



COMMENT ON COLUMN "public"."copilot_agents"."system_prompt_version" IS 'Versão do prompt gerado - incrementa a cada atualização';



COMMENT ON COLUMN "public"."copilot_agents"."is_default" IS 'Apenas um agente pode ser padrão por organização';



COMMENT ON COLUMN "public"."copilot_agents"."active_pipes" IS 'Lista de funis onde o agente está ativo: ["confirmacao", "propostas", "whatsapp", "campanha"]';



COMMENT ON COLUMN "public"."copilot_agents"."active_stages" IS 'Etapas específicas de cada funil onde o agente está ativo (JSONB)';



COMMENT ON COLUMN "public"."copilot_agents"."can_move_cards" IS 'Se o agente pode movimentar cards entre etapas/funis';



COMMENT ON COLUMN "public"."copilot_agents"."auto_move_on_qualify" IS 'Move automaticamente quando qualifica o lead';



COMMENT ON COLUMN "public"."copilot_agents"."auto_move_on_objective" IS 'Move automaticamente quando cumpre o objetivo';



COMMENT ON COLUMN "public"."copilot_agents"."move_rules" IS 'Regras de movimentação automática (JSONB array)';



COMMENT ON COLUMN "public"."copilot_agents"."whatsapp_instance_id" IS 'Instância de WhatsApp onde este agente está ativo. Se NULL, não responde automaticamente.';



COMMENT ON COLUMN "public"."copilot_agents"."business_context" IS 'Contexto do negócio coletado no quiz (produto, ICP, região, prova social, pricing, etc)';



COMMENT ON COLUMN "public"."copilot_agents"."conversation_style" IS 'Diretrizes de estilo e humanização para WhatsApp (ritmo, emojis, perguntas, etc)';



COMMENT ON COLUMN "public"."copilot_agents"."qualification_rules" IS 'Campos mínimos de qualificação e ordem sugerida';



COMMENT ON COLUMN "public"."copilot_agents"."few_shot_examples" IS 'Exemplos curtos de conversa (lead -> agente) para calibrar o tom';



COMMENT ON COLUMN "public"."copilot_agents"."availability" IS 'Regras de disponibilidade do agente: mode(always|scheduled), timezone, days, start, end';



COMMENT ON COLUMN "public"."copilot_agents"."response_delay_seconds" IS 'Atraso artificial de resposta (em segundos) para simular tempo humano';



COMMENT ON COLUMN "public"."copilot_agents"."operation_mode" IS 'Modo de operação: inbound (espera lead), outbound (inicia conversa), hybrid (ambos)';



COMMENT ON COLUMN "public"."copilot_agents"."activation_triggers" IS 'Condições para ativação do agente: tags, origens, campos personalizados';



COMMENT ON COLUMN "public"."copilot_agents"."outbound_config" IS 'Configuração de outbound: delay, template da primeira mensagem';



COMMENT ON COLUMN "public"."copilot_agents"."automation_actions" IS 'Ações automáticas: on_qualify, on_disqualify, on_need_human';



COMMENT ON COLUMN "public"."copilot_agents"."campaign_id" IS 'Campanha vinculada ao agente (opcional)';



COMMENT ON COLUMN "public"."copilot_agents"."can_update_lead" IS 'Se o agente pode atualizar informações do lead no CRM (leads, campos personalizados, notas)';



COMMENT ON COLUMN "public"."copilot_agents"."wizard_version" IS 'Versão do wizard usado para criar o agente (1=legacy, 2=config-driven)';



COMMENT ON COLUMN "public"."copilot_agents"."attend_unknown_contacts" IS 'Audience filter: true = IA atende qualquer phone (cria shadow/real lead). false = só atende phones que já são lead na org. Default true preserva comportamento histórico. Aplicado em agent-message + sz-chat-webhook.';



COMMENT ON COLUMN "public"."copilot_agents"."objective_composite" IS 'Objetivo estruturado em 3 partes: mission (o que fazer), success_criteria (quando deu certo), limits (o que não fazer)';



COMMENT ON COLUMN "public"."copilot_agents"."custom_instructions" IS 'Instruções personalizadas do usuário. Adicionadas ao final do system prompt.';



COMMENT ON COLUMN "public"."copilot_agents"."prompt_hash" IS 'Hash dos campos que afetam o prompt. Usado para detectar quando o cache precisa ser regenerado.';



COMMENT ON COLUMN "public"."copilot_agents"."routing_stages" IS 'Etapas do pipe_whatsapp que ativam este agente. Vazio = nunca roteado por etapa. Apenas o agente is_default=true é usado como fallback.';



COMMENT ON COLUMN "public"."copilot_agents"."llm_temperature_mode" IS 'Modo de temperatura do LLM: criativo=0.9, balanceado=0.7, preciso=0.2';



COMMENT ON COLUMN "public"."copilot_agents"."routing_origins" IS 'Origens do lead (ex: meta_ads, google_ads, whatsapp) que ativam este agente. Vazio = não filtra por origem.';



COMMENT ON COLUMN "public"."copilot_agents"."routing_segments" IS 'Segmentos do lead (ex: enterprise, smb, retail) que ativam este agente. Vazio = não filtra por segmento.';



COMMENT ON COLUMN "public"."copilot_agents"."natural_messaging_config" IS 'Config for natural message splitting: { enabled: bool, intensity: suave|natural|conversacional }';



COMMENT ON COLUMN "public"."copilot_agents"."tts_config" IS 'TTS config via ElevenLabs. NULL = disabled.';



COMMENT ON COLUMN "public"."copilot_agents"."reasoning_mode" IS 'Reasoning chain config: always (toda resposta), actions_only (só quando usar tool), off (legado). Default always.';



COMMENT ON COLUMN "public"."copilot_agents"."behavior_windows" IS 'Array de até 6 janelas de comportamento. Schema cada item: { id: uuid, name: text, days: text[] (mon|tue|wed|thu|fri|sat|sun), start: HH:MM, end: HH:MM, behavior: text (instrução textual injetada no prompt) }. Resolver pega primeira janela que casa (dia+hora) em ordem do array.';



COMMENT ON COLUMN "public"."copilot_agents"."behavior_enforcement" IS 'hard: fora janela com behavior vazio devolve out_of_hours_message canned (não chama LLM). soft: sempre chama LLM injetando contexto temporal — nunca bloqueia resposta.';



COMMENT ON COLUMN "public"."copilot_agents"."handoff_notify_phones" IS 'WhatsApp numbers to notify when agent transfers conversation to human. Non-empty = feature active.';



COMMENT ON COLUMN "public"."copilot_agents"."handoff_notify_instructions" IS 'Natural language instructions for notification routing (e.g. "If order > R$5k, notify manager")';



COMMENT ON COLUMN "public"."copilot_agents"."can_send_document" IS 'Agent capability toggle: send documents/files from the knowledge base via WhatsApp (ENVIAR_DOCUMENTO tool).';



COMMENT ON COLUMN "public"."copilot_agents"."can_transfer_sz_chat" IS 'Agent capability toggle: transfer the conversation to an external SZ.Chat sector (TRANSFERIR_SZ_CHAT tool).';



COMMENT ON COLUMN "public"."copilot_agents"."finalized_at" IS 'NULL = Builder draft (in-progress, hidden from the main agents list, never default). Timestamp = finalized agent; is_active then toggles paused/active normally.';



COMMENT ON CONSTRAINT "copilot_agents_llm_model_allowlist" ON "public"."copilot_agents" IS 'Allowlist de modelos aprovados para Copilot v1. Adicionar modelo = nova migration.';



CREATE TABLE IF NOT EXISTS "public"."copilot_conversation_evaluations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "conversation_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "agent_id" "uuid",
    "lead_id" "uuid",
    "turn_count" integer DEFAULT 0 NOT NULL,
    "user_message" "text" NOT NULL,
    "agent_response" "text" NOT NULL,
    "score_relevance" numeric(3,1),
    "score_tone" numeric(3,1),
    "score_goal_align" numeric(3,1),
    "score_conciseness" numeric(3,1),
    "score_overall" numeric(3,1),
    "strengths" "text",
    "weaknesses" "text",
    "suggestion" "text",
    "model_used" "text" DEFAULT 'google/gemini-2.0-flash-001'::"text",
    "evaluated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "copilot_conversation_evaluations_score_conciseness_check" CHECK ((("score_conciseness" >= (0)::numeric) AND ("score_conciseness" <= (10)::numeric))),
    CONSTRAINT "copilot_conversation_evaluations_score_goal_align_check" CHECK ((("score_goal_align" >= (0)::numeric) AND ("score_goal_align" <= (10)::numeric))),
    CONSTRAINT "copilot_conversation_evaluations_score_overall_check" CHECK ((("score_overall" >= (0)::numeric) AND ("score_overall" <= (10)::numeric))),
    CONSTRAINT "copilot_conversation_evaluations_score_relevance_check" CHECK ((("score_relevance" >= (0)::numeric) AND ("score_relevance" <= (10)::numeric))),
    CONSTRAINT "copilot_conversation_evaluations_score_tone_check" CHECK ((("score_tone" >= (0)::numeric) AND ("score_tone" <= (10)::numeric)))
);


ALTER TABLE "public"."copilot_conversation_evaluations" OWNER TO "postgres";


COMMENT ON TABLE "public"."copilot_conversation_evaluations" IS 'Avaliações automáticas de qualidade de respostas do agente (LLM-as-a-judge). Score 0-10 por dimensão.';



