    "delay_minutes" integer DEFAULT 0 NOT NULL,
    "touch_count" integer,
    "spacing_hours" integer,
    "copy_override" "jsonb",
    "send_only_business_hours" boolean DEFAULT true NOT NULL,
    "business_hours_start" time without time zone DEFAULT '09:00:00'::time without time zone NOT NULL,
    "business_hours_end" time without time zone DEFAULT '18:00:00'::time without time zone NOT NULL,
    "send_days" "text"[] DEFAULT ARRAY['seg'::"text", 'ter'::"text", 'qua'::"text", 'qui'::"text", 'sex'::"text"] NOT NULL,
    "timezone" "text" DEFAULT 'America/Sao_Paulo'::"text" NOT NULL,
