);


ALTER TABLE "public"."copilot_followup_situation_config" OWNER TO "postgres";


COMMENT ON TABLE "public"."copilot_followup_situation_config" IS 'Per-Organization enable/disable + basics for the six canonical Follow-up Situations (ADR-0006). Overlays the Torque-curated catalog defaults.';



COMMENT ON COLUMN "public"."copilot_followup_situation_config"."trigger_stage_keys" IS 'Org-configured stage_keys (of the situation owning pipe) that place a Lead IN this situation. Stage keys are per-Organization; the trigger is never a hardcoded canonical key. Empty = situation never fires until configured.';



CREATE TABLE IF NOT EXISTS "public"."copilot_followup_step_log" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "rule_id" "uuid",
    "lead_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
