    "completed_reason" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone,
    "situation_config_id" "uuid",
    "completed_at" timestamp with time zone,
    CONSTRAINT "copilot_followup_step_log_completed_reason_check" CHECK (("completed_reason" = ANY (ARRAY['all_steps_done'::"text", 'lead_responded'::"text", 'manual_stop'::"text", 'human_replied'::"text", 'situation_resolved'::"text", 'owner_changed'::"text"]))),
    CONSTRAINT "copilot_followup_step_log_owner_check" CHECK (("num_nonnulls"("rule_id", "situation_config_id") = 1))
);


ALTER TABLE "public"."copilot_followup_step_log" OWNER TO "postgres";


COMMENT ON TABLE "public"."copilot_followup_step_log" IS 'Tracks execution progress of multi-step follow-up cadences per lead/rule pair.';



COMMENT ON COLUMN "public"."copilot_followup_step_log"."situation_config_id" IS 'Owning situation config for situation-based cadences (ADR-0006). Mutually exclusive with rule_id (legacy).';



