CREATE TABLE IF NOT EXISTS "public"."leads" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "company" "text",
    "email" "text",
    "phone" "text",
    "utm_campaign" "text",
    "utm_source" "text",
    "utm_medium" "text",
    "utm_content" "text",
    "utm_term" "text",
    "rating" integer DEFAULT 0,
    "faturamento" "text",
    "urgency" "text",
    "segment" "text",
    "sdr_id" "uuid",
    "closer_id" "uuid",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "compromisso_date" timestamp with time zone,
    "organization_id" "uuid",
    "pipe_whatsapp" "text" DEFAULT 'novo'::"text",
    "normalized_phone" "text",
    "ai_disabled" boolean DEFAULT false,
    "ai_disabled_at" timestamp with time zone,
    "ai_disabled_by" "uuid",
    "metrics_period_at" timestamp with time zone,
    "origin" "text",
    "is_shadow" boolean DEFAULT false,
    "qualification_score" integer DEFAULT 0,
    "responsible_id" "uuid",
    "meta_campaign_id" "text",
    "meta_adset_id" "text",
    "meta_ad_id" "text",
    "pre_sale_responsible_id" "uuid",
    "sale_responsible_id" "uuid",
    "contact_id" "uuid",
    "company_entity_id" "uuid",
    "import_batch_id" "uuid",
    "responsible_user_id" "uuid",
    "phone_digits" "text" GENERATED ALWAYS AS ("regexp_replace"(COALESCE("phone", ''::"text"), '[^0-9]'::"text", ''::"text", 'g'::"text")) STORED,
    "deleted_at" timestamp with time zone,
    "deleted_by" "uuid",
    "avatar_url" "text",
    "pre_qualification_tier" "public"."qualification_tier",
    "qualification_tier" "public"."qualification_tier",
    "uf" character(2),
    "uf_source" "text",
    "meta_lead_id" "text",
    "excluded_from_metrics" boolean DEFAULT false NOT NULL,
    CONSTRAINT "leads_qualification_score_check" CHECK ((("qualification_score" >= 0) AND ("qualification_score" <= 100))),
    CONSTRAINT "leads_rating_check" CHECK ((("rating" >= 0) AND ("rating" <= 10))),
    CONSTRAINT "leads_uf_check" CHECK ((("uf" IS NULL) OR ("uf" = ANY (ARRAY['AC'::"bpchar", 'AL'::"bpchar", 'AP'::"bpchar", 'AM'::"bpchar", 'BA'::"bpchar", 'CE'::"bpchar", 'DF'::"bpchar", 'ES'::"bpchar", 'GO'::"bpchar", 'MA'::"bpchar", 'MT'::"bpchar", 'MS'::"bpchar", 'MG'::"bpchar", 'PA'::"bpchar", 'PB'::"bpchar", 'PR'::"bpchar", 'PE'::"bpchar", 'PI'::"bpchar", 'RJ'::"bpchar", 'RN'::"bpchar", 'RS'::"bpchar", 'RO'::"bpchar", 'RR'::"bpchar", 'SC'::"bpchar", 'SE'::"bpchar", 'SP'::"bpchar", 'TO'::"bpchar"])))),
    CONSTRAINT "leads_uf_source_check" CHECK ((("uf_source" IS NULL) OR ("uf_source" = ANY (ARRAY['manual'::"text", 'webhook'::"text", 'ddd'::"text", 'ai'::"text"]))))
)
WITH ("autovacuum_vacuum_scale_factor"='0.05', "autovacuum_analyze_scale_factor"='0.05');


ALTER TABLE "public"."leads" OWNER TO "postgres";


COMMENT ON COLUMN "public"."leads"."pipe_whatsapp" IS 'Estágio do lead no funil WhatsApp (TEXT dinâmico — validado contra pipeline_stages)';



COMMENT ON COLUMN "public"."leads"."ai_disabled" IS 'Se true, o Copilot não responde mensagens deste lead';



COMMENT ON COLUMN "public"."leads"."ai_disabled_at" IS 'Data/hora em que a IA foi desabilitada para este lead';



COMMENT ON COLUMN "public"."leads"."ai_disabled_by" IS 'Usuário que desabilitou a IA para este lead';



COMMENT ON COLUMN "public"."leads"."metrics_period_at" IS 'Quando preenchido, usado no lugar de created_at para filtrar por período nas métricas (ex: leads antigos importados)';



COMMENT ON COLUMN "public"."leads"."origin" IS 'Origem do lead: whatsapp, meta_ads, outro, site, remarketing, google_ads, cal (Cal.com).';



COMMENT ON COLUMN "public"."leads"."is_shadow" IS 'Shadow lead: criado automaticamente pelo copilot, invisível nos pipes até ser promovido';



COMMENT ON COLUMN "public"."leads"."qualification_score" IS 'Score de qualificação de 0 a 100, atualizado pelo copilot conforme coleta informações do lead.';



COMMENT ON COLUMN "public"."leads"."responsible_user_id" IS 'Responsável definitivo do lead (team_member). Usado para resolver instância de escrita. Backfill: COALESCE(closer_id, sdr_id).';



COMMENT ON COLUMN "public"."leads"."excluded_from_metrics" IS 'Fora das métricas de aquisição de lead (Dashboard totalLeads/funil/taxa de conversão). Setado por import-leads destination=custom_pipeline em leads criados pelo import — clientes de base, não leads novos.';



CREATE OR REPLACE VIEW "public"."leads_compat" WITH ("security_invoker"='on') AS
 SELECT "l"."id",
    "l"."name",
    "l"."company",
    "l"."email",
    "l"."phone",
    "l"."utm_campaign",
    "l"."utm_source",
    "l"."utm_medium",
    "l"."utm_content",
    "l"."utm_term",
    "l"."rating",
    "l"."faturamento",
    "l"."urgency",
    "l"."segment",
    "l"."sdr_id",
    "l"."closer_id",
    "l"."notes",
    "l"."created_at",
    "l"."updated_at",
    "l"."compromisso_date",
    "l"."organization_id",
    "l"."pipe_whatsapp",
    "l"."normalized_phone",
    "l"."ai_disabled",
    "l"."ai_disabled_at",
    "l"."ai_disabled_by",
    "l"."metrics_period_at",
    "l"."origin",
    "l"."is_shadow",
    "l"."qualification_score",
    "l"."responsible_id",
    "l"."meta_campaign_id",
    "l"."meta_adset_id",
    "l"."meta_ad_id",
    "l"."pre_sale_responsible_id",
    "l"."sale_responsible_id",
    "l"."contact_id",
    "l"."company_entity_id",
    "c"."job_title" AS "contact_job_title",
    "c"."linkedin_url" AS "contact_linkedin",
    "co"."domain" AS "company_domain",
    "co"."industry" AS "company_industry",
    "co"."size_range" AS "company_size",
    "co"."revenue_range" AS "company_revenue",
    "co"."website" AS "company_website"
   FROM (("public"."leads" "l"
     LEFT JOIN "public"."contacts" "c" ON (("l"."contact_id" = "c"."id")))
     LEFT JOIN "public"."companies" "co" ON (("l"."company_entity_id" = "co"."id")))
  WHERE ("l"."deleted_at" IS NULL);


ALTER VIEW "public"."leads_compat" OWNER TO "postgres";


