CREATE OR REPLACE VIEW "public"."org_visible_members" WITH ("security_invoker"='true') AS
 SELECT "id",
    "user_id",
    "name",
    "role",
    "ote_base",
    "ote_bonus",
    "commission_mrr_percent",
    "commission_projeto_percent",
    "is_active",
    "created_at",
    "updated_at",
    "email",
    "organization_id",
    "job_title",
    "metric_type"
   FROM "public"."team_members" "tm"
  WHERE (NOT (EXISTS ( SELECT 1
           FROM "public"."master_users" "mu"
          WHERE (("mu"."user_id" = "tm"."user_id") AND ("mu"."is_active" = true)))));


