    "subscription_expires_at" timestamp with time zone,
    "payment_customer_id" "text",
    "payment_subscription_id" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "whatsapp_rate_limit" "jsonb" DEFAULT '{"max_per_day": 500, "delay_max_ms": 90000, "delay_min_ms": 30000, "max_per_hour": 100}'::"jsonb",
    "plan_id" "uuid",
    "billing_override" boolean DEFAULT false,
    "billing_override_reason" "text",
    "billing_override_by" "uuid",
    "billing_override_at" timestamp with time zone,
    "user_creation_key" "uuid" DEFAULT "gen_random_uuid"(),
    "confirmacao_overdue_days" integer DEFAULT 5 NOT NULL,
    "limit_overrides" "jsonb" DEFAULT '{}'::"jsonb",
    "org_type" "public"."org_type" DEFAULT 'crm'::"public"."org_type" NOT NULL,
    "elevenlabs_api_key" "text",
    "whatsapp_provider_override" "text",
    "whatsapp_migration_status" "text" DEFAULT 'not_started'::"text" NOT NULL,
    "whatsapp_migration_completed_at" timestamp with time zone,
    "copilot_engine_version" "text" DEFAULT 'v1'::"text" NOT NULL,
    "is_sandbox" boolean DEFAULT false NOT NULL,
    "sandbox_source_org_id" "uuid",
    "sandbox_created_at" timestamp with time zone,
    "capture_groups" boolean DEFAULT true NOT NULL,
    "onboarding_state" "text" DEFAULT 'completed'::"text" NOT NULL,
    "onboarding_completed_at" timestamp with time zone,
    "onboarding_answers" "jsonb",
    "feature_flags" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "default_reorder_cycle_days" integer,
    "quick_blast_max_leads" integer DEFAULT 200 NOT NULL,
    "daily_blast_budget" integer DEFAULT 200 NOT NULL,
    "timezone" "text" DEFAULT 'America/Sao_Paulo'::"text" NOT NULL,
    "auto_create_lead_on_inbound" boolean DEFAULT false NOT NULL,
    "send_governor_mode" "text" DEFAULT 'off'::"text" NOT NULL,
    "send_governor_warmup_enabled" boolean DEFAULT false NOT NULL,
    "send_governor_cold_gate_enabled" boolean DEFAULT false NOT NULL,
    CONSTRAINT "organizations_copilot_engine_version_check" CHECK (("copilot_engine_version" = ANY (ARRAY['v1'::"text", 'v2'::"text"]))),
    CONSTRAINT "organizations_onboarding_state_check" CHECK (("onboarding_state" = ANY (ARRAY['pending_whatsapp'::"text", 'pending_profile'::"text", 'pending_pipelines'::"text", 'pending_automations'::"text", 'completed'::"text"]))),
    CONSTRAINT "organizations_send_governor_mode_check" CHECK (("send_governor_mode" = ANY (ARRAY['off'::"text", 'shadow'::"text", 'enforce'::"text"]))),
    CONSTRAINT "organizations_subscription_plan_check" CHECK ((("subscription_plan" IS NULL) OR ("subscription_plan" = ANY (ARRAY['basic'::"text", 'free'::"text", 'starter'::"text", 'pro'::"text", 'enterprise'::"text", 'torque-1.0'::"text", 'torque-2.0'::"text", 'torque-v8'::"text"])))),
    CONSTRAINT "organizations_subscription_status_check" CHECK (("subscription_status" = ANY (ARRAY['trial'::"text", 'active'::"text", 'overdue'::"text", 'suspended'::"text", 'cancelled'::"text", 'expired'::"text"]))),
    CONSTRAINT "organizations_whatsapp_migration_status_check" CHECK (("whatsapp_migration_status" = ANY (ARRAY['not_started'::"text", 'pending'::"text", 'in_progress'::"text", 'migrated'::"text", 'failed'::"text"]))),
    CONSTRAINT "organizations_whatsapp_provider_override_check" CHECK ((("whatsapp_provider_override" IS NULL) OR ("whatsapp_provider_override" = ANY (ARRAY['uazapi'::"text", 'evolution'::"text"]))))
);


ALTER TABLE "public"."organizations" OWNER TO "postgres";


COMMENT ON TABLE "public"."organizations" IS 'Organizações/Tenants do sistema SaaS';



COMMENT ON COLUMN "public"."organizations"."subscription_status" IS 'Estado da assinatura: trial | active | overdue | suspended | cancelled | expired';



COMMENT ON COLUMN "public"."organizations"."subscription_plan" IS 'Plano: free, starter, pro, enterprise (alinhado a subscription_plans.name)';



COMMENT ON COLUMN "public"."organizations"."whatsapp_rate_limit" IS 'Limites de envio WhatsApp: max_per_hour, max_per_day, delay_min_ms (mínimo entre msgs), delay_max_ms (máximo entre msgs)';



COMMENT ON COLUMN "public"."organizations"."confirmacao_overdue_days" IS 'Dias sem interação (updated_at) no pipe de confirmação para marcar como atrasado. Default 5.';



COMMENT ON COLUMN "public"."organizations"."limit_overrides" IS 'Override de limites por org: {"max_leads": 500, ...}. -1 = ilimitado.';



COMMENT ON COLUMN "public"."organizations"."whatsapp_provider_override" IS 'Override do provider WhatsApp (panic switch). NULL = usa whatsapp_instances.provider.';



COMMENT ON COLUMN "public"."organizations"."whatsapp_migration_status" IS 'Status migração Evolution→Uazapi: not_started | pending | in_progress | migrated | failed.';



COMMENT ON COLUMN "public"."organizations"."whatsapp_migration_completed_at" IS 'Timestamp de conclusão da migração. Usado em auditoria + admin dashboard.';



COMMENT ON COLUMN "public"."organizations"."copilot_engine_version" IS 'Trilha 3.B B3: roteia agent-message entre engine v1 (orchestrator atual) e v2 (módulos refatorados). Default v1.';



COMMENT ON COLUMN "public"."organizations"."capture_groups" IS 'When false, whatsapp-webhook drops group messages on the floor (legacy pre-BL-WA-05 behavior). Default true.';



COMMENT ON COLUMN "public"."organizations"."feature_flags" IS 'Toggles de feature por org. Keys snake_case, valores boolean. Estritamente `true` ativa (hook useFeatureFlag). Independente do par feature_flags/organization_features (definições globais + overrides). Usado pra rollout gradual sem deploy (ex: new_lead_modal_v2 do PRD #284).';



COMMENT ON COLUMN "public"."organizations"."default_reorder_cycle_days" IS 'Default reorder cycle in days for new clients with < 2 orders. NULL = system default (30d).';



COMMENT ON COLUMN "public"."organizations"."quick_blast_max_leads" IS 'Max leads per Quick Blast (Disparo Rapido). Server-enforced safety ceiling - ADR-0002. Default 200.';



COMMENT ON COLUMN "public"."organizations"."daily_blast_budget" IS 'Org-wide Mass Send daily ceiling: max Leads messaged via blast per calendar day (America/Sao_Paulo), summed across every blast. Server-enforced, fail-closed — ADR-0003. Default 200.';



COMMENT ON COLUMN "public"."organizations"."timezone" IS 'IANA timezone of the org (ADR-0017 §5). Every Metric Period is cut in this zone, exclusively by the database (metric_period_bounds). Validated against pg_timezone_names on write.';



COMMENT ON COLUMN "public"."organizations"."auto_create_lead_on_inbound" IS 'Se true, mensagens inbound de WhatsApp de telefones desconhecidos criam lead automaticamente (funil WhatsApp / etapa novo / sem dono), mesmo sem IA ativa ou quando attend_unknown_contacts=false barra a resposta. Default false = comportamento legado (não cria lead sozinho). Lida por agent-message (service_role, bypassa RLS); escrita por admin/owner/master via UI.';



COMMENT ON COLUMN "public"."organizations"."send_governor_mode" IS 'Send Governor mode: off (inert/allow all) | shadow (evaluate + log, never block) | enforce (apply decision). Default off. PR-0 wires shadow only.';



COMMENT ON COLUMN "public"."organizations"."send_governor_warmup_enabled" IS 'When true, the governor tightens the per-number automation cap by a warm-up ramp derived from the number age (P2). Default false.';



COMMENT ON COLUMN "public"."organizations"."send_governor_cold_gate_enabled" IS 'When true, the governor blocks automation to cold contacts (no prior inbound message + no opt-in) under enforce (P4). Default false.';



