COMMENT ON TABLE "public"."password_reset_tokens" IS 'Self-hosted password reset tokens (hash-only). RLS deny-all by design: no policies, no anon/authenticated grants — only service_role (RLS bypass) via the forgot-password/reset-password edge functions. Raw token never stored.';



CREATE TABLE IF NOT EXISTS "public"."payment_history" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "asaas_payment_id" "text",
    "asaas_subscription_id" "text",
    "amount" numeric NOT NULL,
    "discount_applied" numeric DEFAULT 0 NOT NULL,
    "coupon_id" "uuid",
    "billing_cycle" "text" NOT NULL,
    "status" "text" NOT NULL,
    "paid_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
