    "template_id" "uuid",
    "delay_minutes" integer DEFAULT 0 NOT NULL,
    "position" integer DEFAULT 0 NOT NULL,
    "wait_timeout_minutes" integer DEFAULT 1440,
    "timeout_action" "text" DEFAULT 'continue'::"text",
    "timeout_target_stage_id" "uuid",
    "timeout_template_id" "uuid",
    "target_stage_id" "uuid",
    "sdr_assignment_mode" "text" DEFAULT 'specific'::"text",
    "target_sdr_id" "uuid",
    CONSTRAINT "chk_pipe_step_stage_required" CHECK ((("action_type" <> 'change_stage'::"text") OR ("target_stage_id" IS NOT NULL))),
    CONSTRAINT "chk_pipe_step_template_required" CHECK ((("action_type" <> 'send_template'::"text") OR ("template_id" IS NOT NULL))),
    CONSTRAINT "pipe_dispatch_rule_steps_action_type_check" CHECK (("action_type" = ANY (ARRAY['send_template'::"text", 'wait_response'::"text", 'change_stage'::"text", 'assign_sdr'::"text", 'cancel_sequence'::"text"]))),
    CONSTRAINT "pipe_dispatch_rule_steps_delay_minutes_check" CHECK (("delay_minutes" >= 0)),
    CONSTRAINT "pipe_dispatch_rule_steps_sdr_assignment_mode_check" CHECK ((("sdr_assignment_mode" IS NULL) OR ("sdr_assignment_mode" = ANY (ARRAY['specific'::"text", 'round_robin'::"text"])))),
    CONSTRAINT "pipe_dispatch_rule_steps_timeout_action_check" CHECK ((("timeout_action" IS NULL) OR ("timeout_action" = ANY (ARRAY['continue'::"text", 'change_stage'::"text", 'send_template'::"text", 'cancel_sequence'::"text"]))))
);


