    CONSTRAINT "pipeline_stage_events_real_transition" CHECK (("from_stage_key" IS DISTINCT FROM "to_stage_key")),
    CONSTRAINT "pipeline_stage_events_source_check" CHECK (("source" = ANY (ARRAY['trigger'::"text", 'backfill'::"text"])))
);


