COMMENT ON TABLE "public"."pipeline_stage_events" IS 'ADR-0017 / #992 — caderno append-only de transições de stage_key em pipeline_entries. Fonte ÚNICA de métricas de funil (SP-3). Nunca sofre UPDATE/DELETE (trigger de imutabilidade); correção = evento novo.';



CREATE TABLE IF NOT EXISTS "public"."pipeline_stages" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid",
    "pipeline_type" "text" NOT NULL,
    "stage_key" "text" NOT NULL,
    "name" "text" NOT NULL,
    "color" "text" DEFAULT '#64748b'::"text",
    "position" integer DEFAULT 0 NOT NULL,
    "is_active" boolean DEFAULT true,
    "is_final_positive" boolean DEFAULT false,
    "is_final_negative" boolean DEFAULT false,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "auto_move_min_days" integer,
    "auto_move_max_days" integer,
    "target_pipe_type" "text",
    "target_stage_key" "text",
    "default_probability" integer DEFAULT 50,
    "sla_hours" integer,
    "sla_action" "text",
    "sla_escalate_to" "uuid",
    "max_days_in_stage" integer,
    "checklist_template_id" "uuid",
    "target_pipeline_id" "uuid",
    "target_stage_id" "uuid",
    "stage_role" "public"."stage_role" DEFAULT 'open'::"public"."stage_role" NOT NULL,
    "suggested_stage_role" "public"."stage_role",
    "stage_role_suggested_at" timestamp with time zone,
    "stage_role_suggestion_source" "text",
    "stage_role_reviewed_at" timestamp with time zone,
    "stage_role_reviewed_by" "uuid",
    CONSTRAINT "chk_pipeline_stages_target_exclusive" CHECK ((NOT (("target_pipeline_id" IS NOT NULL) AND ("target_pipe_type" IS NOT NULL)))),
    CONSTRAINT "pipeline_stages_default_probability_check" CHECK ((("default_probability" >= 0) AND ("default_probability" <= 100))),
    CONSTRAINT "pipeline_stages_pipeline_type_check" CHECK (("pipeline_type" = ANY (ARRAY['whatsapp'::"text", 'confirmacao'::"text", 'propostas'::"text", 'upsell_base'::"text", 'upsell_gestao'::"text"]))),
    CONSTRAINT "pipeline_stages_sla_action_check" CHECK (("sla_action" = ANY (ARRAY['notify'::"text", 'escalate'::"text", 'auto_move'::"text", 'create_followup'::"text"]))),
    CONSTRAINT "pipeline_stages_suggested_role_not_open" CHECK (("suggested_stage_role" IS DISTINCT FROM 'open'::"public"."stage_role")),
    CONSTRAINT "pipeline_stages_suggestion_source_valid" CHECK ((("stage_role_suggestion_source" IS NULL) OR ("stage_role_suggestion_source" = ANY (ARRAY['deterministic'::"text", 'ai'::"text", 'flag'::"text"]))))
);


ALTER TABLE "public"."pipeline_stages" OWNER TO "postgres";


COMMENT ON COLUMN "public"."pipeline_stages"."max_days_in_stage" IS 'Maximum days a card should stay in this stage before being flagged as stagnant. NULL = no limit.';



COMMENT ON COLUMN "public"."pipeline_stages"."stage_role" IS 'ADR-0017 §1 — papel semântico governado da etapa. Único input de etapa válido para métricas. Renomear a etapa (name) NUNCA altera o role. is_final_positive/is_final_negative são UI-only.';



COMMENT ON COLUMN "public"."pipeline_stages"."suggested_stage_role" IS '#991 / ADR-0017 §1 — sugestão PENDENTE do Stage Role Classifier. Só won/lost persistem aqui (meeting_* auto-aplicam em stage_role). Limpa na revisão humana. NUNCA é input de métrica.';



