CREATE OR REPLACE VIEW "public"."portfolio_retention_cohorts" WITH ("security_invoker"='on') AS
 WITH "cohort_base" AS (
         SELECT "c"."id" AS "client_id",
            "c"."organization_id",
            "c"."closer_id",
            "c"."segment",
            "date_trunc"('month'::"text", "c"."first_sale_at") AS "cohort_month",
            "c"."first_sale_at"
           FROM "public"."upsell_clients" "c"
          WHERE (("c"."is_active" = true) AND ("c"."first_sale_at" IS NOT NULL))
        ), "months" AS (
         SELECT "generate_series"(0, 11) AS "month_offset"
        ), "cohort_orders" AS (
         SELECT "cb"."client_id",
            "cb"."organization_id",
            "cb"."cohort_month",
            "cb"."closer_id",
            "cb"."segment",
            "m"."month_offset",
            (EXISTS ( SELECT 1
                   FROM "public"."upsell_orders" "o"
                  WHERE (("o"."client_id" = "cb"."client_id") AND ("date_trunc"('month'::"text", "o"."sold_at") = ("cb"."cohort_month" + (("m"."month_offset" || ' months'::"text"))::interval)) AND ("o"."approval_status" = 'approved'::"text")))) AS "had_order"
           FROM ("cohort_base" "cb"
             CROSS JOIN "months" "m")
          WHERE (("cb"."cohort_month" + (("m"."month_offset" || ' months'::"text"))::interval) <= "date_trunc"('month'::"text", "now"()))
        )
 SELECT "organization_id",
    "cohort_month",
    "closer_id",
    "segment",
    "month_offset",
    "count"(DISTINCT "client_id") FILTER (WHERE "had_order") AS "active_clients",
    "count"(DISTINCT "client_id") AS "total_clients",
    "round"(((("count"(DISTINCT "client_id") FILTER (WHERE "had_order"))::numeric / (NULLIF("count"(DISTINCT "client_id"), 0))::numeric) * (100)::numeric)) AS "retention_pct"
   FROM "cohort_orders"
  GROUP BY "organization_id", "cohort_month", "closer_id", "segment", "month_offset";


ALTER VIEW "public"."portfolio_retention_cohorts" OWNER TO "postgres";


