COMMENT ON COLUMN "public"."runtime_logs"."duration_ms" IS 'Onda 2: latência da operação em ms. Populado por logRuntime quando aplicável.';



COMMENT ON COLUMN "public"."runtime_logs"."prompt_tokens" IS 'Onda 2: tokens consumidos no prompt LLM (custo).';



COMMENT ON COLUMN "public"."runtime_logs"."completion_tokens" IS 'Onda 2: tokens gerados pelo LLM (custo).';



