COMMENT ON COLUMN "public"."subscription_plans"."discount_annual_pct" IS 'Desconto (%) para ciclo anual';



COMMENT ON COLUMN "public"."subscription_plans"."discount_volume_pct" IS 'Desconto (%) de volume quando ≥ discount_volume_min usuários';



COMMENT ON COLUMN "public"."subscription_plans"."discount_volume_min" IS 'Número mínimo de usuários para ativar desconto de volume';



CREATE TABLE IF NOT EXISTS "public"."support_ticket_attachments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "ticket_id" "uuid" NOT NULL,
    "comment_id" "uuid",
    "path" "text" NOT NULL,
    "filename" "text" NOT NULL,
    "mime" "text" NOT NULL,
    "size_bytes" bigint NOT NULL,
    "is_internal" boolean DEFAULT false NOT NULL,
    "author_user_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "purged_at" timestamp with time zone,
    CONSTRAINT "support_ticket_attachments_filename_check" CHECK (("length"("btrim"("filename")) > 0)),
    CONSTRAINT "support_ticket_attachments_filename_check1" CHECK (("length"("filename") <= 200)),
    CONSTRAINT "support_ticket_attachments_filename_check2" CHECK (("filename" !~ '[[:cntrl:]]'::"text")),
    CONSTRAINT "support_ticket_attachments_filename_check3" CHECK (("filename" !~ '[‎‏‪-‮⁦-⁩]'::"text")),
    CONSTRAINT "support_ticket_attachments_size_bytes_check" CHECK ((("size_bytes" > 0) AND ("size_bytes" <= 26214400)))
);


ALTER TABLE "public"."support_ticket_attachments" OWNER TO "postgres";


COMMENT ON TABLE "public"."support_ticket_attachments" IS 'Anexo de um Chamado. Pende do Comentario; comment_id NULL = veio na abertura. Ver ADR-0022.';



COMMENT ON COLUMN "public"."support_ticket_attachments"."path" IS 'Caminho no bucket. Autorizacao deriva daqui: 1o segmento e o Chamado, 2o segmento internal exige master.';



COMMENT ON COLUMN "public"."support_ticket_attachments"."filename" IS 'Nome original, cru. Nunca entra no caminho: la ele viajaria na URL assinada e nos logs do Storage.';



COMMENT ON COLUMN "public"."support_ticket_attachments"."author_user_id" IS 'Nullable: o anexo pertence ao Chamado e sobrevive ao autor, como o proprio Chamado.';



COMMENT ON COLUMN "public"."support_ticket_attachments"."purged_at" IS 'Quando a retencao levou o arquivo. A linha sobrevive: a thread mostra que houve evidencia e que ela expirou.';



CREATE TABLE IF NOT EXISTS "public"."support_ticket_comments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "ticket_id" "uuid" NOT NULL,
    "author_user_id" "uuid",
    "body" "text" NOT NULL,
    "is_internal" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "from_staff" boolean DEFAULT false NOT NULL,
    CONSTRAINT "support_ticket_comments_body_check" CHECK (("length"("btrim"("body")) > 0)),
    CONSTRAINT "support_ticket_comments_internal_implies_staff" CHECK (((NOT "is_internal") OR "from_staff"))
);


ALTER TABLE "public"."support_ticket_comments" OWNER TO "postgres";


COMMENT ON TABLE "public"."support_ticket_comments" IS 'Comentario de um Chamado. NAO e Message: Message e unidade de WhatsApp/Meta dentro de uma Conversation.';



COMMENT ON COLUMN "public"."support_ticket_comments"."is_internal" IS 'Nota do staff, invisivel para a Organizacao. Filtrada na policy, nunca no frontend.';



COMMENT ON COLUMN "public"."support_ticket_comments"."from_staff" IS 'True = escrito pelo suporte da Torque (console master). False = mensagem da Organização (painel do cliente). Carimba a ORIGEM, não a identidade do autor — um master escreve dos dois lados.';



CREATE TABLE IF NOT EXISTS "public"."support_tickets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "author_user_id" "uuid",
    "title" "text" NOT NULL,
    "description" "text",
    "tipo" "public"."support_ticket_tipo" NOT NULL,
    "impacto" "public"."support_ticket_impacto" NOT NULL,
    "severidade" "public"."support_ticket_severidade",
    "status" "public"."support_ticket_status" DEFAULT 'aberto'::"public"."support_ticket_status" NOT NULL,
    "assigned_master_user_id" "uuid",
    "defect_url" "text",
    "support_context" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "first_response_at" timestamp with time zone,
    "resolved_at" timestamp with time zone,
    "awaiting_since" timestamp with time zone,
    "awaiting_customer_ms" bigint DEFAULT 0 NOT NULL,
    "reopen_count" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "author_gestor_id" "uuid",
    "closed_at" timestamp with time zone,
    CONSTRAINT "support_tickets_awaiting_customer_ms_check" CHECK (("awaiting_customer_ms" >= 0)),
    CONSTRAINT "support_tickets_reopen_count_check" CHECK (("reopen_count" >= 0)),
    CONSTRAINT "support_tickets_title_check" CHECK ((("length"("btrim"("title")) >= 3) AND ("length"("btrim"("title")) <= 200)))
);


ALTER TABLE "public"."support_tickets" OWNER TO "postgres";


COMMENT ON TABLE "public"."support_tickets" IS 'Chamado: pedido de ajuda de uma Organizacao para o suporte da Torque. Ver ADR-0018.';



COMMENT ON COLUMN "public"."support_tickets"."author_user_id" IS 'Nullable: o Chamado pertence a Organizacao e sobrevive ao autor.';



COMMENT ON COLUMN "public"."support_tickets"."tipo" IS 'Mutavel: e a saida da triagem, nao um fato da abertura.';



COMMENT ON COLUMN "public"."support_tickets"."impacto" IS 'Declarado pelo usuario. Ele sabe se esta parado; nao sabe se e critico.';



COMMENT ON COLUMN "public"."support_tickets"."severidade" IS 'Veredito do staff. Nulo ate a triagem. Cliente nunca escreve.';



COMMENT ON COLUMN "public"."support_tickets"."defect_url" IS 'Issue do GitHub. Contar chamados por esta URL torna severidade uma medida.';



COMMENT ON COLUMN "public"."support_tickets"."support_context" IS 'Snapshot imutavel: rota, versao, browser, erros de cliente, session_id.';



COMMENT ON COLUMN "public"."support_tickets"."author_gestor_id" IS 'Marcador de autor-gestor (ADR-0021 §9). NULL = autor normal (Team Member). Setado = o Chamado foi aberto por este Gestor de Portfólio, sempre ancorado a uma org vinculada. Staff da Torque exibe selo "Gestor".';



COMMENT ON COLUMN "public"."support_tickets"."closed_at" IS 'Quando o chamado foi fechado. Marco da retencao de anexos (ADR-0022, 9).';



