CREATE OR REPLACE VIEW "public"."unified_inbox_messages" WITH ("security_invoker"='on') AS
 SELECT "cm"."id",
    "cm"."organization_id",
    "cm"."lead_id",
    "cm"."channel",
    "cm"."direction",
    "cm"."content",
    "cm"."media_url",
    "cm"."message_type",
    "cm"."sender_name",
    "cm"."sender_profile_pic",
    "cm"."timestamp" AS "sent_at",
    "cm"."phone_number",
    NULL::"uuid" AS "email_id",
    "cm"."external_id" AS "external_ref"
   FROM "public"."channel_messages" "cm"
UNION ALL
 SELECT "e"."id",
    "e"."organization_id",
    "e"."lead_id",
    'email'::"public"."channel_type" AS "channel",
        CASE
            WHEN "e"."is_outbound" THEN 'outbound'::"text"
            ELSE 'inbound'::"text"
        END AS "direction",
    COALESCE("e"."snippet", "left"("e"."body_text", 200)) AS "content",
    NULL::"text" AS "media_url",
    'text'::"text" AS "message_type",
    COALESCE("e"."from_name", "e"."from_address") AS "sender_name",
    NULL::"text" AS "sender_profile_pic",
    "e"."sent_at",
    NULL::"text" AS "phone_number",
    "e"."id" AS "email_id",
    "e"."message_id" AS "external_ref"
   FROM "public"."emails" "e";


ALTER VIEW "public"."unified_inbox_messages" OWNER TO "postgres";


