CREATE OR REPLACE VIEW "public"."v_cron_job_status" WITH ("security_invoker"='on') AS
 SELECT "j"."jobname",
    "j"."schedule",
    "j"."active",
    "jrd"."status" AS "last_status",
    "jrd"."return_message" AS "last_message",
    "jrd"."start_time" AS "last_run_at",
    ("jrd"."end_time" - "jrd"."start_time") AS "last_duration",
        CASE
            WHEN ("j"."schedule" = '* * * * *'::"text") THEN 'every 1 min'::"text"
            WHEN ("j"."schedule" = '*/2 * * * *'::"text") THEN 'every 2 min'::"text"
            WHEN ("j"."schedule" = '*/5 * * * *'::"text") THEN 'every 5 min'::"text"
            WHEN ("j"."schedule" ~~ '0 % * * *'::"text") THEN 'daily'::"text"
            ELSE "j"."schedule"
        END AS "frequency_label",
    (EXTRACT(epoch FROM ("now"() - "jrd"."start_time")) / (60)::numeric) AS "minutes_since_last_run"
   FROM ("cron"."job" "j"
     LEFT JOIN LATERAL ( SELECT "job_run_details"."status",
            "job_run_details"."return_message",
            "job_run_details"."start_time",
            "job_run_details"."end_time"
           FROM "cron"."job_run_details"
          WHERE ("job_run_details"."jobid" = "j"."jobid")
          ORDER BY "job_run_details"."start_time" DESC
         LIMIT 1) "jrd" ON (true))
  ORDER BY "j"."jobname";


ALTER VIEW "public"."v_cron_job_status" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_cron_job_status" IS 'Quick diagnostic: last run status and timing for every pg_cron job. Query this to debug a stuck job: SELECT * FROM v_cron_job_status WHERE jobname = ''name'';';



