COMMENT ON COLUMN "public"."whatsapp_messages"."processed_by_agent_at" IS 'Timestamp when this message was processed by the AI agent. NULL = not processed yet. Used for message batching - multiple messages from the same lead are grouped and processed together.';



COMMENT ON COLUMN "public"."whatsapp_messages"."assigned_to" IS 'Usuário responsável por esta mensagem/conversa. NULL = não atribuído (visível para todos). Admins veem todas as mensagens.';



COMMENT ON COLUMN "public"."whatsapp_messages"."search_tsv" IS 'Generated tsvector para full-text search em português. Derivado de content. Atualizado automaticamente em INSERT/UPDATE. Indexado via GIN (idx_whatsapp_messages_search_tsv). Consumido por RPC search_messages.';



COMMENT ON COLUMN "public"."whatsapp_messages"."reactions" IS 'Array of { emoji: string, from: "me" | "them", count: number }. Updated by whatsapp-webhook messages_update handler.';



COMMENT ON COLUMN "public"."whatsapp_messages"."edited" IS 'True when sender edited the message via provider. Set by webhook messages_update.';



COMMENT ON COLUMN "public"."whatsapp_messages"."pinned_at" IS 'When the message was pinned in the chat. Null = not pinned.';



COMMENT ON COLUMN "public"."whatsapp_messages"."deleted_at" IS 'When the message was deleted for all. UI should render strikethrough or placeholder.';



COMMENT ON COLUMN "public"."whatsapp_messages"."received_via" IS 'Which writer produced this row. webhook (default), history_sync, dlq_replay, manual_replay. No CHECK so new recovery paths do not require migrations.';



COMMENT ON COLUMN "public"."whatsapp_messages"."is_group" IS 'True when this message was sent in a WhatsApp group (remote_jid ends in @g.us). Lead creation, agent-message dispatch and pipeline upserts must skip rows where is_group = true.';



COMMENT ON COLUMN "public"."whatsapp_messages"."media_expired" IS 'True when the message''s media was purged by the 30-day retention job. media_url is set NULL at the same time. Chat UI renders a graceful expired state.';



CREATE TABLE IF NOT EXISTS "public"."whatsapp_rate_tracking" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "instance_id" "uuid",
    "hour_key" "text" NOT NULL,
    "day_key" "text" NOT NULL,
    "messages_this_hour" integer DEFAULT 0,
    "messages_this_day" integer DEFAULT 0,
    "last_message_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"()
);


ALTER TABLE "public"."whatsapp_rate_tracking" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."whatsapp_webhook_dlq" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "received_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "source_ip" "text",
    "url_path" "text",
    "event" "text",
    "reason" "text" NOT NULL,
    "payload" "jsonb" NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "last_attempt_at" timestamp with time zone,
    "last_error" "text",
    "resolved_at" timestamp with time zone,
    "resolved_instance_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
)
WITH ("autovacuum_vacuum_scale_factor"='0.05', "autovacuum_analyze_scale_factor"='0.05');


ALTER TABLE "public"."whatsapp_webhook_dlq" OWNER TO "postgres";


COMMENT ON TABLE "public"."whatsapp_webhook_dlq" IS 'Dead letter queue for Uazapi webhook events that failed initial processing. Replayed every 5 minutes by whatsapp-dlq-replay. service_role only.';



COMMENT ON COLUMN "public"."whatsapp_webhook_dlq"."reason" IS 'Why the event was queued. Allowed values include: missing_instance, unknown_instance, parse_error, downstream_error. Free-form text � no CHECK constraint so the producer can add new reasons without migrations.';



COMMENT ON COLUMN "public"."whatsapp_webhook_dlq"."attempts" IS 'Number of replay attempts. 5 attempts ? Sentry critical + manual review.';



CREATE TABLE IF NOT EXISTS "public"."workflow_execution_steps" (
