CREATE TABLE IF NOT EXISTS "public"."workflows" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "is_active" boolean DEFAULT false NOT NULL,
    "trigger_type" "text" NOT NULL,
    "trigger_config" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "definition" "jsonb" DEFAULT '{"edges": [], "nodes": []}'::"jsonb" NOT NULL,
    "loop_limit" integer DEFAULT 100 NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "wrapper_for" "text",
    "wrapper_source_id" "uuid",
    "enrollment_criteria" "jsonb" DEFAULT '{}'::"jsonb",
    "re_enrollment_enabled" boolean DEFAULT false NOT NULL,
    "re_enrollment_cooldown_days" integer DEFAULT 30,
    "re_enrollment_max_times" integer DEFAULT 1,
    CONSTRAINT "workflows_wrapper_for_check" CHECK ((("wrapper_for" IS NULL) OR ("wrapper_for" = ANY (ARRAY['pipe_rule'::"text", 'campaign_rule'::"text"]))))
);


ALTER TABLE "public"."workflows" OWNER TO "postgres";


COMMENT ON COLUMN "public"."workflows"."wrapper_for" IS 'Trilha 3.A: marca workflow como wrapper auto-gerado de pipe_rule ou campaign_rule. NULL = workflow user-created via builder visual.';



COMMENT ON COLUMN "public"."workflows"."wrapper_source_id" IS 'Trilha 3.A: FK virtual pra pipe_dispatch_rules.id ou campanha_dispatch_rules.id (depende de wrapper_for).';



