CREATE POLICY "Admins can delete api_keys" ON "public"."api_keys" FOR DELETE USING ((( SELECT "public"."is_master_user"() AS "is_master_user") OR ("organization_id" IN ( SELECT "team_members"."organization_id"
   FROM "public"."team_members"
  WHERE (("team_members"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("team_members"."role" = 'admin'::"public"."app_role"))))));



CREATE POLICY "Admins can insert api_keys" ON "public"."api_keys" FOR INSERT WITH CHECK ((( SELECT "public"."is_master_user"() AS "is_master_user") OR ("organization_id" IN ( SELECT "team_members"."organization_id"
   FROM "public"."team_members"
  WHERE (("team_members"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("team_members"."role" = 'admin'::"public"."app_role"))))));



CREATE POLICY "Admins can insert own org pipeline config" ON "public"."pipeline_display_config" FOR INSERT WITH CHECK (("organization_id" IN ( SELECT "team_members"."organization_id"
   FROM "public"."team_members"
  WHERE (("team_members"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("team_members"."role" = 'admin'::"public"."app_role")))));



CREATE POLICY "Admins can manage followup rules" ON "public"."copilot_agent_followup_rules" USING ((("agent_id" IN ( SELECT "copilot_agents"."id"
   FROM "public"."copilot_agents"
  WHERE ("copilot_agents"."organization_id" IN ( SELECT "public"."get_my_organization_ids"() AS "get_my_organization_ids")))) AND (EXISTS ( SELECT 1
   FROM "public"."user_roles"
  WHERE (("user_roles"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("user_roles"."role" = 'admin'::"public"."app_role"))))));



CREATE POLICY "Admins can update api_keys" ON "public"."api_keys" FOR UPDATE USING ((( SELECT "public"."is_master_user"() AS "is_master_user") OR ("organization_id" IN ( SELECT "team_members"."organization_id"
   FROM "public"."team_members"
  WHERE (("team_members"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("team_members"."role" = 'admin'::"public"."app_role"))))));



CREATE POLICY "Admins can update own org pipeline config" ON "public"."pipeline_display_config" FOR UPDATE USING (("organization_id" IN ( SELECT "team_members"."organization_id"
   FROM "public"."team_members"
