CREATE POLICY "meeting_participants_delete_own_org" ON "public"."meeting_participants" FOR DELETE USING ((EXISTS ( SELECT 1
   FROM "public"."meetings" "m"
  WHERE (("m"."id" = "meeting_participants"."meeting_id") AND ("m"."organization_id" IN ( SELECT "tm"."organization_id"
